         .word   $083a
         .word   $0837
         .word   $0834
         .word   $0831
         .word   $082e
         .word   $082b
         .word   $0829
         .word   $0827
         .word   $0824
         .word   $0822
         .word   $0820
         .word   $081e
         .word   $081c
         .word   $081b
tbl_NoteLengths:
         .byte   $01,$02,$03,$04,$06,$08,$0c,$10
         .byte   $18,$20
; (note names begin with 'A', but values start at 'C' and wrap around)
tbl_NoteNameToValue:
         .byte   18
         .byte   22
         .byte   0
         .byte   4
         .byte   8
         .byte   10
         .byte   14
tbl_OctaveBaseNoteVals:
         .byte   0
         .byte   24
         .byte   48
         .byte   72
         .byte   96
         .byte   120

vZpKeyRdCtr .set $28
_Reset:  lda     #$00
         sta     PPUCTRL
         sta     PPUMASK    ;turn off rendering
         jsr     WaitForVBlank
         jsr     WaitForVBlank
         lda     #$4c       ;JMP opcode
         sta     zpNmiTrampoline
         lda     #<NMI_DefaultHandler
         sta     zpNmiTrampoline+1
         lda     #>NMI_DefaultHandler
         sta     zpNmiTrampoline+2 ;set default NMI handler to NMI_DefaultHandler
         jsr     InitPpuApu ;init various PPU, APU stuff
         jsr     DoCLS_1    ;clear bg screen 1
         lda     #>VRAM_screen0
         sta     zpPpuScreenBasePage ;send screen updates to screen 0
         lda     #30
         sta     vZpKeyRdCtr
@keyRdLp:
         jsr     ReadKeyInsMacros ;read keyboard
         beq     @haveKbd   ;null char returned? -> done checking
         dec     vZpKeyRdCtr ;else, either key being held, or kbd not connected
         bne     @keyRdLp   ;-> loop until key-down reported for 30 checks
         lda     #$05
         sta     zpCH
         lda     #$04
         sta     zpCV       ;LOCATE 5,4
         lda     #DTU__KEYBOARD_WO_SETSUZOKU
         jsr     DirectTheUser
         lda     #DTU__SHITE_KUDASAI
         jsr     DirectTheUser ;ask the user to please connect the keyboard
@waitKbdConn:
         jsr     ReadKeyInsMacros ;read keyboard
         bne     @waitKbdConn ;-> loop until null character returned (kbd connected)
@haveKbd:
         jsr     CheckBackupSwitch ;is the backup switch on?
         bcc     @buSwOff   ;off -> good to go!
         jsr     DoCLS      ;on: this locks the battery-backed RAM, which we don't want
         lda     #$01
         sta     zpCH
         lda     #$04
         sta     zpCV       ;LOCATE 1,4
         lda     #DTU__BACKUP_SWITCH_WO
         jsr     DirectTheUser
         lda     #DTU__OFF_NI_SHITE_KUDASAI
         jsr     DirectTheUser ;ask the user to turn off the cart's backup switch
@waitBuSwOff:
         jsr     CheckBackupSwitch ;test backup switch
         bcs     @waitBuSwOff ;-> loop until it's off
@buSwOff:
         lda     #$00
         sta     zpBgGotFlag ;clear zpBgGotFlag
         lda     zpBackupRstrd
         cmp     #BU_RESTORED_MARK ;did we already restore program from battery backup?
         beq     HotStart   ;yes -> skip restoration, then
         lda     bbBackupAvail
         cmp     #BU_AVAIL_MARK ;does battery-backed RAM indicate a program is backed-up?
         bne     RstNoBackupReady ;no ->
         jsr     DoCLS_1    ;clear screen 1
         lda     bgGotFlag
         sta     zpBgGotFlag ;note whether we have BG data backed-up
         lda     bbTXTEND   ;copy battery-backed TXTEND to the real one
         sta     zpTXTEND
         lda     bbTXTEND+1
         sta     zpTXTEND+1
         lda     #<basicProgram ;copy (hard-coded) basicProgram start to TXTTAB
         sta     zpTXTTAB
         lda     #>basicProgram
         sta     zpTXTTAB+1
         lda     #$00
         tax
@delBuVarsLp:
         sta     $6000,x    ;delete the backup vars, now that they're restored
         inx                ;(avoids them getting out of date, forces user to run BACKUP cmd again)
         cpx     #$05
         bne     @delBuVarsLp ;-> loop until backup vars deleted (5 bytes)
         jsr     Clear      ;clear BASIC vars
HotStart:
         jsr     InitVars   ;init zero-page vars
         jsr     PrintHotStart ;print the "HOT START" message
         jsr     EnsureSOL  ;CRLF
         lda     zpBgGotFlag ;have we got bg data backed-up, too?
         beq     @basic     ;no -> start up BASIC
         lda     #<str_BG   ;yes, bg backed up: indicate it
         sta     zpOutputStr
         lda     #>str_BG
         sta     zpOutputStr+1
         jsr     PrintString ;print "[BG]"
         jsr     EnsureSOL  ;CRLF
         jsr     RestoreBackupBgData ;restore the backed-up bg data
@basic:  jmp     CmdFn_END  ;enter BASIC

str_BG:  .asciiz "[BG]"

RstNoBackupReady:
         jsr     DoCLS_1    ;clear screen 1
         lda     #BU_RESTORED_MARK
         sta     zpBackupRstrd ;no backup avail, so mark it "restored" to avoid future check
         lda     #$00
         sta     bgGotFlag  ;if no backup, no backed-up BG data
         jmp     RstNoBackupStartBasic

; SYSTEM command; also BACKUP.
CmdFn_SYSTEMorBACKUP:
         lda     zpPpuMaskVal
         and     #$ef
         sta     zpPpuMaskVal ;disable sprites
         sta     PPUMASK
         lda     #$4c       ;JMP opcode?
         sta     bbBackupAvail ;idk why we're JMPing to the null byte
         lda     zpTXTEND   ; at the end of the BASIC prog, but anyway
         sta     bbTXTEND
         lda     zpTXTEND+1
         sta     $6003
         jsr     DoCLS      ;clear the screen
         lda     #$02
         sta     zpCH
         lda     #$04
         sta     zpCV       ;LOCATE 2,4
         lda     #DTU__BACKUP_SWITCH_WO
         jsr     DirectTheUser
         lda     #DTU__ON
         jsr     DirectTheUser
         lda     #DTU__NI_SHITE_KUDASAI
         jsr     DirectTheUser ;print "Please turn on the backup switch" (in Japanese)
@whileBuSwOff:
         jsr     ReadKeyInsMacros
         cmp     #$03       ;check if STOP key is pressed
         beq     HotStart   ;pressed? -> BASIC hot start
         jsr     CheckBackupSwitch ;is backup switch on?
         bcc     @whileBuSwOff ;no -> loop until it is, or until STOP key pressed
         jsr     DoCLS      ;clear screen
         lda     #$05
         sta     zpCH
         lda     #$04
         sta     zpCV       ;LOCATE 5,4
         lda     #DTU__DENGEN_WO
         jsr     DirectTheUser
         lda     #DTU__OFF_NI_SHITE_KUDASAI
         jsr     DirectTheUser ;print "Please turn off power" (in Japanese)
@stopLp: jsr     ReadKeyInsMacros
         cmp     #$03       ;STOP key pressed?
         bne     @stopLp    ;no -> just keep checking for it
         jmp     _Reset     ;yes -> cold-start BASIC

; Sets the current VRAM address from the A (high) and X (low) registers.
PpuGoToAX:
         sta     PPUADDR
         stx     PPUADDR
         rts

; Checks whether the physical battery-backup switch on the back of the Family
; BASIC cartridge is on or off. Carry is unset while switch is off, set if on
CheckBackupSwitch:
         lda     $6000
         pha                ;save whatever's at location $6000 (cartridge RAM start)
         lda     #$19
         sta     $6000      ;try writing to it
         cmp     $6000      ;do we read back the value we just wrote?
         beq     @swOff     ;yes -> backup switch is off
         pla                ;no: backup switch is on
         sta     $6000      ;restore original val at $6000
         sec                ;set carry (switch on)
         rts                ;and return

@swOff:  pla
         sta     $6000      ;restore original val at $6000
         clc                ;clear carry (switch is off)
         rts                ;and return

; Tell the user to do something
; (turn backup switch on/off, power off, connect keyboard)
DirectTheUser:
         asl     A          ;multiply message index by 2, for table indexing
         tax
         lda     tbl_DirectTheUserStrs,x ;load the message string
         sta     zpOutputStr
         lda     tbl_DirectTheUserStrs+1,x
         sta     zpOutputStr+1
         jmp     PrintString ;and output it

strON:   .asciiz " ON"
strKEYBOARD_WO_SETSUZOKU:
         .byte   $66,$2d,$aa,$2d,$a5,$20,$8d,$20,$6d,$71,$a0,$67,$00
strDENGEN_WO:
         .byte   $a4,$8c,$9a,$8c,$20,$8d,$00
strBACKUP_SWITCH_WO:
         .byte   $a6,$96,$67,$60,$96,$ad,$20,$6c,$61,$96,$70,$20,$8d,$00
strOFF_NI_SHITE_KUDASAI:
         .byte   $20        ;Falls thru to next string start
         .byte   $4f
         .byte   $46
         .byte   $46
strNI_SHITE_KUDASAI:
         .byte   $20,$75    ;Falls thru to next string start
strSHITE_KUDASAI:
         .byte   $20,$6b,$72,$67,$a1,$6a,$61,$00
tbl_DirectTheUserStrs:
         .word   strON
         .word   strKEYBOARD_WO_SETSUZOKU
         .word   strDENGEN_WO
         .word   strBACKUP_SWITCH_WO
         .word   strOFF_NI_SHITE_KUDASAI
         .word   strNI_SHITE_KUDASAI
         .word   strSHITE_KUDASAI

RstNoBackupStartBasic:
         ldx     #$ff
         txs                ;initialize stack pointer register
         jsr     InitVars   ;clear zero-page vars
         jsr     ResetTxtVarPtrs ;initialize basic start/end (empty)
         jsr     PrintStartupText ;print BASIC startup text
CmdFn_END:
         jsr     ClearStoppedFlag ;clear "stopped" flag
         sta     zpErrHandStat ;store zero (EH_NO_HANDLER)
ResetAndEnterDirectMode:
         lda     #$00
         sta     zpAutoEnabled ;turn off auto-increment and erase its data
         sta     zpAutoLNumIncr
         sta     zpAutoLNumIncr+1
         ldx     #$ff       ;clear the CPU stack
         txs
         txa                ;and push #$FFFF (as a limit to NEXT/RETURN stack searches?)
         pha
         pha
         jsr     DeactivateKanaMode ;ensure we're in ASCII typing mode
SaveStackAndDirectMode:
         tsx
         stx     zpSavedStack
         cli
; Loop over user input lines, obeying commands and entering numbered program
; code lines.
DirectModeLoop:
         ldx     zpSavedStack ;restore stack ptr from zpSavedStack
         txs
         jsr     EnsureSOL
         jsr     PrintOK
         lda     zpStoppedFlag ;STOPped?
         beq     @skipPd    ;no -> skip period
         lda     #'.'       ;yes: print period after "OK", to indicate it was a STOP
         jsr     PrintOneChar ; (and can be CONTinued)
@skipPd: jsr     EnsureSOL  ;another CRLF
DML_skipOK:
         jsr     DirectMode_handleAuto ;auto-prefix line number, if active
         jsr     ReadLine   ;read a line of the user's input
         cmp     #$03       ;STOP typed during line input?
         beq     DML_cancelAuto ;yes -> ignore line and reprompt
         jsr     InitLineBufferScanning ;point TXTPTR at lineBuffer
         jsr     GetTxtChar
         jsr     TxtSkipSpaces
         and     #$ff       ;empty line?
         beq     DML_skipOK ;yes -> reprompt
         jsr     IsDigit    ;start with a digit?
         bcs     @directExec ;no -> directly execute commands
         jsr     ProcessNumberedLine ;yes -> handle the numbered line
         jsr     Clear      ;clear variables (we may have just trampled variable space)
         jmp     DML_skipOK

@directExec:
         jmp     ExecuteDirectModeLine

DML_cancelAuto:
         lda     zpAutoEnabled
         beq     DML_skipOK
         lda     #$00
         sta     zpAutoEnabled
         jmp     DirectModeLoop

DirectMode_handleAuto:
         lda     zpAutoEnabled ;AUTO active?
         beq     rts_8325   ;no -> nothing to do; return
         lda     zpNxtAutoLNum ;copy the next auto linenum to zpFindLNum
         sta     zpFindLNum
         lda     zpNxtAutoLNum+1
         sta     zpFindLNum+1
         jsr     FindLineNum ;and search for that line number
         bne     DML_noSuchLine ;no such line? -> don't need to handle it then
         jsr     SaveTXTPTR ;save TXTPTR
         lda     zpTxtLink
         sta     zpTXTPTR   ;set found line as new TXTPTR
         lda     zpTxtLink+1
         sta     zpTXTPTR+1
         jsr     PrintLineNumAndDetok ;print the line we found
         jsr     RestoreTXTPTR ;restore saved TXTPTR
         ldx     zpCV       ;get CV (which is one past the just-printed line)
         dex                ;decrement (on the printed line)
         dex                ;decrement again (just above the printed line)
@findLineStart:
         jsr     DoesRowWrap ;is this a row that wrapped to next line?
         beq     @found     ;no -> found end of prev line
         dex                ;yes, wraps. Back up one and see if *that* wraps
         bpl     @findLineStart
@found:  inx                ;incr, from end of prev line, to start of our printed line
         stx     zpCV       ;and save as current row
DML_noSuchLine:
         lda     zpNxtAutoLNum ;zCH is guaranteed to be 0 already,
         sta     zpWAccum   ; since printed line ended with CRLF
         lda     zpNxtAutoLNum+1
         sta     zpWAccum+1 ;copy auto linenum to WAccum
         jsr     PosDecStrFromWord ;convert to decimal
         jsr     FindFirstNonzeroDigit ;skip leading zeroes
         jsr     QueueOutpNumStrTmp ;queue it for output
         lda     #$20       ;plus a SPACE character
         jsr     QueueCharForOutput
         jsr     PrintOutBuf ;print out linenum + space.
IncrementAutoLNum:
         clc                ;finally, increment auto linenum for next time
         lda     zpNxtAutoLNum
         adc     zpAutoLNumIncr
         sta     zpNxtAutoLNum
         lda     zpNxtAutoLNum+1
         adc     zpAutoLNumIncr+1
         bcs     DeactivateAutoAndError ;overflowed? -> deactivate AUTO and error.
         sta     zpNxtAutoLNum+1
rts_8325:
         rts

DeactivateAutoAndError:
         lda     #$00
         sta     zpAutoEnabled
         jmp     ErrorOverflow

; This routine used to flag that we are in direct mode, and there is no line
; number for the executing BASIC code.
StrikeRunLineNum:
         lda     #$ff
         sta     zpRunLineNum
         sta     zpRunLineNum+1
         rts

ExecuteDirectModeLine:
         jsr     Tokenize   ; tokenize the line
         lda     #<dmFakeNextLine
         sta     zpRunTxtNxtLnk ;Set "next line link" to an arbitrary location that starts with zero (reads as end of program)
         lda     #>dmFakeNextLine
         sta     zpRunTxtNxtLnk+1
         lda     #<tokenizeBuffer ;point TXTPTR at tokenizeBuffer
         sta     zpTXTPTR   ; so we execute from there
         lda     #>tokenizeBuffer
         sta     zpTXTPTR+1
         jsr     StrikeRunLineNum
; From here on down, this routine is used both by ExecuteDirectModeLine
; (directly above), and also by a running basic program (for each command)
ExecuteCommand:
         jsr     StopIfStopKey
         jsr     ExecCheckMem
         jsr     TxtSkipSpaces
         pha
         lda     zpTXTPTR   ;save this spot as start of the current command
         sta     zpTxtThisCmd
         lda     zpTXTPTR+1
         sta     zpTxtThisCmd+1
         jsr     TxtPtrIncr
         pla                ;got null char (end of line)?
         beq     skipToNextLine_83B4 ;yes -> skip to next
         cmp     #':'       ;got colon?
         beq     ExecuteCommand ;yes -> reset zpTxtThisCmd to here
         pha
         jsr     MaybePrintTrace ;print line number trace, if TRON is active
         pla
         cmp     #$27       ;got apostrophe (REM)?
         beq     skipToNextLine_83B4 ;yes -> skip line
         cmp     #$80       ;got a command token?
         bcs     execCmdByTok_83B7 ;yes -> execute it
         jsr     IsAlpha    ;got an alphabetic character?
         bcs     errSyntax_83B1 ;no -> error
         pha
         jsr     TxtPtrDecr ;backup TXTPTR to the start of the var name
         pla
         jsr     EvalVarNameOrSynErr ;find or create the variable for this name
         lda     zpVarType  ;push the var type
         pha
         lda     zpVarData  ;push the var data ptr
         pha
         lda     zpVarData+1
         pha
         jsr     SkipEqualsOrErr ;demand a '=' here
         jsr     FrmEval    ;evaluate the value
         pla
         sta     zpVarData+1 ;pull var data ptr and restore
         pla
         sta     zpVarData
         pla
         sta     zpVarType  ;pull var type and restore
         ldy     #$00
         and     #$0f
         cmp     #TYP_STR   ;is var base type a string?
         beq     ExecCmd_SetStringVar ;yes -> handle as string
         jsr     ErrorUnlessInteger ;ensure value for int is int!
         lda     exprParseStk ;copy expression result to var data
         sta     (zpVarData),y
         lda     exprParseStk+1
         iny
         sta     (zpVarData),y
         jmp     ExecuteCommand ;continue executing successive commands

errSyntax_83B1:
         jmp     ErrorSyntax

skipToNextLine_83B4:
         jmp     ExecSkipToNextLine

execCmdByTok_83B7:
         jmp     ExecuteCommandByToken

ErrorStringTooLong:
         lda     #err_ST
         jmp     PrintErrorAndStop

ExecCmd_SetStringVar:
         jsr     ErrorUnlessString ;ensure value for string var is string!
         jsr     CpyExprStrToStrVar ;copy the string value to our variable data space
         jmp     ExecuteCommand ;continue executing successive commands

setEmptyAndRts:
         sta     (zpVarData),y
         rts

CpyExprStrToStrVar:
         ldy     #$00
         lda     exprParseStk ;examine string length
         beq     setEmptyAndRts ;zero? -> just copy the length only
         cmp     #32        ;len >= 32?
         bcs     ErrorStringTooLong ;yes -> error, too long
         sta     (zpVarData),y ;save length to variable
         lda     exprParseStk+1 ;copy str content ptr into zero-page pointers for indexing
         sta     zpMisc
         lda     exprParseStk+2
         sta     zpMisc+1
         iny
         tya
         clc
         adc     zpVarData
         sta     zpVarData
         lda     #$00
         adc     zpVarData+1
         sta     zpVarData+1 ;set copy dest ptr to one past zpVarData (i.e. contents, not strlen)
         ldx     exprParseStk
         ldy     #$00
@cpyLp:  lda     (zpMisc),y
         sta     (zpVarData),y
         iny
         dex
         bne     @cpyLp
rts_83FC:
         rts

; Print line number trace, if active
MaybePrintTrace:
         lda     zpTraceOnFlag ;return if trace is off, or if we're in direct mode
         beq     rts_83FC
         lda     #$ff
         cmp     zpRunLineNum
         bne     @doTrace
         cmp     zpRunLineNum+1
         beq     rts_83FC
@doTrace:
         lda     #'#'
         jsr     QueueCharForOutput ;queue a '#'
         lda     zpRunLineNum
         sta     zpWAccum
         lda     zpRunLineNum+1
         sta     zpWAccum+1
         jsr     PosDecStrFromWord ;queue the line number
         jsr     FindFirstNonzeroDigit
         jsr     QueueOutpNumStrTmp
         lda     #$20       ;queue a SPACE
         jsr     QueueCharForOutput
         jmp     PrintOutBuf ;now print the queue

ExecuteCommandByToken:
         sec
         sbc     #$80       ;remove high bit from token
         cmp     #$44       ;was it a function token, rather than command token?
         bcs     ErrorSyntax ;yes -> syntax error
         asl     A          ;double the value (for jump table index)
         tax
         lda     jtbl_Commands,x ;put address of command handler into zpMisc
         sta     zpMisc
         lda     jtbl_Commands+1,x
         sta     zpMisc+1
         tsx
         stx     zpSavedStack ;save stack pointer
         jsr     IsEndOfCmd ;load next non-space char in A, and set Z iff end of command
         jsr     JmpIndirectZpMisc ;execute the command
         jmp     ExecuteCommand ;continue executing successive commands

; Enters DirectModeLoop. First checks if we have a resumable error AND were
; executing a direct command, and gives a "NR" (No Resume) error if so.
FinishExecution:
         lda     zpErrHandStat
         cmp     #EH_IN_HANDLER
         beq     @errHandNeverResmd
@enterDirectMode:
         jmp     SaveStackAndDirectMode

@errHandNeverResmd:
         jsr     @chkDirect ;are we in direct mode (no line num)?
         bcs     @enterDirectMode ;yes -> just go to direct mode prompt
         jmp     ErrorNoResume ;no: error, bc we handled an error but didn't resume after

@chkDirect:
         lda     #$ff
         cmp     zpRunLineNum
         bne     @notDirect
         cmp     zpRunLineNum+1
         bne     @notDirect
         sec
         rts

@notDirect:
         clc
         rts

CmdFn_DATAorREM:
         pla                ;pull return addr (we'll jump directly)
         pla
; Also used by apostrophe ('), and to skip the remainder of a false IF statement
ExecSkipToNextLine:
         lda     zpRunTxtNxtLnk ;replace zpTXTPTR with ptr to start of next line
         sta     zpTXTPTR
         lda     zpRunTxtNxtLnk+1
         sta     zpTXTPTR+1
; Also used by RUN. Update line linkage info before running a line
ExecuteLine:
         jsr     GetTxtChar ;get offset from here to start of next line
         beq     FinishExecution ;zero (last line of prog)? -> completed execution
         clc
         adc     zpTXTPTR   ;add offset to current TXTPTR
         sta     zpRunTxtNxtLnk ;and store in zpRunTxtNxtLnk as ptr to start of next line
         lda     #$00
         adc     zpTXTPTR+1
         sta     zpRunTxtNxtLnk+1
         iny
         lda     (zpTXTPTR),y ;save current line's line number
         sta     zpRunLineNum
         iny
         lda     (zpTXTPTR),y
         sta     zpRunLineNum+1
         jsr     TxtPtrAdvThree ;skip TXTPTR past offset and line number
         jmp     ExecuteCommand ;and execute the first command

; Emit a syntax error (code [SN]) and stop execution. In addition to being
; called directly from various places, this function is also in the jump table
; for the keywords THEN, TO, STEP, and OFF, since these are all marker tokens
; and not real commands. (ON can start legit commands, so it does not go here.)
ErrorSyntax:
         lda     #err_SN
         .byte   $ae
ErrorIllegalValue:
         lda     #err_IL
         jmp     PrintErrorAndStop

AdvThenIsEndOfCmd:
         jsr     TxtPtrIncr
; Z is set, if and only if we're at the end of the command (no more args)
IsEndOfCmd:
         jsr     TxtSkipSpaces
         and     #$ff
         beq     @rts
         cmp     #':'
@rts:    rts

ClearStoppedTraceAndError:
         jsr     ClearStoppedFlag
         sta     zpTraceOnFlag ;storing zero
ClearErrorFlags:
         sta     zpErrHandStat ;clear error/resume flags
         sta     zpErrCode
         sta     zpUnusedErrVar
         sta     zpErrLineNum
         sta     zpErrLineNum+1
         rts

CmdFn_NEW:
         jsr     ResetTxtVarPtrs ;reset pointers to BASIC text and vars
         jmp     ResetAndEnterDirectMode ;reset auto-incr and enter direct-mode prompt

ResetTxtVarPtrs:
         jsr     ClearStoppedTraceAndError
         sta     basicProgram ;clear offset and line number
         sta     basicProgram+1
         sta     basicProgram+2
         ldx     #$06
         stx     zpTXTTAB   ;set TXTTAB to $6006
         inx
         stx     zpTXTEND   ;set TXTEND one byte past that ($6007)
         inx
         stx     zpVARTAB   ;set VARTAB one past that ($6008)
         inx
         stx     zpVAREND   ;and VAREND one past VARTAB ($6009)
         inx
         stx     zpGpStrIdx ;;set $21,$22 to byte after that (NEVER USED!)
         lda     #$60
         sta     zpTXTTAB+1 ;set high bytes (#$60) for all of the above
         sta     zpTXTEND+1
         sta     zpVARTAB+1
         sta     zpVAREND+1
         sta     zp22
         rts

; Handles a numbered line. If the line consists only of a number, then delete
; the indicated line; otherwise, tokenize the line and insert it where it
; belongs.
ProcessNumberedLine:
         jsr     ClearStoppedFlag ;we're about to mess with line ordering; disallow CONT
         jsr     StrikeRunLineNum
         jsr     ParseDecimalWordFromTxt ;get the typed line number
         lda     #$ff
         cmp     zpWAccum   ;line num = 65535?
         bne     @proceed   ;no
         cmp     zpWAccum+1 ;maybe... check high byte too
         bne     @proceed   ;less than 65535
         beq     ErrorIllegalValue ; = 65535, not allowed

@proceed:
         lda     zpWAccum
         sta     zpNxtAutoLNum ;record line number for AUTO
         lda     zpWAccum+1
         sta     zpNxtAutoLNum+1
         jsr     IncrementAutoLNum
         jsr     GetTxtChar ;get a char
         cmp     #$20       ;is it a space?
         bne     @notSp     ;no -> stick with this char
         jsr     TxtPtrIncrAndGetChar ;yes: get the next char
@notSp:  and     #$ff       ;just a line number, no content?
         beq     TxtDeleteLineWAccum ;yes -> just delete the line if it exists
         lda     zpWAccum   ;no: put line number in zpFindLNum
         sta     zpFindLNum
         lda     zpWAccum+1
         sta     zpFindLNum+1
         jsr     Tokenize   ;and tokenize the contents via zpTokenizePtr into tokenizeBuffer
; Record tokenized length in zpWAccum
         sec
         lda     zpTokenizePtr
         sbc     #<tokenizeBuffer ;subtracting #$00... silly!
         sta     zpWAccum
         lda     zpTokenizePtr+1
         sbc     #>tokenizeBuffer
         sta     zpWAccum+1
;  
         lda     #$02
         clc
         adc     zpWAccum
         sta     zpNewLineOffset
         lda     zpFindLNum
         sta     zpInsLineNum
         lda     zpFindLNum+1
         sta     zpInsLineNum+1
         jsr     TxtDeleteLine ;delete any existing line w same #
         jmp     TxtInsertLine ;then insert ours

; Find the position for the line number zpFindLNum within the BASIC program,
; leaving zpTxtLink pointing at the closest less-than-or-equal numbered line.
; Z flag is set iff an exact line-number match was found.
vZpInsDelNxtLnk .set $0b    ;link to next line after the one being inserted/deleted
FindLineNum:
         lda     zpTXTTAB   ;Point zpTxtLink at program start
         sta     zpTxtLink
         lda     zpTXTTAB+1
         sta     zpTxtLink+1
FLN_nextLine:
         ldy     #$00
         lda     (zpTxtLink),y ;read offset to next ln. != 0?
         bne     notDone    ;not zero -> continue to process
         lda     #$ff       ;zero: out of lines. Indicate not exact, and return.
rts_8550:
         rts

notDone: ldy     #$02
         lda     zpFindLNum+1
         cmp     (zpTxtLink),y ;compare line num high bytes
         bne     @hiDiff    ;high bytes differ -> check how 
         dey                ;high bytes same, check low
         lda     zpFindLNum
         cmp     (zpTxtLink),y
         beq     rts_8550   ;line numbers equal -> return
@hiDiff: bcc     rts_8550   ;sought line # < cur line #? -> also return
; Fast-forward to next BASIC line
         ldy     #$00
         clc
         lda     (zpTxtLink),y ;get offset to next line
         adc     zpTxtLink  ;add to pointer for current line
         sta     zpTxtLink  ;save as new pointer
         lda     zpTxtLink+1 ;(handle high bytes too)
         adc     #$00
         sta     zpTxtLink+1
         jmp     FLN_nextLine ;-> loop back around and check the new line pointer

; Delete designated line of BASIC code
TxtDeleteLineWAccum:
         lda     zpWAccum
         sta     zpFindLNum
         lda     zpWAccum+1
         sta     zpFindLNum+1
TxtDeleteLine:
         jsr     FindLineNum ;found line number?
         bne     rts_8550   ;no -> nothing to do
TxtDeleteFoundLine:
         ldy     #$00
         lda     (zpTxtLink),y ;get offset to following line
         sta     zpTmp3C    ;record length of line to delete
         clc
         adc     zpTxtLink  ;add to line link to get start of next line
         sta     vZpInsDelNxtLnk
         lda     zpTxtLink+1
         adc     #$00
         sta     vZpInsDelNxtLnk+1
; Starting from the next line, copy back over the deleted line, including
; offsets, moving all forward lines back by the amount of space this line used
; to occupy.
; Not a terribly fast copy: checks source pointer against program end on _every_
; byte written.
CopyLinesBack:
         ldy     #$00
         lda     (vZpInsDelNxtLnk),y
         sta     (zpTxtLink),y
         inc     vZpInsDelNxtLnk ;increment copy source
         bne     @noHi
         inc     vZpInsDelNxtLnk+1
@noHi:   inc     zpTxtLink  ;increment copy dest
         bne     @noHi2
         inc     zpTxtLink+1
@noHi2:  lda     zpTxtLink+1
         cmp     zpTXTEND+1 ;have we reached the program end?
         bne     CopyLinesBack ;no -> copy next byte
         lda     zpTxtLink  ;maybe: check low byte, too
         cmp     zpTXTEND
         bne     CopyLinesBack ;not the end-> copy next byte
         sec                ;source ptr reached end; move end back to dest ptr
         lda     zpTXTEND
         sbc     zpTmp3C    ;subtract length of deleted line from prog end
         sta     zpTXTEND
         lda     zpTXTEND+1
         sbc     #$00
         sta     zpTXTEND+1
         rts

; Make room for a newly-tokenized line to be inserted into the program... then
; insert it!
TxtInsertLine:
         lda     zpTXTEND   ;get the current program end (low byte)
         clc
         adc     zpNewLineOffset ;add the length of the new line (including header)
         sta     zpWAccum   ;save in WAccum
         lda     zpTXTEND+1 ;add any carry to high byte
         adc     #$00
         sta     zpWAccum+1 ;save that too
         jsr     CheckFreeSpaceOrError ;ensure we have space for it
         jsr     FindLineNum ;find where this line goes
         lda     zpTXTEND   ;get current program end (low byte)
         sta     vZpInsDelNxtLnk ;save it
         clc
         adc     zpNewLineOffset ;add length of the new line to it
         sta     zpMisc     ;and save in zpMisc
         lda     zpTXTEND+1 ;get program end (high byte)
         sta     vZpInsDelNxtLnk+1 ;save it
         adc     #$00       ;add the carry from adding new line's len
         sta     zpMisc+1   ;save in zpMisc high byte
@backCpyLp:
         ldy     #$00       ;starting with the byte past the end of final line
         lda     (vZpInsDelNxtLnk),y ; and its terminator, copy that byte from the old location,
         sta     (zpMisc),y ; new-line-length bytes forward to new loc
         jsr     TIL_DecrOldLocPtr ;--oldPtr
         jsr     TIL_DecrNewLocPtr ;--newPtr
         lda     zpTxtLink
         cmp     vZpInsDelNxtLnk ;have we reached the spot we'll insert the line at?
         bne     @backCpyLp ;no -> loop, copy, decrement, until we reach it
         lda     zpTxtLink+1 ;check the high byte too
         cmp     vZpInsDelNxtLnk+1 ;high bytes match?
         bne     @backCpyLp ;no -> not quite there yet, keep copying
         lda     (vZpInsDelNxtLnk),y ;yes, made it. Copy this last byte forward
         sta     (zpMisc),y
         ldy     #$00
         lda     zpNewLineOffset
         sta     (zpTxtLink),y ;now copy the new line's length as the offset to next line
         iny
         lda     zpInsLineNum
         sta     (zpTxtLink),y ;and copy its line number
         iny
         lda     zpInsLineNum+1
         sta     (zpTxtLink),y ;(high byte, too)
         iny
         clc
         lda     #$03
         adc     zpTxtLink
         sta     zpTxtLink  ;advance write ptr by 3 (skipping next-line offset, and line #)
         lda     #$00
         adc     zpTxtLink+1
         sta     zpTxtLink+1 ;and handle any carry for the ptr's high byte
         lda     zpNewLineOffset
         sec
         sbc     #$03       ;adjust the offset value from here to next line, by same amount
         tax                ;and store in X register
         ldy     #$00
         lda     #<tokenizeBuffer
         sta     zpTokenizePtr ;point zpTokenizePtr at the tokenizeBuffer
         lda     #>tokenizeBuffer
         sta     zpTokenizePtr+1
@lineCpyLp:
         lda     (zpTokenizePtr),y ;copy from tokenizeBuffer (new line)
         sta     (zpTxtLink),y ; to new line location
         iny                ;incr copy index
         dex                ;decr remaining chars
         bne     @lineCpyLp ;chars left? -> keep looping/copying
         clc
         lda     zpTXTEND
         adc     zpNewLineOffset ;add the new line length to program end,
         sta     zpTXTEND   ; and save new value
         lda     #$00
         adc     zpTXTEND+1
         sta     zpTXTEND+1 ;handle the carry, too
         ldy     #$00
         tya
         sta     (zpTXTEND),y ;write final null byte after program end. And another after that.
         iny
         sta     (zpTXTEND),y
         rts                ;-> done

TIL_DecrOldLocPtr:
         lda     vZpInsDelNxtLnk ;get low byte of old-loc ptr
         beq     @oldLowZero ;is it zero? -> decrement both high and low bytes
         dec     vZpInsDelNxtLnk ;no, decrement it
         rts                ;-> and return

@oldLowZero:
         dec     vZpInsDelNxtLnk ;decr low
         dec     vZpInsDelNxtLnk+1 ;decr high
         rts                ;-> return

TIL_DecrNewLocPtr:
         lda     zpMisc     ;get low byte of new-loc ptr
         beq     @newLowZero ;zero? -> decrement bth high and low bytes
         dec     zpMisc     ;else just decr low byte
         rts                ;-> and return

@newLowZero:
         dec     zpMisc     ;decr low
         dec     zpMisc+1   ;decr high
         rts                ;-> return

InitVars:
         lda     #$04
         sta     zpTempo    ;initialize tempo for each musical voice
         sta     zpTempo+1
         sta     zpTempo+2
         lda     #$08
         sta     zpNoteLen  ;set a default note length for each musical voice
         sta     zpNoteLen+1
         sta     zpNoteLen+2
         lda     #$03
         sta     zpOctave   ;set a default octave for each musical voice
         sta     zpOctave+1 ; (dotted half-note, according to manual)
         sta     zpOctave+2
         lda     #$0f
         sta     zpVolume   ;set default volume (max) for each musical voice
         sta     zpVolume+1
         sta     zpVolume+2
         lda     #$30
         sta     zpEnvelope ;turn off envelope for each musical voice
         sta     zpEnvelope+1
         sta     zpEnvelope+2
         lda     #$02       ;set duty cycle (50%) for each musical voice
         sta     zpDuty
         sta     zpDuty+1
         sta     zpDuty+2
         jsr     ClearStoppedTraceAndError ;clear stop/trace/error flags
         sta     zpInsertMode ;clear auto-insert mode
         sta     zpRandom+1
         lda     #<memoryTop
         sta     zpFRETOP   ;reset FRETOP
         lda     #$03
         sta     zpRandom   ;reset RAND PRNG to start at #$0003
         sta     zpKeyClickFlg ;turn keyclicks on
         lda     #>memoryTop
         sta     zpFRETOP+1
         jsr     ClearOam
         jsr     ClearSpriteData
         jmp     InitPpuApu

CmdFn_RUN:
         jsr     Clear      ;flush away any variables
         jsr     ClearStoppedFlag ;clear various flags
         jsr     ClearErrorFlags
         jsr     ClearSpriteData
         jsr     ClearOam
         jsr     IsEndOfCmd ;do we have an arg?
         bne     gotoCmd_86D6 ;yes -> GOTO that line
         ldx     #$00       ;reset the stack pointer
         txs
         lda     #$ff
         pha                ;indicate limit of NEXT, RETURN stack searches?
         pha
         lda     zpTXTTAB   ;set TXTPTR to start of program
         sta     zpTXTPTR
         lda     zpTXTTAB+1
         sta     zpTXTPTR+1
         jmp     ExecuteLine ;-> and execute first line

gotoCmd_86D6:
         jmp     CmdFn_GOTO

SkipEqualsOrErr:
         jsr     TxtSkipSpaces
         cmp     #tok_OP_EQ
         bne     errSyn_86E3
         jmp     TxtPtrIncr

errSyn_86E3:
         jmp     ErrorSyntax

; The two BASIC commands that accept line number ranges as arguments - LIST, and
; DELETE - use this routine to read their parameters
ReadLineNumRange:
         php                ;push processor flags
         ldx     #$00
         stx     zpLNumStart
         stx     zpLNumStart+1
         dex
         stx     zpLNumEnd
         stx     zpLNumEnd+1
         plp                ;pop processor flags
         beq     rts_8757   ;no args? -> nothing to do, exit
         cmp     #','
         beq     RdLNRng_secondArg
         cmp     #'-'
         beq     RdLNRng_secondArg ;comma or dash? -> handle second arg
         cmp     #'.'       ;period?
         bne     RdLNRng_firstArg ;no -> handle first arg
         lda     zpContRunLineNum ;period found: use STOPped line
         sta     zpLNumStart ; as the start
         sta     zpLNumEnd  ; and end (for now), of the range
         lda     zpContRunLineNum+1 ;high byte
         jmp     RdLNRng_period ;-> set high bytes, and accept possible 2nd arg

RdLNRng_firstArg:
         cmp     #tok_LNUM_AFTER ;line num prefix token?
         bne     errSyn_86E3 ;no -> error
         jsr     TxtPtrIncrAndGetChar ;read first byte of line number
         sta     zpLNumStart ;use as both start and end of line range
         sta     zpLNumEnd
         jsr     TxtPtrIncrAndGetChar ;get high byte of line-num first argument
RdLNRng_period:
         sta     zpLNumStart+1 ;and set start+end high bytes too
         sta     zpLNumEnd+1
         jsr     AdvThenIsEndOfCmd ;get next byte. Is it the end of the command?
         beq     rts_8757   ;yes -> done parsing args
         cmp     #','       ;else, got a comma or dash?
         beq     RdLNRng_secondArg ;yes -> process 2nd arg
         cmp     #'-'
         bne     errSyn_86E3 ;else -> error
RdLNRng_secondArg:
         jsr     AdvThenIsEndOfCmd ;end of cmd after comma-or-dash?
         beq     RdLNRng_progEndIsEnd ;yes -> set end of range to end of program
         cmp     #'.'       ;else, got a period as 2nd arg?
         bne     @lnum      ;no -> expect line number
         lda     zpContRunLineNum ;got a period. Set CONT line as end of range.
         sta     zpLNumEnd
         lda     zpContRunLineNum+1
         jmp     @hiByt     ;-> and finish up args processing

@lnum:   cmp     #tok_LNUM_AFTER ;got the line-num token prefix?
         bne     errSyn_86E3 ;no -> error
         jsr     TxtPtrIncrAndGetChar ;get line-number 2nd arg
         sta     zpLNumEnd  ;and set as end-of-range
         jsr     TxtPtrIncrAndGetChar
@hiByt:  sta     zpLNumEnd+1
         jsr     TxtPtrIncr
         jmp     rts_8757   ;done processing args

RdLNRng_progEndIsEnd:
         lda     #$ff       ;set end of line-num range to maximum value (end of program)
         sta     zpLNumEnd
         sta     zpLNumEnd+1
rts_8757:
         rts                ;done processing args

CmdFn_DELETE:
         beq     errSyn_86E3 ;no arg? -> error
         ldx     #$ff
         stx     zpListOrDelete ;set DELETE mode
         jsr     ReadLineNumRange
         jsr     DoListOrDelete ;Perform the DELETE
         jmp     Clear      ;-> Clear variables, and end command.

CmdFn_LIST:
         jsr     ReadLineNumRange
         lda     #$00
         sta     zpListOrDelete ;set LIST mode
; The two commands that both operate on line-number ranges - LIST, and DELETE -
; both use this routine to perform their actions. The value of the variable
; zpListOrDelete ($51) is used to determine what actual action to perform on
; each line within the range.
DoListOrDelete:
         jsr     SaveTXTPTR ;save the original TXTPTR away
         lda     zpLNumStart ;save "start" line num as line to find
         sta     zpFindLNum
         lda     zpLNumStart+1
         sta     zpFindLNum+1
         jsr     FindLineNum ;...and then find it.
         ldy     #$00
         lda     (zpTxtLink),y ;read offset to next line num. Are we at end of prog?
         beq     LoD_RestoreTxtPtrAndReturn ;yes -> restore TXTPTR and exit LIST or DELETE.
         lda     zpTxtLink
         sta     zpTXTPTR   ;set TXTPTR start of found line linkage;
         lda     zpTxtLink+1 ; we'll use it to scan through the range
         sta     zpTXTPTR+1
LoD_mainLp:
         ldy     #$00
         lda     (zpTXTPTR),y ;end of program?
         beq     LoD_RestoreTxtPtrAndReturn ;yes -> restore TXTPTR and exit LIST or DELETE.
         iny
         lda     (zpTXTPTR),y ;read current line num
         sta     zpWAccum   ;save in WAccum
         iny
         lda     (zpTXTPTR),y
         sta     zpWAccum+1
         lda     zpLNumEnd  ;set WParam to end-of-range line num
         sta     zpWParam
         lda     zpLNumEnd+1
         sta     zpWParam+1
         jsr     WordCompare ;compare current line num, with range's end line num
         beq     @notPastEnd ;cur > end?
         bcs     LoD_RestoreTxtPtrAndReturn ;yes -> restore TXTPTR and exit LIST or DELETE.
@notPastEnd:
         lda     zpListOrDelete ;are we doing LIST?
         beq     ListCurLine ;yes -> LIST the current line
; Delete one line of the range
         lda     zpTXTPTR   ;no: we'll DELETE it
         sta     zpTxtLink  ;Copy current line linkage to zpTxtLink
         lda     zpTXTPTR+1
         sta     zpTxtLink+1
         jsr     TxtDeleteFoundLine ;and delete the line
         jmp     LoD_mainLp ;iterate again for next line in range

ListCurLine:
         jsr     PrintLineNumAndDetok
         jsr     PauseOnEsc
         jmp     LoD_mainLp ;iterate again for next line in range

; Pause listing (within LIST or FIND) if the Escape key is pressed.
; Honor STOP key if that's pressed.
PauseOnEsc:
         jsr     ReadKeyMaybeStop ;read from keyboard
         beq     @rts       ;no key pressed? -> return to list next line
         cmp     #$1b       ;ESCAPE key?
         bne     @rts       ;no -> return to list next line
@escPause:
         jsr     ReadKeyMaybeStop ;pause LISTing until some key other than ESCAPE is pressed
         beq     @escPause
         cmp     #$1b
         beq     @escPause
@rts:    rts                ;return to iterating over lines to LIST

ReadKeyMaybeStop:
         jsr     StopIfStopKey
         jmp     ReadKeyInsMacros

LoD_RestoreTxtPtrAndReturn:
         jmp     RestoreTXTPTR

QueueOutpNumStrTmp:
         lda     #zpNumStrTmp ;point zpOutputStr at zpNumStrTmp, as source
         clc                ; for output queuing
         adc     zpTmp46    ;add index to start position
         sta     zpOutputStr ;(carry isn't needed, the string is up to 6 chars max)
         lda     #>zpNumStrTmp
         sta     zpOutputStr+1
         jmp     QueueOutputStr ;queue the output string

; Print line number and the detokenized contents of the line. Used by
; DirectModeLoop when AUTO is active, and by LIST, and FIND.
PrintLineNumAndDetok:
         lda     #$00
         sta     zpOutTxtCurPos
         ldy     #$01
         lda     (zpTXTPTR),y ;put the line number at zpTXTPTR into WAccum
         sta     zpWAccum
         iny
         lda     (zpTXTPTR),y
         sta     zpWAccum+1
         jsr     PosDecStrFromWord
         jsr     FindFirstNonzeroDigit
         jsr     QueueOutpNumStrTmp ;queue up the line number to be printed
         lda     #$20
         jsr     QueueCharForOutput ;and add a SPACE character afterward
         lda     #$03
         clc
         adc     zpTXTPTR   ;set up zpTokenizePtr to detokenize from the line's contents
         sta     zpTokenizePtr
         lda     #$00
         adc     zpTXTPTR+1
         sta     zpTokenizePtr+1
         jsr     DetokenizeLine ;detokenize from zpTokenizePtr, into lineBuffer
         jsr     PointOutStrAtLineBufStart ;point zpOutputStr at lineBuffer
         jsr     PrintString ;print our queued line number plus detokenized stuff in lineBuffer
         lda     zpTokenizePtr
         sta     zpTXTPTR   ;(useless setting of zpTXTPTR; we throw it away a few lines below)
         lda     zpTokenizePtr+1
         sta     zpTXTPTR+1
         jsr     DoCRLF     ;carriage return + new line. (AUTO will have to back us back up.)
         lda     #$01
         clc
         adc     zpTokenizePtr ;zpTokenizePtr now points at null terminator at end of line
         sta     zpTXTPTR   ;set zpTXTPTR to next byte after that
         lda     #$00       ; (the "line offset" byte of next line)
         adc     zpTokenizePtr+1
         sta     zpTXTPTR+1
         rts

CheckForStopKey:
         lda     #$05
         sta     JOY1       ;write $05 to keyboard: reset row/col scanning
         pha                ;stall 21 cycles (~12 ns)
         pla
         pha
         pla
         pha
         pla
         lda     #$04
         sta     JOY1       ;write $04: prep read for column 0 of a new row
         lda     #$06
         sta     JOY1       ;welect second col, first row
         lda     JOY2       ;read key column state
         and     #$10       ;mask out all but STOP key
         rts

StopIfStopKey:
         jsr     CheckForStopKey
         beq     Stop
         rts

CmdFn_STOP:
         pla                ;pull return address off of stack -
         pla                ; we're not returning!
Stop:    lda     #NC_NoCmd
         sta     zpNMICMD   ;reset NMI sub-command (stopping music, etc)
         jsr     ReadKeyInsMacros
         bne     Stop       ;wait until no key is actively being pressed
         jsr     SetPpuCtrlAndEnableNmi
         jsr     Stop_saveContext
         lda     #$ff       ;set stopped flag
         sta     zpStoppedFlag
         cmp     zpRunLineNum ;are we executing in direct mode?
         bne     @skipClear ;no, low byte doesn't match -> skip flag clear
         cmp     zpRunLineNum+1
         bne     @skipClear ;no, high byte doesn't match -> skip flag clear
         jsr     ClearStoppedFlag ;nevermind, re-clear the stopped flag
@skipClear:
         jmp     Stop_PrintBreakBeepExit

ErrorCannotContinue:
         lda     #err_CC
         jmp     PrintErrorAndStop

Stop_saveContext:
         lda     zpRunLineNum ;save current running context for later restoration via CONT cmd
         sta     zpContRunLineNum
         lda     zpRunLineNum+1
         sta     zpContRunLineNum+1
         lda     zpRunTxtNxtLnk
         sta     zpContRunTxtNxtL
         lda     zpRunTxtNxtLnk+1
         sta     zpContRunTxtNxtL+1
         lda     zpTxtThisCmd
         sta     zpContTxtThisCmd
         lda     zpTxtThisCmd+1
         sta     zpContTxtThisCmd+1
         rts

CmdFn_CONT:
         lda     zpStoppedFlag ;have context saved from STOP?
         beq     ErrorCannotContinue ;no -> error
         lda     zpContTxtThisCmd ;yes -> restore running context from previous STOP
         sta     zpTXTPTR
         lda     zpContTxtThisCmd+1
         sta     zpTXTPTR+1
@skipLp: jsr     SkipToken
         jsr     IsEndOfCmd
         bne     @skipLp    ;skip tokens until we're at end of command (colon or EOL)
         lda     zpContRunTxtNxtL
         sta     zpRunTxtNxtLnk
         lda     zpContRunTxtNxtL+1
         sta     zpRunTxtNxtLnk+1
         lda     zpContRunLineNum
         sta     zpRunLineNum
         lda     zpContRunLineNum+1
         sta     zpRunLineNum+1
ClearStoppedFlag:
         lda     #$00
         sta     zpStoppedFlag
         rts

CmdFn_PRINT:
         beq     doCRLF_8939 ;no args? -> CRLF and return
         jsr     FrmEval    ;evaluate argument
         lda     zpArgTyp
         cmp     #$03       ;is it string?
         beq     strArg     ;yes -> handle string arg
         lda     exprParseStk
         sta     zpWAccum   ;else, copy integer value to WAccum
         lda     exprParseStk+1
         sta     zpWAccum+1
         jsr     DecStrFromWord ;convert to decimal string
         jsr     QueueOutpNumStrTmp ;queue it for output
PRINT_outputThenNextArg:
         jsr     PrintOutBuf ;tell NMI handler to output the buffer
         jmp     PRINT_afterArg ;-> and handle any more args

strArg:  lda     exprParseStk ;get string length
         beq     PRINT_afterArg ;empty string? -> already done with string then!
         ldy     #$00
         lda     exprParseStk+1 ;point zpMisc at string
         sta     zpMisc
         lda     exprParseStk+2
         sta     zpMisc+1
@strCpyLp:
         lda     (zpMisc),y ;get a char from string
         cmp     #$20       ;is it a printable character?
         bcs     @prAble
         lda     #$00       ;if not, replace with null char
@prAble: sta     lineBuffer,y ;copy the char into lineBuffer
         iny                ;move to next character
         dec     exprParseStk ;decrement string length
         bne     @strCpyLp  ;strlen != 0? -> loop around to copy next character
         lda     #$00
         sta     lineBuffer,y ;null-terminate lineBuffer
         jsr     PointOutStrAtLineBufStart
         jsr     QueueOutputStr ;queue contents of lineBuffer to be printed
         jmp     PRINT_outputThenNextArg ;-> print queued output, handle next arg

; dead/unreachable code
         jsr     TxtPtrIncr
; end unreachable
PRINT_afterArg:
         jsr     IsEndOfCmd ;no args remain?
         beq     doCRLF_8939 ;yes -> CRLF then return
         cmp     #';'       ;else, got semicolon?
         beq     @semicolon ;yes ->
         cmp     #','       ;else, got comma?
         bne     @notComma  ;no -> just print as another arg (if any)
         lda     #$09       ;(TAB)
         jsr     PrintOneChar ;print TAB
@semicolon:
         jsr     AdvThenIsEndOfCmd ;move past semicolon
         beq     rts_8938   ;out of args? just end (no CRLF on semicolon or comma)
         jmp     PRINT_afterArg ;else -> handle whatever else there is

@notComma:
         jsr     IsEndOfCmd
         bne     CmdFn_PRINT ;(always) -> handle more args
rts_8938:
         rts

doCRLF_8939:
         jmp     DoCRLF

; Copies the null-terminated string pointed at by zpOutputStr ($52)
; to genPurposeBuf ($700), queueing for output
QueueOutputStr:
         ldy     #$00
         ldx     zpOutTxtCurPos
@lp:     lda     (zpOutputStr),y
         beq     rts_8938   ;-> rts
         jsr     QueueCharForOutput
         iny
         jmp     @lp

QueueNullForOutput:
         lda     #$00
QueueCharForOutput:
         ldx     zpOutTxtCurPos
         sta     genPurposeBuf,x
         inc     zpOutTxtCurPos
         beq     @skip
         rts

@skip:   dec     zpOutTxtCurPos ;zpOutTxtCurPos <- #$FF
         rts

; Copy a string to the output buffer, set zpNMICMD to NC_FlushOutp, and wait for
; NMI handler to finish copying to the screen.
PrintString:
         jsr     QueueOutputStr
; NUL-terminate the output buffer, and wait for NMI to print it.
; On exit, Z is guaranteed to be set.
PrintOutBuf:
         jsr     QueueNullForOutput
         lda     zpOutTxtCurPos
         beq     rts1       ;-> rts
         lda     #NC_FlushOutp ; -> NMICMD_FlushQueuedOutput
         ldx     #$00
         stx     zpOutTxtStartPos ;reset output to go to start of buffer (after we've printed it) (fall through!)
; Set NMICMD and wait for NMI handler to finish processing it.
WaitForNmiSubcommand:
         sta     zpNMICMD
@lp:     lda     zpNMICMD
         bne     @lp
rts1:    rts

NMI_DefaultHandler:
         pha
         lda     #<oamBuffer
         sta     OAMADDR
         lda     #>oamBuffer ;Trigger DMA transfer of CPU page $02 to VRAM page $00
         sta     OAMDMA
         lda     zpNmiAnimNxtFr ;are we running animations this frame?
         bne     animAndTog_898E ;yes -> go animate
         lda     zpNmiAnimate ;no: Are animations active?
         beq     @ckCmd     ;no -> just handle any active NMI subcommand
         lda     #$ff       ;yes: we'll handle animations NEXT frame.
         sta     zpNmiAnimNxtFr ;set the flag, then handle NMI subcmds for this frame
@ckCmd:  lda     zpNMICMD   ;active command?
         bne     NmiHandleCmd ;yes -> go handle it
         pla
         rti

animAndTog_898E:
         jmp     AnimateAndToggleNextFrame

; Set up sub-command address, then jump to it
NmiHandleCmd:
         tax
         dex                ;NC constants are one greater than cmd index
         txa
         asl     A          ;mul by 2 for jtbl index
         tax
         lda     jtbl_NMICMD,x
         sta     zpMisc+2   ;store handler pointer
         lda     jtbl_NMICMD+1,x
         sta     zpMisc+3
         jmp     (zpMisc+2) ;and jump to it

jtbl_NMICMD:
         .word   NMICMD_FlushQueuedOutput
         .word   NMICMD_BufferCurLine
         .word   NMICMD_CopyCharsLeft
         .word   NMICMD_ClearToEndOfRow
         .word   NMICMD_GetCharUnderCursor
         .word   NMICMD_SetBgPalette
         .word   NMICMD_SetSprPalette
         .word   NMICMD_ShowCursor
         .word   NMICMD_RestoreCharAtCursor
         .word   NMICMD_PlayMusic
         .word   NMICMD_PpuMaskUpdate
         .word   NMICMD_PpuMaskClear
         .word   NMICMD_InsertChar
         .word   NMICMD_CopyRowDown_ph0
         .word   NMICMD_CopyRowDown_ph1

NMICMD_PpuMaskClear:
         lda     #$00
         .byte   $ae
NMICMD_PpuMaskUpdate:
         lda     zpPpuMaskVal
         sta     PPUMASK
NMICMD_DeactivateSubcmd:
         lda     #NC_NoCmd
         sta     zpNMICMD
         jsr     NmiSetVScrollAndEnableNmi
         pla
         rti

NMICMD_GetCharUnderCursor:
         jsr     NmiGetCharUnderCursor
         jmp     NMICMD_DeactivateSubcmd

NmiGetCharUnderCursor:
         jsr     PpuGoToCursor
         lda     PPUDATA
         lda     PPUDATA
         sta     zpCharUnderCurs
         rts

NMICMD_ShowCursor:
         jsr     NmiGetCharUnderCursor
         jsr     PpuGoToCursor
         lda     zpCursorChar
setCurs: sta     PPUDATA
         jmp     NMICMD_DeactivateSubcmd

NMICMD_RestoreCharAtCursor:
         jsr     PpuGoToCursor
         lda     zpCharUnderCurs
         jmp     setCurs

; Erases from cursor to end of current row
NMICMD_ClearToEndOfRow:
         jsr     PpuGoToCursor
         ldx     zpCH       ;set X reg to current cursor x pos
         lda     #key_Space
@blankLp:
         sta     PPUDATA    ;write a space to location in VRAM
         inx                ;next char position
         cpx     #COLS      ;did we reach the end of the line?
         bne     @blankLp   ;no -> loop until we do
         jmp     NmiEndCmdCleanupAndExit ;-> finish up

NMICMD_FlushQueuedOutput:
         jsr     CalcCursorTilemapPos
         ldx     zpOutTxtStartPos
         jsr     PpuGoToCursor
@outLp:  lda     genPurposeBuf,x ;grab a char from out buf
         beq     QueueOutpDeactivate ;NUL -> buf is done
         sta     PPUDATA    ;not NUL; copy char to screen 
         inc     zpCH       ;advance the cursor
         lda     #COLS
         cmp     zpCH       ;have we reached the row end?
         beq     @wrap      ;yes -> handle wraparound to next row
         lda     #$0e
         cmp     zpCH       ;are we at 15th column?
         beq     @susp      ;yes -> print rest next NMI
         inx
         bne     @outLp     ;(always) loop back to output next char
; Done printing for this frame.
; Save our progress, and continue next NMI
@susp:   inx
         stx     zpOutTxtStartPos
         jmp     NmiSameCmdCleanupAndExit

; We've reached the end of the screen line: wrap around to next column
@wrap:   lda     #$00
         sta     zpCH
         txa
         pha
         ldx     zpCV
         lda     #$ff
         jsr     MarkWrappedRow
         pla
         tax
         inc     zpCV
         lda     #ROWS
         cmp     zpCV
         beq     @scroll
         inx
         stx     zpOutTxtStartPos
         jmp     NmiSameCmdCleanupAndExit

; Output cursor has gone to a row below the displayed screen, so
; scroll the screen.
@scroll: inx
         stx     zpOutTxtStartPos
         jsr     CursorHome
         jsr     NmiSetVScrollAndEnableNmi
         lda     zpPpuCtrlVal
         sta     PPUCTRL
         jsr     CalcCursorTilemapPos
         jsr     WaitForVBlank
         jsr     PpuGoToCursor
         ldx     #COLS
         lda     #$20       ;SPACE character
@lp:     sta     PPUDATA
         dex
         bne     @lp
         stx     zpNMICMD   ;deactivate command (#NC_NoCmd)
         jsr     NmiSetVScrollAndEnableNmi
         jsr     ScrollScreenOneRowNoErase
         lda     #NC_FlushOutp
         sta     zpNMICMD
         pla                ;pull accum (pushed by NMI_DefaultHandler)
         rti

; Indicate end of screen outputting, reset output buffer, cleanup, and exit.
QueueOutpDeactivate:
         sta     zpNMICMD
         sta     zpOutTxtCurPos
         sta     zpOutTxtStartPos
         beq     NmiSameCmdCleanupAndExit

; Copies the current row, through to the end of the line, into lineBuffer.
; (Copies multiple rows if the line is wrapped.)
; This command is invoked when handling CR on input, to get a copy of the line
; for input processing.
NMICMD_BufferCurLine:
         lda     #$00
         sta     zpCH       ;move to start of current row
         jsr     CalcCursorTilemapPos ;calculate VRAM addr for cursor
         jsr     PpuGoToCursor ;tell PPU to start reading from there
         ldy     #COLS      ;set Y to # of chars in a row
         lda     PPUDATA    ;fake read from PPU (prime the pump!)
         ldx     zpLineBufIdx ;get current index into line buffer
@bufCpyLp:
         lda     PPUDATA    ;read a byte from the screen
         sta     lineBuffer,x ;store in the lineBuffer
         inx                ;incr lineBuffer idx
         cpx     #$ff       ;line buffer full?
         beq     @done      ;yes -> finished buffering
         dey                ;one less char to copy from row
         bne     @bufCpyLp  ;more to copy? -> loop back for next char
         stx     zpLineBufIdx ;update lineBuffer's index past where we copied to
         ldx     zpCV
         jsr     DoesRowWrap ;does the current row line-wrap to the next?
         beq     @done      ;line doesn't wrap -> done; terminate active NMICMD
         inc     zpCV       ;line wraps: copy next row on next NMI
         bne     NmiSameCmdCleanupAndExit ;(always) -> finish up until then
@done:   lda     #$ff
         ldx     a:$00a9    ;(NOOP: disabled LDA #$00, but nothing jumps to it.)
         sta     zpOutTxtStartPos
NmiEndCmdCleanupAndExit:
         lda     #NC_NoCmd
NmiSetCmdCleanupAndExit:
         sta     zpNMICMD   ;turn our command indicator off
; Many NMICMD handlers jump to here when done with the current frame
NmiSameCmdCleanupAndExit:
         jsr     NmiSetVScrollAndEnableNmi
         pla                ;pull pushed A-reg value
         rti                ;-> and return from interrupt

; Shifts the contents of a row on screen, left.
; 
; Parameters:
;   zpCursTileAddr ($4a) {addr/2}: start of copy region (end is end of the row)
;   zpMisc         ($19) {addr/2}: destination to copy to
; 
; Only ever used by Backspace, to shift line contents past the cursor over to
; the left by one column. Thus zpMisc will hold the address of the current
; cursor position, and zpCursTileAddr will hold the address of one past that.
NMICMD_CopyCharsLeft:
         jsr     PpuGoToCursor ;go to (one past) current location in VRAM
         lda     PPUDATA    ;initial, fake read
         ldx     #$00
         ldy     zpCH
@cpyLp:  lda     PPUDATA    ;copy from cursor to end of row, to lineBuffer
         sta     lineBuffer,x
         inx
         iny
         cpy     #COLS
         bne     @cpyLp
         lda     zpMisc+1   ;go to (true) current position
         ldx     zpMisc
         jsr     PpuGoToAX
         ldx     #$00
         ldy     zpCH
@cpyBackLp:
         lda     lineBuffer,x ;copy the lineBuffer back out to PPUDATA.
         sta     PPUDATA
         inx
         iny
         cpy     #COLS
         bne     @cpyBackLp
         beq     NmiEndCmdCleanupAndExit ;done!

; Sets background palette number at genPurposeBuf ($200),
; to values at $201-$204.
NMICMD_SetBgPalette:
         lda     #>PPU_PALETTE_RAM
         sta     PPUADDR
         lda     genPurposeBuf ;set addr to PPU palette RAM + ((palette num from genPurposeBuf) * 4)
         asl     A
         asl     A
NmiWritePalette:
         sta     PPUADDR
         lda     genPurposeBuf+1 ;write the palette color values
         sta     PPUDATA
         lda     genPurposeBuf+2
         sta     PPUDATA
         lda     genPurposeBuf+3
         sta     PPUDATA
         lda     genPurposeBuf+4
         sta     PPUDATA
         lda     #>PPU_PALETTE_RAM ;set addr to PPU palette RAM start
         sta     PPUADDR
         lda     #<PPU_PALETTE_RAM
         sta     PPUADDR
         sta     PPUADDR    ;then to #$0000?
         sta     PPUADDR
         jsr     NmiSetVScrollAndEnableNmi
         jsr     SetPpuCtrlAndEnableNmi
         jmp     NMICMD_DeactivateSubcmd

; Sets sprite palette number at genPurposeBuf ($200),
; to values at $201-$204.
NMICMD_SetSprPalette:
         lda     #>PPU_PALETTE_RAM
         sta     PPUADDR    ;set addr to PPU palette RAM + 16 (for sprite palettes) + ((palette num from genPurposeBuf) * 4)
         lda     genPurposeBuf
         asl     A
         asl     A
         ora     #$10
         bne     NmiWritePalette

; Inserts designated character into the current row, shifting all chars past the
; cursor, to the right by one. The char that was previously at the end of the
; row but shifted off, is saved for subsequent calls.
vZpInsChar .set  $b0        ;the character to insert
NMICMD_InsertChar:
         jsr     PpuGoToCursor ;go to cursor
         ldy     zpCH
         ldx     #$01
         lda     vZpInsChar ;put char-to-be-inserted at start of lineBuffer
         sta     lineBuffer ; (set by caller)
         lda     PPUDATA    ;initial fake read
@cpyLp:  lda     PPUDATA    ;copy char to lineBuffer
         sta     lineBuffer,x
         inx
         iny
         cpy     #COLS      ;loop until we reach end of row
         bne     @cpyLp
         sta     vZpInsChar ;last char will be re-inserted in following line (in subsequent call)
         jsr     PpuGoToCursor ;return to cursor
         ldx     #$00
         ldy     zpCH
@insCpyLp:
         lda     lineBuffer,x ;copy chars back out to screen,
         sta     PPUDATA    ; with inserted char at start
         inx                ; (everything else shifts right)
         iny
         cpy     #COLS
         bne     @insCpyLp  ;loop until we reach end of row
NmiSetVScrollAndDeactivate:
         jsr     NmiSetVScrollAndEnableNmi
         jmp     NMICMD_DeactivateSubcmd ;done!

NMICMD_CopyRowDown_ph0:
         jsr     PpuGoToCursor ;go to cursor position in VRAM
         ldx     #$00       ;(I think CH must be 0?)
         lda     PPUDATA    ;fake read
@cpyLp:  lda     PPUDATA    ;get char from screen
         sta     lineBuffer,x ;copy to line buffer
         inx
         cpx     #COLS      ;loop until we reach the same position on next row
         bne     @cpyLp
         lda     #$0f       ;next phase: copy back out to next row, on next frame
         jmp     NmiSetCmdCleanupAndExit

NMICMD_CopyRowDown_ph1:
         inc     zpCV       ;move cursor down one row
         jsr     CalcCursorTilemapPos ;calculate addr for new position
         jsr     PpuGoToCursor ;and go there
         ldx     #$00
@cpyLp:  lda     lineBuffer,x ;copy from line buffer to screen
         sta     PPUDATA
         inx
         cpx     #COLS
         bne     @cpyLp     ;copy 28 chars out (a row's worth)
         jmp     NmiSetVScrollAndDeactivate ;done!

; Point zpTxtPtr at lineBuffer ($500)
InitLineBufferScanning:
         lda     #<lineBuffer
         sta     zpTXTPTR
         lda     #>lineBuffer
         sta     zpTXTPTR+1
         rts

PointOutStrAtLineBufStart:
         lda     #<lineBuffer
         sta     zpOutputStr
         lda     #>lineBuffer
         sta     zpOutputStr+1
rts_8BB5:
         rts

CheckFreeSpaceOrError:
         lda     zpFRETOP
         sec
         sbc     #$04       ;subtract 4 from end of free space
         sta     zpWParam
         lda     zpFRETOP+1
         sbc     #$00
         sta     zpWParam+1
         jsr     WordCompare ;and compare what's in WAccum to that
         bcc     rts_8BB5   ;less than zpFRETOP - 4? -> we're fine. Return.
ErrorOutOfMemory:
         lda     #err_OM    ;ERROR: insufficient memory!
         jmp     PrintErrorAndStop

; Check that we have enough stack space (20 bytes) to execute a line of BASIC.
; Error if we do not.
ExecCheckMem:
         tsx
         cpx     #$14
         bcc     ErrorOutOfMemory
rts_8BD2:
         rts

AUTO_errSyn:
         lda     #$00
         sta     zpAutoEnabled
         jmp     ErrorSyntax

CmdFn_AUTO:
         php                ;push processor flags
         pha                ;push accum
         lda     #10
         sta     zpAutoEnabled ;enable auto-increment
         sta     zpNxtAutoLNum ;set next linenum to auto-prefix as 10, by default
         sta     zpAutoLNumIncr ;increment by 10 by default
         lda     #$00
         sta     zpNxtAutoLNum+1 ;set high bytes line num, increment
         sta     zpAutoLNumIncr+1
         pla                ;pull original accum
         plp                ;pull proc flags (from arg test)
         beq     rts_8BD2   ;no args? Done! (defaults above were enough)
         cmp     #','       ;is next char a comma?
         beq     @argTwo    ;yes -> skip first arg, handle next
         cmp     #$0b       ;got line-number arg indicator byte?
         bne     AUTO_errSyn ;no -> error out
         jsr     TxtPtrIncr ;move past line-number prefix token
         jsr     TxtPtrGetCharAndIncr ;get first byte of line num
         sta     zpNxtAutoLNum ;set it as first line num to prefix
         jsr     TxtPtrGetCharAndIncr ;get 2nd byte
         sta     zpNxtAutoLNum+1 ;set as high byte for next line num
         jsr     IsEndOfCmd ;any more args?
         beq     rts_8BD2   ;no -> done!
@argTwo: jsr     SkipCommaOrSynErr ;yes: skip expected comma
         jsr     TxtSkipSpaces ;and any spaces
         cmp     #$0b       ;got line-number arg indicator byte?
         bne     AUTO_errSyn ;no -> error out
         jsr     TxtPtrIncr ;copy "line number" as auto-increment amount
         jsr     TxtPtrGetCharAndIncr
         sta     zpAutoLNumIncr
         jsr     TxtPtrGetCharAndIncr
         sta     zpAutoLNumIncr+1
         rts                ;done!

RENUM_SetCharAndIncr:
         ldy     #$00
         sta     (zpTXTPTR),y
         jmp     TxtPtrIncr

errSyn_8C27:
         jmp     ErrorSyntax

restoreTxtPtr_8C2A:
         jmp     RestoreTXTPTR

errIllVal_8C2D:
         jmp     ErrorIllegalValue

vZpNewStartLNum .set $7c    ;new starting line number
vZpOldStartLNum .set $7e    ;old starting line number
vZpRenumIncrAmt .set $80    ;amount to increment each new line number by.
vZpRenumNextLNum .set $84   ;next line number to write
CmdFn_RENUM:
         php                ;push processor flags
         pha                ;push accum (char at TXTPTR)
         lda     #10
         sta     vZpNewStartLNum
         sta     vZpRenumIncrAmt
         lda     #$00
         sta     vZpNewStartLNum+1
         sta     vZpOldStartLNum
         sta     vZpOldStartLNum+1
         sta     vZpRenumIncrAmt+1
         pla                ;pull accum
         plp                ;pull flags
         beq     RENUM_checkNewGeOld ;no args? -> stick to the defaults
         cmp     #','       ;got comma?
         beq     @arg2      ;yes -> skip 1st arg, check 2nd
         cmp     #tok_LNUM_AFTER ;got line-num prefix token?
         bne     errSyn_8C27 ;no? -> error
         jsr     TxtPtrIncr ;yes. Skip the prefix token.
         jsr     TxtPtrGetCharAndIncr ;get new-start line num low byte
         sta     vZpNewStartLNum ;and store
         jsr     TxtPtrGetCharAndIncr ;low byte
         sta     vZpNewStartLNum+1
         jsr     IsEndOfCmd ;more args?
         beq     RENUM_checkNewGeOld ;no -> everything else uses defaults
@arg2:   jsr     SkipCommaOrSynErr ;skip comma
         jsr     TxtSkipSpaces ;and spaces
         cmp     #','       ;another comma?
         beq     @arg3      ;yes -> skip 2nd arg
         cmp     #tok_LNUM_AFTER ;else, line-num prefix token?
         bne     errSyn_8C27 ;no -> error
         jsr     TxtPtrIncr ;move past token
         jsr     TxtPtrGetCharAndIncr ;get byte
         sta     vZpOldStartLNum ;set low byte of starting (old) line number
         jsr     TxtPtrGetCharAndIncr ;'nother byte
         sta     vZpOldStartLNum+1 ;set high byte of starting (old) line number
         jsr     IsEndOfCmd ;end of command?
         beq     RENUM_checkNewGeOld ;yes -> leave increment amt at default of 10
@arg3:   jsr     SkipCommaOrSynErr ;skip expected comma
         jsr     TxtSkipSpaces ;and spaces
         cmp     #tok_LNUM_AFTER ;got line-num prefix token?
         bne     errSyn_8C27 ;no -> error
         jsr     TxtPtrIncr ;move past token byte
         jsr     TxtPtrGetCharAndIncr ;get byte
         sta     vZpRenumIncrAmt ;set as low byte of increment amt
         jsr     TxtPtrGetCharAndIncr ;'nother byte
         sta     vZpRenumIncrAmt+1 ;set as high byte of increment amt
         bne     RENUM_checkNewGeOld ;high byte nonzero? Yes -> continue
         lda     vZpRenumIncrAmt ;high byte zero. Low byte zero?
         beq     errIllVal_8C2D ;yes -> error. Can't have a zero increment!
RENUM_checkNewGeOld:
         lda     vZpNewStartLNum+1
         cmp     vZpOldStartLNum+1
         beq     @cmpLo     ;is new start lnum (hi byte) > old start lnum (hi byte)?
         bcs     RENUM_argsDone ;yes -> everything's great
@cmpLo:  lda     vZpNewStartLNum ;else, is new start lnum (lo byte) >= old start lnum (lo byte)?
         cmp     vZpOldStartLNum ;BUG! Permits high byte lower, as long as low byte is highger!
         bcs     RENUM_argsDone ; This can result in repeated line numbers, and/or lower coming after higher
         jmp     ErrorIllegalValue

restoreTxtPtr_8CAE:
         jmp     restoreTxtPtr_8C2A

RENUM_argsDone:
         jsr     SaveTXTPTR ;save away curent TXTPTR
         jsr     ErrorIfNewLNumsOverflow ;go check whether new line numbers
         lda     zpTXTTAB   ; will overflow, and error if so
         sta     zpTXTPTR
         lda     zpTXTTAB+1 ;point TXTPTR at first line of BASIC
         sta     zpTXTPTR+1
         jsr     GetTxtChar ;get offset to 2nd line in program
         beq     restoreTxtPtr_8CAE ;BASIC program empty? -> nothing to do; return
         jsr     TxtPtrAdvThree ;skip over offset and line num
@RENUM_scanCodeForLNums:
         jsr     GetTxtChar ;get a byte of line content
         beq     @advLine   ;end of line? -> advance to next
         cmp     #tok_LNUM_AFTER ;got a line num prefix token?
         beq     @lnumTokFound
         jsr     SkipToken  ;else skip this byte
         jmp     @RENUM_scanCodeForLNums ; and check next

@advLine:
         jsr     TxtPtrIncrAndGetChar ;are we at prog end?
         beq     RENUM_doRenum ;yes -> done scanning for line numbers in content
         jsr     TxtPtrAdvThree
         jmp     @RENUM_scanCodeForLNums

@lnumTokFound:
         lda     zpTXTPTR   ;push TXTPTR lo, hi
         pha
         lda     zpTXTPTR+1
         pha
         jsr     TxtPtrIncr ;skip line-num prefix token byte
         jsr     TxtPtrGetCharAndIncr ;save following line num as line-to-find
         sta     zpFindLNum
         jsr     TxtPtrGetCharAndIncr
         sta     zpFindLNum+1
         jsr     FindLineNum ;find the indicated line num
         beq     @match     ;exact match? -> leave zpTxtLink as FindLineNum set it
         lda     #$ff       ;else (not found): invalidate zpTxtLink
         sta     zpTxtLink
         sta     zpTxtLink+1
@match:  pla                ;restore TXTPTR from stack
         sta     zpTXTPTR+1
         pla
         sta     zpTXTPTR
         lda     #tok_LLINK_AFTER ;save over line-number token with line-link token,
         jsr     RENUM_SetCharAndIncr ; so we can scan over them again
         lda     zpTxtLink  ; and replace with updated line number
         jsr     RENUM_SetCharAndIncr
         lda     zpTxtLink+1
         jsr     RENUM_SetCharAndIncr
         jmp     @RENUM_scanCodeForLNums ;return to scanning for more line numbers

RENUM_doRenum:
         lda     vZpOldStartLNum ;set the (original) first line of renumber range
         sta     zpFindLNum ; as the line to search for
         lda     vZpOldStartLNum+1
         sta     zpFindLNum+1
         jsr     FindLineNum ;and find it
         lda     zpTxtLink
         sta     zpTXTPTR   ;point TXTPTR at the start of the found line
         lda     zpTxtLink+1
         sta     zpTXTPTR+1
RENUM_renumLoop:
         jsr     GetTxtChar ;read the line's offset byte
         beq     RENUM_replaceLineLinks ;end of prog? -> replace line links with updated line numbers
         pha                ;push offset to next line
         jsr     TxtPtrIncr
         lda     vZpNewStartLNum ;write renumbered line number over old one
         jsr     RENUM_SetCharAndIncr
         lda     vZpNewStartLNum+1
         jsr     RENUM_SetCharAndIncr
         pla                ;pull offset to next line
         sec
         sbc     #$03       ;subtract 3 (bc we just advanced by 3)
         clc
         adc     zpTXTPTR   ;advance TXTPTR to start of next line
         sta     zpTXTPTR
         lda     #$00
         adc     zpTXTPTR+1
         sta     zpTXTPTR+1
         clc
         lda     vZpRenumIncrAmt ;advance next line number by increment
         adc     vZpNewStartLNum
         sta     vZpNewStartLNum
         lda     vZpRenumIncrAmt+1
         adc     vZpNewStartLNum+1
         sta     vZpNewStartLNum+1
         jmp     RENUM_renumLoop ;loop around to renumber this next line

RENUM_replaceLineLinks:
         lda     zpTXTTAB   ;point TXTPTR at start of BASIC program once again
         sta     zpTXTPTR
         lda     zpTXTTAB+1
         sta     zpTXTPTR+1
         jsr     TxtPtrAdvThree ;skip offset, line number
RENUM_linkReplLoop:
         jsr     GetTxtChar ;get a byte from line content
         beq     advLine    ;end of line? -> scan next line
         cmp     #tok_LLINK_AFTER ;got a line-link prefix byte (that we wrote earlier)?
         beq     linkFound  ;yes -> replace with updated line num
         jsr     SkipToken  ;else, skip this byte
         jmp     RENUM_linkReplLoop ;and check the next

restoreTxtPtr_8D76:
         jmp     RestoreTXTPTR

advLine: jsr     TxtPtrIncrAndGetChar ;are we at prog end?
         beq     restoreTxtPtr_8D76 ;yes -> restore TXTPTR, then all done
         jsr     TxtPtrAdvThree ;skip offset and line-num bytes
         jmp     RENUM_linkReplLoop ;and return to scanning for line links to replace

linkFound:
         ldy     #$00
         lda     #tok_LNUM_AFTER
         sta     (zpTXTPTR),y ;replace line-link token byte with line-num token
         iny
         lda     (zpTXTPTR),y
         sta     zpTxtLink  ;read the line link into zpTxtLink
         iny
         lda     (zpTXTPTR),y
         sta     zpTxtLink+1
         cmp     #$ff
         bne     @writeNewLNum
         lda     zpTxtLink
         cmp     #$ff       ;invalid link (orig line num invalid)?
         bne     @writeNewLNum ;no -> safe to use real line num
@skipLNumAndIterate:
         jsr     TxtPtrAdvThree ;skip over line link
         jmp     RENUM_linkReplLoop ;and iterate to find/replace more

@writeNewLNum:
         dey                ;back up a byte
         lda     (zpTxtLink),y ;overwrite line link with its new number
         sta     (zpTXTPTR),y
         iny
         lda     (zpTxtLink),y
         sta     (zpTXTPTR),y
         jmp     @skipLNumAndIterate ;-> go back to finding/replacing line links

ErrorIfNewLNumsOverflow:
         lda     vZpNewStartLNum ;save new first line number, to "next" line number
         sta     vZpRenumNextLNum
         lda     vZpNewStartLNum+1
         sta     vZpRenumNextLNum+1
         lda     vZpOldStartLNum ;save old first line num of range, as line to find
         sta     zpFindLNum
         lda     vZpOldStartLNum+1
         sta     zpFindLNum+1
         jsr     FindLineNum ;find it!
         lda     zpTxtLink  ;point TXTPTR at first byte of found line (the offset to next)
         sta     zpTXTPTR
         lda     zpTxtLink+1
         sta     zpTXTPTR+1
@lnumLp: jsr     GetTxtChar ;get the offset byte. At prog end?
         beq     rts_8DEE   ;yes -> return
         clc
         adc     zpTXTPTR   ;advance TXTPTR to start of following line
         sta     zpTXTPTR
         lda     #$00
         adc     zpTXTPTR+1
         sta     zpTXTPTR+1
         clc
         lda     vZpRenumIncrAmt ;advance "next line num" by increment amount
         adc     vZpRenumNextLNum
         sta     vZpRenumNextLNum
         lda     vZpRenumIncrAmt+1
         adc     vZpRenumNextLNum+1
         sta     vZpRenumNextLNum+1 ;did we overflow a new line number?
         bcs     errIllVal_8DEF ;yes -> error
         jmp     @lnumLp    ;else, loop back and check another line-num increment

rts_8DEE:
         rts

errIllVal_8DEF:
         jmp     ErrorIllegalValue

; Sets Z flag iff zpWAccum contains (+/-)32768 (#$8000)
; Sets C if and only if zpWAccum is negative
Cmp32768:
         lda     zpWAccum+1
         cmp     #$80
         beq     @ckLo
         rts

@ckLo:   lda     zpWAccum
         sec
         rts

WParamNegate:
         sec
         lda     #$00
         sbc     zpWParam
         sta     zpWParam
         lda     #$00
         sbc     zpWParam+1
         sta     zpWParam+1
         rts

SetIntAndSubtract:
         lda     #$02
         sta     zpArgTyp
; This routine, together with the Add routine it wraps, is the most ridiculously
; overcoded and overcomplicated "subtract two words" implementation I have ever
; laid eyes on. Could save a ton of code space by just using WordSubtract and
; checking for overflow afterward. Always negates the first operand (except when
; it's -32,768 and therefore can't be) before passing to the Add sub, and
; therefore always negates the result as well. Add, itself, may well negate the
; first operand and the result, meaning that both WAccum and the result from adc
; or sbc may undergo multiple negations (and even if they only undergo it once,
; it's unnecessary and ineffecient).
Subtract:
         jsr     ErrorUnlessInteger
         jsr     Cmp32768
         beq     Sub_WAccumIs32768 ;zpWAccum = -32768? -> ensure zpWParam is 0
         jsr     WAccumNegate
         lda     zpWAccum+1
         bmi     @haveNegArg
         lda     zpWParam+1
         bmi     @haveNegArg
         jsr     WordAdd
         jsr     Cmp32768
         beq     rts_8E3F
         bcc     WAccumNegate
         jmp     ErrorOverflow

@haveNegArg:
         jsr     Add
WAccumNegate:
         sec
         lda     #$00
         sbc     zpWAccum
         sta     zpWAccum
         lda     #$00
         sbc     zpWAccum+1
         sta     zpWAccum+1
rts_8E3F:
         rts

Sub_WAccumIs32768:
         lda     zpWParam+1
         bpl     errOverfl  ;BUG: produces OV ERROR even if WParam is zero lol
         jsr     WParamNegate
         jmp     Add

errOverfl:
         jmp     ErrorOverflow

CopyWParamToWAccum:
         lda     zpWParam
         sta     zpWAccum
         lda     zpWParam+1
         sta     zpWAccum+1
         lda     zpWParam+2
         sta     zpWAccum+2
rts_8E59:
         rts

ConcatenateStrings:
         ldx     zpGpStrIdx
         stx     zpCursTileAddr
         lda     zpWAccum   ;strlen == 0?
         beq     CopyWParamToWAccum ;yes -> just use other operand then
         clc
         ldy     zpWParam   ;param len == 0?
         beq     rts_8E59   ;yes -> nothing to do, return
         adc     zpWParam   ;add the two strlens
         cmp     #$20       ; >= 32?
         bcs     errOverfl  ;yes -> too big to fit in a string var
         sta     zpCursTileAddr+1
         lda     zpWAccum+1 ;copy strptr to $19.1A
         sta     zpMisc
         lda     zpWAccum+2
         sta     zpMisc+1
         ldy     #$00
@cpyWaccumOutb:
         lda     (zpMisc),y ;copy zpWAccum str to outbuf
         sta     genPurposeBuf,x
         inx
         iny
         dec     zpWAccum
         bne     @cpyWaccumOutb
         lda     zpWParam+1 ;copy PARAM str to outbuf (after ACC)
         sta     zpMisc
         lda     zpWParam+2
         sta     zpMisc+1
         ldy     #$00
@cpyParamOutb:
         lda     (zpMisc),y
         sta     genPurposeBuf,x
         iny
         inx
         dec     zpWParam
         bne     @cpyParamOutb
         stx     zpGpStrIdx
         lda     zpCursTileAddr+1
         sta     zpWAccum
         lda     zpCursTileAddr
         sta     zpWAccum+1
         lda     #$07
         sta     zpWAccum+2
         rts

SetIntAndAdd:
         lda     #TYP_INT
         sta     zpArgTyp
; This routine is the most ridiculously overcoded and overcomplicated "add two
; words" implementation I have ever laid eyes on. Could save a ton of code space
; by just using WordAdd and checking for overflow afterward. It branches on
; positivity for each argument, maneuvering with negation to ensure it performs
; an operation on two positive operands. John Brooks (jbrooks@blueshiftinc.com)
; points out that this is a common strategy for multiplication and division, but
; quite useless for addition/subtraction. Such a waste!
Add:     lda     zpArgTyp
         cmp     #TYP_STR   ;are we working with strs?
         beq     ConcatenateStrings ;yes -> concatenate them
         lda     zpWAccum+1 ;no: we are working with integer words
         bmi     AddInt_WAccumIsNeg ;WAccum neg -> handle that case
         lda     zpWParam+1 ;WParam neg?
         bmi     ParamNegateThenSubtract ;yes -> handle
         jsr     WordAdd    ;both args positive, just add
         bmi     ErrorOverflow ;and error if the result is neg
         rts

ParamNegateThenSubtract:
         jsr     WParamNegate
WordSubtract:
         sec
         lda     zpWAccum
         sbc     zpWParam
         sta     zpWAccum
         lda     zpWAccum+1
         sbc     zpWParam+1
         sta     zpWAccum+1
         rts

AddInt_WAccumIsNeg:
         lda     zpWParam+1
         bmi     AddInt_BothNeg
         jsr     WAccumNegate
         jsr     WordSubtract
         jmp     WAccumNegate

AddInt_BothNeg:
         jsr     WAccumNegate
         jsr     WParamNegate
         jsr     WordAdd
         jsr     Cmp32768
         beq     @rts
         bcs     ErrorOverflow
         jmp     WAccumNegate

@rts:    rts

ErrorOverflow:
         lda     #err_OV
         jmp     PrintErrorAndStop

; Adds $2C.2D to $28.29, leaves in $28.29.
WordAdd: clc
         lda     zpWParam
         adc     zpWAccum
         sta     zpWAccum
         lda     zpWParam+1
         adc     zpWAccum+1
         sta     zpWAccum+1
         rts

; Clears the scratch space used by WordMultiply. The first byte ($34) is never
; actually cleared (not necessary), and the last four ($38 thru $3B) are never
; actually used by anything.
ClearMultiplyScratch:
         lda     #$00
         ldx     #$08
@clearLp:
         sta     zpMulScratch,x
         dex
         bne     @clearLp   ;-> write eight "zero" bytes
         rts                ;-> done

MultiplyAndCheckPosNeg:
         lda     zpWAccum+1 ;is WAccum negative?
         bmi     @wAccNeg   ;yes -> check WPararm
         lda     zpWParam+1 ;else is WAccum negative?
         bmi     @mulExpectNeg ;yes -> expect negative result
@mulExpectPos:
         jsr     WordMultiplyAsWord
         jsr     IsWAccumZero ;WAccum == 0?
         beq     rts_8F43   ;yes? -> done
         lda     zpWAccum+1 ;is result negative?
         bmi     ErrorOverflow ;yes -> overflow error
         rts

@wAccNeg:
         lda     zpWParam+1 ;WAccum is neg. Is Wparam also negative?
         bmi     @mulExpectPos ;yes -> expect pos result
@mulExpectNeg:
         jsr     WordMultiplyAsWord
         jsr     IsWAccumZero ;WAccum == 0?
         beq     rts_8F43   ;yes -> done
         lda     zpWAccum+1 ;is result positive?
         bpl     ErrorOverflow ;yes -> overflow error
         rts

; Multiply, and cause an overflow error (OV) if it doesn't fit in a word.
; Multiplies the contents of $28.29 by $2C.2D, leaving the results in $28.29.
; 
; BUG: won't cause overflow if (result MOD (2 ** 24)) fits in a word. for
; example, multiplying 4095 * 4095 produces overflow, but multiplying 4097
; * 4097 does NOT. This is because it checks for overflow in $36, but not
; in $37.
WordMultiplyAsWord:
         jsr     WordMultiplyWithTypeCheck
         lda     zpMulScratch+2
         bne     ErrorOverflow
         rts

IsWAccumZero:
         lda     zpWAccum
         bne     rts_8F43
         lda     zpWAccum+1
rts_8F43:
         rts

; Multiplies the contents of $28.29 by $2C.2D leaving the results in $28.29.
WordMultiplyWithTypeCheck:
         jsr     ErrorUnlessInteger
WordMultiply:
         jsr     ClearMultiplyScratch ;clear scratch-space values
         jsr     EnsureWAccParmPositive ;make sure WAccum, WParam hold positive values
         pha                ;push whether we need to negate after bc of sign changes
         ldx     #$10       ;set X reg to sixteen (bits)
         clc
@multLoop:
         ror     zpWAccum+1 ;shift WAccum right by one
         ror     zpWAccum   ;was the bit set?
         bcc     @zeroBit   ;no -> skip adding param
         clc                ;yes, bit was set: must add param here
         lda     zpMulScratch+2
         adc     zpWParam
         sta     zpMulScratch+2 ;add WParam to 2 bytes (16 bits) left of result space
         lda     zpMulScratch+3
         adc     zpWParam+1
         sta     zpMulScratch+3 ;add the carry to a byte left of that
@zeroBit:
         ror     zpMulScratch+3 ;now shift all result bits right one (this will happen 16 times in all)
         ror     zpMulScratch+2
         ror     zpMulScratch+1
         ror     zpMulScratch
         dex                ;one shift done. More remain?
         bne     @multLoop  ;-> loop for a total of 16 shifts
         lda     zpMulScratch ;result is in zpMulScratch+0,+1
         sta     zpWAccum   ;copy to WParam as the result
         lda     zpMulScratch+1
         sta     zpWAccum+1
WMul_PullAndObeyNegFlag:
         pla                ;pull negation flag. Do we need to negate?
         beq     rts_8F9C   ;no -> we're done
         jmp     WAccumNegate ;yes: negate accum and return

vZpNegateResult .set $34
EnsureWAccParmPositive:
         lda     #$00
         sta     vZpNegateResult ;start with assumption we won't negate the result
         lda     zpWAccum+1 ;is WAccum negative?
         bpl     @wpPos     ;no -> move on to WParam
         jsr     WAccumNegate ;yes: make it positive
         lda     #$ff
         sta     vZpNegateResult ;mark that we should negate the result
@wpPos:  lda     zpWParam+1 ;is WParam negative?
         bpl     @ldaAndRts ;no -> we're done!
         jsr     WParamNegate ;yes: negate WParam
         lda     #$ff
         sec
         sbc     vZpNegateResult ;toggle result negation/reversesetting
         sta     vZpNegateResult
@ldaAndRts:
         lda     vZpNegateResult ;this var will be destroyed after; load into accum so caller can push to stack
rts_8F9C:
         rts

; Divide WAccum by WParam. Waccum+2,3 will hold remainder/modulus
WordDivide:
         jsr     ErrorUnlessInteger
         jsr     EnsureWAccParmPositive
         pha                ;push on stack, whether we should negate result after
         lda     #$00
         sta     zpWAccum+2
         sta     zpWAccum+3
         ldx     #16        ;loop over 16 bits
@divLoop:
         asl     zpWAccum
         rol     zpWAccum+1
         rol     zpWAccum+2
         rol     zpWAccum+3
         lda     zpWAccum+2
         sec                ;LONG DIVISION in binary!
         sbc     zpWParam   ;perform a throwaway subtraction of WParam
         lda     zpWAccum+3 ; from the shortest initial portion of WAccum
         sbc     zpWParam+1 ; that we can subtract from
         bcc     @noSbc     ;carry clear (borrow set)? -> can't subtract, try a longer portion
         lda     zpWAccum+2 ;no borrow: perform subtract for real!
         sec
         sbc     zpWParam
         sta     zpWAccum+2
         lda     zpWAccum+3
         sbc     zpWParam+1
         sta     zpWAccum+3
         inc     zpWAccum
@noSbc:  dex
         bne     @divLoop
         jmp     WMul_PullAndObeyNegFlag

; Exactly the same as WordSubtract. Useless duplicate routine.
WordSubtractClone:
         sec
         lda     zpWAccum
         sbc     zpWParam
         sta     zpWAccum
         lda     zpWAccum+1
         sbc     zpWParam+1
         sta     zpWAccum+1
         rts

; Compare WAccum to WParam
WordCompare:
         lda     zpWAccum+1
         cmp     zpWParam+1
         beq     @cmpLow
         rts

@cmpLow: lda     zpWAccum
         cmp     zpWParam
         rts

; Compare two operands, in WAccum and WParam. We'll refer to contents of WAccum
; as "A", and WParam as "B".
vZpStrLenA .set  $4a
vZpStrLenB .set  $4b
Compare: lda     zpArgTyp
         cmp     #TYP_STR   ;args string type?
         beq     CompareStrings ;yes -> compare strings
         lda     zpWAccum+1 ;is A negative?
         bmi     Cmp_AIsNegative ;yes -> check B
         lda     zpWParam+1 ;is B negative?
         bmi     Cmp_AGreaterThanB ;yes -> A isn't, so A > B
         lda     zpWAccum+1 ;no: both are pos
         cmp     zpWParam+1 ;cmp A, B high bytes
         beq     Cmp_LoBytes1
         bcs     Cmp_AGreaterThanB
Cmp_ALessThanB:
         clc                ;clear carry for "less than"
         lda     #$ff       ;indicate unequal
         rts

Cmp_AGreaterThanB:
         sec                ;set carry for "greater than or equal"
         lda     #$ff       ;indicate unequal
         rts

Cmp_LoBytes1:
         lda     zpWAccum   ;this routine exactly identical to Cmp_LoBytes
         cmp     zpWParam
         beq     Cmp_Equal
         bcs     Cmp_AGreaterThanB
         jmp     Cmp_ALessThanB

Cmp_Equal:
         sec                ;set carry for "greater than or equal"
         lda     #$00       ;and load zero to signify equality
         rts

Cmp_AIsNegative:
         lda     zpWParam+1 ;is B positive?
         bpl     Cmp_ALessThanB ;yes -> A < B
         lda     zpWAccum+1 ;compare A, B high bytes
         cmp     zpWParam+1
         beq     Cmp_LoBytes ;equal? -> compare low bytes
         bcs     Cmp_AGreaterThanB ;A high byte > B high byte? -> A > B
         jmp     Cmp_ALessThanB ;else -> A < B

Cmp_LoBytes:
         lda     zpWAccum
         cmp     zpWParam   ;compare A, B low bytes
         beq     Cmp_Equal  ;equal? -> A == B
         bcs     Cmp_AGreaterThanB ;A low byte > B low byte? -> A > B
         jmp     Cmp_ALessThanB ;else -> A < B

; Compare two strings. Comments in this area refer to first operand as `a$`, 2nd
; as `b$`. This does not actually refer to real variable names.
CompareStrings:
         lda     zpWAccum+1
         sta     zpMisc
         lda     zpWAccum+2
         sta     zpMisc+1
         lda     zpWParam+1
         sta     zpMisc+2
         lda     zpWParam+2
         sta     zpMisc+3
         lda     zpWAccum   ;str len 1st operand
         beq     CmpStr_LenAZero ;len(a$) == 0? -> check len(b$)
         sta     vZpStrLenA ;store len(a$)
         beq     Cmp_AGreaterThanB ;NEVER branches - they forgot to compare len(b$) first!
         lda     zpWParam   ;get len(b$) - should've come before instr above!
         sta     vZpStrLenB ;store it
         ldy     #$00
@strCmpLp:
         lda     (zpMisc),y ;get char from a$
         cmp     (zpMisc+2),y ;cmp char from b$
         bcc     Cmp_ALessThanB ;a$[i] < b$[i]? -> a$ < b$
         beq     @charEq    ;(this and next instr should've been single bne)
         jmp     Cmp_AGreaterThanB ;not less, not eq -> a$ > b$

@charEq: iny                ;bump next char to check
         dec     vZpStrLenA ;decrement len(a$)
         beq     @lenAZero  ;len(a$) == 0? -> check len(b$)
         dec     vZpStrLenB ;decrement len(b$)
         beq     Cmp_AGreaterThanB ;len(b$) == 0? -> a$ > b$
         jmp     @strCmpLp  ;neither are zero; loop back around to check next char

@lenAZero:
         dec     vZpStrLenB ;decrement len(b$)
         beq     Cmp_Equal  ;zero, too? -> strs equal
         jmp     Cmp_ALessThanB ;;else -> a$ < b$

CmpStr_LenAZero:
         lda     zpWParam   ;str len 2nd operand
         beq     Cmp_Equal  ;len(b$) == 0? -> they're both equal
         jmp     Cmp_ALessThanB

; stores A at zpTXTPTR, then increments zpTXTPTR.
; If, after incrementing, zpTXTPTR has wraooed to next page, tehn it is
; decremented to point at the last byte of preceding page, and null-terminated.
TxtPtrStoreAndAdv:
         ldy     #$00
         sta     (zpTXTPTR),y
         inc     zpTXTPTR
         beq     @overfl
         rts

@overfl: dec     zpTXTPTR
         lda     #$00
         sta     (zpTXTPTR),y
         rts

TxtPtrGetCharAndIncr:
         ldy     #$00
         lda     (zpTXTPTR),y
TxtPtrIncr:
         inc     zpTXTPTR
         beq     @hi
         and     #$ff
         rts

@hi:     inc     zpTXTPTR+1
         and     #$ff
         rts

TxtPtrIncrAndGetChar:
         ldy     #$00
         inc     zpTXTPTR
         beq     @hi
         lda     (zpTXTPTR),y
         rts

@hi:     inc     zpTXTPTR+1
         lda     (zpTXTPTR),y
         rts

TxtPtrDecr:
         lda     zpTXTPTR   ;is low byte zero?
         beq     @lowZero   ;yes -> decr both bytes
         dec     zpTXTPTR   ;no: decr just low byte
         rts                ;and return

@lowZero:
         dec     zpTXTPTR   ;decr lo
         dec     zpTXTPTR+1 ;decr hi
         rts                ;-> return

; Get the next program character (doesn't increment)
GetTxtChar:
         ldy     #$00
         lda     (zpTXTPTR),y
         rts

; dead/unreachable code
SetTxtCharDEAD:
         ldy     #$00
         sta     (zpTXTPTR),y
         rts

TxtIncAndSkipSpaces:
         jsr     TxtPtrIncr
TxtSkipSpaces:
         ldy     #$00
         lda     (zpTXTPTR),y
         cmp     #$20
         beq     TxtIncAndSkipSpaces
         rts

; Clears carry if A is a digit, sets otherwise
IsDigit: cmp     #'0'
         bcc     @secRts
         cmp     #':'       ;'9' + 1
         bcs     @secRts    ;better: bcs $90D3
         clc
         rts

@secRts: sec
rts_90D3:
         rts

nxtDig:  inc     zpTmp46
FindFirstNonzeroDigit:
         ldx     zpTmp46
         lda     zpNumStrTmp,x ;did we get null terminator byte?
         beq     @null      ;yes -> skipped too many, back up one so we have '0'
         cmp     #$30       ;no; do we have a '0' digit?
         beq     nxtDig     ;yes -> move past it and check next
         rts                ;no: we found first non-zero digit then. Return.

@null:   dec     zpTmp46    ;back up one so we have '0'
         rts

ParsePosOrNegDecWFromTxt:
         jsr     TxtSkipSpaces
         cmp     #'-'       ;Is cur char a '-'?
         bne     ParsePosDecWFromTxt ;no -> then it better be a string of digits. Parse them.
         jsr     TxtPtrIncr ;yes, then advance TXTPTR
         jsr     ParsePosOrNegDecWFromTxt ;and call ourselves recursively to get a (possibly re-negated) number
         jmp     WAccumNegate ;negating afterward.

; dead/unreachable code
         jsr     ParsePosDecWFromTxt
         jsr     Cmp32768
         beq     errOverfl1
         rts

; Parses a decimal number at zpTxtPtr into zpWAccum, leaving zpTXTPTR after the
; parsed number.
ParseDecimalWordFromTxt:
         lda     #TYP_INT
         sta     zpArgTyp
         lda     #$00
         sta     zpWAccum   ;start with zero in WAccum
         sta     zpWAccum+1
@digitsLoop:
         lda     #$0a
         sta     zpWParam
         lda     #$00
         sta     zpWParam+1
         ldy     #$00
         lda     (zpTXTPTR),y
         jsr     IsDigit
         bcs     rts_90D3   ;not a digit? -> done
         pha                ;push the digit
         jsr     WordMultiplyAsWord ;multiply WAccum by 10 (will be zero the first time!)
         pla                ;pull digit
         sec
         sbc     #'0'       ;subtract value of '0' char, now 0-9
         sta     zpWParam   ;store in WParam
         jsr     WordAdd    ;and perform add
         bcs     errOverfl1 ;overflow? -> error
         jsr     TxtPtrIncr ;advance to next digit
         jmp     @digitsLoop ;and loop around

; Parse a decimal word at TXTPTR, and throw an overflow error if it overflowed
; to negative. As a special exception, a value of 32,768 is allowed (so that
; later code can check if it was preceded with '-').
ParsePosDecWFromTxt:
         jsr     ParseDecimalWordFromTxt
         lda     zpWAccum+1
         bmi     @ck32768
         rts

@ck32768:
         jsr     Cmp32768
         bne     errOverfl1
         rts

errOverfl1:
         jmp     ErrorOverflow

; Converts a (POSITIVE) word (at WAccum) into a null-terminated string of five
; decimal digits in ASCII, stored at zpNumStrTmp.
vZpDigitIdx .set $46        ;index into zpNumStrTmp to store next digit
vZpDigitChar .set $47       ;character holding the digit value for current decimal place
PosDecStrFromWord:
         lda     #$00
         sta     vZpDigitIdx
PosDecStrMidStr:
         lda     vZpDigitIdx
         pha
         lda     #$10       ;put 10,000 into zpWParam
         sta     zpWParam
         lda     #$27
         sta     zpWParam+1
         jsr     DecStr_findPlaceValue ;find digit for the ten-thousands place
         lda     #$e8       ;put 1,000 into zpWParam
         sta     zpWParam
         lda     #$03
         sta     zpWParam+1
         jsr     DecStr_findPlaceValue ;find digit for the thousands place
         lda     #$64       ;put 100 into zpWParam
         sta     zpWParam
         lda     #$00
         sta     zpWParam+1
         jsr     DecStr_findPlaceValue ;find digit for the hundreds place
         lda     #$0a       ;put 10 into zpWParam
         sta     zpWParam
         jsr     DecStr_findPlaceValue ;find digit for the tens place
         lda     zpWAccum
         clc
         adc     #$30
         jsr     DecStr_putAndAdv ;finally, store the remaining ones digit
         lda     #$00
         jsr     DecStr_putAndAdv ;and null-terminate the string
         pla
         sta     vZpDigitIdx ;restore vZpDigitIdx to what it was at start (usually #$00)
         rts

DecStr_putDigit:
         jsr     WordAdd    ;we subtracted too far; add it back in
         lda     vZpDigitChar ;put the digit, and advance to next
DecStr_putAndAdv:
         ldx     vZpDigitIdx
         sta     zpNumStrTmp,x
         inc     vZpDigitIdx
         rts

DecStr_findPlaceValue:
         lda     #'0'       ;start with the character '0'
         sta     vZpDigitChar
@divLp:  jsr     WordSubtractClone ;did current place value "go into" WAccum? (division)
         bcc     DecStr_putDigit ;no -> put char and return for next place value
         inc     vZpDigitChar ;yes: increment digit
         jmp     @divLp     ;and see if it "goes into" WAccum again

; Converts a (possibly negative) word (at WAccum) into a null-terminated string
; of five decimal digits in ASCII, stored at zpNumStrTmp. Will be preceded
; either by a space (positive), or '-' (negative)
DecStrFromWord:
         lda     #$00
         sta     vZpDigitIdx
         ldy     #$20       ;SPACE char
         lda     zpWAccum+1 ;is WAccum positive (or zero)?
         bpl     @pos       ;yes -> keep prefix as SPACE char
         jsr     WAccumNegate ;no: negate WAccum
         ldy     #'-'       ; and prefix with '-' instead
@pos:    tya
         pha                ;push the prefix
         jsr     PosDecStrMidStr ;convert the positive decimal
         jsr     FindFirstNonzeroDigit ;advance to first non-'0' digit
         dec     vZpDigitIdx ;then backup one from there
         pla                ;pull prefix char
         jsr     DecStr_putAndAdv ;and store it as the prefix
         dec     vZpDigitIdx ;then back up so it's at the start
         rts

; Converts a value from $0-$F to a hex digit in ASCII.
HexFromNybble:
         cmp     #10        ;A reg >= 10?
         bcs     @needLet   ;yes -> need a hex letter
         adc     #'0'       ;no: decimal digit is fine
         rts                ;-> return

@needLet:
         clc                ;(convert to hex letter-digit)
         adc     #$37       ;#$0A + #$37 = #$41 ('A'); #$0F + #$37 = #$46 ('F')
         rts                ;-> return

; Converts a byte into two hex digits in ASCII, storing them at $3D + x.
HexFromByte:
         pha                ;push the byte
         and     #$f0       ;grab the high nybble, and shift it into low
         lsr     A
         lsr     A
         lsr     A
         lsr     A
         jsr     HexFromNybble ;convert to hex
         sta     zpNumStrTmp,x ;store in the tmp string
         inx                ;incr out-string index
         pla                ;pull original byte
         and     #$0f       ;grab the low nybble
         jsr     HexFromNybble ;convert to hex
         sta     zpNumStrTmp,x ;store in string
         inx                ;incr out-string index to next char
         rts                ;-> return

; Converts a word (at WAccum) into a null-terminated string of four hexadecimal
; digits in ASCII, stored at zpNumStrTmp.
HexStrFromWord:
         ldx     #$00
         stx     zpTmp46
         lda     zpWAccum+1
         jsr     HexFromByte ;convert WAccum high byte, store in string
         lda     zpWAccum
         jsr     HexFromByte ;convert WAccum low byte
         lda     #$00
         sta     zpNumStrTmp,x ;add null terminating char to number string
rts_91EC:
         rts                ;-> return

; Converts a hex string at zpTXTPTR, to a binary word in zpWAccum.
WordFromHex:
         lda     #TYP_INT
         sta     zpArgTyp   ;exprssion result type will be integer
         ldx     #$00
         lda     #$00
         sta     zpWAccum   ;zero out WAccum
         sta     zpWAccum+1
@chrLp:  jsr     GetTxtChar ;get hex string char
         sec
         sbc     #'0'       ;subtract value of ASCII code for '0'
         bcc     rts_91EC   ;char val was < '0'? -> return; not a hex str
         cmp     #10
         bcc     @decDig    ;result < 10? -> is a decimal digit, handle that
         sec                ;else, is a hex letter-digit (A-F)
         sbc     #$07       ;subtract 7 more from ASCII code
         cmp     #10        ;result < 10?
         bcc     rts_91EC   ;yes -> return; char val was not hex
         cmp     #16        ;result >= 16?
         bcs     rts_91EC   ;yes -> return; char val was not hex
@decDig: pha                ;push the value to CPU stack
         jsr     @shiftResultLeft ;multiply running result by 16
         pla                ;pull translated hex digit's value
         sta     zpWParam   ;set WParam to it
         lda     #$00
         sta     zpWParam+1
         jsr     WordAdd    ;add to running value in WAccum
         jsr     TxtPtrIncr ;advance to next char in string
         jmp     @chrLp     ;-> loop back to handle next character

@shiftResultLeft:
         txa
         pha                ;push X reg to CPU stack
         lda     #$10
         sta     zpWParam
         lda     #$00
         sta     zpWParam+1
         jsr     WordMultiplyAsWord ;multiply running result by 16 (shifting existing digits over one base16 place)
         pla
         tax                ;pull and restore X reg
         rts                ;->return

TokAdvAndgetChar:
         jsr     TokAdvance
TokGetChar:
         ldy     #$00
         lda     (zpTokenizePtr),y
         rts

TokGetCharAndAdv:
         ldy     #$00
         lda     (zpTokenizePtr),y
TokAdvance:
         inc     zpTokenizePtr
         bne     flagsRts
         inc     zpTokenizePtr+1
         bne     flagsRts
; Store two NULs in a row at the end of tokenizeBuffer
TokBufTerminate:
         lda     #$00
         jsr     TokStoreCharAndAdv
TokStoreCharAndAdv:
         ldy     #$00
         sta     (zpTokenizePtr),y
         inc     zpTokenizePtr
         beq     errOverfl_9258 ;exceeded our buffer? -> error
flagsRts:
         and     #$ff
         rts

errOverfl_9258:
         jmp     ErrorOverflow

; Tokenize the line pointed at by zpTXTPTR ($09.$0A), to tokenizeBuffer ($300)
Tokenize:
         lda     #<tokenizeBuffer
         sta     zpTokenizePtr
         lda     #>tokenizeBuffer
         sta     zpTokenizePtr+1
TokenizeMain:
         jsr     TokCpySpacesFromTxt
         and     #$ff
tokMainNoCpySpc:
         beq     TokBufTerminate ;NUL? -> finish up
         cmp     #'?'       ;shorthand for PRINT
         beq     tokQMark
         cmp     #'"'
         beq     TokStorAndCopyUntilQuo
         cmp     #$27       ;shorthand for (non-buggy) REM
         beq     TokStorAndCopyRest
         cmp     #'.'
         beq     TokOther
         cmp     #'&'
         beq     TokenizeHexNum
         jsr     IsDigit
         bcc     TokenizeNumber
         jsr     TokenizeKeyword
         bcc     storeTokHndlArgs
; We didn't recognize anything special.
; Skip high-bit-set bytes, skip control chars, and store everything
; else verbatim.
TokOther:
         jsr     TxtPtrIncr
         cmp     #$80
         bcs     TokenizeMain ;skip high bytes without storing
         cmp     #$20
         bcc     TokenizeMain ;skip control chars w/o store
         cmp     #$40
         bcc     @storePunct
; Copy presumed var name out to tokenizeBuffer, verbatim 
@lp:     jsr     TokStoreCharAndAdv
         ldy     #$00
         lda     (zpTXTPTR),y
         jsr     IsAlNum
         bcs     TokenizeMain
         jsr     TxtPtrIncr
         jmp     @lp

@storePunct:
         jsr     TokStoreCharAndAdv
         jmp     TokenizeMain

tokQMark:
         jmp     TokQMark

storeTokHndlArgs:
         jmp     StoreTokenAndHandleArgs

TokStorAndCopyRest:
         ldy     #$00
         .byte   $ae
TokStorAndCopyUntilQuo:
         ldy     #$22
         sty     zpToken
TokStorAndCopyUntilTok:
         jsr     TokStoreCharAndAdv
         jsr     TxtPtrIncr
TokCopyUntilTok:
         jsr     GetTxtChar
         beq     tokMainNoCpySpc ; -> TokBufTerminate
         cmp     zpToken
         bne     TokStorAndCopyUntilTok
         jmp     TokOther

TokenizeNumber:
         lda     #tok_NUM_AFTER
         pha
         jsr     ParsePosDecWFromTxt
         lda     zpWAccum+1 ;did num fit in a single byte?
         bne     @tokNumWord ;no -> process word
         lda     zpWAccum
         cmp     #$0a       ;low byte > 9?
         bcs     @tokNumWord ;yes -> process as word
         tax                ;no: store as single byte
         pla                ;pop the num tok, won't use it
         inx                ;inc so we can't get #$00
         txa
         jmp     tokStorAndCont

@tokNumWord:
         jsr     Cmp32768   ; = 32768?
         beq     @is32768
         jmp     storeWordAndCont

@is32768:
         lda     zpToken
         cmp     #tok_OP_MINUS ;this num preceded by '-'?
         bne     @errOverfl
         jmp     storeWordAndCont

@errOverfl:
         jmp     ErrorOverflow

TokenizeHexNum:
         jsr     TxtPtrIncr ;skip the '&'
         jsr     GetTxtChar
         cmp     #'H'       ;got an (optional) 'H'?
         bne     @noH
         jsr     TxtPtrIncr ;yes -> skip it
@noH:    lda     #tok_HEX_AFTER
         pha                ;push hex-num prefix token
         jsr     WordFromHex ;convert hex string to binary number
storeWordAndCont:
         pla                ;pull token byte
         jsr     TokStoreCharAndAdv ;store it in tokenized line
         lda     zpWAccum
         jsr     TokStoreCharAndAdv ;store low byte of converted num
         lda     zpWAccum+1
tokStorAndCont:
         jsr     TokStoreCharAndAdv ;and high byte
         jmp     TokenizeMain ;-> return to tokenize loop

rts_931D:
         rts

TokCpySpacesFromTxt:
         jsr     GetTxtChar
         cmp     #$20       ;space?
         bne     rts_931D   ;no -> rts
         jsr     TokStoreCharAndAdv ;yes: store and check next
         jsr     TxtPtrIncr
         jmp     TokCpySpacesFromTxt

; Entered when we just processed a REM keyword into a token.
; Copies the rest of the line verbatim, to the tokenizeBuffer.
; 
; This has a BUG! If the katakana "small yo" (ョ) character appears anywhere
; within the REM statement, then the verbatim copying _ends_, and BASIC returns
; to trying to convert keywords into tokens, corrupting the REM statement's
; contents. This happens because this character has the same value as the token
; used for REM, and a typo means the copier is told to stop at the next REM
; character, instead of at NUL (#$00).
; 
; Many Japanese words contain this character. I kind of can't believe searching
; for this bug didn't come up with any results, as users back in the day must
; have run across it. Maybe they didn't understand how the REM line was getting
; corrupted, as it would only show up when you think to LIST it back out again.
; Or maybe hardly anyone used REM directly, but used the single-quot (`)
; instead.
; 
; Note that the single-quot (') shorthand for REM, handled separately at $9272,
; does _not_ exhibit this bug.
TokRemCopyToEnd:
         lda     #$00       ;BUG: this should be lda, Brett: changed
         sta     zpToken    ;...or else this should be sty
         jmp     TokCopyUntilTok

TokenizeLineRanges:
         jsr     TokCpySpacesFromTxt
         jsr     IsDigit
         bcc     TokenizeLineNumber
         cmp     #','
         beq     tokAndNum
         cmp     #'-'
         beq     tokAndNum
         cmp     #'.'
         beq     tokAndNum
tokenizeMain:
         jmp     TokenizeMain

TokQMark:
         lda     #tok_PRINT
         sta     zpToken
         jsr     TxtPtrIncr ;weird that it falls through here. Exits eventually at $9376.
StoreTokenAndHandleArgs:
         lda     zpToken
         jsr     TokStoreCharAndAdv
         cmp     #tok_REM
         beq     TokRemCopyToEnd
         cmp     #tok_LIST
         beq     TokenizeLineRanges
         cmp     #tok_DELETE
         beq     TokenizeLineRanges
         cmp     #tok_AUTO
         beq     TokenizeLineRanges
         cmp     #tok_RENUM
         beq     TokenizeLineRanges
         cmp     #tok_RESUME
         beq     @numOrCont
         cmp     #tok_DATA
         beq     TokDataArgs
         cmp     #tok_SYSTEM ;is it a command that takes a line number arg?
         bcs     tokenizeMain ;no -> return to normal tokenizing
@numOrCont:
         jsr     TokCpySpacesFromTxt ;yes -> parse line number if it's there
         jsr     IsDigit
         bcs     tokenizeMain
TokenizeLineNumber:
         jsr     ParseDecimalWordFromTxt
         lda     #$0b
         jsr     TokStoreCharAndAdv
         lda     zpWAccum
         jsr     TokStoreCharAndAdv
         lda     zpWAccum+1
         jsr     TokStoreCharAndAdv
         jsr     TokCpySpacesFromTxt
delimAndNum:
         cmp     #','
         beq     tokAndNum
         cmp     #'-'
         bne     tokenizeMain
tokAndNum:
         jsr     TokStoreCharAndAdv
         jsr     TxtPtrIncr
         jsr     TokCpySpacesFromTxt
         jsr     IsDigit
         bcc     TokenizeLineNumber
         jmp     delimAndNum

TokDataArgs:
         jsr     TokCpySpacesFromTxt
         cmp     #':'
         beq     tokenizeMain
         and     #$ff
@txtEnd: beq     tokenizeMain
         cmp     #'"'
         beq     @dquo
@dquoOut:
         jsr     TokStoreCharAndAdv
         jsr     TxtPtrIncr
         jmp     TokDataArgs

@dquo:   jsr     TokStoreCharAndAdv
         jsr     TxtPtrIncr
         jsr     TokCpySpacesFromTxt
         cmp     #'"'
         beq     @dquoOut
         and     #$ff
         beq     @txtEnd
         jmp     @dquo

TokTblGetChar:
         ldy     #$00
         lda     (zpTokTblScn),y
rts_93DE:
         rts

IncrTokTblScn:
         inc     zpTokTblScn
         bne     rts_93DE   ; -> rts
         inc     zpTokTblScn+1
         rts

; Returns with carry clear if keyword matched; carry set otherwise
TokenizeKeyword:
         lda     #<tbl_KeywordTokens
         sta     zpTokTblScn
         lda     #>tbl_KeywordTokens
         sta     zpTokTblScn+1
@nxtKwd: jsr     TokTblGetChar
         tax
         inx                ;did we get #$ff (end-of-table byte)?
         beq     @kwdNotFnd ;yes -> return false (load txt char, set carry, rts)
         sta     zpToken
         jsr     IncrTokTblScn
         jsr     SaveTXTPTR
; Loop over keyword from tbl_KeywordTokens, and word at zpTXTPTR, to see if
; they're a match
@cmpKwd: jsr     GetTxtChar
         sta     zpSavedTxtChar
         jsr     TokTblGetChar
         cmp     zpSavedTxtChar
         bne     @ckForAbbrv
         jsr     TxtPtrIncr ;chars matched, incr and check next
         jsr     IncrTokTblScn
         jsr     TokTblGetChar
         bpl     @cmpKwd
@retTrue:
         clc                ;reached token byte of next kwd, so keyword matched!
         rts                ;return true (zpToken has the token)

@ckForAbbrv:
         jsr     TxtPtrGetCharAndIncr
         cmp     #'.'       ;did user abbreviate the keyword?
         beq     @retTrue   ;yes -> we matched, return true
         jsr     RestoreTXTPTR
@skipToNextKwd:
         jsr     TokTblGetChar
         bmi     @nxtKwd
         jsr     IncrTokTblScn
         jmp     @skipToNextKwd

@kwdNotFnd:
         jsr     GetTxtChar
         sec
         rts

SaveTXTPTR:
         lda     zpTXTPTR
         sta     zpSavedTXTPTR
         lda     zpTXTPTR+1
         sta     zpSavedTXTPTR+1
         rts

RestoreTXTPTR:
         lda     zpSavedTXTPTR
         sta     zpTXTPTR
         lda     zpSavedTXTPTR+1
         sta     zpTXTPTR+1
         rts

; Detokenizes from zpTokenizePtr to lineBuffer (via zpTXTPTR)
; Caller must take care to save/restore previous value of zpTXTPTR
DetokenizeLine:
         jsr     InitLineBufferScanning ;point zpTXTPTR at start of lineBuffer
DetokenizeLineCont:
         jsr     TokGetChar ;get the char pointed at by zpTokenizePtr
         beq     Detok_finish ;null terminator? -> copy that to zpTXTPTR and return
         cmp     #$20       ;possible leading byte for number token?
         bcc     DetokNumber ;yes -> translate it
         cmp     #$80       ;non-token, low-value character?
         bcc     Detok_checkHandleDQuot ;yes -> handle possible situations for that
         pha                ;no, must be keyword token. Push token byte
         jsr     Detok_keyword ;expand the token to a keyword
         jsr     TokAdvance
         pla
         cmp     #tok_REM   ;was it the token for REM?
         beq     Detok_copyRemaining ;yes -> copy all remaining chars verbatim
         jmp     DetokenizeLineCont ;no -> continue detokenizing

Detok_finish:
         lda     #$00       ;unnecessary: we only arrive here if A is already #$00
         jmp     TxtPtrStoreAndAdv

DetokNumber:
         cmp     #11        ;token >= 11?
         bcs     DetokNumberWord ;yes -> not a single-byte token
         sta     zpWAccum   ;no: single-byte token; translate to decimal 0-9
         dec     zpWAccum   ;decrement byte to get real value
         lda     #$00
         sta     zpWAccum+1 ;expand byte to word
         jsr     TokAdvance ;advance past our single-byte number token
         jmp     DetokDecimalNum ;and detokenize it

DetokNumberWord:
         pha                ;push token byte
         jsr     TokAdvAndgetChar ;move number contents into WAccum, and move zpTokenizePtr past them
         sta     zpWAccum
         jsr     TokAdvAndgetChar
         sta     zpWAccum+1
         jsr     TokAdvance
         pla                ;pull token byte
         cmp     #tok_HEX_AFTER ;is it for a hex number?
         bne     DetokDecimalNum ;no -> detokenize as decimal
         lda     #'&'       ;yes: store "&H"
         jsr     TxtPtrStoreAndAdv
         lda     #'H'
         jsr     TxtPtrStoreAndAdv
         jsr     HexStrFromWord ;and then output the number as hex
         jmp     CopyNumToTxtPtr

DetokDecimalNum:
         jsr     PosDecStrFromWord ;get decimal for word at WAccum
CopyNumToTxtPtr:
         jsr     FindFirstNonzeroDigit ;skip to first non-zero digit
         ldx     zpTmp46
@cpyNumLp:
         lda     zpNumStrTmp,x ;get digit
         beq     DetokenizeLineCont ;end of number? ->
         jsr     TxtPtrStoreAndAdv ;copy out to zpTXTPTR and advance to next
         inx
         jmp     @cpyNumLp  ;loop around to copy next digit

Detok_checkHandleDQuot:
         cmp     #'"'       ;double-quote char?
         bne     Detok_checkHandleApos ;no -> maybe it's an apostrophe
@cpy:    jsr     Detok_copyOneChar ;yes, is quote. Copy until we see another one
         jsr     TokGetChar ;get char
         cmp     #$22       ;is terminating double-quote?
         beq     Detok_copyCharContinue ;yes -> copy it and continue normal detokenizing
         and     #$ff       ;terminating null '\0'?
         bne     @cpy       ;no -> loop around, keep copying
         jmp     DetokenizeLineCont ;yes -> finish up detok

Detok_copyCharContinue:
         jsr     Detok_copyOneChar
         jmp     DetokenizeLineCont

Detok_checkHandleApos:
         cmp     #$27       ;apostrophe (REM shorthand)?
         bne     Detok_copyCharContinue ;no -> copy the single character and continue
cpyLp:   jsr     Detok_copyOneChar ;copy chars until '\0'
Detok_copyRemaining:
         jsr     TokGetChar
         bne     cpyLp
         jmp     DetokenizeLineCont ;finish out detok

Detok_copyOneChar:
         jsr     TokGetCharAndAdv
         jmp     TxtPtrStoreAndAdv

Detok_keyword:
         sta     zpToken
         lda     #<tbl_KeywordTokens ;set zpTokTblScan to the start of the tokens table
         sta     zpTokTblScn
         lda     #>tbl_KeywordTokens
         sta     zpTokTblScn+1
         jsr     TokTblGetChar ;get char from table
@chkToken:
         cmp     #$ff       ;did we reach end of tokens table?
         beq     rts_950F   ;don't replace token with anything
         cmp     zpToken    ;is this the token we're looking for?
         beq     Detok_copyKeyword ;yes -> copy the keyword out
@notOurKwd:
         jsr     IncrTokTblScn ;no, not our keyword
         jsr     TokTblGetChar ;skip chars until next token byte
         bpl     @notOurKwd
         jmp     @chkToken  ;got token byte -> check if it's ours

Detok_copyKeyword:
         jsr     IncrTokTblScn ;move past token byte
@cpyKwd: jsr     TokTblGetChar ;get a keyword character
         bmi     rts_950F   ;reached next token byte? -> done
         jsr     TxtPtrStoreAndAdv ;copy out to zpTXTPTR
         jsr     IncrTokTblScn ;move to next keyword character
         jmp     @cpyKwd    ;loop until keyword has been copied

rts_950F:
         rts

CmdFn_ERROR:
         jsr     EvalByteInteger
         jmp     PrintErrorAndStop

ErrorResumeWithoutErrHandl:
         lda     #err_RE
         jmp     PrintErrorAndStop

ErrorNoResume:
         lda     #EH_NO_HANDLER
         sta     zpErrHandStat
         lda     #err_NR
         jmp     PrintErrorAndStop

errSyntax_9524:
         jmp     ErrorSyntax

CmdFn_RESUME:
         php                ;push CPU flags
         ldx     zpErrHandStat ;get err handler status
         beq     ErrorResumeWithoutErrHandl ;no error handler installed? -> error about that
         cpx     #EH_HANDLER_DEFINED ;handler installed, but not called?
         beq     ErrorNoResume ;yes -> error about that
         plp                ;else, pull flags. Did we get an arg?
         beq     RESUME_restoreContext ;no -> restore and exit
         cmp     #tok_LNUM_AFTER ;else, is arg a line num?
         beq     RESUME_goToLineArg ;yes -> handle
         cmp     #tok_NEXT  ;is it the NEXT token?
         bne     errSyntax_9524 ;no -> no supported args given: ERROR
         jsr     RESUME_restoreContext ;yes: restore context (and return to next instr)
@skipCmd:
         jsr     IsEndOfCmd ;now skip the original offending command (skip to the NEXT one)
         beq     rts_956F   ;no -> done
