CmdFn_FIND:
         jsr     EvalString ;evaluate string argument (to expr parse stack)
         jsr     SaveTXTPTR ;save away current TXTPTR
         lda     zpTXTTAB
         sta     zpTXTPTR   ;reset TXTPTR to start of program
         lda     zpTXTTAB+1
         sta     zpTXTPTR+1
FIND_linesLoop:
         jsr     GetTxtChar ;are we at program end?
         beq     restoreTxtPtr_9570 ;restore original TXTPTR and exit
         clc
         lda     zpTXTPTR
         adc     #$03       ;set zpTokenizePtr to TXTPTR + 3 (skipping next-line offset, line num bytes)
         sta     zpTokenizePtr
         lda     #$00
         adc     zpTXTPTR+1
         sta     zpTokenizePtr+1
         lda     zpTXTPTR
         pha                ;push value of TXTPTR to CPU stack
         lda     zpTXTPTR+1
         pha
         jsr     DetokenizeLine ;detokenize this line into lineBuffer
         pla                ; (wouldn't it be more efficient to tokenize FIND contents and search for that instead?)
         sta     zpTXTPTR+1 ;pull TXTPTR back off stack (detokenize probably overwrote)
         pla
         sta     zpTXTPTR
         lda     exprParseStk ;put FIND arg string info into WParam
         sta     zpWParam
         lda     exprParseStk+1
         sta     zpWParam+1
         lda     exprParseStk+2
         sta     zpWParam+2
         lda     #<lineBuffer ;put detokenized current line info into WAccum+1
         sta     zpWAccum+1
         lda     #>lineBuffer
         sta     zpWAccum+2
         ldy     #$00       ;init Y reg
@countLp:
         lda     (zpWAccum+1),y ;determine length of detokenized line,
         beq     @lineEnd   ; by counting chars in Y reg, until we reach a terminating null
         iny                ;increment Y
         bne     @countLp   ;(always) -> loop, keep counting chars
@lineEnd:
         sty     zpWAccum   ;save Y-reg (character count) as strlen for WAccum
         jsr     CheckInStr ;check whether user str is contained within detokenized line
         beq     @nextLine  ;no match? -> advance and check next line
         jsr     PrintLineNumAndDetok ;match; print the line # and (re-)detokenized contents
         jsr     PauseOnEsc ;pause if Esc is being pressed
         jmp     FIND_linesLoop ;-> check for matches in next line

@nextLine:
         jsr     GetTxtChar ;get offset to next line of BASIC
         clc
         adc     zpTXTPTR   ;add to TXTPTR (point it at next line)
         sta     zpTXTPTR
         lda     #$00
         adc     zpTXTPTR+1
         sta     zpTXTPTR+1
         jmp     FIND_linesLoop ;-> and loop back around to check for matches

CIS_matchFailedRetZero:
         lda     #$00
         rts

; Checks if the string identified by WParam is contained within the string
; identified by WAccum. Returns the index to the first occurrance, if found, or
; zero if not found.
vZpHayStkRemn .set $19
vZpNeedleRemn .set $1b      ;how many chars left to haystack we can index
vZpHayStkIdx .set $6b
vZpNeedleIdx .set $6c
CheckInStr:
         lda     #$00
         sta     vZpHayStkIdx ;initialize indices into haystack and needle strings
         sta     vZpNeedleIdx
         lda     zpWAccum   ;get haystack string length
         sta     vZpHayStkRemn ;save as how many characters left in haystack, to match
         cmp     zpWParam   ;are there fewer chars remaining to haystack than are in needle?
         bcc     CIS_matchFailedRetZero ;yes -> search failed, match impossible now
CIS_tryNextHayStkChar:
         lda     zpWParam   ;get needle string length
         sta     vZpNeedleRemn ;save as how many chars left in needle, to compare
         lda     vZpHayStkIdx ;get current index into needle
         pha                ; and push to CPU stack
@matchLp:
         ldy     vZpHayStkIdx
         lda     (zpWAccum+1),y ;get char from haystack
         ldy     vZpNeedleIdx
         cmp     (zpWParam+1),y ;does it match char in needle?
         bne     @restartNextHayStkChar ;no -> reset search at next haystack char
         dec     vZpNeedleRemn ;decrement # chars remaining in check in needle
         beq     @matchSucc ;out of needle chars? -> return the index!
         inc     vZpHayStkIdx ;increment the character indices
         inc     vZpNeedleIdx
         jmp     @matchLp   ;loop back around to check next needle/haystack chars

@matchSucc:
         pla                ;pull index to start of match within haystack
         clc
         adc     #$01       ;add one to it (cvt from 0-based to 1-based indexing)
         rts                ;return

@restartNextHayStkChar:
         pla                ;pull (aborted) start of match in haystack
         sta     vZpHayStkIdx ;set as haystack index again
         inc     vZpHayStkIdx ;and increment to start searching again at next char
         lda     #$00
         sta     vZpNeedleIdx ;reset needle index to zero
         dec     vZpHayStkRemn ;one less haystack char remaining to be checked
         beq     CIS_matchFailedRetZero ; == 0? -> no more matches possible; indicate match failure
         jmp     CIS_tryNextHayStkChar ;else, restart matching at the new haystack position

; Turn keyclicks on or off. Pulls some funny tricks to reuse the same ON/OFF
; check logic as CmdFn_TR (just below)
vZpAmClick .set  $74        ;flag to indicate whether we're handling "CLICK ON/OFF" or "TR ON/OFF"
CmdFn_CLICK:
         ldy     #$ff       ;indicate we're CLICK
         sta     vZpAmClick
         bmi     OnOff      ;check arg for ON/OFF

; For TRON, TROFF commands. Pulls some funny tricks to let CmdFn_CLICK (above)
; reuse the same ON/OFF check logic
CmdFn_TR:
         ldy     #$00       ;indicate we're TR--
         sty     vZpAmClick
OnOff:   cmp     #tok_ON    ;check arg for ON/OFF
         beq     @on        ;ON? -> load #$FF
         cmp     #tok_OFF   ;OFF?
         bne     errSyn_96A3 ;neither ON nor OFF -> error
         lda     #$00       ;OFF. Load #$00
         .byte   $2c        ;skip next instr
@on:     lda     #$ff
         ldy     vZpAmClick ;are we TR--?
         beq     @tr        ;yes -> store in the tr flag
         sta     zpKeyClickFlg ;otherwise, store in the key-click flag
         .byte   $2c        ;skip next instr
@tr:     sta     zpTraceOnFlag
         jmp     TxtPtrIncr

CmdFn_GOSUB:
         tax                ;move acc value to X-reg for a bit
         pla
         sta     zpSavedRts ;pull return address and save it
         pla
         sta     zpSavedRts+1
         txa
         jsr     FindLineFromArg ;find the line number for the argument
         jsr     SkipLineNumArgs ;and skip TXTPTR past it
         lda     zpTXTPTR
         pha                ;push this TXTPTR addr
         lda     zpTXTPTR+1
         pha
         lda     zpRunLineNum
         pha                ;push the current line number
         lda     zpRunLineNum+1
         pha
         lda     zpRunTxtNxtLnk
         pha                ;push the link to the following line
         lda     zpRunTxtNxtLnk+1
         pha
         lda     #>GOSUB_STK_MARKER
         pha                ;push special #$FF00 marker indicating a GOSUB
         lda     #GOSUB_STK_MARKER
         pha
         lda     zpSavedRts+1
         pha                ;now re-push our return address, so the return still works
         lda     zpSavedRts
         pha
         jmp     GoTo       ;and jump to the line in argument

ErrorReturnWithoutGosub:
         lda     #err_RG
         jmp     PrintErrorAndStop

RETURN_noArg:
         pla                ;pull up our return address and save aside
         sta     zpSavedRts
         pla
         sta     zpSavedRts+1
         pla                ;pull up next byte
         cmp     #GOSUB_STK_MARKER ;does it match our marker byte?
         bne     ErrorReturnWithoutGosub ;no -> error. Most recent stack-y thing wasn't GOSUB.
         pla                ;next marker byte match?
         bne     ErrorReturnWithoutGosub ;no -> error
         pla                ;yes: we can RETURN
         sta     zpRunTxtNxtLnk+1 ;pull up link to next BASIC line, at time of GOSUB
         pla                ; and set it
         sta     zpRunTxtNxtLnk
         pla                ;pull up line number we GOSUB'd from
         sta     zpRunLineNum+1 ;and set that
         pla
         sta     zpRunLineNum
         pla                ;pull BASIC program text location, and set
         sta     zpTXTPTR+1
         pla
         sta     zpTXTPTR
RestoreReturnAddrAndRts:
         lda     zpSavedRts+1
         pha                ;finally, plop this routine's return address back down
         lda     zpSavedRts
         pha
         rts                ;and return to it

errSyn_96A3:
         jmp     ErrorSyntax

CmdFn_RETURN:
         beq     RETURN_noArg ;no args? -> normal return
         pla                ;have a linenum arg. Pull stack items, but don't restore
         sta     zpSavedRts ;first, pull up our own return addr
         pla
         sta     zpSavedRts+1
         pla
         cmp     #$ff       ;did we get the GOSUB mark?
         bne     ErrorReturnWithoutGosub ;no -> error
         pla                ;2nd byte of GOSUB mark?
         bne     ErrorReturnWithoutGosub ;no -> error
         tsx
         txa
         clc
         adc     #$06
         tax
         txs                ;pop 6 state items off the stack, ignoring them
         lda     zpSavedRts+1
         pha                ;plop our return addr back down
         lda     zpSavedRts
         pha
         jsr     IsEndOfCmd ;and fall through to GOTO.
CmdFn_GOTO:
         jsr     FindLineFromArg
GoTo:    ldy     #$00
         lda     (zpTxtLink),y ;get offset to next line
         clc
         adc     zpTxtLink  ;add to current line ptr
         sta     zpRunTxtNxtLnk
         lda     #$00
         adc     zpTxtLink+1
         sta     zpRunTxtNxtLnk+1 ;and store in zpRunTxtNxtLnk
         iny
         lda     (zpTxtLink),y ;save line number as current
         sta     zpRunLineNum
         iny
         lda     (zpTxtLink),y
         sta     zpRunLineNum+1
         clc
         lda     #$03       ;add 3 to start of the line (past offset, line num), and set that as TXTPTR
         adc     zpTxtLink
         sta     zpTXTPTR
         lda     #$00
         adc     zpTxtLink+1
         sta     zpTXTPTR+1
         rts                ;get to executin'!

; Verifies that token at TXTPTR is a line number, and parses it.
; Does not consume it (leaves TXTPTR where it is).
FindLineFromArg:
         cmp     #tok_LNUM_AFTER ;is arg designated as line number?
         bne     errSyn_96A3 ;no -> error
         ldy     #$01
         lda     (zpTXTPTR),y ;set zpFindLNum = arg
         sta     zpFindLNum
         iny
         lda     (zpTXTPTR),y
         sta     zpFindLNum+1
         jsr     FindLineNum ;and find the indicated line
         bne     ErrorUndefLineNum ;error if it doesn't exist
rts_9704:
         rts

ErrorUndefLineNum:
         lda     #err_UL
         jmp     PrintErrorAndStop

CmdFn_CALL:
         jsr     FrmEval    ;evaluate argument
         jmp     (exprParseStk) ;then, just jump thru the zp ptr to the expr parse stack!

errIll_9710:
         jmp     ErrorIllegalValue

readChar_9713:
         jmp     ReadChar

vZpPauseCtr .set $74
CmdFn_PAUSE:
         beq     readChar_9713 ;no arg? -> just pause until char press
         lda     #$00
         sta     vZpPauseCtr
         jsr     FrmEval    ;eval integer argument
         jsr     ErrorUnlessInteger
         lda     exprParseStk+1
         bmi     errIll_9710 ;negative number? -> error
         bne     @notZero   ;do pause
         lda     exprParseStk ;zero. Is low byte also zero?
         beq     rts_9704   ;yes -> no pause then
@notZero:
         inc     exprParseStk+1 ;incr high byte
@pauseLp:
         jsr     StopIfStopKey ;check for and handle STOP key during PAUSE
         dec     vZpPauseCtr
         bne     @pauseLp   ;loop around STOP check 256 times
         dec     exprParseStk ;decrement low byte user arg,
         bne     @pauseLp   ;loop for another 256
         lda     exprParseStk+1 ;low byte zero
         beq     @rts       ;(NEVER) all zero -> exit PAUSE
         dec     exprParseStk+1 ;high byte not zero, decrement and do 65k more iterations
         bne     @pauseLp   ; unless dec went to zero, in which case return
@rts:    rts

CmdFn_LOCATE:
         jsr     EvalByteInteger ;eval first arg
         cmp     #COLS      ; >= num cols?
         bcs     errIll_9710 ;yes -> too big
         sta     zpSavedCH  ;save
         jsr     EvalCommaThenByteInt ;comma, then second arg
         cmp     #ROWS      ; >= num rows
         bcs     errIll_9710 ;yes -> too big
         sta     zpSavedCV  ;save
         jmp     RestoreCursorPos ;"restore" saved pos to actual cursor pos

CmdFn_POKE:
         jsr     FrmEval    ;eval arg (addr)
         lda     exprParseStk
         sta     zpPokeAddr ;and save it to zero page
         lda     exprParseStk+1
         sta     zpPokeAddr+1
         ldy     #$00
         sty     zpTmp46    ;init write index to 0
@wrLoop: jsr     EvalCommaThenByteInt ;comma, then write val arg
         ldy     zpTmp46
         sta     (zpPokeAddr),y ;write val to requested addr
         inc     zpTmp46    ;increment addr to next byte
         jsr     IsEndOfCmd ;another arg?
         bne     @wrLoop    ;yes -> write arg to next byte
