IF_noEval:
         pla                ;pull up return addr from CPU stack
         pla
         jmp     ExecSkipToNextLine ;and skip to next line (skips colon stmts too)

CmdFn_IF:
         jsr     FrmEval    ;evaluate condition expression
__:      lda     exprParseStk
         ora     exprParseStk+1
