goto_9797:
         jmp     CmdFn_GOTO

gotThen: jsr     AdvThenIsEndOfCmd ;after the THEN, does the IF cmd end?
         beq     CmdFn_POKE ;yes -> a very roundabout way to a syntax error...
         cmp     #$0b       ;else, did we get a line number?
         beq     goto_9797  ;yes -> GOTO it
         rts                ;else, return and execute following command (same as no THEN)

CmdFn_CLEAR:
         bne     ClearAndSet ;got arg? -> handle
Clear:   lda     zpTXTEND+1 ;set zpVARTAB = zpTXTEND + 1
         sta     zpVARTAB+1
         ldx     zpTXTEND
         inx
         bne     @vtNoHi
         inc     zpVARTAB+1
@vtNoHi: stx     zpVARTAB
         lda     zpVARTAB+1 ;set zpVAREND = zpVARTAB + 1
         sta     zpVAREND+1
         ldx     zpVARTAB
         inx
         bne     @veNoHi
         inc     zpVAREND+1
@veNoHi: stx     zpVAREND
         ldy     #$00
