ClearAndSet:
         jsr     Clear      ;do the normal CLEAR stuff first, then handle arg
         jsr     FrmEval    ;got back from main CLEAR. Evaluate the arg.
         jsr     ErrorUnlessInteger ;make sure it's an int
         lda     exprParseStk+1
         cmp     #$70       ;arg >= #$7000?
         bcs     errIllVal_97F6 ;yes -> error. That's past available RAM.
         cmp     zpVAREND+1 ;arg < zpVAREND? (in the high bytes)
         bcc     errIllVal_97F6 ;yes -> error. We're already using more space than that.
         bne     @veNotEq   ;arg > zpVAREND? -> skip next check
         lda     exprParseStk ;high bytes were exactly equal
         cmp     zpVAREND   ;check low bytes
         bcc     errIllVal_97F6 ;arg < zpVAREND? -> error. Below already-used space
@veNotEq:
         lda     exprParseStk ;we're good: set the end of BASIC "Free space" to the arg.
         sta     zpFRETOP
         lda     exprParseStk+1
         sta     zpFRETOP+1
         rts

errSyn_97F3:
         jmp     ErrorSyntax

errIllVal_97F6:
         jmp     ErrorIllegalValue

errTypeMism_97F9:
