vZpForIdxVarPtr .set $7c    ;pointer to the value of the index variable
vZpForLineNum .set $86
vZpForSvTXTPTR .set $88
CmdFn_FOR:
         pla
         sta     zpSavedRts
         pla
         sta     zpSavedRts+1 ;pull up return address, save it aside
