         sta     vZpForSvTXTPTR
         lda     zpTXTPTR+1
         sta     vZpForSvTXTPTR+1
         lda     zpRunTxtNxtLnk
         pha                ;push link to next line of BASIC (2 bytes)
         lda     zpRunTxtNxtLnk+1
         pha
         lda     zpRunLineNum ;push current line number (2 bytes)
         pha
         lda     zpRunLineNum+1
         pha
