         sta     vZpForSvTXTPTR
         pla
         sta     zpForStepVal+1 ;pull up STEP increment value
         pla
         sta     zpForStepVal
         pla
         sta     zpForLimitVal+1 ;pull up FOR limit expression value
         pla
         sta     zpForLimitVal
         pla
         sta     vZpForIdxVarPtr+1 ;pull up pointer to the index var's value
         pla
         sta     vZpForIdxVarPtr
         pla
         sta     vZpForLineNum+1 ;pull line number
         pla
         sta     vZpForLineNum
         pla
         sta     zpForNxtLnLnk+1 ;pull link to the next line of BASIC after FOR statement
         pla
         sta     zpForNxtLnLnk
