         lda     vZpForLineNum+1
         pha
         sta     zpRunLineNum+1
FOR_NEXT_PushStuffAndRts:
         lda     vZpForIdxVarPtr ;push the pointer to the contents of the index variable (2 bytes)
         pha
         lda     vZpForIdxVarPtr+1
         pha
         lda     zpForLimitVal ;push the FOR limitnig value (2 bytes)
         pha
         lda     zpForLimitVal+1
         pha
         lda     zpForStepVal ;push the STEP increment value (2 bytes)
         pha
         lda     zpForStepVal+1
         pha
         lda     vZpForSvTXTPTR ;push the TXTPTR value for just-after the FOR statement (2 bytes)
         pha
         sta     zpTXTPTR   ;and also restore it as current TXTPTR value
         lda     vZpForSvTXTPTR+1
         pha
         sta     zpTXTPTR+1
         lda     #>FOR_STK_MARKER ;push the FOR marker bytes (2)
         pha
         lda     #FOR_STK_MARKER
         pha
restoreRtnAddrAndRts_9901:
         jmp     RestoreReturnAddrAndRts ;-> now restore the saved return address, and return to it

NEXT_doStep:
         lda     zpForStepVal+1 ;is the STEP value negative?
         bmi     @negStep   ;yes -> handle negative STEP (no reversal)
         jsr     @doStep    ;evaluate STEP
         jsr     Compare    ;compare updated index var to limit
         bcs     @clcRts    ;reverse the carry bit/result of comparison
         sec
         rts                ;and return

@clcRts: clc
         rts

@negStep:
         jsr     @doStep    ;advance index var by STEP val
         jmp     Compare    ;-> compare new index var to limit value, and return

@doStep: lda     zpForStepVal ;copy step value to WParam
         sta     zpWParam
         lda     zpForStepVal+1
         sta     zpWParam+1
         jsr     SetIntAndAdd ;add step to index var
         ldy     #$00
         lda     zpWAccum
