         iny
         lda     zpWAccum+1
         sta     (vZpForIdxVarPtr),y
         lda     zpForLimitVal ;load limit value into WParam (for Compare)
         sta     zpWParam
         lda     zpForLimitVal+1
         sta     zpWParam+1
rts_9938:
         rts                ;-> return (Compare will be next)

errSyntasx_9939:
         jmp     ErrorSyntax

vZpStrLen .set   $1b
vZpSkipChars .set $52
vZpStartCV .set  $7e
vZpStartCH .set  $80
CmdFn_INPUT:
         beq     errSyntasx_9939 ;end of cmd? -> error
         cmp     #'"'       ;got a double-quote?
         bne     prQMark    ;no -> skip handling it then
         jsr     INPUT_printStr ;else, print the string
         cmp     #','       ;got following comma?
         beq     skipQMark  ;yes -> skip printing question mark
         cmp     #';'       ;else got semicolon?
         bne     errSyntasx_9939 ;no -> error
prQMark: lda     #'?'
         jsr     PrintOneChar ;print '?'
skipQMark:
         lda     zpCV       ;save current cursor position at start of input
         sta     vZpStartCV
         lda     zpCH
         sta     vZpStartCH
         jsr     INPUT_readLine ;read the input line from user
         jsr     StopIfStopKey ;honor stop key if it's pressed
         lda     #$00
         sta     vZpSkipChars
@adjForScrlLp:
         lda     vZpStartCV
         cmp     zpLineStartRow ;does our notion of starting row match the input buffer routine's?
         beq     @atStartRow ;yes -> only have to deal with the one line
         dec     vZpStartCV ;no: screen scrolled since we started typing
         clc
         lda     #COLS
         adc     vZpSkipChars ;vZpSkipChars += COLS
         sta     vZpSkipChars ; (for each line we scrolled)
         bne     @adjForScrlLp ;(always) -> check if we scrolled another line, too
@atStartRow:
         lda     vZpStartCH
         clc
         adc     vZpSkipChars
         sta     vZpSkipChars ;also skip the number of chars up until
INPUT_getVar:
         jsr     TxtSkipSpaces ; the column input started at.
         jsr     EvalVarNameOrSynErr ;find (or create) the variable named next (after optional string literal)
         jsr     SaveTXTPTR ;save current TXTPTR
         lda     vZpSkipChars
         sta     zpTXTPTR   ;skip the determined # of chars at start of lineBuffer
         lda     #>lineBuffer
         sta     zpTXTPTR+1 ;and point TXTPTR at it
         lda     zpVarType  ;get the type of the variable we parsed
         and     #$0f       ;(basic type, if array)
         cmp     #TYP_STR   ;string type?
         beq     INPUT_stringVar ;yes -> handle string
         jsr     READ_parseNumber ;no, parse a number
         lda     zpTXTPTR   ;save current TXTPTR
         sta     vZpSkipChars ; so it gets restored when we loop back around
         ldy     #$00
         lda     zpWAccum
         sta     (zpVarData),y ;save parsed number into variable
         iny
         lda     zpWAccum+1
         sta     (zpVarData),y
INPUT_checkNextArg:
         jsr     RestoreTXTPTR ;restore TXTPTR to point at INPUT args again
         jsr     TxtSkipSpaces
         cmp     #','       ;got a comma?
         bne     rts_9938   ;no -> done with INPUT
         jsr     TxtPtrIncr ; (doesn't check if there's leftover data in the string!)
         jsr     SaveTXTPTR ;yes. Save TXTPTR to just-past the comma
         lda     vZpSkipChars ;point TXTPTR back into the input string again
         sta     zpTXTPTR
         lda     #>lineBuffer
         sta     zpTXTPTR+1
         ldy     #$00
         lda     (zpTXTPTR),y
         cmp     #','       ;is next char of string a comma?
         bne     @restoreAndPrQMark ;no -> print question mark and return to evaluating BASIC
         inc     vZpSkipChars ;move past the string's comma
         jsr     RestoreTXTPTR ;return TXTPTR to BASIC so we can parse var name
         jmp     INPUT_getVar ;-> and loop back around to assign stuff to that next var

@restoreAndPrQMark:
         jsr     RestoreTXTPTR ;restore TXTPTR to point into BASIC program again
         jmp     prQMark    ;print question mark, and return

INPUT_stringVar:
         jsr     TxtSkipSpaces ;skip leading spaces in input string
         lda     #$00
         sta     vZpStrLen  ;initialize str len for str var arg
         tay                ;init Y reg
         tax                ;init X reg
@cpyGenPBufLp:
         lda     (zpTXTPTR),y ;read a char from input string
         beq     @cpyStrVar ;end of string? -> copy to var
         cmp     #','
         beq     @cpyStrVar ;comma? -> also copy out var
         sta     genPurposeBuf,x ;else store in genPurposeBuf
         inc     vZpStrLen  ;advance string length
         inx                ;advance to next char in input str
         jsr     TxtPtrIncr ;and in genPurposeBuf
         jmp     @cpyGenPBufLp ;loop for next character in input line

@cpyStrVar:
         lda     vZpStrLen  ;set copied string in genPurposeBuf
         sta     exprParseStk ; as top of expr stack
         lda     #<genPurposeBuf
         sta     exprParseStk+1
         lda     #>genPurposeBuf
         sta     exprParseStk+2
         jsr     CpyExprStrToStrVar ;...and then copy the string on stack, into the INPUT var
         lda     zpTXTPTR
         sta     vZpSkipChars ;move input string past string we processed
         jmp     INPUT_checkNextArg ;-> see if there are more INPUT args

errSyntax_9A0B:
         jmp     ErrorSyntax

CmdFn_SWAP:
         jsr     EvalVarNameOrSynErr ;evaluate variable name
         lda     zpVarType
         and     #$0f       ;push base type of var
         pha
         lda     zpVarData  ;push pointer to variable data
         pha
         lda     zpVarData+1
         pha
         jsr     SkipCommaOrSynErr ;comma comes next
         jsr     TxtSkipSpaces
         jsr     EvalVarNameOrSynErr ;parse second var name
         pla
         sta     zpMisc+1   ;save first var's data ptr to zpMisc
         pla
         sta     zpMisc
         lda     zpVarType
         and     #$0f
         sta     zpVarType  ;strip off any "array" bit on 2nd var's type
         pla                ;pull first var type
         cmp     zpVarType  ;compare to 2nd. Match?
         bne     errTypeMismatch_9A4E ;no -> error
         tax
         cmp     #TYP_INT   ;int? use "2" as size of data to swap
         beq     @int
         ldx     #33        ;else use 33 as str data length
@int:    ldy     #$00
@cpyLp:  lda     (zpVarData),y ;get a byte from var 2
         pha                ;push
         lda     (zpMisc),y ;get a byte from var 1
         sta     (zpVarData),y ;copy to var 2
         pla                ;pull byte from var 1
         sta     (zpMisc),y ;write to var 2
         iny                ;next byte
         dex                ;done copying?
         bne     @cpyLp     ;no -> copy next byte
         rts                ;yes. Done!

errTypeMismatch_9A4E:
         jmp     ErrorTypeMismatch

INPUT_printStr:
         jsr     TxtPtrIncr
         ldy     #$00
         lda     (zpTXTPTR),y ;get char
         beq     errSyntax_9A0B ;terminating null? -> missing var after, so syntax err
         cmp     #'"'       ;got terminating double-quote?
         beq     @strDone   ;yes -> done
         jsr     PrintOneChar ;else, print the char
         jmp     INPUT_printStr ;and loop around for next char in str

@strDone:
         jsr     AdvThenIsEndOfCmd ;is cmd end?
         beq     errSyntax_9A0B ;yes -> missing var after, so syntax err
         jmp     TxtPtrIncr ;-> move past closing dquot, and return to INPUT/LINPUT

CmdFn_LINPUT:
         beq     errSyntax_9A0B ;cmd end? -> syntax error
         cmp     #'"'       ;got a double-quote?
@noStr:  bne     @noStrOrDone
         jsr     INPUT_printStr
         cmp     #','       ;require following ',' or ';' (and then var)
         beq     @noStrOrDone
         cmp     #';'
         bne     errSyntax_9A0B
@noStrOrDone:
         jsr     ReadLine   ;read the line (into lineBuffer)
         jsr     StopIfStopKey ;check for and honor STOP key occurrance during input
         jsr     TxtSkipSpaces
         jsr     EvalVarNameOrSynErr ;process the following string var name
         lda     zpVarType  ;get base type of var
         and     #$0f
         cmp     #TYP_STR   ;is it string?
         bne     errTypeMismatch_9A4E ;no -> error
         ldx     #$00
         ldy     #$00
         lda     lineBuffer,x ;get first char of input line
         cmp     #$20       ;space char?
         bne     @countLen  ;no -> 
         inx                ;yes, space
         lda     lineBuffer,x ;just a single space is the whole string?
         beq     @cpyVar    ;yes -> copy empty str to var
         dex                ;no -> move back to include space char in copying
@countLen:
         lda     lineBuffer,x ;get char from input line
         beq     @cpyVar    ;end of line/str? -> len is in Y reg; copy to var
         sta     genPurposeBuf,x ;copy into genPurposeBuf (but never use??)
         inx
         iny
         jmp     @countLen  ;-> loop for next char in input line

@cpyVar: sty     exprParseStk ;set Y as str len
         lda     #<lineBuffer
         sta     exprParseStk+1 ;point str-to-copy at lineBuffer
         lda     #>lineBuffer
         sta     exprParseStk+2
         jmp     CpyExprStrToStrVar ;-> perform the copy

; Not actually a CmdFn. This is just CmdFn_ON followed by an ERROR token.
CmdFn_ON_ERROR:
         jsr     AdvThenIsEndOfCmd
         cmp     #$80       ;followed by GOTO token?
         bne     errSyntax_9AFA ;no -> syntax error
         jsr     AdvThenIsEndOfCmd ;skip past GOTO, and any spaces
         ldy     #$00
         lda     (zpTXTPTR),y ;do we have a line number?
         cmp     #$0b
         bne     errSyntax_9AFA ;no -> syntax error
         iny
         lda     (zpTXTPTR),y ;is line num low byte zero?
         bne     @handleLNum ;no -> handle line num
         iny
         lda     (zpTXTPTR),y ;get lnum high byte
         sta     zpErrHandLNum+1 ;save as handler addr
         bne     @handleLNum ;lnum high byte zero? no -> handle line num
         sta     zpErrHandStat ;storing 0 (EH_NO_HANDLER)
         rts

@handleLNum:
         jsr     IsEndOfCmd ;skip spaces
         jsr     FindLineFromArg ;find the designated line number (or error)
         ldy     #$01
         lda     (zpTXTPTR),y ;store the line num arg as error handler line num
         sta     zpErrHandLNum
         iny
         lda     (zpTXTPTR),y
         sta     zpErrHandLNum+1
         jsr     SkipLineNumArgs
         lda     #EH_HANDLER_DEFINED ;indicate we've got an error handler installed
         sta     zpErrHandStat
         rts                ;and done!

errSyntax_9AFA:
         jmp     ErrorSyntax

CmdFn_ON:
         cmp     #tok_ERROR ;followed by an ERROR token?
         beq     CmdFn_ON_ERROR ;yes -> do ON ERROR
         jsr     EvalByteInteger ;else, BASIC-style switch statement. Evaluate the int expr
         jsr     TxtSkipSpaces
         pha                ;and push next token to CPU stack
         jsr     TxtPtrIncr
         ldx     exprParseStk ;was the expr zero?
         beq     ON_skipArgsThenPlaAndRet ;yes -> just skip the list of line numbers, "GOTO" following cmd.
@argLp:  jsr     IsEndOfCmd ;out of line num args?
         beq     pla_rts_9B51 ;yes -> pull token and return
         cmp     #tok_LNUM_AFTER ;did we get a line num token?
         bne     errSyntax_9AFA ;no -> error
         dex                ;decrement expr value (= how many args to skip)
         beq     @hit       ;decremented expr at zero? -> go to this line
         jsr     TxtPtrAdvThree ;else we skip this arg
         jsr     IsEndOfCmd ;end of cmd?
         beq     pla_rts_9B51 ;yes -> done. Pull token and rts
         jsr     SkipCommaOrSynErr ;parse following comma
         jmp     @argLp     ;-> loop to next line-num arg

@hit:    pla
         cmp     #tok_RESUME ;got "RESUME" token?
         beq     ON_rsm     ;yes -> exec RESUME cmd
         sec
         sbc     #TOKEN_START ;else, subtract token start
         cmp     #$05       ; <= tok_THEN? (GOTO, GOSUB, RUN, RETURN, RESTORE, THEN)
         bcs     errSyntax_9AFA ;no -> error (other commands disallowed)
         asl     A          ;token value (- #$80) * 2 -> index into commands table
         tax
         lda     jtbl_Commands,x
         sta     zpMisc     ;copy command addr to zpMisc
         lda     jtbl_Commands+1,x
         sta     zpMisc+1
         jsr     TxtSkipSpaces
         jmp     (zpMisc)   ;-> execute (line number at TXTPTR will be the arg)

ON_rsm:  jsr     IsEndOfCmd ;set CPU flags for whether we're at end of cmd
         jmp     CmdFn_RESUME ;-> RESUME

ON_skipArgsThenPlaAndRet:
         jsr     SkipLineNumArgs ;skip remaining line-num args
pla_rts_9B51:
         pla                ;pull token
rts_9B52:
         rts                ;and return

; Skips TXTPTR past a range of line numbers, whether comma-separated,
; or ranged with '-'
SkipKnownLineNumArgs:
         jsr     TxtPtrAdvThree ;we know we're at line num arg: skip it
SkipLineNumArgs:
         jsr     IsEndOfCmd ;check for more line num args
         beq     rts_9B52   ;end of cmd? -> rts
         cmp     #$0b       ;another line num arg?
         beq     SkipKnownLineNumArgs ;yes -> skip that
         jsr     SkipCommaOrSynErr ;no -> must be comma. Skip that, then arg.
         jmp     SkipLineNumArgs

errIll_9B65:
         jmp     ErrorIllegalValue

vZpStrPtr .set   $19
vZpStrAvail .set $90
CmdFn_KEY:
         cmp     #$86       ;LIST token?
         beq     CmdFn_KEYLIST
         jsr     EvalByteInteger ;get numeric arg
         beq     errIll_9B65 ;zero? -> ill val error
         cmp     #$09
         bcs     errIll_9B65 ; >= 9? -> ill val error
         pha                ;push arg (fkey num)
         jsr     SkipCommaOrSynErr ;skip required comma
         jsr     EvalString ;evaluate string
         pla                ;pull fkey num
         sec
         sbc     #$01       ;decrement (F1 -> 0 index)
         asl     A
         asl     A
         asl     A
         asl     A          ;mul by 16 for indexing macro defs
         tax
         lda     exprParseStk ;did user define empty string?
         beq     KEY_nullTerminate ;yes -> just null terminate and return
         ldy     #$00
         lda     exprParseStk+1 ;copy ptr to string contents
         sta     vZpStrPtr
         lda     exprParseStk+2
         sta     vZpStrPtr+1
         lda     #$0f       ;max str len
         sta     vZpStrAvail
@cpyLp:  lda     (vZpStrPtr),y ;get a char from user string
         sta     fnKey1_DfnBuf,x ;copy to macro definition
         inx                ;incr src and dst
         iny
         dec     exprParseStk ;one less byte of str available
         beq     KEY_nullTerminate ;out of room? -> finish up
         dec     vZpStrAvail
         bne     @cpyLp     ;otherwise loop to copy next char
         rts

KEY_nullTerminate:
         lda     #$00
         sta     fnKey1_DfnBuf,x
         rts

; Not actually found in jtbl_Commands. It's CmdFn_KEY when followed by
; LIST token.
vZpFKeyNum .set  $74
vZpFKeyDigit .set $90
CmdFn_KEYLIST:
         jsr     TxtPtrIncr ;move ptr past LIST token
         lda     #'0'
         sta     vZpFKeyDigit
         lda     #$00
         sta     vZpFKeyNum
@eachFKeyLp:
         lda     #'F'
         jsr     QueueCharForOutput ;queue output: 'F'
         inc     vZpFKeyDigit
         lda     vZpFKeyDigit
         jsr     QueueCharForOutput ;queue output: fn key number
         lda     #$20
         jsr     QueueCharForOutput ;queue output: SPACE char
         lda     vZpFKeyNum
         asl     A
         asl     A
         asl     A
         asl     A          ;multiply fkey num by 16
         tay
@prKeyDefLp:
         lda     fnKey1_DfnBuf,y ;get char from fkey macro string
         beq     @cpyDone   ;null char -> done printing
         cmp     #$20       ;is it a printable character?
         bcc     @escCtrl   ;no -> escape control. Example: Ctrl-M -> "(M)"
         jsr     QueueCharForOutput ;yes: queue character for printing
         iny
         jmp     @prKeyDefLp ;loop until null or control

@escCtrl:
         pha                ;push the control char
         lda     #'('
         jsr     QueueCharForOutput ;queue up paren
         pla                ;pull control char
         clc
         adc     #$40       ;shift it into the printable region
         jsr     QueueCharForOutput ;and queue to print
         lda     #')'       ;closing paren
         jsr     QueueCharForOutput
         iny
         jmp     @prKeyDefLp ;go back to printing chars

@cpyDone:
         jsr     PrintOutBuf ;print queued chars
         jsr     DoCRLF     ;CRLF
         inc     vZpFKeyNum
         lda     vZpFKeyNum
         cmp     #$08       ;done 8 fkeys?
         bcc     @eachFKeyLp ;no -> do next fkey
         rts                ;yes: done

errSyn_9C09:
         jmp     ErrorSyntax

vZpNewVarName .set $7c
vZpNewVarMaxIdx .set $7e
vZpNewVarAryDimens .set $82 ;number of dimens in new array var
vZpNewVarType .set $84
CmdFn_DIM:
         jsr     IsAlpha    ;is next char alphabetic?
         bcs     errSyn_9C09 ;no, can't be a varname then -> error
         sta     vZpNewVarName
         lda     #TYP_INT
         sta     vZpNewVarType
         lda     #$00
         sta     vZpNewVarName+1
         jsr     TxtPtrIncrAndGetChar ;get next char
         jsr     IsAlNum    ;alphanumeric?
         bcs     @notAlNum  ;no -> not part of name
         sta     vZpNewVarName+1 ;yes, it's the 2nd char of var name; store it
         jsr     TxtPtrIncr ;(note: DIM can't accept oversized names,
@notAlNum:
         jsr     TxtSkipSpaces ; unlike normal assignments)
         cmp     #'$'       ;next char == '$'
         bne     @notStr    ;no -> don't update type
         inc     vZpNewVarType ;mark the new type as str
         jsr     AdvThenIsEndOfCmd
@notStr: cmp     #'('       ;next char == '('?
         bne     errSyn_9C09 ;no -> error (DIM in FB can only declare arrays)
         lda     #$00
         sta     vZpNewVarAryDimens ;set # dimens to 1 (value: 0), until we hear otherwise
         jsr     AdvThenEvalByteInt ;eval specified max index
         sta     vZpNewVarMaxIdx ;and save it
         jsr     TxtSkipSpaces
         cmp     #')'       ;closed paren?
         beq     @closeP    ;yes -> no second index
         inc     vZpNewVarAryDimens ;no, it's 2-dimensional. Increment # dimens
         jsr     EvalCommaThenByteInt ;parse comma and then another index
         sta     vZpNewVarMaxIdx+1 ;and store it
         jsr     IsEndOfCmd ;check if we're at end of command (and then ignore result??)
         cmp     #')'       ;NOW closed paren?
         bne     errSyn_9C09 ;no -> error
@closeP: jsr     TxtPtrIncr
         jsr     DIM_ReserveArrayMem ;reserve space for the new array
         jsr     IsEndOfCmd ;end of cmd?
         beq     @rts       ;yes -> exit
         jsr     SkipCommaOrSynErr ;parse a separating comma
         jsr     TxtSkipSpaces ;and any spaces
         jmp     CmdFn_DIM  ;then process the next declaration

@rts:    rts

ErrorDuplicateDefinitions:
         lda     #err_DD
         jmp     PrintErrorAndStop

DIM_ReserveArrayMem:
         jsr     FindVar_7C_7D_84 ;can we find a matching var?
         bcs     ErrorDuplicateDefinitions ;yes -> error duplicate var
         jsr     DisallowBothIdxAtMax
         lda     #$01       ;set multiplicand to 1
         sta     zpWParam
         jsr     ClearOperandHiBytes
         lda     vZpNewVarMaxIdx
         sta     zpWAccum   ;set multiplier to size of dimen 1 (max idx + 1)
         inc     zpWAccum
         bne     @waNoOverfl
         inc     zpWAccum+1 ;(incr to get # elems from max idx)
@waNoOverfl:
         lda     vZpNewVarAryDimens ;have only one dimen?
         beq     @oneDim    ;yes -> leave multiplicand where it is
         lda     vZpNewVarMaxIdx+1 ;no, multiply the # elems for both
         sta     zpWParam
         inc     zpWParam   ;(increment to get # elems)
         bne     @oneDim
         inc     zpWParam+1
@oneDim: jsr     WordMultiply
         jsr     GetSizeOfElementType
         sta     zpWParam
         lda     #$00
         sta     zpWParam+1
         jsr     WordMultiply ;then multiply the result by the size of the array's element type
         lda     #$05
         sta     zpWParam   ;add space for var name and type info
         lda     vZpNewVarAryDimens ;only one dimen?
         beq     @oneDim1   ;yes -> we're good
         inc     zpWParam   ;no, we need one more byte of space for type info (for 2nd max idx)
@oneDim1:
         jsr     WordAdd    ;(do the add)
         bcs     errOutOfMem_9CD3 ;(OOM if so indicated)
         lda     zpVarData
         sta     zpMisc
         sta     zpWParam
         lda     zpVarData+1
         sta     zpMisc+1
         sta     zpWParam+1
         jsr     WordAdd    ;now add that to the variable location (end of var table)
         bcs     errOutOfMem_9CD3 ;overflow past #$FFFF? -> OOM error
         lda     zpFRETOP+1
         sta     zpWParam+1
         lda     zpFRETOP
         sta     zpWParam
         jsr     WordCompare ;did we overflow past zpFRETOP?
         bcc     DIM_InitializeArrayVar
errOutOfMem_9CD3:
         jmp     ErrorOutOfMemory

DisallowBothIdxAtMax:
         lda     #$ff
         cmp     vZpNewVarMaxIdx
         bne     @rts
         cmp     vZpNewVarMaxIdx+1
         beq     errOutOfMem_9CD3
@rts:    rts

DIM_InitializeArrayVar:
         ldy     #$00
         lda     zpVarType  ;store var type (including array flag)
         sta     (zpVarData),y
         iny
         lda     zpVarName  ;store var name first char
         sta     (zpVarData),y
         iny
         lda     zpVarName+1 ;store var name 2nd char
         sta     (zpVarData),y
         iny
         lda     vZpNewVarAryDimens ;store # dimens
         sta     (zpVarData),y
         iny
         lda     vZpNewVarMaxIdx ;store first max idx
         sta     (zpVarData),y
         lda     vZpNewVarAryDimens ;just one dimen?
         beq     @oneDim2   ;yes -> skip storing a 2nd idx
         iny                ;no, store 2nd max idx
         lda     vZpNewVarMaxIdx+1
         sta     (zpVarData),y
@oneDim2:
         lda     zpWAccum   ;set the new end of the vars table
         sta     zpVAREND
         lda     zpWAccum+1
         sta     zpVAREND+1
         clc
         ldx     #$05       ;5 bytes past var start: that's where the contents begin
         lda     vZpNewVarAryDimens ;is it one-dimensional?
         beq     @oneDim3   ;yes -> stick with 5
         inx                ;no: actually we need 6 to include the 2nd max idx
@oneDim3:
         txa
         adc     zpMisc     ;add the offset
         sta     zpMisc
         lda     #$00
         adc     zpMisc+1
         sta     zpMisc+1
@ClearElemsLp:
         ldy     #$00       ;Initialize all the array contents to zeroes
         lda     #$00
         sta     (zpMisc),y ;set zero
         inc     zpMisc     ;increment scanning ptr
         bne     @noCarry
         inc     zpMisc+1
@noCarry:
         lda     zpMisc+1
         cmp     zpVAREND+1 ;at var table end?
         bne     @ClearElemsLp ;no -> next loop iteration
         lda     zpMisc
         cmp     zpVAREND   ;check high byte too
         bne     @ClearElemsLp
         ldy     #$00
         lda     #$00
         sta     (zpMisc),y ;set next 3 bytes after vars end to 0, too
         iny
         sta     (zpMisc),y
         iny
         sta     (zpMisc),y
         rts                ;and return

; Not in jtbl_Commands: in reality, this is just "SAVE S", not "SAVES".
CmdFn_SAVES:
         jsr     TxtPtrIncr
         jsr     GetFileNameArg
         jsr     FileNameCpyToLineBuffer
         jmp     SaveBackgroundMap

; Transfer vars from $7C, $7D, and $84 to the spots that FindVar uses for the
; search key, then call it
FindVar_7C_7D_84:
         lda     zpBgGotFlag
         sta     zpVarName
         lda     zp7D
         sta     zpVarName+1
         lda     zpForNxtLnLnk
         ora     #$80
         sta     zpVarType
         jsr     FindVar
         jmp     CpyVarPtrToVarData

; BASIC PROGRAM HEADER FORMAT:
; 
; byte 0:        #$02
; bytes 1 - 17:  null-term'd filename (no len byte)
; bytes 18 -19:  program size in bytes
; bytes 20 - 21: pointer to prog start (zpTXTTAB)
; bytes 22-127:  (unused) 
CmdFn_SAVE:
         cmp     #'S'
         beq     CmdFn_SAVES ;divert to save screen, not prog
         jsr     GetFileNameArg
         jsr     FileNameCpyToLineBuffer
         lda     #CAS_HDR_PROG
         sta     lineBuffer
         lda     zpTXTTAB
         sta     lineBuffer+$14
         sta     zpWParam
         lda     zpTXTTAB+1
         sta     lineBuffer+$15
         sta     zpWParam+1
         lda     zpTXTEND
         sta     zpWAccum
         lda     zpTXTEND+1
         sta     zpWAccum+1
         jsr     SetIntAndSubtract ;get prog len from prog start and end
         lda     zpWAccum
         sta     lineBuffer+$12
         lda     zpWAccum+1
         sta     lineBuffer+$13
         jsr     Print_WRITING_fileName
         jsr     CasSendHeader
         jmp     CasSendData

Print_WRITING_fileName:
         lda     #<strWRITING
         sta     zpOutputStr
         lda     #>strWRITING
         sta     zpOutputStr+1
         jsr     PrintString
         beq     PrintFileName ;always branches
Print_LOADING_fileName:
         lda     #<strLOADING
         sta     zpOutputStr
         lda     #>strLOADING
         sta     zpOutputStr+1
         jsr     PrintString
         beq     PrintFileName ;always branches
Print_SKIP_fileName:
         lda     #<strSKIP
         sta     zpOutputStr
         lda     #>strSKIP
         sta     zpOutputStr+1
         jsr     PrintString
PrintFileName:
         lda     #<lineBuffer+1
         sta     zpOutputStr
         lda     #>lineBuffer
         sta     zpOutputStr+1
         jsr     PrintString
         jmp     DoCRLF

LoadSkipFile:
         jsr     Print_SKIP_fileName
         jmp     LD_skipped

; Not in jtbl_Commands: in reality, this is just "LOAD S", not "LOADS".
CmdFn_LOADS:
         jsr     TxtPtrIncr
         jsr     GetFileNameArg
         jmp     LoadBackgroundMap

CmdFn_LOAD:
         ldx     #$00
         stx     zpLoadQFlag
         cmp     #'S'
         beq     CmdFn_LOADS
         cmp     #$8b       ;"LOAD?"?... actually literally the PRINT token
         bne     @notLOADQ  ;no -> leave flag at zero
         dec     zpLoadQFlag ; = #$ff
         jsr     TxtPtrIncr
@notLOADQ:
         jsr     GetFileNameArg
LD_skipped:
         jsr     CasRcvHeader
         bcs     ErrorTapeRead
         jsr     LoadCheckFilename ;does filename match our arg (if any)?
         bcs     LoadSkipFile ;no -> skip this file and try the next
         lda     lineBuffer
         cmp     #CAS_HDR_PROG ;is it a Program header?
         bne     LoadSkipFile ;no; BG header or other. Skip that, too.
         jsr     Print_LOADING_fileName ;yes, this is it! Tell user the good news
         lda     zpLoadQFlag ;"LOAD?"?
         beq     LoadProgram ;no -> load program
         jsr     CasVrfyProgram
         bcs     ErrorTapeRead
         rts

LoadProgram:
         lda     zpTXTTAB   ;don't trust header's load destination; override with TXTTAB
         sta     lineBuffer+$14
         lda     zpTXTTAB+1
         sta     lineBuffer+$15
         jsr     CasRcvFileData
         bcs     ErrorTapeRead
         lda     zpCasBufPtr ;Wherever we finished loading, wll, that's the program
         sta     zpTXTEND   ; end. We should mark it.
         lda     zpCasBufPtr+1
         sta     zpTXTEND+1
         jsr     @nullByteToCasBuf ;put NUL byte there
         jsr     IncrCasBufPtr
         lda     zpCasBufPtr
         sta     zpVARTAB   ;next byte is start of vars
         lda     zpCasBufPtr+1
         sta     zpVARTAB+1
         jsr     @nullByteToCasBuf ;NUL there
         jsr     IncrCasBufPtr
         lda     zpCasBufPtr
         sta     zpVAREND   ;next byte end of vars
         lda     zpCasBufPtr+1
         sta     zpVAREND+1
@nullByteToCasBuf:
         ldy     #$00       ;NUL there
         lda     #$00
         sta     (zpCasBufPtr),y
         rts

ErrorTapeRead:
         lda     #err_TP
         jmp     PrintErrorAndStop

; Used by SAVE, LOAD, etc. Checks if there's a string argument, and if so,
; copies it (temporarily) to upper half of lineBuffer. Otherwise, sets that area
; to 16 blanks (space characters). (It gets copied to (almost) the start of
; lineBuffer, later)
GetFileNameArg:
         jsr     FileNameInit
         lda     #$00
         sta     zpHaveFNameArg
         jsr     IsEndOfCmd ;is there an arg?
         beq     @rts       ;no -> nothing to do; return
         jsr     EvalString ;yes: expect prog name str
         lda     exprParseStk+1
         sta     zpMisc
         lda     exprParseStk+2
         sta     zpMisc+1
         lda     exprParseStk ;is the string empty?
         beq     @rts       ;yes -> return
         ldy     #$00
         ldx     #$00
@cpyName:
         lda     (zpMisc),y ;copy eval'd str as filename
         sta     lineBuffer+$80,x
         inx
         iny
         dec     exprParseStk
         bne     @cpyName
         lda     #$00
         sta     lineBuffer+$80,x
         lda     #$01
         sta     zpHaveFNameArg
@rts:    rts

; Initialize the temporary file name area of lineBuffer (+128) to 16 spaces,
; followed by the null terminator
FileNameInit:
         ldx     #$00
         ldy     #$10
         lda     #$20
@setSpcLp:
         sta     lineBuffer+$80,x
         inx
         dey
         bne     @setSpcLp
         lda     #$00
         sta     lineBuffer+$80,x
         rts

; Copy file name (stored from lineBuffer + 128), to LineBuffer + 1
FileNameCpyToLineBuffer:
         ldx     #$00
         ldy     #$10
@namCpy: lda     lineBuffer+$80,x
         sta     lineBuffer+1,x
         inx
         dey
         bne     @namCpy
         lda     #$00
         sta     lineBuffer+1,x
         rts

LoadCheckFilename:
         lda     zpHaveFNameArg ;did LOAD get a filename arg?
         beq     @success   ;no -> just report true
         ldx     #$00       ;yes: compare
         ldy     #$10       ;16 char max filename
@cmpLp:  lda     lineBuffer+1,x
         cmp     lineBuffer+$80,x
         bne     @failure
         inx
         dey
         bne     @cmpLp
@success:
         clc
         rts

@failure:
         sec
         rts

CmdFn_RESTORE:
         beq     RestoreFromStart ;no arg? restore from start of prog
         jsr     FindLineFromArg
         jsr     SkipLineNumArgs
         lda     #$03
         clc
         adc     zpTxtLink  ;add 3 to found line pointer (skipping line linkage and number)
         sta     zpNextDataPtr ;and set that as next place to start future DATA searches
         lda     #$00
         adc     zpTxtLink+1 ;add any carry
ResFinish:
         sta     zpNextDataPtr+1 ;set high byte of DATA link
         lda     #$00
         sta     zpNextDataIdx ;clear char index
         rts

; Reset DATA pointer to start of first BASIC line.
RestoreFromStart:
         lda     zpTXTTAB
         clc
         adc     #$03       ;init DATA search to begin from first line of program (past initial line)link
         sta     zpNextDataPtr
         lda     #$00
         adc     zpTXTTAB+1
         jmp     ResFinish  ;(just above)

; Skips the next token.
; 
; BUG: does NOT skip entire comments. The DATA token, for instance, will be
; recognized if it occurs within a comment (as a Japanese "small e" ェ)
SkipToken:
         jsr     GetTxtChar
         cmp     #$80       ;have a token?
         bcs     @incrTxtPtrAndReturn ;just increment to skip it
         cmp     #tok_NUM_AFTER ;have a decimal number?
         beq     TxtPtrAdvThree ;skip it
         cmp     #tok_HEX_AFTER ;have a hex number?
         beq     TxtPtrAdvThree ;skip it
         cmp     #tok_LNUM_AFTER ;have a line number?
         beq     TxtPtrAdvThree ;skip it
         cmp     #'"'       ;double-quote?
         beq     READ_skipStrLit ;skip the string literal
         jsr     IsAlpha    ;is it an alphabetic character?
         bcc     SkipVarName ;skip a var name
@incrTxtPtrAndReturn:
         jmp     TxtPtrIncr ;everything else, skip one char

; Advance zpTXTPTR by 3
TxtPtrAdvThree:
         jsr     TxtPtrIncr
         jsr     TxtPtrIncr
         jmp     TxtPtrIncr

eosFnd:  pla                ;restore A
         jmp     TxtPtrIncr

READ_skipStrLit:
         pha
@skipStrLp:
         jsr     TxtPtrIncrAndGetChar
         cmp     #'"'       ;have double-quote?
         beq     eosFnd     ;skipt it then return (we're done!)
         and     #$ff       ;have end-of-line?
         bne     @skipStrLp ;no -> skip char, check next
         pla                ;yes: restore A and return
         rts                ;we've successfully skipped string

; Skips over a variable name. This does not include any trailing '$', just
; alphanumeric strings.
SkipVarName:
         pha
@skipAlNumLp:
         jsr     TxtPtrIncrAndGetChar
         jsr     IsAlNum
         bcc     @skipAlNumLp
         pla
         rts

vZpStrLen .set   $1b
vZpEOsMark .set  $3c
CmdFn_READ:
         jsr     EvalVarNameOrSynErr
         jsr     SaveTXTPTR ;save away current text position
         lda     zpNextDataPtr ;load up TXTPTR with where we left off from previous READs
         sta     zpTXTPTR
         lda     zpNextDataPtr+1
         sta     zpTXTPTR+1
         lda     zpNextDataIdx ;were we in the middle of a line?
         bne     READ_midDataStmt ;yes -> handle
@dataCmdSeekLp:
         jsr     GetTxtChar ;loop until found DATA statement, or end of program
         beq     @foundEol  ;end of line? set up scanning for next one
         cmp     #tok_DATA
         beq     READ_foundDataCmd ;got DATA? -> read from it
         jsr     SkipToken
         jmp     @dataCmdSeekLp

@foundEol:
         jsr     TxtPtrIncrAndGetChar ;adv and get char
         beq     ErrorOutOfData ;a second '\0'? -> we're at the prog end and out of data; error out.
         jsr     TxtPtrAdvThree ;not '\0'. Skip past "next" offset, and line number.
         jmp     @dataCmdSeekLp ;go back to looking for a DATA cmd

ErrorOutOfData:
         lda     #err_OD
         jmp     PrintErrorAndStop

READ_foundDataCmd:
         lda     #$ff       ;not really sure what the point of this is.
         sta     zpNextDataIdx ;just to invalidate curent value I guess?
         jsr     SkipToken  ;skip the DATA token we found
READ_midDataStmt:
         lda     zpVarType  ;get the type of the var we're looking for
         and     #$0f       ;strip the array bit, if present
         cmp     #TYP_STR   ;is it a string?
         beq     READ_seekStrings ;yes -> handle that
         jsr     IsEndOfCmd ;no -> we're seeking ints then
         beq     ErrorOutOfData ;did we run out of data? -> error out
         jsr     READ_parseNumber
         ldy     #$00
         lda     zpWAccum
         sta     (zpVarData),y ;copy number from WAccum into the variable's data
         lda     zpWAccum+1
         iny
         sta     (zpVarData),y
         jsr     IsEndOfCmd ;are we at the end of the DATA command?
         beq     READ_setupNextDataCmdSeek ;yes -> go find next DATA stmt
         jsr     TxtSkipSpaces
         cmp     #','       ;no: check if next char (after spaces) is a comma
         beq     READ_gotDataComma ;comma? -> see if we can start from here next time
         jmp     ErrorTypeMismatch ;not comma: error!

READ_gotDataComma:
         jsr     TxtPtrIncr
         jsr     IsEndOfCmd ;are we at the end of the DATA cmd, after a comma (empty field)?
         beq     ErrorOutOfData ;yes -> error!
         jmp     READ_setupNextReadLoc ;no: we found next READ's field to use

READ_setupNextDataCmdSeek:
         lda     #$00       ;Next READ, search for a DATA statement starting from here.
         sta     zpNextDataIdx
READ_setupNextReadLoc:
         lda     zpTXTPTR   ;Next READ, use the value we're at now.
         sta     zpNextDataPtr ;save current TXTPTR to zpNextDataPtr
         lda     zpTXTPTR+1
         sta     zpNextDataPtr+1
         jsr     RestoreTXTPTR ;and restore TXTPTR to just after the READ variable
         jsr     TxtSkipSpaces
         cmp     #','       ;comma? -> handle next var
         beq     READ_gotReadComma
rts_9FB9:
         rts

READ_gotReadComma:
         jsr     TxtPtrIncr
         jsr     TxtSkipSpaces
         jsr     IsAlpha    ;got alphabetic char?
         bcs     rts_9FB9   ;no -> allow the spurious trailing comma, and finish cmd
         jmp     CmdFn_READ ;yes -> start over again for new variable

READ_seekStrings:
         lda     #$00
         sta     vZpStrLen  ;set string length to zero
         tax
         lda     #','       ;set comma as end-of-string to seek
         sta     vZpEOsMark
         jsr     IsEndOfCmd ;we're not at the end of the command, are we?
         beq     ErrorOutOfData
         cmp     #'"'       ;do we have a double-quote?
         bne     @seekEosLp ;no -> skip skipping it
         sta     vZpEOsMark ;set dbl quot as end-of-string to seek
         jsr     TxtPtrIncr
@seekEosLp:
         lda     (zpTXTPTR),y ;are we at end of the line?
         beq     READ_eocStoreStrVar ;yes -> store the string var
         cmp     vZpEOsMark ;EOS mark (comma or dquot)?
         beq     @eosFnd    ;yes -> store the string var, and possibly skip a comma
         sta     genPurposeBuf,x ;otherwise, copy char into tmp buffer
         inc     vZpStrLen  ;incr string len
         inx
         jsr     TxtPtrIncr ;incr TXTPTR
         jmp     @seekEosLp ;and loop back to check that

@eosFnd: jsr     TxtPtrIncr
         jsr     IsEndOfCmd ;end of the command?
         beq     READ_eocStoreStrVar ;yes -> go and store string var
         cmp     #','       ;comma?
         bne     READ_storeStrVar ;no -> go and store string var
         jsr     TxtPtrIncr ;yes: skip TXTPTR past comma character
         jmp     READ_storeStrVar ;-> go and store string var

READ_eocStoreStrVar:
         lda     #$00       ;mark that we're not in the middle of a line for next READ
         sta     zpNextDataIdx
READ_storeStrVar:
         lda     vZpStrLen  ;move str info onto expression stack
         sta     exprParseStk
         lda     #<genPurposeBuf
         sta     exprParseStk+1
         lda     #>genPurposeBuf
         sta     exprParseStk+2
         jsr     CpyExprStrToStrVar ;and call the fn that will copy that to the var
         jmp     READ_setupNextReadLoc

vZpPlayPtr .set  $91
CmdFn_PLAY:
         jsr     EvalString ;parse following string
         lda     exprParseStk ;is the string empty?
         beq     rts_A086   ;yes -> nothing to do, then
         lda     zpTXTPTR
         pha                ;push TXTPTR to CPU stack
         lda     zpTXTPTR+1
         pha
         lda     exprParseStk+1 ;point TXTPTR at the arg string
         sta     zpTXTPTR
         lda     exprParseStk+2
         sta     zpTXTPTR+1
         lda     #>genPurposeBuf ;point vZpPlayPtr at the general-purpose buffer
         sta     vZpPlayPtr+1
         lda     #<genPurposeBuf
         sta     vZpPlayPtr
         sta     zpPlayVoxIdx
         jsr     PLAY_copyVoiceToGenPurpBuf ;copy one voice from the arg string into genPurposeBuf
         lda     #PLAY_INDEX_V1
         sta     vZpPlayPtr ;advance buffer pointer to start of next voice
         sta     zpPlayVoxIdx+1
         jsr     PLAY_copyVoiceToGenPurpBuf ;copy next voice from the arg string into genPurposeBuf
         lda     #PLAY_INDEX_V2
         sta     vZpPlayPtr ;advance buffer pointer to start of next voice
         sta     zpPlayVoxIdx+2
         jsr     PLAY_copyVoiceToGenPurpBuf ;copy final voice from the arg string into genPurposeBuf
         lda     #$01
         sta     zpNoteRealLen ;initialize note lengths (1, bc will be decremented before check)
         sta     zpNoteRealLen+1
         sta     zpNoteRealLen+2
         lda     #$7f
         sta     SQ1_SWEEP  ;initialize (and disable) the APU sweep registers
         sta     SQ2_SWEEP
         lda     #$07
         sta     zpPlayStatus ;record all three voices as active
         sta     SND_CHN    ;disable DMA and noise channels, enable triangle and the square waves
         lda     #NC_PlayMusic
         sta     zpNMICMD   ;tell NMI handler to start playing the music
@playLp: jsr     StopIfStopKey ;Stop if STOP is pressed
         lda     zpPlayStatus ;check status of player
         bmi     playError  ; < 0? -> error occurred, handle
         bne     @playLp    ; > 0? -> still playing, keep looping
         lda     #NC_NoCmd  ;else, done playing
         sta     zpNMICMD   ;disable NMI command
         sta     SND_CHN    ;disable all sound channels
         pla                ;restore TXTPTR to point at BASIC
         sta     zpTXTPTR+1
         pla
         sta     zpTXTPTR
rts_A086:
         rts                ;-> done!

playError:
         lda     #NC_NoCmd  ;reset NMI handler command
         sta     zpNMICMD
         sta     SND_CHN    ;turn off all sound channels
         jmp     ErrorSyntax ; -> syntax error

NMICMD_PlayMusic:
         txa                ;push X (value is 18)
         pha
         tya                ;push Y
         pha
         lda     #$c0
         sta     JOY2       ;synchronize APU frame counter
         jsr     PM_FeedTheVoices
         pla                ;pull Y
         tay
         pla                ;pull X
         tax
         pla                ;pull A (pushed at start of NMI_DefaultHandler)
         rti                ;-> exit NMI handling

PM_FeedTheVoices:
         lda     #2
         sta     zpCurVoice ;start with third voice (voice 2)
         lda     #CHAN_MASK_TRI ;(the triangle channel)
         sta     zpCurVoxMask
@voiceLp:
         lda     zpPlayStatus ;did a syntax error occur?
         bmi     rts_A0B8   ;yes -> exit NMI so it can be handled by PLAY command
         jsr     PM_FeedCurVoice ;update this voice's state for where we are in the music
         lsr     zpCurVoxMask
         dec     zpCurVoice ;next (lower) voice number
         bpl     @voiceLp   ;-> loop back to handle voice, until all three handled
rts_A0B8:
         rts                ;-> return and exit NMI handler

PM_FeedCurVoice:
         lda     zpPlayStatus
         and     zpCurVoxMask ;is the current voice still playing?
         beq     rts_A0B8   ;no -> return, handle next voice
         ldx     zpCurVoice
         dec     zpNoteRealLen,x ;is this voice currently playing a note or rest?
         bne     rts_A0B8   ;yes -> return, nothing to process
         lda     zpPlayVoxIdx,x
         sta     vZpPlayPtr ;set play ptr to next PLAY char for this voice
         lda     #SHARP_UNUSED
         sta     zpSharpVal ;deactivate sharp by default
PM_DoCurPlayChar:
         ldy     #$00
         lda     (vZpPlayPtr),y ;get cur PLAY char. End of PLAY string for cur voice?
         bne     PM_ProcessCurPlayChar ;not end -> handle the char
         lda     zpPlayStatus
         sec
         sbc     zpCurVoxMask
         sta     zpPlayStatus
         sta     SND_CHN    ;remove this channel's mask from zpPlayStatus
         ldx     zpCurVoice
         lda     vZpPlayPtr
         sta     zpPlayVoxIdx,x ;update this voice's buffer index (so it stays pointing at null char)
         rts                ;-> and return, handle next voice

PM_ProcessCurPlayChar:
         inc     vZpPlayPtr ;increment PLAY ptr (next char)
         cmp     #$20       ;was the play character a SPACE?
         beq     PM_DoCurPlayChar ;yes -> do nothing, handle next char
PM_isCharM:
         cmp     #'M'       ;got 'M' (envelope)?
         bne     PM_isCharO ;no -> check next
         lda     (vZpPlayPtr),y ;get M arg
         beq     PM_SetSyntaxError ;no arg? -> error
         ldx     #ENV_UNUSED ;default (unused) value, assuming arg is '0'
         cmp     #'0'
         beq     @setEnv
         cmp     #'1'
         bne     PM_SetSyntaxError ;neither 0 nor 1? -> error
         ldx     #ENV_USED  ;mark envelope as used
@setEnv: inc     vZpPlayPtr ;advance to next PLAY char
         ldy     zpCurVoice
         stx     zpEnvelope,y ;set env use/don't use for this voice
         bpl     PM_DoCurPlayChar ;-> handle next PLAY char
PM_isCharO:
         cmp     #'O'       ;got 'O' (octave)?
         bne     PM_isCharT ;no -> check next
         lda     (vZpPlayPtr),y ;get O arg
         beq     PM_SetSyntaxError ;no arg? -> error
         inc     vZpPlayPtr ;advance to next char
         cmp     #'6'       ; >= '6'?
         bcs     PM_SetSyntaxError ;yes -> error
         sec
         sbc     #'0'       ;convert from ASCII digit, to binary number
         bcc     PM_SetSyntaxError ; < 0? -> error
         ldx     zpCurVoice
         sta     zpOctave,x ;set the octave value for cur voice
         bpl     PM_DoCurPlayChar ;-> handle next PLAY char
PM_isCharT:
         cmp     #'T'       ;got 'T' (tempo)?
         bne     PM_isCharV ;no -> check next
         lda     (vZpPlayPtr),y ;get T arg
         beq     PM_SetSyntaxError ;no arg? -> error
         inc     vZpPlayPtr ;advance to next PLAY char
         cmp     #'9'       ;arg char too high to be a digit?
         bcs     PM_SetSyntaxError ;yes -> error
         sec
         sbc     #'0'       ;convert from ASCII digit, to binary number
         beq     PM_SetSyntaxError ; <= 0? -> error
         bcc     PM_SetSyntaxError
         ldx     zpCurVoice
         sta     zpTempo,x  ;set tempo for current voice
pmDoCurPlayChar_A138:
         bpl     PM_DoCurPlayChar ;-> handle next PLAY char
PM_isCharV:
         cmp     #'V'       ;got 'V' (volume, or envelope length)?
         bne     PM_isCharY ;no -> check next
         lda     (vZpPlayPtr),y ;get first char of V arg
         beq     PM_SetSyntaxError ;no arg? -> error
         inc     vZpPlayPtr ;advance next PLAY char
         cmp     #':'
         bcs     PM_SetSyntaxError ; > '9'? -> error
         sec
         sbc     #$30       ;convert from ASCII digit, to binary number
         bcc     PM_SetSyntaxError ; < 0? -> error
         cmp     #1         ;was first char a '1'?
         bne     @setVol    ;no -> just a single-digit arg for V, then
         lda     (vZpPlayPtr),y ;else, check for a 2nd digit
         cmp     #'6'       ;char value >= '6'?
         bcs     @setVolOne ;yes -> not part of our arg; so, just '1'
         sec
         sbc     #$30       ;convert from ASCII code, to binary number of digit
         bcc     @setVolOne ;char < '0'? -> not part of arg, so just '1'
         clc
         adc     #$0a       ;the first '1' was a tens digit. Add ten to value from 2nd digit.
         inc     vZpPlayPtr ;advance to next PLAY char
         bne     @setVol    ;-> set the volume
@setVolOne:
         lda     #$01
@setVol: ldx     zpCurVoice
         sta     zpVolume,x ;set volume (or envelope) to user-specified level
         bpl     pmDoCurPlayChar_A138 ;-> handle next PLAY char
PM_SetSyntaxError:
         lda     #$80
         sta     zpPlayStatus
         rts

PM_isCharY:
         cmp     #'Y'       ;got 'Y' (duty)?
         bne     PM_isCharSharp ;no -> check next
         lda     (vZpPlayPtr),y ;get Y arg
         cmp     #'4'       ; >= '4'?
         bcs     PM_SetSyntaxError ;yes -> error
         sec
         sbc     #'0'       ;convert from ASCII code, to binary number
         bcc     PM_SetSyntaxError ; <= 0? -> error
         inc     vZpPlayPtr ;advance to next PLAY char
         lsr     A
         ror     A
         ror     A          ;shift left 3 places, for use as value in APU volume register
         ldx     zpCurVoice
         sta     zpDuty,x   ;save as "duty" value
         bpl     pmDoCurPlayChar_A138 ;-> handle next PLAY char
PM_isCharSharp:
         cmp     #'#'       ;got '#'?
         bne     PM_isCharR ;no -> check next
         lda     #SHARP_USED
         sta     zpSharpVal ;mark next note name as sharp
         bpl     pmDoCurPlayChar_A138 ;-> handle next PLAY char

PM_isCharR:
         cmp     #'R'       ;got 'R'? (rest)
         bne     PM_isCharNoteName ;no -> check next
         jsr     PM_calcNoteLen
         lda     zpCurVoice ;take the current voice #
         asl     A          ;multiply by 4, to get an APU register index
         asl     A
         tay                ;set as the Y-reg value
         lda     #$90       ;silence value for square channels
         cpy     #$08       ;are we on the triangle channel?
         bne     @setVol    ;no -> keep square silence value
         lda     #$00       ;yes -> use silence value for triangle channel
@setVol: sta     SQ1_VOL,y  ;set silence for current voice's sound channel
         rts                ;-> return

PM_isCharNoteName:
         cmp     #'A'       ;char >= 'A'?
         bcc     PM_SetSyntaxError ;no -> syntax error (unrecognized char)
         cmp     #'H'       ;char > 'G'?
         bcs     PM_SetSyntaxError ;yes -> syntax error
         pha                ;push char value
         jsr     PM_calcNoteLen ;get the note length, adjusted by tempo
         ldx     zpCurVoice ;get the current voice number
         txa
         asl     A          ;multiply by 4, for APU register index
         asl     A
         tay
         cmp     #$08       ;is this the triangle channel?
         bne     @square    ;no -> handle for squarewave channel
         lda     zpNoteRealLen,x ;get the tempo-adjusted note length
         sec
         sbc     #$01       ;subtract 1
         cmp     #14        ;less than 14?
         bcc     @notMax    ;yes -> just use the value
         lda     #14        ;else, use max of 14
@notMax: asl     A          ;shift left 2 places
         asl     A
         ldy     zpEnvelope,x ;are we using "envelope" for the triangle channel?
         beq     @keepEnv   ;yes, using -> use our note-len-based value
         lda     #$81       ;no, not using: set control flag, and set counter reload to 1
@keepEnv:
         ldy     #$08
         bne     @setVol

@square: lda     zpVolume,x ;merge the duty, envelope, and volume values
         ora     zpDuty,x
         ora     zpEnvelope,x
@setVol: sta     SQ1_VOL,y  ;write duty, envelope, and volume to APU register
         pla                ;pull the note name ('A' to 'G')
         sec
         sbc     #'A'       ;convert A-G -> 0-6
         tay                ;set as Y-reg value
         lda     zpOctave,x ;get voice's current octave
         tax
         lda     tbl_OctaveBaseNoteVals,x ;get base note value for the current octave
         clc
         adc     tbl_NoteNameToValue,y ;add to that, the value for the note name
         adc     zpSharpVal ;add 2 if it's sharped
         tax                ;save note value in X reg
         lda     zpCurVoice ;get current voice
         asl     A          ;times 4 for APU register index
         asl     A
         tay                ;save in Y reg
         cmp     #$08       ;triangle channel?
         bne     @sq        ;no -> use note value as-is for square waves
         txa                ;yes, triangle: add one octave to get the actual note we'll use
         clc
         adc     #NOTE_VAL_OCTAVE
         tax
@sq:     lda     tbl_NoteValToPdLen,x ;get the period length for the note value,
         sta     SQ1_LO,y   ; and set the appropriate APU registers to trigger
         lda     tbl_NoteValToPdLen+1,x ; our note's pitch
         sta     SQ1_HI,y
         rts                ;-> return

PM_calcNoteLen:
         lda     (vZpPlayPtr),y ;load the next char after note name (or 'R')
         beq     @parseDone ;no char after? -> done parsing
         cmp     #':'       ; > '9'?
         bcs     @parseDone ;yes -> not a note length, done parsing
         sec
         sbc     #'0'       ;convert from ASCII digit code, to binary number
         bcc     @parseDone ; < 0? -> not a note length, done parsing
         tax
         lda     tbl_NoteLengths,x ;convert number to a note length (from table)
         ldx     zpCurVoice
         sta     zpNoteLen,x ;set note length for this voice
         inc     vZpPlayPtr ;advance to next PLAY char
@parseDone:
         jsr     ClearOperandHiBytes
         ldx     zpCurVoice
         lda     zpNoteLen,x ;stick note length into WAccum (single byte)
         sta     zpWAccum
         lda     zpTempo,x
         sta     zpWParam   ;stick voice's tempo mark into WParam (single byte)
         jsr     WordMultiply ;multiply these
         lda     zpWAccum
         ldx     zpCurVoice
         sta     zpNoteRealLen,x ;set it as the "real" note length
         lda     vZpPlayPtr
         sta     zpPlayVoxIdx,x ;update the PLAY buffer index for this voice
         rts                ;-> and return

PLAY_copyVoiceToGenPurpBuf:
         lda     exprParseStk ;end of string?
         beq     @nullTerm  ;yes -> null-terminate and return
         dec     exprParseStk ;decrement string length
         jsr     TxtPtrGetCharAndIncr ;get a char from the string (and increment pointer)
         cmp     #':'       ;colon? -> null-terminate and return
         beq     @nullTerm
         ldy     #$00
         sta     (vZpPlayPtr),y ;copy it into general-purpose buffer
         inc     vZpPlayPtr ;advance genPurposeBuf pointer
         bne     PLAY_copyVoiceToGenPurpBuf ;(always) -> loop around to copy next character
@nullTerm:
         ldy     #$00
         lda     #$00
         sta     (vZpPlayPtr),y ;terminate with a null char
         rts

errSyn_A25F:
         jmp     ErrorSyntax

errIllVal_A262:
         jmp     ErrorIllegalValue

AdvThenEvalByteInt:
         jsr     TxtPtrIncr
         jmp     EvalByteInteger

EvalCommaThenByteInt:
         jsr     SkipCommaOrSynErr
EvalByteInteger:
         jsr     FrmEval
         jsr     ErrorUnlessInteger
         lda     exprParseStk+1 ;anything in the high byte?
         bne     errIllVal_A262 ;We're looking for values that fit in a byte
         lda     exprParseStk
         rts

EvalString:
         jsr     FrmEval
         jmp     ErrorUnlessString

; Evaluate the formula at the current location in the BASIC program tokenized
; text.
FrmEval: lda     #$00
         sta     zpArgTyp
         sta     zpExprStkIdx
         lda     #$80
         sta     zpGpStrIdx
         jsr     Expression
         lda     zpArgTyp
         beq     errSyn_A25F
         rts

EnsureIntAndSkipToken:
         jsr     ErrorUnlessInteger
         jmp     TxtPtrIncr

; The formula evaluator does a recursive parser thing, instead of operator
; precedence. Most of these parsers are in page $A2. One first calls Expression
; (this fn), which calls ExprOR, which calls ExprAND, etc, until it gets about 9
; calls deep and finally hits ExprUnaryOrLiteral, which processes unary ops,
; vars, and literals, and then if it finds a binary op it sets the accumulator
; to that op's token code, and falls back up the chain, letting one of the
; recursive handlers deal with it. This technique is easier to code, but not
; terribly efficient.
; 
; Expression itself (this fn) directly handles XOR expressions (the lowest-
; precedence binary op), delegating to ExprOr (and below) for any higher-
; precedence op than XOR.
Expression:
         jsr     ExprOr     ;process more tightly-bound operations
AgainXor:
         cmp     #tok_OP_XOR ;we at an XOR token?
         beq     @xor       ;yes -> handle
         rts                ;no: all done evaluating expressions!

@xor:    jsr     EnsureIntAndSkipToken ;expect int (boolean)
         jsr     ExprOr     ;eval 2nd operand
         jsr     IntPullWParamGetWAccum ;expect that to be an int too, and prep args
         lda     zpWAccum
         eor     zpWParam   ;XOR the low bytes
         sta     zpWAccum
         lda     zpWAccum+1
         eor     zpWParam+1 ;XOR the high bytes
         sta     zpWAccum+1
         jsr     ReplaceExprStkTopWAccum ;replace top stack item
         jmp     AgainXor   ;and go evaluate any further expressions

; Parse an OR expression, or an expression of higher precedence.
ExprOr:  jsr     ExprAnd    ;process more tightly-bound operations
AgainOr: cmp     #tok_OP_OR ;we at an OR token?
         beq     @or        ;yes -> handle
         rts                ;no OR; wind our way up to lower-precedence ops

@or:     jsr     EnsureIntAndSkipToken ;expect int (boolean)
         jsr     ExprAnd    ;eval 2nd operand
         jsr     IntPullWParamGetWAccum ;expect that to be an int too, and prep args
         lda     zpWAccum
         ora     zpWParam   ;OR the low bytes
         sta     zpWAccum
         lda     zpWAccum+1
         ora     zpWParam+1 ;OR the high bytes
         sta     zpWAccum+1
         jsr     ReplaceExprStkTopWAccum ;replace top stack item
         jmp     AgainOr    ;and go check for a proceeding OR expression

; Parse an AND expression, or an expression of higher precedence.
ExprAnd: jsr     ExprRelOp  ;process more tightly-bound operations
AgainAnd:
         cmp     #tok_OP_AND ;we at an AND token?
         beq     @and       ;yes -> handle
         rts                ;no AND; wind our way up to lower-precedence ops

@and:    jsr     EnsureIntAndSkipToken ;expect int (boolean)
         jsr     ExprRelOp  ;eval 2nd operand
         jsr     IntPullWParamGetWAccum ;expect that to be an int too, and prep args
         lda     zpWAccum
         and     zpWParam   ;AND the low bytes
         sta     zpWAccum
         lda     zpWAccum+1
         and     zpWParam+1 ;AND the high bytes
         sta     zpWAccum+1
         jsr     ReplaceExprStkTopWAccum ;replace top stack item
         jmp     AgainAnd   ;and go check for a proceeding AND expression

; Parse a relational expression (<>, >=, <=, =, >, <) or an expression
; of higher precedence.
ExprRelOp:
         jsr     ExprPlusMinus ;process more tightly-bound operations
AgainRelOp:
         cmp     #tok_OP_NE ;is the next byte a token greater or equal to '<>'?
         bcs     maybeRel   ;yes, check more
rts_A30B:
         rts                ;no rel op; wind our way up to lower-precedence ops

maybeRel:
         cmp     #tok_OP_PLUS ;is it a token >= '+'?
         bcs     rts_A30B   ;yes -> not a rel op
         sec
         sbc     #tok_OP_NE ;subtract '<>' tok val and multiply by 2
         asl     A          ; to get an index
         tax
         lda     jtbl_RelOps,x ;load and push ptr to this op's handling routine
         pha
         lda     jtbl_RelOps+1,x
         pha
         lda     zpArgTyp   ;also push type of 1st operand
         pha
         jsr     TxtPtrIncr ;move past operator token
         jsr     ExprPlusMinus ;and eval 2nd operand (as any more tightly-bound expr)
         pla                ;pull and compare 1st operand type
         cmp     zpArgTyp   ;diff from 2nd operand's type?
         bne     errTypeMism_A370 ;yes -> error
         jsr     PullWParamGetWAccum ;get args into WAccum, WParam
         pla
         sta     zpMisc+1   ;pull handler routine and place in zpMisc
         pla
         sta     zpMisc
         jsr     JmpIndirectZpMisc ;execute!
         ldx     #TYP_INT   ;no matter what type args had, result is int (0 or -1)
         stx     zpArgTyp
         jmp     AgainRelOp ;check for any more rel ops to eval

JmpIndirectZpMisc:
         jmp     (zpMisc)

; Parse an addition or subtraction expression, or an expression of higher
; precedence.
ExprPlusMinus:
         jsr     ExprMod    ;process more tightly-bound operations
AgainPlusMinus:
         cmp     #tok_OP_PLUS ;next token == '+'?
         beq     @add       ;yes -> handle add
         cmp     #tok_OP_MINUS ;else, next token == '-'?
         beq     @sub       ;yes -> handle subtract
         rts                ;no add or subtract; wind our way up to lower-precedence ops

@add:    jsr     @prepArgs  ;get args from stack into WAccum, WParam
         jsr     AddAndReplaceExpr ;do the add
         jmp     AgainPlusMinus ;and any other add/subtract operations that immediately follow

@sub:    jsr     @prepArgs  ;get args from stack into WAccum, WParam
         jsr     SubtractAndReplaceExpr ;do the subtract
         jmp     AgainPlusMinus ;and any other add/subtract operations that immediately follow

@prepArgs:
         lda     zpArgTyp   ;get/push arg type before evaluating 2nd arg expr
         pha
         jsr     TxtPtrIncr ;move past '+' or '-' operator
         jsr     ExprMod    ;eval 2nd operand (as any more tightly-bound expr)
         pla                ;pull type of preceding operand
         cmp     zpArgTyp   ;do operand types differ?
         bne     errTypeMism_A370 ;yes -> error
         jmp     PullWParamGetWAccum ;get operands into WAccum, WParam, and return

errTypeMism_A370:
         jmp     ErrorTypeMismatch

; Parse a modulo expression, or an expression of higher precedence.
ExprMod: jsr     ExprMulDiv ;process more tightly-bound operations
AgainMod:
         cmp     #tok_OP_MOD ;is the next token a MOD?
         beq     @mod       ;yes -> perform modulo op
         rts                ;no mod; wind our way up to lower-precedence ops

@mod:    lda     zpArgTyp   ;get/push arg type before evaluating 2nd arg expr
         pha
         jsr     TxtPtrIncr ;move past MOD operator
         jsr     ExprMulDiv ;eval 2nd operand (as any more tightly-bound expr)
         pla                ;pull type of preceding operand
         cmp     zpArgTyp   ;do operand types differ?
         bne     errTypeMism_A370 ;yes -> error
         jsr     PullWParamGetWAccum ;get operands into WAccum, WParam
         jsr     ModAndReplaceExpr ;perform modulo
         jmp     AgainMod   ;and any other modulo operations that immediately follow

; Parse a multiplication or division expression, or an expression of higher
; precedence.
ExprMulDiv:
         jsr     ExprLiteralUnaryOrFn ;parse literal, unary, or function expr
AgainMulDiv:
         cmp     #tok_OP_DIV ;is the next token a '/'?
         beq     @div       ;yes -> perform division
         cmp     #tok_OP_MUL ;or maybe it's a '*'?
         beq     @mul       ;yes -> perform multiplication
         rts                ;no mul or div; wind our way up to lower-precedence ops

@div:    jsr     @prepArgs  ;get args from stack into WAccum, WParam
         jsr     DivAndReplaceExpr ;perform the division
         jmp     AgainMulDiv ;perform any immediately following mul or div

@mul:    jsr     @prepArgs  ;get args from stack into WAccum, WParam
         jsr     MulAndReplaceExpr ;perform the multiplication
         jmp     AgainMulDiv ;perform any immediately following mul or div

@prepArgs:
         lda     zpArgTyp   ;get/push arg type before evaluating 2nd arg expr
         pha
         jsr     TxtPtrIncr ;move past '/' operator
         jsr     ExprLiteralUnaryOrFn ;eval 2nd operand
         pla                ;pull 1st arg's type and compare
         cmp     zpArgTyp   ;do operand types differ?
         bne     errTypeMism_A370 ;yes -> error
         jmp     PullWParamGetWAccum ;get operands into WAccum, WParam

IntPullWParamGetWAccum:
         jsr     ErrorUnlessInteger
PullWParamGetWAccum:
         ldx     zpExprStkIdx ;get parse stack position
         cpx     #$7d       ;less than 3 from the end?
         bcs     errIll_A407 ;yes -> error... shouldn't this be out of memory,
         dex                ; instead of illegal? also we're literally about to
         dex                ; reduce the stack size by 3, so why do we even
         dex                ; need this check?
         stx     zpExprStkIdx ;pull last result off of stack, and place in WParam
         lda     exprParseStk,x
         sta     zpWParam
         lda     exprParseStk+1,x
         sta     zpWParam+1
         lda     exprParseStk+2,x
         sta     zpWParam+2
         dex
         dex
         dex
         lda     exprParseStk,x ;get preceding result off expr stack, place in WAccum
         sta     zpWAccum   ;doesn't pull - caller will typically replace
         lda     exprParseStk+1,x ; with its result
         sta     zpWAccum+1
         lda     exprParseStk+2,x
         sta     zpWAccum+2
         rts

; Evaluate the following unary or literal expression, and then copy the
; evaluated result into WAccum
EvalUnaryIntoWAccum:
         jsr     TxtPtrIncr ;advance to next token char
         jsr     ExprLiteralUnaryOrFn ;parse whatever's there
         ldx     zpExprStkIdx
         dex
         dex
         dex
         lda     exprParseStk,x
         sta     zpWAccum   ;move evaluation result into zpWAccum
         lda     exprParseStk+1,x ;(result still remains on expression stack)
         sta     zpWAccum+1
         rts

errIll_A407:
         jmp     ErrorIllegalValue

DoExprNegate:
         jsr     EvalUnaryIntoWAccum ;get following atomic expression into WAccum
         jsr     WAccumNegate ;and negate it
         lda     zpWAccum   ;copy result to parsed-expression stack
         sta     exprParseStk,x
         lda     zpWAccum+1
         sta     exprParseStk+1,x
         jmp     TxtSkipSpaces

DoExprNot:
         jsr     EvalUnaryIntoWAccum
         lda     #$ff
         sec
         sbc     exprParseStk,x
         sta     exprParseStk,x
         lda     #$ff
         sec
         sbc     exprParseStk+1,x
         sta     exprParseStk+1,x
         jmp     SetIntTypAndSkipSpc

vZpSavX  .set    $19
vZpSavY  .set    $90
ParseStrLit:
         jsr     TxtPtrIncr
         ldy     #$00
         ldx     zpGpStrIdx
@cpyLp:  lda     (zpTXTPTR),y ;copy literal contents into genPurposeBuf as temp str
         beq     @eol       ;end of line? -> done copying
         cmp     #'"'       ;end of string literal found?
         beq     @afterCopy ;yes -> package up for exprParseStk
         sta     genPurposeBuf,x
         inx
         iny
         cpy     #$20       ;32 chars reached?
         beq     errIll_A407 ;yes -> illegal
         jmp     @cpyLp

@afterCopy:
         jsr     TxtPtrIncr
@eol:    stx     vZpSavX
         sty     vZpSavY
         tya
         clc
         adc     zpTXTPTR
         sta     zpTXTPTR   ;advance zpTXTPTR past the end of string literal
         lda     #$00
         adc     zpTXTPTR+1
         sta     zpTXTPTR+1
         ldx     zpExprStkIdx
         lda     vZpSavY    ;push str len to parse stack
         sta     exprParseStk,x
         lda     zpGpStrIdx ;push pointer to tmp string on parse stack
         sta     exprParseStk+1,x
         lda     #>genPurposeBuf
         sta     exprParseStk+2,x
         inx
         inx
         inx
         stx     zpExprStkIdx ;update stack pointer past newly-pushed stuff
         lda     vZpSavX
         sta     zpGpStrIdx ;update temp string index past what we copied in
         lda     #TYP_STR   ;indicate cur expr is string
         sta     zpArgTyp
         jmp     TxtSkipSpaces

errSyn_A484:
         jmp     ErrorSyntax

doExprNot_A487:
         jmp     DoExprNot

doExprNegate_A48A:
         jmp     DoExprNegate

txtPtrIncr_A48D:
         jsr     TxtPtrIncr
; Handles literals, unary operators (-, +, NOT, etc), and literals.
ExprLiteralUnaryOrFn:
         jsr     IsEndOfCmd ;is this the end of the command ('\0' or ':')?
         beq     errSyn_A484 ;yes -> syntax error (we're expecting an op or atom!)
         cmp     #11        ;have a single-digit number?
         bcc     ParseSingleDigitNum
         cmp     #tok_OP_MINUS ;unary '-'?
         beq     doExprNegate_A48A
         cmp     #tok_OP_NOT ;NOT unary op?
         beq     doExprNot_A487
         cmp     #tok_NUM_AFTER ;decimal number?
         beq     ParseNumLiteral
         cmp     #tok_HEX_AFTER ;hex number?
         beq     ParseNumLiteral
         cmp     #tok_OP_PLUS ;unary '+'?
         beq     txtPtrIncr_A48D ;yes -> (no effect - just incr zpTXTPTR!)
         cmp     #'('       ;parenthesized expression?
         beq     DoExprParens
         cmp     #'"'       ;string literal?
         beq     ParseStrLit
         cmp     #'A'       ;punctuation or raw digits?
         bcc     errSyn_A4E4 ;matched -> syntax error
         cmp     #'['       ;'A' thru 'Z'?
         bcc     DoExprVarName ;yes -> handle (presumed) var name
         cmp     #tok_MOVE  ;MOVE fn?
         beq     exprMove_A4E7 ;-> eval that
         cmp     #tok_ABS
         bcc     errSyn_A4E4 ;error unless we have a token >= ABS but < XOR
         cmp     #tok_OP_XOR ;(BASIC built-in functions)
         bcs     errSyn_A4E4
         sec
         sbc     #tok_ABS   ;subtract value of tok_ABS
         asl     A          ;and double for pointer index
         tax
         lda     jtbl_Functions,x ;lookup the function, evaluate it, and return
         sta     zpMisc
         lda     jtbl_Functions+1,x
         sta     zpMisc+1
         jsr     TxtPtrIncr ;move TXTPTR past function token
         jsr     TxtSkipSpaces
         jsr     JmpIndirectZpMisc
         jmp     TxtSkipSpaces

errSyn_A4E4:
         jmp     ErrorSyntax

exprMove_A4E7:
         jmp     ExprMove

DoExprParens:
         jsr     TxtPtrIncr
         jsr     Expression
         jsr     SkipRParenOrSynErr
         jmp     TxtSkipSpaces

ParseNumLiteral:
         ldx     zpExprStkIdx
         ldy     #$01
         lda     (zpTXTPTR),y
         sta     exprParseStk,x ;move numeric literal directly onto parse stack
         iny                ;(not including leading token byte)
         inx
         lda     (zpTXTPTR),y
         sta     exprParseStk,x
         inx                ;increment index ("push" the literal onto the expr stack)
         inx
         stx     zpExprStkIdx
         jsr     TxtPtrAdvThree ;advance zpTXTPTR past the literal
SetIntTypAndSkipSpc:
         lda     #TYP_INT
         sta     zpArgTyp
         jmp     TxtSkipSpaces

ParseSingleDigitNum:
         ldx     zpExprStkIdx
         sta     exprParseStk,x ;store the digit into the parse buffer
         dec     exprParseStk,x ;and decrement to the true number value
         lda     #$00
         sta     exprParseStk+1,x ;store the high byte (#$00)
         inx
         inx
         inx
         stx     zpExprStkIdx ;incr buffer index past number, and terminating null?
         jsr     TxtPtrIncr ;advance to next byte of tokenized line
         jmp     SetIntTypAndSkipSpc

DoExprVarName:
         jsr     EvalVarName
         ldx     zpExprStkIdx
         lda     zpVarType  ;get the variable data's type
         and     #$0f       ;(ignore whether or not it's from an array)
         cmp     #TYP_STR   ;is it a string?
         beq     DEVN_exprStr ;yes -> do string stuff
         ldy     #$00       ;no: we have an int
         lda     (zpVarData),y ;copy int onto parse stack
         sta     exprParseStk,x
         iny
         lda     (zpVarData),y
         sta     exprParseStk+1,x
         iny
         lda     (zpVarData),y ;and the... type ID byte of the var that follows it?
         sta     exprParseStk+2,x ;I suppose it's just a padding byte to make the size come out right
DEVN_advExprAndRts:
         inx
         inx
         inx
         stx     zpExprStkIdx ;advance parse stack index past the evaluated var data
         lda     zpVarType  ;and set var type as current expr value's type
         and     #$0f
         sta     zpArgTyp
         jmp     TxtSkipSpaces ;skip spaces and return

DEVN_exprStr:
         ldy     #$00
         lda     (zpVarData),y
         sta     exprParseStk,x ;strlen -> parse stack
         lda     #$01
         clc
         adc     zpVarData  ;then pointer at str contents
         sta     exprParseStk+1,x
         lda     #$00
         adc     zpVarData+1
         sta     exprParseStk+2,x
         jmp     DEVN_advExprAndRts ;advance the parse stack index and return

errSyn_A573:
         jmp     ErrorSyntax

; Given a var name at zpTXTPTR, looks it up and points zpVarData at its
; contents.
zpArrayVarIdx .set $19
vZpMaxIdx .set   $4a        ;The max indices for an array var's dimensions
vZpSkipVarBaseType .set $73 ;underlying (non-array) base type for the array var we're skipping
vZpAryNumDimens .set $74    ;dimensionality of array var, -1 (0 or 1)
EvalVarNameOrSynErr:
         jsr     IsAlpha
         bcs     errSyn_A573
         ldx     #$00
         stx     zpExprStkIdx ;empty the parse stack
EvalVarName:
         ldx     #$00
         stx     zpVarName+1 ;clear variable name second byte
         sta     zpVarName  ;store var name first char (we already got)
         jsr     TxtPtrIncrAndGetChar ;get next char from line
         jsr     IsAlNum    ;is it alphanumeric?
         bcs     @nonAlNum  ;no -> look into that
         sta     zpVarName+1 ;yes, store as var name 2nd char
@alNumLp:
         jsr     TxtPtrIncrAndGetChar ;loop over any remaining alphanumeric chars, ignoring
         jsr     IsAlNum
         bcc     @alNumLp
@nonAlNum:
         lda     #TYP_INT
         sta     zpVarType
         jsr     TxtSkipSpaces
         cmp     #'$'
         bne     @notStr
         lda     #TYP_STR
         sta     zpVarType
         jsr     TxtPtrIncr
@notStr: jsr     TxtSkipSpaces
         cmp     #'('       ;array index?
         beq     EvalArrayVar ;yes -> handle array var index
         jsr     FindVar    ;find the var (string or int)
         bcs     EVN_varFound ;found -> get its data
         ldy     #$00       ;not found. Make one!
         lda     zpVarType  ;(we're at end of vars tab now)
         sta     (zpVARPTR),y ;store variable type
         iny
         lda     zpVarName  ;store variable name
         sta     (zpVARPTR),y
         iny
         lda     zpVarName+1
         sta     (zpVARPTR),y
         iny
         lda     #$00
         sta     (zpVARPTR),y ;store zeroes to next three bytes
         iny                ;(appropriate for both int AND str!)
         sta     (zpVARPTR),y
         iny
         sta     (zpVARPTR),y ;(third byte indicates vars tab end, if INT)
         lda     zpVarType
         cmp     #TYP_INT
         beq     @int       ;int? ->
         lda     #$00       ;string. Clear its contents to zero.
         ldx     #$21
@clearStrLp:
         iny
         sta     (zpVARPTR),y
         dex
         bne     @clearStrLp
         lda     #$21
@int:    clc
         adc     #$03       ;add size of var type, name, and data to VARPTR
         adc     zpVARPTR
         sta     zpWAccum
         lda     #$00
         adc     zpVARPTR+1
         sta     zpWAccum+1
         jsr     CheckFreeSpaceOrError ;error if we have insufficient free space for new var
         lda     zpWAccum
         sta     zpVAREND   ;record the new vars table end location
         lda     zpWAccum+1
         sta     zpVAREND+1
EVN_varFound:
         clc
         lda     #$03
         adc     zpVARPTR   ;add 3 to VARPTR to skip type and name
         sta     zpVarData  ;and store result in zpVarData
         lda     #$00
         adc     zpVARPTR+1
         sta     zpVarData+1
         rts

CpyVarPtrToVarData:
         lda     zpVARPTR
         sta     zpVarData
         lda     zpVARPTR+1
         sta     zpVarData+1
rts_A610:
         rts

ParseIntExprOrTMErr:
         jsr     Expression
         lda     #$02
         cmp     zpArgTyp
         beq     rts_A610
errTypMism_A61A:
         jmp     ErrorTypeMismatch

singleIdxAry:
         jmp     EvalSingleIdxAryVar

EvalArrayVar:
         lda     zpVarName
         pha
         lda     zpVarName+1
         pha
         lda     zpVarType
         ora     #TYP_ARRAY_FLAG ;high bit = "array" flag?
         pha
         jsr     TxtPtrIncr
         jsr     ParseIntExprOrTMErr ;evaluate int expression for array index
         ldx     zpExprStkIdx
         dex
         dex
         dex
         lda     exprParseStk,x ;save away first byte of idx
         pha
         jsr     ParsStkPopIdx ;verify idx fits in 1 byte, and pop from parse stack
         bcc     singleIdxAry ;only one index? -> handle
; If we reach here, there's a second index provided for this array
         jsr     SkipCommaOrSynErr
         jsr     ParseIntExprOrTMErr ;evaluate int expr for 2nd index
         ldx     zpExprStkIdx
         dex
         dex
         dex
         lda     exprParseStk,x ;save away first byte of 2nd idx
         pha
         jsr     ParsStkPopIdx ;verify idx fits in 1 byte, and pop from parse stack
         bcs     errTypMism_A61A ;didn't end with ')'? -> error!
         jsr     TxtPtrIncr ;advance TXTPTR past closing parenthesis
         pla
         sta     zpMisc+2   ;restore 2nd index (to $1B)
         pla
         sta     zpArrayVarIdx ;restore 1st index (to $19)
         pla
         sta     zpVarType  ;restore var type
         pla
         sta     zpVarName+1 ;restore 2nd byte of variable name
         pla
         sta     zpVarName  ;restore 1st byte of var name
         jsr     FindVar    ;find the matching variable
         bcc     errIllVal_A6BA ;didn't find? -> error IL (arrays must be DIM'd before use)
         ldy     #$03
         lda     (zpVARPTR),y ;is the found array var 2-dimensional?
         beq     errIllVal_A6BA ;no -> error (we're looking for 2-dimensional)
         iny
         lda     (zpVARPTR),y ;get max idx for first dimen
         cmp     zpArrayVarIdx ;less than the specified 1st index?
         bcc     errIllVal_A6BA ;yes -> error
         tax                ;save max idx to x
         iny
         lda     (zpVARPTR),y ;get max idx for second dimen
         cmp     zpMisc+2   ;less than the specified 2nd index?
         bcc     errIllVal_A6BA ;yes -> error
         jsr     ClearOperandHiBytes
         inx                ;max idx, +1 -> num elements in 1st dim
         bne     @not256
         inc     zpWAccum+1
@not256: stx     zpWAccum
         lda     zpMisc+2
         sta     zpWParam
         jsr     WordMultiply ;times value for 2nd index
         lda     zpArrayVarIdx
         sta     zpWParam
         jsr     SetIntAndAdd ;and add the value of the 1st index
         jsr     GetSizeOfElementType
         sta     zpWParam
         jsr     WordMultiply ;multiply by size of element type
         lda     #$06       ;add size of two-dimension array variable preamble
EAV_getArrayElem:
         sta     zpWParam
         jsr     SetIntAndAdd ;do the preamble add
         lda     zpVARPTR
         sta     zpWParam
         lda     zpVARPTR+1
         sta     zpWParam+1
         jsr     SetIntAndAdd ;add to the current pointer into var tab (pointing at found var)
         lda     zpWAccum   ;save result as ptr to the element value
         sta     zpVarData
         lda     zpWAccum+1
         sta     zpVarData+1
         rts

errIllVal_A6BA:
         jmp     ErrorIllegalValue

EvalSingleIdxAryVar:
         jsr     TxtPtrIncr
         pla
         sta     zpArrayVarIdx ;restore the index value
         pla
         sta     zpVarType  ;this will have high-bit set now!
         pla
         sta     zpVarName+1 ;restore var name
         pla
         sta     zpVarName
         jsr     FindVar
         bcc     errIllVal_A6BA ;didn't find -> error IL (arrays must be DIM'd before use)
         ldy     #$03
         lda     (zpVARPTR),y ;is the found array var 2-dimensional?
         bne     errIllVal_A6BA ;yes -> error (we're looking for single!)
         iny
         lda     (zpVARPTR),y ;get max array index
         cmp     zpArrayVarIdx ;is it less than the index used in the expression?
         bcc     errIllVal_A6BA ;yes -> error
         lda     zpArrayVarIdx
         sta     zpWAccum
         jsr     GetSizeOfElementType
         sta     zpWParam
         jsr     ClearOperandHiBytes
         jsr     WordMultiply ;multiply index by size of elements
         lda     #$05       ;add size of single-dimension array variable preamble
         jmp     EAV_getArrayElem

; Pops the evaluated array index off the parse stack, erroring if the index
; value exceeds one byte (too big to be an index!). Returns with carry clear if
; and only if next token is a closing parenthesis (')')
ParsStkPopIdx:
         lda     exprParseStk+1,x ;second index byte is #$00?
         bne     errIllVal_A6BA ;no -> too big! error
         stx     zpExprStkIdx ;save our backed-up stack index
         jsr     TxtSkipSpaces
         cmp     #')'       ;next char == ')'?
         bne     @retFalse  ;no -> return false
         clc                ;yes, return true
         rts

@retFalse:
         sec
         rts

GetSizeOfElementType:
         lda     zpVarType
         and     #$0f
GetSizeOfType:
         cmp     #TYP_INT
         beq     @rts       ;INT? type #$02, has size #$02... -> just return!
         lda     #33        ;strings are 33 bytes total. 1 len, 31 content, 1 terminating null
@rts:    rts

; Finds variable record from zpVarName ($8A.8B) and zpVarType ($90, temp use).
; Unlike most other routines in Family BASIC, exiting with carry set indicates
; success, reset indicates failure.
FindVar: lda     zpVARTAB
         sta     zpVARPTR
         lda     zpVARTAB+1
         sta     zpVARPTR+1
@findVarLoop:
         ldy     #$00
         lda     (zpVARPTR),y ;end of variables table?
         beq     @retFail   ;yes -> FAIL
         cmp     zpVarType  ;matches our sought variable type?
         bne     @skipVar   ;no -> skip to next var
         iny
         lda     (zpVARPTR),y
         cmp     zpVarName  ;first letter of var name matches?
         bne     @skipVar   ;no -> skip to next var
         iny
         lda     (zpVARPTR),y
         cmp     zpVarName+1 ;second char of var name matches?
         bne     @skipVar   ;no -> skip to next var
         sec                ;var matched- return success (carry set)!
         rts

@skipVar:
         ldy     #$00       ;skipVar
         lda     (zpVARPTR),y ;is it an array type?
         bmi     @skipAryVar ;yes -> handle skipping array
         jsr     GetSizeOfType ;no, get basic type size
         clc
         adc     #$03       ;add the 3 bytes for type and name
         adc     zpVARPTR   ;and add to variables table index to skip the var
         sta     zpVARPTR
         lda     #$00
         adc     zpVARPTR+1
         sta     zpVARPTR+1
@contIfNotVarsEnd:
         lda     zpVAREND   ;did we reach end of var table?
         cmp     zpVARPTR
         bne     @findVarLoop ;no -> check next var for a match
         lda     zpVAREND+1 ;low byte matched.
         cmp     zpVARPTR+1 ;does high byte?
         bne     @findVarLoop ;no -> check next var for a match
@retFail:
         clc                ;yes: end of vars with no match. Return failure (carry clear)
         rts

@skipAryVar:
         and     #$0f
         sta     vZpSkipVarBaseType ;record array's element type (stripping array flag)
         ldy     #$03
         lda     (zpVARPTR),y
         sta     vZpAryNumDimens ;number of array dimensions, minus one.
         iny
         lda     (zpVARPTR),y
         sta     vZpMaxIdx  ;max index of array
         iny
         lda     (zpVARPTR),y ;max index of 2nd dimension of array (if 2 dimension)
         sta     vZpMaxIdx+1 ;(otherwise, this is first byte of first element!)
         jsr     ClearOperandHiBytes ;clear WParam+1, WAccum+1
         sta     zpWParam   ;clear low byte of WParam as well
         lda     vZpMaxIdx
         sta     zpWAccum   ;1st dimension max index goes into WAccum
         lda     vZpAryNumDimens ;one-dimensional array, or two?
         beq     @oneDim    ;one -> leave WParam zero (ought to skip the first multiply, but doesn't)
         lda     vZpMaxIdx+1 ;two: max idx of 2nd dimension -> WParam
         sta     zpWParam
@oneDim: inc     zpWAccum   ;increment WParam (max idx -> number-of-elements)
         bne     @waHi
         inc     zpWAccum+1
@waHi:   inc     zpWParam   ;increment WAccum (max idx -> number-of-elements)
         bne     @wpHi
         inc     zpWParam+1
@wpHi:   jsr     WordMultiply ;multiply them (now have total number of elements)
         lda     vZpSkipVarBaseType
         jsr     GetSizeOfType ;get element type size
         sta     zpWParam   ;store in WParam
         lda     #$00
         sta     zpWParam+1
         jsr     WordMultiply ;multiply
         lda     #$05       ;total number of bytes for the elements
         sta     zpWParam   ; plus 5 for array type and name, and max index value
         lda     vZpAryNumDimens
         beq     @oneDim2
         inc     zpWParam   ;...make that 6, for the two max index entries
@oneDim2:
         jsr     SetIntAndAdd ;(do that add)
         lda     zpVARPTR
         sta     zpWParam
         lda     zpVARPTR+1
         sta     zpWParam+1
         jsr     SetIntAndAdd ;now add to our index into the variables table
         lda     zpWAccum   ;and put result back into index
         sta     zpVARPTR
         lda     zpWAccum+1
         sta     zpVARPTR+1
         jmp     @contIfNotVarsEnd ;we succesfully skipped the array var! Check the next.

secAndRts:
         sec
         rts

; clears carry if A is alphanumeric, sets otherwise
IsAlNum: cmp     #$30       ; < '0' (punctuation, or control chars)?
         bcc     secAndRts
         cmp     #$3a       ; digit?
         bcc     clcAndRts
; clears carry if A is alphabetic, sets otherwise
IsAlpha: cmp     #$41       ; additional punctuation?
         bcc     secAndRts
         cmp     #$5b       ; another set of punctuation?
         bcs     secAndRts
clcAndRts:
         clc
         rts

ClearOperandHiBytes:
         lda     #$00
         sta     zpWParam+1
         sta     zpWAccum+1
         rts

AddAndReplaceExpr:
         jsr     Add
; Copies WAccum to the expression parse stack, replacing the previous top
; exprssion on the stack
ReplaceExprStkTopWAccum:
         ldx     zpExprStkIdx
         dex
         dex
         dex
         lda     zpWAccum
         sta     exprParseStk,x
         lda     zpWAccum+1
         sta     exprParseStk+1,x
         lda     zpWAccum+2
         sta     exprParseStk+2,x
         jmp     TxtSkipSpaces

SubtractAndReplaceExpr:
         jsr     Subtract
         jmp     ReplaceExprStkTopWAccum

MulAndReplaceExpr:
         jsr     MultiplyAndCheckPosNeg
         jmp     ReplaceExprStkTopWAccum

DivAndReplaceExpr:
         lda     zpWParam   ;check for division by zero
         bne     @notZero
         lda     zpWParam+1
         beq     ErrorDivisionByZero
@notZero:
         jsr     WordDivide
         jmp     ReplaceExprStkTopWAccum

ErrorDivisionByZero:
         lda     #err_DZ
         jmp     PrintErrorAndStop

ModAndReplaceExpr:
         lda     zpWAccum+1
         pha
         jsr     DivAndReplaceExpr ;perform division
         lda     zpWAccum+2 ;move remainder to WAccum
         sta     zpWAccum
         lda     zpWAccum+3
         sta     zpWAccum+1
         pla                ;was the divisor positive?
         bpl     @chkRslt   ;yes -> check result
         lda     zpWAccum+1
         bmi     @replStkTop
@negate: jsr     WAccumNegate
@replStkTop:
         jmp     ReplaceExprStkTopWAccum

@chkRslt:
         lda     zpWAccum+1 ;is result positive?
         bpl     @replStkTop ;yes -> leave result alone
         bmi     @negate    ;no: negate then close up

OpFn_NotEq:
         jsr     Compare    ;compare A and B
         bne     RelOp_ReturnTrue ;unequal? -> return true
RelOp_ReturnFalse:
         lda     #$00       ;load 0 (false)
RelOp_RetTrueOrFalse:
         sta     zpWAccum   ;store acc to both bytes of WAccum
         sta     zpWAccum+1
         jmp     ReplaceExprStkTopWAccum ;and replace as result at top of expr parse stack

RelOp_ReturnTrue:
         lda     #$ff       ;load -1 (true)
         jmp     RelOp_RetTrueOrFalse

OpFn_LtEq:
         jsr     Compare    ;compare A and B
         beq     RelOp_ReturnTrue ;equal? -> true
         bcc     RelOp_ReturnTrue ;A < B? -> also true
         jmp     RelOp_ReturnFalse ;else -> false

OpFn_GrEq:
         jsr     Compare    ;compare A and B
         bcs     RelOp_ReturnTrue ;A >= B? true
         jmp     RelOp_ReturnFalse ;else -> false

OpFn_Equal:
         jsr     Compare    ;compare A and B
         beq     RelOp_ReturnTrue ;A == B? -> true
         jmp     RelOp_ReturnFalse ;else -> false

OpFn_GreaterThan:
         jsr     Compare    ;compare A and B
         beq     RelOp_ReturnFalse ;A == B? -> false
         bcs     RelOp_ReturnTrue ;else A >= B? -> true
         jmp     RelOp_ReturnFalse ;otherwise -> false

OpFn_LessThan:
         jsr     Compare    ;compare A and B
         bcc     RelOp_ReturnTrue ;A < B? -> true
         jmp     RelOp_ReturnFalse ;else -> false

; Jump table for relative/comparative operators
jtbl_RelOps:
         .word   OpFn_NotEq ; <>
         .word   OpFn_GrEq  ; >=
         .word   OpFn_LtEq  ; <=
         .word   OpFn_Equal ; =
         .word   OpFn_GreaterThan ; >
         .word   OpFn_LessThan ; <

SkipLParenOrSynErr:
         ldx     #'('
         .byte   $2c
SkipRParenOrSynErr:
         ldx     #')'
         stx     zpHeldKeyChar
         jsr     TxtSkipSpaces
         cmp     zpHeldKeyChar
         bne     errSyn_A8D1
         jmp     TxtPtrIncr

errIllVal_A88B:
         jmp     ErrorIllegalValue

ExprMove:
         jsr     TxtPtrIncr
         jsr     EvalParenByteOrError ;evaluate MOVE arg
         ldy     zpWAccum
         cpy     #$08       ;arg >= 8?
         bcs     errIllVal_A88B ;yes -> error
         lda     sprAttrFlags,y ;get DEF MOVE data on specified sprite
         and     #$10       ;select whether movement is active
         beq     @zero      ;zero? -> keep that value
         lda     #$ff       ;non-zero, convert to value (-1)
@zero:   sta     zpWAccum   ;save that value to WAccum (as word)
         sta     zpWAccum+1
         jsr     SkipRParenSetParseStkInt ;and save it as the parse stack top
         jmp     TxtSkipSpaces

ZeroWAccum:
         lda     #$00
         sta     zpWAccum
; (Only "truncates" bc caller always sets A-reg to zero)
TruncWAccumToByte:
         sta     zpWAccum+1
         sta     zpWAccum+2
         rts

; Skips over a parentheses at TXTPTR, or errors if no paren.
; Evaluates the parenthesized expression, and copies the three bytes to WAccum
EvalParenExprOrError:
         jsr     SkipLParenOrSynErr
         jsr     Expression
         ldx     zpExprStkIdx
         dex
         lda     exprParseStk,x
         sta     zpWAccum+2
         dex
         lda     exprParseStk,x
         sta     zpWAccum+1
         dex
         lda     exprParseStk,x
         sta     zpWAccum
         rts

errSyn_A8D1:
         jmp     ErrorSyntax

; dead/unreachable code
         ldx     zpExprStkIdx
         lda     zpWAccum
         sta     exprParseStk,x
         inx
         lda     zpWAccum+1
         sta     exprParseStk,x
         inx
         inx
         stx     zpExprStkIdx
         rts

FnFn_CSRLIN:
         lda     zpCV
         sta     zpWAccum   ;load cursor y pos into low byte of WAccum
PushWAccByteToParseStk:
         lda     #$00
         sta     zpWAccum+1 ;zero out high byte of WAccum
PushWAccIntToParseStk:
         inc     zpExprStkIdx ;create space on parse stack for a "pushed" return value
         inc     zpExprStkIdx
         inc     zpExprStkIdx
SetParseStkTopToWAccInt:
         lda     #TYP_INT
         sta     zpArgTyp   ;set current type as int
SetParseStkTopToWAcc:
         ldx     zpExprStkIdx
         dex
         dex
         dex
         lda     zpWAccum   ;copy 3 bytes from WAcccum over the top item of the parse stack
         sta     exprParseStk,x
         lda     zpWAccum+1
         sta     exprParseStk+1,x
         lda     zpWAccum+2
         sta     exprParseStk+2,x
         rts                ;done

FnFn_ERR:
         lda     zpErrCode
         sta     zpWAccum   ;load last error's code into WAccum
         jmp     PushWAccByteToParseStk ;and return it via expr parse stack

FnFn_ERL:
         lda     zpErrLineNum
         sta     zpWAccum   ;get line num from last err into WAccum
         lda     zpErrLineNum+1
         sta     zpWAccum+1
         jmp     PushWAccIntToParseStk ;and return it via the expr parse stack

FnFn_FRE:
         jsr     AmtFreeMemToWAccum ;get the amount of free memory into WAccum
         jmp     PushWAccIntToParseStk ;and push that to parse stack

AmtFreeMemToWAccum:
         sec
         lda     zpFRETOP   ;save (FRETOP - VAREND) to WAccum
         sbc     zpVAREND
         sta     zpWAccum
         lda     zpFRETOP+1
         sbc     zpVAREND+1
         sta     zpWAccum+1
         rts

FnFn_POS:
         jsr     EvalParenIntOrError ;read (and discard) dummy integer argument
         lda     zpCH       ;copy cursor x pos to low byte of WAccum
SetWacByteSkipRPSetParseStkInt:
         sta     zpWAccum   ;set Waccum low byte to what's in A reg
         lda     #$00
         sta     zpWAccum+1 ;zero out the high byte of WAccum
         jmp     SkipRParenSetParseStkInt ;skip right paren, and return WAccum in expr stack

GetActorDefMoveIdxFromArg:
         jsr     EvalParenByteOrError ;get actor # arg into WAccum (as byte)
GetActorDefMoveIdx:
         lda     zpWAccum   ;read actor # from WAccum (byte)
         jsr     ErrUnlessZeroThruSeven ;ensure it's a value < 8
         asl     A          ;multiply by 8, for MOVE dfn indexing
         asl     A
         asl     A
         tax
         rts                ;and return in X-reg

; Parses an open paren (or errors), then parses an integer and errors unless its
; value is in the range 0 thru 7 (inclusive - sprite actor number). The parsed
; value is in both A reg and X reg upon (successful) exit.
EvalParenZeroThruSevenOrError:
         jsr     EvalParenByteOrError
         lda     zpWAccum
         jsr     ErrUnlessZeroThruSeven
         tax
         rts

FnFn_XPOS:
         jsr     GetActorDefMoveIdxFromArg ;get index from actor-num arg
         lda     defMovSPosX,x ;grab X pos
         jmp     SetWacByteSkipRPSetParseStkInt ;-> and return it

FnFn_YPOS:
         jsr     GetActorDefMoveIdxFromArg ;get index from actor-num arg
         lda     defMovSPosY,x ;grab Y pos
         jmp     SetWacByteSkipRPSetParseStkInt ;-> and return it

FnFn_VCT:
         jsr     GetActorDefMoveIdxFromArg ;get index from actor-num arg
         lda     defMovSFacing,x ;grab facing
         jmp     SetWacByteSkipRPSetParseStkInt ;-> and return it

FnFn_PEEK:
         jsr     EvalParenIntOrError ;eval parenthesized int arg
         ldy     #$00
         lda     (zpWAccum),y ;peek at specified addr
         sta     zpWAccum
         sty     zpWAccum+1 ;save result to WAccum
SkipRParenSetParseStkInt:
         jsr     SkipRParenOrSynErr
         jmp     SetParseStkTopToWAccInt

FnFn_ABS:
         jsr     EvalParenIntOrError ;eval parenthesized arg
         jsr     Cmp32768   ;is the value -32,768?
         beq     errOverfl_A999 ;yes -> can't negate, won't fit
         lda     zpWAccum+1
         bmi     @neg       ;negative? -> negate it to positive
         jmp     SkipRParenSetParseStkInt ;-> else just set expr value as-is

@neg:    jsr     WAccumNegate ;negate
         jmp     SkipRParenSetParseStkInt ;-> then set as our value on parse stack

errOverfl_A999:
         jmp     ErrorOverflow

FnFn_SGN:
         jsr     EvalParenIntOrError ;parse parenthesized int argument
         lda     zpWAccum+1 ;is it negative?
         bmi     @neg       ;yes -> handle; else, is it positive?
         bne     @pos       ;yes -> handle
         lda     zpWAccum   ;(check low byte pos too, if high byte is zero)
         bne     @pos
         lda     #$00       ;zero: set Waccum to zero
         .byte   $2c
@neg:    lda     #$ff       ;neg: set Waccum to -1
         sta     zpWAccum
@wrHiBhyteAndFinish:
         sta     zpWAccum+1
         jmp     SkipRParenSetParseStkInt ;-> skip closing parenthesis, and return WAccum

@pos:    lda     #$01       ;pos: set Waccum to 1
         sta     zpWAccum
         lda     #$00       ;load zero for high byte
         beq     @wrHiBhyteAndFinish

FnFn_RND:
         jsr     EvalParenIntOrError ;get parenthesized int arg (max ret val)
         lda     zpWAccum
         pha
         lda     zpWAccum+1
         pha                ;push the max val to CPU stack
         lda     zpRandom
         sta     zpWAccum
         lda     zpRandom+1 ;take previous PRNG result
         sta     zpWAccum+1 ;and place in WAccum
         lda     #$83
         sta     zpWParam
         lda     #$03
         sta     zpWParam+1 ;multiply by 899
         jsr     WordMultiplyWithTypeCheck
         lda     #$7f
         and     zpWAccum+1 ;clear away sign bit (max 32,767)
         sta     zpWAccum+1
         sta     zpRandom+1 ;store the result as the new value for zpRandom
         lda     zpWAccum
         sta     zpRandom
         pla                ;pull the user's arg, and stick into WParam
         sta     zpWParam+1
         pla
         sta     zpWParam
         jsr     WordMultiplyWithTypeCheck ;multiply by the (7-bit) random number we got
         asl     zpWAccum+1 ;then shift the result (including overflow) one bit left
         rol     zpMulScratch+2
         rol     zpMulScratch+3
         lda     zpMulScratch+2
         sta     zpWAccum   ;store the 16-bit overflow
         lda     zpMulScratch+3 ; in WAccum (it's guaranteed to be
         sta     zpWAccum+1 ; less than the user's number)
         jmp     SkipRParenSetParseStkInt ;read past the closing paren, set top of parse stack to our return value

ErrorTypeMismatch:
         lda     #err_TM
         jmp     PrintErrorAndStop

; Same as EvalParenIntOrError, below, but additionally error if the int value
; doesn't fit in a single byte.
EvalParenByteOrError:
         jsr     EvalParenIntOrError
         jmp     ErrIfWAccumIsWord

; If we're at a parenthesized integer expression, evaluate it and place in
; WAccum. If not, ErrorTypeMismatch.
EvalParenIntOrError:
         jsr     EvalParenExprOrError
ErrorUnlessInteger:
         lda     #TYP_INT
         .byte   $ae
ErrorUnlessString:
         lda     #TYP_STR
         cmp     zpArgTyp
         bne     ErrorTypeMismatch
         rts

EvalParenStrOrError:
         jsr     EvalParenExprOrError
         jmp     ErrorUnlessString

FnFn_LEN:
         jsr     EvalParenStrOrError ;get parenthesized string
TruncWAccumParseRParen:
         lda     #$00
         jsr     TruncWAccumToByte ;clear WAccum bytes except lowest
         jmp     SkipRParenSetParseStkInt ;-> finish up

FnFn_ASC:
         jsr     EvalParenStrOrError ;get parenthesized string arg
         lda     zpWAccum   ;empty string?
         beq     TruncWAccumParseRParen ;yes -> return zero
         ldy     #$00
         lda     (zpWAccum+1),y ;read first char of string
         sta     zpWAccum   ;save its value in zpWAccum
         jmp     TruncWAccumParseRParen ;-> clear other bytes of WAccum and read closing paren. Done!

errIllVal_AA38:
         jmp     ErrorIllegalValue

FnFn_SCR_STR:
         jsr     SaveCursorPos ;save CH/CV
         jsr     EvalParenByteOrError ;read first arg; x pos
         lda     zpWAccum
         cmp     #COLS      ; >= # columns?
         bcs     errIllVal_AA38 ;yes -> error
         sta     zpCH       ;else, save as cursor x pos (for now)
         jsr     CommaThenIntExprToWAccum ;read 2nd arg; y pos
         jsr     ErrIfWAccumIsWord ;ensure only uses one byte
         lda     zpWAccum
         cmp     #ROWS      ; >= # rows?
         bcs     errIllVal_AA38 ;yes -> error
         sta     zpCV       ;else, save as cursor y pos (for now)
         jsr     TxtSkipSpaces
         cmp     #')'       ;do we have closing paren?
         beq     @getTileId ;yes -> we're getting the tile ID/character at that pos
         jsr     CommaThenIntExprToWAccum ;else get 3rd arg
         lda     zpWAccum   ; == 0?
         beq     @getTileId ;yes -> same as omitted. We're getting tile ID/character
         jsr     ErrUnlessZeroOrOne ;if it's not zero, ensure it's one
         jsr     GetTileQuadPaletteNum ;go and fetch the palette number for this location
         lda     zpPaletteNum
         jmp     @finish    ;-> restore cursor pos and return the value

@getTileId:
         jsr     CalcCursorTilemapPos ;calculate address in VRAM of tile at x, y
         lda     #NC_GetCharUnderCursor
         jsr     WaitForNmiSubcommand ;get the char/tile ID for that
         lda     zpCharUnderCurs
@finish: sta     zpWAccum   ;save value to WAccum
         jsr     RestoreCursorPos ;restore original CH/CV
         jmp     MakeSingleCharStrFromWAcc ;make a string out of the char found, and return that via expr parse stack

FnFn_CHR_STR:
         jsr     EvalParenByteOrError ;get parenthesized byte-sized int arg
MakeSingleCharStrFromWAcc:
         lda     zpWAccum   ;get its value into A reg
ReturnNewSingleCharStrFromAReg:
         jsr     MakeSingleCharStrFromAReg
SetParseStkTopToWAccStr:
         lda     #TYP_STR
         sta     zpArgTyp   ;set var type = string
         jsr     SkipRParenOrSynErr ;read closing paren
         jmp     SetParseStkTopToWAcc ;return our value by setting the top value of the expression stack

MakeSingleCharStrFromAReg:
         ldx     zpGpStrIdx
         sta     genPurposeBuf,x ;store value in A-reg to genPurposeBuf
         inc     zpGpStrIdx ;increment index to reflect our consumption of a single byte
         lda     #$01
         sta     zpWAccum   ;set first byte of WAccum to 1 (string length)
         stx     zpWAccum+1 ;point the next two bytes at the space
         lda     #>genPurposeBuf ; in genPurposeBuf we just wrote to
         sta     zpWAccum+2
         rts                ;return

vZpStrLen .set   $90
FnFn_STR_STR:
         jsr     EvalParenIntOrError ;eval parenthesized int
         jsr     DecStrFromWord ;convert int to decimal string
CopyDecOrHexStr:
         jsr     FindFirstNonzeroDigit ;skip leading zeroes
         lda     #$00
         sta     vZpStrLen  ;start with strlen of 0
         ldy     zpGpStrIdx
         ldx     zpTmp46    ;get the position of first non-zero digit into X
@cpyLp:  lda     zpNumStrTmp,x ;get char from decimal str
         beq     @copyDone  ;null terminator? -> done copying
         sta     genPurposeBuf,y ;else write char to genPurposeBuf
         inx
         iny
         inc     vZpStrLen  ;increment strlen
         jmp     @cpyLp     ;-> copy next character

@copyDone:
         lda     zpGpStrIdx ;load original index into genPurposeBuf (str start)
         sty     zpGpStrIdx ;save new index
         sta     zpWAccum+1 ;save str start low byte
         lda     #>genPurposeBuf
         sta     zpWAccum+2 ;save str start high byte (genPurposeBuf)
         lda     vZpStrLen
         sta     zpWAccum   ;save strlen
         jmp     SetParseStkTopToWAccStr ;-> wrap things up

FnFn_HEX_STR:
         jsr     EvalParenIntOrError ;eval parenthesized int
         jsr     HexStrFromWord ;convert int to hex string
         jmp     CopyDecOrHexStr ;proceed as for STR$

vZpStrLen .set   $74
FnFn_VAL:
         jsr     EvalParenStrOrError ;parse parenthesized string arg
         lda     zpWAccum   ;empty string?
         beq     VAL_returnZero ;yes -> return as zero
         jsr     SaveTXTPTR ;save TXTPTR
         lda     zpWAccum
         sta     vZpStrLen  ;use string length as a copy countdown
         ldx     #$00
         ldy     #$00
@cpyLp:  lda     (zpWAccum+1),y ;copy string contents into LineBuffer
         sta     lineBuffer,x
         inx
         iny
         dec     vZpStrLen  ;decr chars to copy. == 0?
         bne     @cpyLp     ;no -> loop and copy next character
         lda     #$00
         sta     lineBuffer,x ;null-terminate the string
         jsr     InitLineBufferScanning ;point TXTPTR at LineBuffer
         jsr     READ_parseNumber ;parse a number from the string into WAccum
         jsr     RestoreTXTPTR ;restore TXTPTR to past the argument
         jmp     SkipRParenSetParseStkInt ;skip past right-paren, and return the value in WAccum onto parse stack

VAL_returnZero:
         jsr     ZeroWAccum
         jmp     SkipRParenSetParseStkInt

ParseAndNegateDecWord:
         jsr     TxtPtrIncr ;advance txtptr
         jsr     TxtSkipSpaces ;and skip any spaces
         jsr     IsDigit    ;cur char a digit?
         bcs     @recurse   ;no -> look for another '-', '+', or (especially) '&'
         jsr     ParsePosOrNegDecWFromTxt ;parse a (possibly re-negated) number
         jmp     WAccumNegate ;and negate it, returning.

@recurse:
         jsr     READ_parseNumber
         jmp     WAccumNegate

advAndRedo:
         jsr     TxtPtrIncr
READ_parseNumber:
         ldy     #$00
         lda     (zpTXTPTR),y
         cmp     #'-'       ;cur char == '-'?
         beq     ParseAndNegateDecWord ;yes -> parse and negate a number
         cmp     #'+'       ;cur char == '+'?
         beq     advAndRedo ;yes -> ignore, advance, and restart these checks
         cmp     #'&'       ;cur char == '&'?
         beq     READ_parseHexNum
         jsr     ParsePosOrNegDecWFromTxt ;<- it'll be positive, bc we already checked for '-'
         jsr     Cmp32768   ;and therefore, if we get 32768, it's an overflow
         beq     errOverfl_AB46 ;(overflow? -> error)
         rts

errOverfl_AB46:
         jmp     ErrorOverflow

READ_parseHexNum:
         jsr     TxtPtrIncr
         lda     (zpTXTPTR),y
         cmp     #'H'
         bne     @noH       ;skip optional 'H', and parse a hex number
         jsr     TxtPtrIncr
@noH:    jmp     WordFromHex

FnFn_INKEY_STR:
         jsr     IsEndOfCmd ;any chars after INKEY$?
         beq     @argOmitted ;no -> omitted arg, return active keyboard char
         cmp     #'('       ;have a left paren?
         bne     @argOmitted ;no -> omitted arg, return active keyboard char
         jsr     EvalParenExprOrError ;yes, it's a left parenthesis. Move past it, and a dummy expression.
         jsr     ReadChar   ;read char from keyboard, waiting for keypress
         jmp     ReturnNewSingleCharStrFromAReg ;return that value as (single-char) string

@argOmitted:
         jsr     ReadKeyInsMacros ;read any curently-pressed keys
         beq     @retEmpty  ;nothing pressed? -> return empty string
         jsr     MakeSingleCharStrFromAReg ;else make single-char string from the keypress
@pushStr:
         jsr     PushWAccIntToParseStk ;push the string in WAccum to expr parse stack
         lda     #TYP_STR   ;and set the type accordingly
         sta     zpArgTyp
         rts

@retEmpty:
         jsr     ZeroWAccum
         jmp     @pushStr

; Illegal Value error if WAccum's high byte is non-zero
ErrIfWAccumIsWord:
         lda     zpWAccum+1
         bne     errIllVal_AB8A
         rts

EnsureLtStrLenMax:
         cmp     #STRLEN_MAX
         bcs     errIllVal_AB8A
         rts

errIllVal_AB8A:
         jmp     ErrorIllegalValue

ReadLEFTorRIGHTstrArgs:
         jsr     EvalParenStrOrError ;eval left paren, string argument
         lda     zpWAccum
         pha                ;push strlen
         lda     zpWAccum+1
         pha                ;and two pointer bytes (to the string data)
         lda     zpWAccum+2
         pha
         jsr     CommaThenIntExprToWAccum ;eval comma, integer substr len
         jsr     ErrIfWAccumIsWord ;ensure it's byte-sized
         lda     zpWAccum
         jsr     EnsureLtStrLenMax ;and also < max strlen
         pla
         sta     zpMisc+1   ;pull the str ptr bytes,
         pla                ; and stuff them into zpMisc
         sta     zpMisc
         pla                ;pull orig string length (leaving in A-reg)
         rts                ;return (strptr in zpMisc, strlen in A-reg, and substr len in WAccum)

; dead/unreachable code
         jmp     ErrorSyntax

FnFn_INSTR:
         jsr     EvalParenStrOrError ;parse first string arg (haystack)
         ldx     zpWAccum   ;load strlen into X reg
         ldy     #$00
@cpyLp:  lda     (zpWAccum+1),y ;get a char from string
         sta     lineBuffer,y ;copy into lineBuffer
         iny
         dex                ;copied whole string?
         bne     @cpyLp     ;no -> loop back, copy next char
         lda     zpWAccum
         pha                ;push the string length
         jsr     CommaThenExprToWAccum ;parse comma, then 2nd string arg (needle)
         jsr     ErrorUnlessString
         lda     zpWAccum
         sta     zpWParam   ;copy string info from WAccum to WParam
         lda     zpWAccum+1
         sta     zpWParam+1
         lda     zpWAccum+2
         sta     zpWParam+2
         pla                ;pull string length
         sta     zpWAccum   ;store in WAccum byte 0
         lda     #<lineBuffer
         sta     zpWAccum+1 ;copy ptr to lineBuffer (holding haystack string) into WAccum+1,2
         lda     #>lineBuffer
         sta     zpWAccum+2
         jsr     CheckInStr ;perform the matching
         sta     zpWAccum   ;save index result into zpWAccum
         lda     #$00       ;(clearing high byte)
         sta     zpWAccum+1 ;(and ancilliary bytes)
         sta     zpWAccum+2
         jmp     SkipRParenSetParseStkInt ;skip closing paren, and return our value via expr parse stack

vZpStrLen .set   $4a
vZpCpyCountDwn .set $90
FnFn_LEFT_STR:
         jsr     ReadLEFTorRIGHTstrArgs ;read args
         sta     vZpStrLen  ;save orig str len
         lda     zpWAccum   ;substr len == 0?
         beq     LEFT_RIGHT_returnEmptyStr ;yes -> return empty str
         cmp     vZpStrLen  ;substr len >= orig str len?
         bcs     LEFT_RIGHT_returnOrigStr ;yes -> just return orig str
retFromSetOrigStr:
         lda     zpMisc
         sta     zpWAccum+1 ;just set return string pointer to orig:
         lda     zpMisc+1   ; this is LEFT$ so we can just adjust the returned string's length
LEFT_RIGHT_finishUp:
         sta     zpWAccum+2 ; (conveniently already correct, and at the right addr)
         jmp     SetParseStkTopToWAccStr ;return WAccum via expr parse stack

LEFT_RIGHT_returnOrigStr:
         lda     vZpStrLen
         sta     zpWAccum   ;set orig str len as substr len
         jmp     retFromSetOrigStr ;just return orig str, substr with same len is just orig str

LEFT_RIGHT_returnEmptyStr:
         sta     zpWAccum+1 ;clear WAccum+1 (+2 will clear after jmp below)
         jmp     LEFT_RIGHT_finishUp ;clear WAccum+2 and return on expr parse stack

SC_errSyn:
         jmp     ErrorSyntax

SkipCommaOrSynErr:
         jsr     TxtSkipSpaces
         cmp     #','
         bne     SC_errSyn
         jmp     TxtPtrIncr

CommaThenExprToWAccum:
         jsr     SkipCommaOrSynErr ;demand a comma here
         jsr     Expression ;parse an expression
         ldx     zpExprStkIdx ;pull the expression value, and
         dex                ; save it to zpWAccum
         lda     exprParseStk,x
         sta     zpWAccum+2
         dex
         lda     exprParseStk,x
         sta     zpWAccum+1
         dex
         lda     exprParseStk,x
         sta     zpWAccum
         stx     zpExprStkIdx ;save new reduced index (effecting the "pull" from expr stack)
         rts                ;done

CommaThenIntExprToWAccum:
         jsr     CommaThenExprToWAccum
         jmp     ErrorUnlessInteger

FnFn_RIGHT_STR:
         jsr     ReadLEFTorRIGHTstrArgs ;read args
         sta     vZpStrLen  ;save str arg's length
         lda     zpWAccum   ;get substr length
         beq     LEFT_RIGHT_returnEmptyStr ; == 0? -> return empty str
         cmp     vZpStrLen  ; substr len >= orig str len?
         bcs     LEFT_RIGHT_returnOrigStr ;yes -> just return the contents of original string
         sec
         lda     vZpStrLen  ;else, subtract substr len from full str len
         sbc     zpWAccum
         clc
         adc     zpMisc     ;add to str ptr
         sta     zpMisc
         lda     #$00
         adc     zpMisc+1   ;ptr high byte, too
         sta     zpMisc+1
         lda     zpWAccum
         sta     vZpCpyCountDwn ;copy substr len to countdown var
         ldx     zpGpStrIdx
         ldy     #$00
@cpyLp:  lda     (zpMisc),y ;read char from orig str (at shifted position)
         sta     genPurposeBuf,x ;copy into general-purpose buffer
         inx
         iny
         dec     vZpCpyCountDwn ;decrement # chars to copy. == 0?
         bne     @cpyLp     ;no -> loop around, copy next char
         lda     zpGpStrIdx ;point WAccum at general-purpose buffer
         sta     zpWAccum+1 ; location we copied to
         stx     zpGpStrIdx
         lda     #>genPurposeBuf
         sta     zpWAccum+2
         jmp     SetParseStkTopToWAccStr ;-> return the copied string via expr parse stack

errIllVal_AC7E:
         jmp     ErrorIllegalValue

vZpStrPtr .set   $19
vZpSubStrStartIdx .set $1b
vZpSubStrLen .set $1c
vZpCpyCountDwn .set $90
FnFn_MID_STR:
         jsr     EvalParenStrOrError ;read paren, string arg
         lda     zpWAccum
         pha                ;push the string info
         lda     zpWAccum+1
         pha
         lda     zpWAccum+2
         pha
         jsr     CommaThenIntExprToWAccum ;next read start index arg
         jsr     ErrIfWAccumIsWord ;ensure it's < 256
         lda     zpWAccum   ; == 0?
         beq     errIllVal_AC7E ;yes -> invalid index
         jsr     EnsureLtStrLenMax ; >= 32? also invalid index
         sec
         sbc     #$01       ;sub 1 (cvt from 1-based index to 0-based)
         pha                ;push the index
         jsr     CommaThenIntExprToWAccum ;read substr length arg
         jsr     ErrIfWAccumIsWord ;ensure < 256
         lda     zpWAccum   ; == 0?
         beq     MID_pullArgsRetEmptyStr ;yes -> pull up args, return empty string
         jsr     EnsureLtStrLenMax ;ensure substr len < max strlen
         sta     vZpSubStrLen ;save the substr len
         pla                ;pull the start index
         sta     vZpSubStrStartIdx ;and save that too
         pla                ;also the original string's ptr
         sta     vZpStrPtr+1
         pla
         sta     vZpStrPtr
         pla                ;pull orig str's len
         cmp     vZpSubStrStartIdx ; <= start index?
         beq     MID_retEmptyStr ;yes -> return empty string
         bcc     MID_retEmptyStr
         sec
         sbc     vZpSubStrStartIdx ;orig str len - substr start idx
         cmp     vZpSubStrLen ; < substr len?
         bcc     MID_setSubStrLen ;yes -> set remaining len as the new substr len
MID_setLenJmpBack:
         lda     vZpSubStrStartIdx ; (and return back here)
         clc
         adc     vZpStrPtr  ;add start idx to str ptr
         sta     vZpStrPtr  ; and save
         lda     #$00
         adc     vZpStrPtr+1 ;(high byte, too)
         sta     vZpStrPtr+1
         lda     vZpSubStrLen
         sta     zpWAccum   ;save substr len to WAccum
         sta     vZpCpyCountDwn ;and use as # chars to copy
         ldx     zpGpStrIdx
         ldy     #$00
@cpyLp:  lda     (vZpStrPtr),y ;get a byte from str
         sta     genPurposeBuf,x ;copy to gen-purpose str buf
         inx                ;incr X-reg (genPurpose idx)
         iny                ;incr Y-reg (source str idx)
         dec     vZpCpyCountDwn ;decrement chars-to-copy. Done copying?
         bne     @cpyLp     ;not yet -> iterate over remaining chars
         lda     zpGpStrIdx ;done copying.
         sta     zpWAccum+1 ;save ptr into genPurposeBuf as str ptr, to WAccum
         stx     zpGpStrIdx ;update index to free space in genPurposeBuf
         lda     #>genPurposeBuf
         sta     zpWAccum+2
         jmp     SetParseStkTopToWAccStr ;-> return new substr on expression stack

MID_setSubStrLen:
         sta     vZpSubStrLen
         jmp     MID_setLenJmpBack ;-> "return"

MID_pullArgsRetEmptyStr:
         pla                ;pull args off stack
         pla
         pla
         pla
MID_retEmptyStr:
         jsr     ZeroWAccum ;zero the WAccum
         jmp     SetParseStkTopToWAccStr ;-> return empty string

vZpPadBtns .set  $90        ;Holds state of gamepad buttons
errIllVal_AD02:
         jmp     ErrorIllegalValue

EvalLParenPadNumAndGetBtns:
         jsr     EvalParenByteOrError ;read left paren, then byte-size int arg
; Get the state of buttons (including d-pad) as a set of 8 boolean bits, into
; $90. WAccum indicates which gamepad to read.
GetButtons:
         lda     zpWAccum   ;get byte-size val from WAccum
         beq     @zero      ; == 0? -> skip ahead a bit
         cmp     #$01       ;else, eq 1?
         bne     errIllVal_AD02 ;neither 0 nor 1 -> error
         lda     #<JOY2     ;we'll read from JOY2
         .byte   $ae        ;(skip next instr)
@zero:   lda     #<JOY1     ;we'll read from JOY1
         sta     zpMisc
         lda     #>JOY1
         sta     zpMisc+1
         lda     #$05
         sta     JOY1       ;tell controllers to load shfit registers
         nop                ;wait a bit
         nop
         lda     #$04
         sta     JOY1       ;lock shift registers
         nop                ;wait a bit
         nop
         ldx     #$08       ;set X-reg as counter for 8 single-bit reads
         ldy     #$00
@joyRdLp:
         lda     (zpMisc),y ;read from gamepad
         lsr     A          ;shift into carry
         rol     vZpPadBtns ;shift from carry onto gamepad buttons-state var
         nop                ;wait a bit before next gamepad read
         nop
         dex                ;decr bit counter. Did we record 8 bits/buttons?
         bne     @joyRdLp   ;no -> loop around for next button state
         rts                ;yes: done

FnFn_STICK:
         jsr     EvalLParenPadNumAndGetBtns ;parse gamepad-num arg, and get buttons state for it
         jsr     GetButtons ;re-read the buttons (why?!)
         lda     vZpPadBtns
         and     #$0f       ;mask out everything but d-pad buttons
ST_setWAccumAndSaveExpr:
         sta     zpWAccum   ;save this val to WAccum
         jmp     SkipRParenSetParseStkInt ;-> and return as our result

FnFn_STRIG:
         jsr     EvalLParenPadNumAndGetBtns ;parse gamepad-num arg, and get buttons state for it
         lda     vZpPadBtns
         lsr     A          ;shift off the d-pad state, leaving
         lsr     A          ; other buttons in the lower four bits
         lsr     A
         lsr     A
         jmp     ST_setWAccumAndSaveExpr ;-> and return the result

; shifts A left 4 times, effectively multiplying it by 16
MulABy16:
         asl     A
         asl     A
         asl     A
         asl     A
         rts

errIllVal_AD58:
         jmp     ErrorIllegalValue

CmdFn_GAME:
         cmp     #','       ;start with comma (2nd arg)?
         beq     GAME_mapOnly ;yes -> go handle
         jsr     EvalByteInteger ;else parse first arg
         cmp     #$04       ; >= 4?
         bcs     errIllVal_AD58 ;yes -> error
         sta     zpGameNum  ;save arg as "game number"
         jsr     CmdFn_CLS_Scr1 ;clear SCREEN 1
         jsr     IsEndOfCmd ;no more args?
         beq     @oneArg    ;correct -> skip handling arg 2
         jsr     SkipCommaOrSynErr ;read expected comma
         jsr     EvalByteInteger ;parse arg 2. Des it equal zero?
         beq     @oneArg    ;yes -> same as no 2nd arg
         cmp     #$01
         bne     errIllVal_AD58
         jsr     GAME_loadBgMap ;load up the background map
@oneArg: jsr     InitVars
         jsr     GAME_loadGame
         lda     #$00
         jmp     CmdFn_RUN

GAME_mapOnly:
         jsr     SkipCommaOrSynErr ;skip over comma (can't fail: we know it's there)
         jsr     EvalByteInteger ;parse "second" arg
         beq     @rts       ;"GAME ,0"? -> done (nothing to do).
         jsr     GAME_loadBgMap ;just load the background map
@rts:    rts                ; then exit (no game)

GAME_loadGame:
         lda     zpTXTTAB
         sta     zpMisc     ;init write pointer to start of TXTTAB
         lda     zpTXTTAB+1
         sta     zpMisc+1
         lda     zpGameNum  ;recall game num
         asl     A          ;multiply by 2 for indexing
         tax
         lda     tbl_GameTXTENDs,x ;load TXTEND value for this game
         sta     zpTXTEND   ;and store it as the current one
         lda     tbl_GameTXTENDs+1,x
         sta     zpTXTEND+1
         lda     tbl_GameTexts,x ;init read ptr to start of the selected game
         sta     zpMisc+2
         lda     tbl_GameTexts+1,x
         sta     zpMisc+3
         ldy     #$00
@cpyLp:  lda     (zpMisc+2),y ;load a byte from in-ROM game
         sta     (zpMisc),y ;store it in TXTTAB
         inc     zpMisc+2   ;increment source ptr
         bne     @noHiSrc
         inc     zpMisc+3
@noHiSrc:
         inc     zpMisc     ;increment dest ptr
         bne     @noHiDst
         inc     zpMisc+1
@noHiDst:
         lda     #>memoryTop+1
         cmp     zpMisc+1   ;copy to end of RAM at $7000 (not to TXTEND!)
         bne     @cpyLp
         jmp     Clear

GAME_loadBgMap:
         lda     #<gameBackgroundMap ;prep background map for reading
         sta     zpMisc
         lda     #>gameBackgroundMap
         sta     zpMisc+1
         jsr     AwaitVBlankAndClearPpuMask ;wait until safe to do PPU ops. Disable rendering.
         lda     #>VRAM_screen1
         sta     PPUADDR
         lda     #<VRAM_screen1
         sta     PPUADDR
         ldy     #$00
@cpyLp:  lda     (zpMisc),y ;read a byte from built-in map
         sta     PPUDATA    ;write byte to screen 1
         iny                ;advance read idx. Finished reading one page?
         bne     @cpyLp     ;no -> loop around copy next byte
         inc     zpMisc+1   ;increment source page num
         lda     #$d4
         cmp     zpMisc+1   ;are we at RAM page $D4?
         bne     @cpyLp     ;no -> copy another page to VRAM
         jsr     NmiSetVScrollAndEnableNmi ;yes: ensure NMI enabled
         jmp     AwaitVBlankAndUpdatePpuMask ;and re-enable rendering. Return

CmdFn_CLS_Scr1:
         lda     #$01
         sta     zpWAccum
         jmp     cls_fakedArg

cls_noScrSwNeeded:
         pla
         pla
doCls:   jmp     DoCLS

CmdFn_CLS:
         beq     doCls      ;no args ->
         jsr     EvalByteInteger ;get int arg
         cmp     #$02       ; < 2?
         bcs     errIllVal_ae45 ;no -> err
cls_fakedArg:
         lda     zpCV
         pha                ;push orig cursor Y pos
         lda     zpPpuScreenBasePage
         pha                ;push orig upd scr
         lda     zpWAccum
         beq     @swScr0    ;arg is 0? -> switch to that
         lda     #>VRAM_screen1 ;no: switch to scr 1
         cmp     zpPpuScreenBasePage ;already updating scr 1?
         beq     cls_noScrSwNeeded ;yes -> leave alone, discard saved pos
         sta     zpPpuScreenBasePage ;no -> do the switch
         lda     #$00
         sta     zpVScroll1 ;and clear scroll pos
         beq     @doCls

@swScr0: lda     #>VRAM_screen0
         cmp     zpPpuScreenBasePage ;already updating scr 0?
         beq     cls_noScrSwNeeded ;yes -> leave alone, discard saved pos
         sta     zpPpuScreenBasePage ;no -> do the switch
         lda     #$00
         sta     zpVScroll0 ;and clear scroll pos
@doCls:  jsr     DoCLS
         pla
         sta     zpPpuScreenBasePage ;restore original update screen
         pla
         sta     zpCV       ;and original cursor Y pos
         rts

nmiOnAndRts:
         jsr     NmiSetVScrollAndEnableNmi
         rts

errIllVal_ae45:
         jmp     ErrorIllegalValue

CmdFn_SCREEN:
         jsr     EvalByteInteger ;get int arg.
         beq     @got0or1   ;== 0? ->
         cmp     #$01       ;== 1?
         bne     errIllVal_ae45
@got0or1:
         and     #$ff
         sta     zpCurScreenNum
         beq     @useScr0   ;SCREEN 0? ->
         lda     #>VRAM_screen1 ;SCREEN 1. Save base addr high byte.
         sta     zpPpuScreenBasePage
         lda     zpPpuCtrlVal
         ora     #$01       ;Tell PPU to switch active screen to 1
@setPpuCtrlAndCont:
         sta     zpPpuCtrlVal
         jsr     WaitForVBlank
         jsr     SetPpuCtrlAndEnableNmi
         jsr     NmiSetVScrollAndEnableNmi
         jsr     CursorHome ;LOCATE 0,0
         jsr     IsEndOfCmd ;done with args?
         beq     nmiOnAndRts ;yes -> finish up
         jsr     SkipCommaOrSynErr
         jsr     EvalByteInteger ;get next int arg
         beq     @secondSrc0 ;== 0? ->
         cmp     #$01       ;or == 1?
         bne     errIllVal_ae45 ;neither? -> illegal!
         lda     #>VRAM_screen1 ;== 1. send updates, only, to 1.
         sta     zpPpuScreenBasePage
         rts

@secondSrc0:
         lda     #>VRAM_screen0 ;send updates, only, to scr 0.
         sta     zpPpuScreenBasePage
         rts

@useScr0:
         lda     #>VRAM_screen0 ;SCREEN 0. Save base addr high byte.
         sta     zpPpuScreenBasePage
         lda     zpPpuCtrlVal
         and     #$fe       ;Tell PPU to switch active screen to 0
         jmp     @setPpuCtrlAndCont

errIllVal_AE93:
         jmp     ErrorIllegalValue

BgtFile_GoToScreen0:
         lda     #$00
         sta     zpCurScreenNum ;set SCREEN 0
         lda     #>VRAM_screen0
         sta     zpPpuScreenBasePage
         lda     zpPpuCtrlVal
         and     #$fe       ;mask out bg base addr, so SCREEN 0 is displayed by PPU
         sta     zpPpuCtrlVal
         jmp     SetPpuCtrlAndEnableNmi ;-> enact updated PPUCTRL, then return

; dead/unreachable code
         lda     #$01
         sta     zpCurScreenNum
         lda     #>VRAM_screen1
         sta     zpPpuScreenBasePage
         lda     zpPpuCtrlVal
         ora     #$01
         sta     zpPpuCtrlVal
         jmp     SetPpuCtrlAndEnableNmi

CmdFn_FILTER:
         jsr     EvalByteInteger ;read arg
         cmp     #$08       ; >= 8?
         bcs     errIllVal_AE93 ;yes -> error
         jsr     MulABy16   ;shift the arg val left 5 places
         asl     A
         sta     zpHeldKeyChar ;store in some handy var
         lda     zpPpuMaskVal ;load PPUMASK value
         and     #$1f       ;mask out the filter bits
         ora     zpHeldKeyChar ;merge with our shifted arg
         sta     zpPpuMaskVal ;save PPUMASK value
         sta     PPUMASK    ;and update it in the PPU
         rts                ;done!

CmdFn_CGEN:
         jsr     EvalByteInteger ;get argument
         cmp     #$04       ; >= 4?
         bcs     errIllVal_AE93 ;yes -> error
         asl     A          ;shift the value left 3 places:
         asl     A          ; from bits 0 and 1 to bits 3 and 4.
         asl     A
         sta     zpCursFlashCtr ;save away for a tick
         lda     zpPpuCtrlVal ;get the PPUCTRL value
         and     #$e7       ;mask away everything but bits 3 and 4
         ora     zpCursFlashCtr ;now combine with the value we got form user arg
         sta     zpPpuCtrlVal ;save
         jmp     SetPpuCtrlAndEnableNmi ;and update

; Clear all sprite tiles and attrs, move positions off-screen
ClearOam:
         ldx     #$00
         lda     #$ef
@lp:     sta     oamBuffer,x
         inx
         bne     @lp
         rts

vZpColorCntUp .set $02      ;count down to write palette colors
vZpColorCntDown .set $7c    ;count up, the actual color num to set
CmdFn_PALET:
         ldx     #$00
         stx     zpPaletBgOrSpr ;start with assumption: bg sprite
         cmp     #'B'       ;first arg 'B'?
         beq     @bgPal     ;yes -> user said bg palette, our guess was right!
         cmp     #'S'       ;first arg 'S'?
         bne     errSyn_AF4C ;no -> err
         lda     #$10       ;set sprite palette offset
         sta     zpPaletBgOrSpr
@bgPal:  jsr     AdvThenEvalByteInt ;which palette num?
         cmp     #$04       ; >= 4?
         bcs     errIllVal_AF49 ;yes -> error
         pha                ;push palette num
         lda     #$04
         sta     vZpColorCntUp ;four colors in a palette
         lda     #$00
         sta     vZpColorCntDown ;start with color #0
@colorLp:
         jsr     EvalCommaThenByteInt ;read comma, then user's color arg
         ldy     vZpColorCntDown
         sta     zpNumStrTmp,y ;write color into arbitrary buf
         inc     vZpColorCntDown ;incr color #
         dec     vZpColorCntUp ;did we do 4?
         bne     @colorLp   ;no -> loop to next color
         pla                ;pull the palette num
         sta     genPurposeBuf
         lda     zpNumStrTmp ;copy color choices into genPurposeBuf
         sta     genPurposeBuf+1 ; (why didn't we just write there
         lda     zpNumStrTmp+1 ; in the first place?!)
         sta     genPurposeBuf+2
         lda     zpNumStrTmp+2
         sta     genPurposeBuf+3
         lda     zpNumStrTmp+3
         sta     genPurposeBuf+4
         ldy     #NC_SetBgPalette ;select "set bg palette" cmd
         ldx     zpPaletBgOrSpr ;what did user actually ask for?
         beq     @bg        ;bg? -> good call then
         iny                ;spr -> #NC_SetSprPalette it is
@bg:     tya
         jmp     WaitForNmiSubcommand ;set the palette

ErrUnlessZeroThruSeven:
         cmp     #$08
         bcs     errIllVal_AF49
         rts

errIllVal_AF49:
         jmp     ErrorIllegalValue

errSyn_AF4C:
         jmp     ErrorSyntax

; Selects a preset set-of-four-pallets, to save as current pallet.
; First arg is bg pallet set (0 or 1), 2nd is sprite pallet set (0, 1 or 2).
vZpPaletteSetPtr .set $52
vZpNmiCmd .set   $73        ;which palette-setting NMI subcmd we'll use
vZpColorCpyCtr .set $74
vZpPaletteCpyIdx .set $75   ;iterates the selected palette set as copy source
CmdFn_CGSET:
         cmp     #','       ;got comma?
         beq     @arg2      ;skip arg one, go to arg two
         jsr     EvalByteInteger ;evaluate arg one
         beq     @argGood   ;error unless it's zero or one
         cmp     #$01
         bne     errIllVal_AF49
@argGood:
         asl     A          ;multiply by two, for index into table
         tax
         lda     tbl_CgsetBgPaletteSets,x ;get the pallet-set pointer from table
         sta     vZpPaletteSetPtr
         lda     tbl_CgsetBgPaletteSets+1,x
         sta     vZpPaletteSetPtr+1
         lda     #$00
         sta     zpPaletBgOrSpr ;indicate we're doing background palette set
         jsr     CGSET_SetPaletteSet ;and set it
         jsr     IsEndOfCmd
         beq     @rts
         cmp     #$2c
         bne     errSyn_AF4C
@arg2:   jsr     AdvThenEvalByteInt ;evaluate 2nd arg
         cmp     #$03       ;error unless 0, 1, or 2
         bcs     errIllVal_AF49
         asl     A          ;multiply by two, for index into table
         tax
         lda     tbl_CgsetSprPaletteSets,x ;get the pallet pointer from table
         sta     vZpPaletteSetPtr
         lda     tbl_CgsetSprPaletteSets+1,x
         sta     vZpPaletteSetPtr+1
         lda     #$01
         sta     zpPaletBgOrSpr ;indicate we're doing sprite palette set
         jsr     CGSET_SetPaletteSet ;and set it
@rts:    rts                ;done

CGSET_SetPaletteSet:
         lda     #$00
         sta     genPurposeBuf ;PPU palette number (start at zero)
         sta     vZpPaletteCpyIdx ;index for copying from palette set
@palSetLp:
         lda     #$04
         ldx     #$01       ;just after the PPU palette number we saved for the NMI handler
         sta     vZpColorCpyCtr ;set to count of 4 colors to copy
         ldy     vZpPaletteCpyIdx
@palCpyLp:
         lda     (vZpPaletteSetPtr),y ;load color from palette
         sta     genPurposeBuf,x ;save color to genPurposeBuf
         inx
         iny
         dec     vZpColorCpyCtr
         bne     @palCpyLp  ;repeat until total of 4 colors copied
         sty     vZpPaletteCpyIdx ;save index into palette set (we're at start of next palette to copy)
         lda     #NC_SetBgPalette
         sta     vZpNmiCmd  ;default to setting bg palette set; might change before use
         lda     zpPaletBgOrSpr ;was bg palettes correct?
         beq     @doBg      ;yes -> leave NMI cmd alone
         inc     vZpNmiCmd  ;no -> use #NC_SetSprPalette instead
@doBg:   lda     vZpNmiCmd
         jsr     WaitForNmiSubcommand ;invoke/wait for NMI palette-setting handler
         inc     genPurposeBuf ;increment which palette num we're on
         lda     genPurposeBuf
         cmp     #$04       ;did we copy 4 palettes?
         bne     @palSetLp  ;no -> loop around to set next palette
         rts                ;that's the full set - we're done

; Not a real CmdFn. CmdFn_SPRITE when followed by ON token.
CmdFn_SPRITE_ON:
         lda     zpPpuMaskVal
         ora     #$10       ;add "sprites enabled" flag to PPUMASK
savePpu: sta     zpPpuMaskVal
         sta     PPUMASK
         jmp     TxtPtrIncr ;advance TXTPTR past ON/OFF token

; Not a real CmdFn. CmdFn_SPRITE when followed by OFF token.
CmdFn_SPRITE_OFF:
         lda     zpPpuMaskVal
         and     #$ef       ;mask out "sprites enabled" flag from PPUMASK
         jmp     savePpu    ;and save it

SpriteErase:
         pla                ;get sprite number
         jsr     MulABy16   ; *= 16
         tax                ;and transfer to X reg
         ldy     #$04
@clrSprLp:
         lda     #SPR_NullTile ;repeat four times (one for each sprite tile in actor):
         sta     oamSprYPos,x ;move ypos off-screen
         sta     oamSprXPos,x ;move xpos off-screen
         sta     oamSprTileId,x ;wset tile ID to empty tile
         inx
         inx
         inx
         inx
         dey
         bne     @clrSprLp
         rts                ;SPRITE command is finished disabling the sprite.

; dead/unreachable code
         jmp     ErrorIllegalValue

         jmp     ErrorSyntax

vZpXPos  .set    $19
vZpXOff  .set    $1a        ;offset to add to X pos for a given tile
vZpYPos  .set    $1b
vZpYOff  .set    $1c        ;offset to add to Y pos for a given tile
vZpSpriteNum .set $6d
vZpTileCtr .set  $74
vZpTwoByTwo .set $90        ;Whether the sprite is 2x2 tiles (1), or 1x1 tiles (0)
CmdFn_SPRITE:
         cmp     #tok_ON
         beq     CmdFn_SPRITE_ON
         cmp     #tok_OFF
         beq     CmdFn_SPRITE_OFF
         jsr     EvalByteInteger ;get sprite num
         jsr     ErrUnlessZeroThruSeven ;complain if not 0-7
         pha                ;push
         jsr     IsEndOfCmd ;is that all there is?
         beq     SpriteErase ;yes -> disable the sprite
         jsr     EvalCommaThenByteInt ;no, then expect a comma followed by an int (x pos)
         pha                ;push x pos
         jsr     EvalCommaThenByteInt ;expect another comma and int (y pos)
         sta     vZpYPos    ;store it
         pla
         sta     vZpXPos    ;store x pos
         pla
         sta     vZpSpriteNum ;and sprite num
         tax                ;and move sprite num into X reg
         lda     sprTwoByTwoFlags,x
         sta     vZpTwoByTwo ;save info on whether this sprite is 1x1 or 2x2
         lda     vZpSpriteNum ;get sprite num
         asl     A          ; *= 4
         asl     A
         tax                ;save as X-reg
         asl     A
         asl     A          ; *= 4 again (so, * 16 total)
         pha                ;push that for later
         tay                ;and also set Y-reg
         lda     #$04
         sta     vZpTileCtr ;counter for 4 tiles of the sprite character
@tileCpy:
         lda     sprTileMaps,x ;copy tile ID from sprite char definition
         sta     oamSprTileId,y ;copy to its spot in the OAM buffer
         inx                ;increment one for source
         iny                ;and four for dest (OAM buffer)
         iny
         iny
         iny
         dec     vZpTileCtr ;decrement tile counter
         bne     @tileCpy   ;tiles left to copy? -> loop until we did 4
         pla                ;pull sprite # times 16
         tay                ;reset Y-reg to that again
         lda     vZpYPos
         sta     oamSprYPos,y ;copy Y position to OAM
         lda     vZpXPos
         sta     oamSprXPos,y ;and X position
         lda     vZpTwoByTwo ;is this a 2x2 sprite character?
         bne     @setOtherTiles ;yes -> set X and Y positions for those tiles, too
         rts                ;no: done!

@setOtherTiles:
         lda     #$00       ;top-right tile
         sta     vZpYOff
         lda     #$08
         sta     vZpXOff
         jsr     @setOneTile
         lda     #$00       ;bottom-left tile
         sta     vZpXOff
         lda     #$08
         sta     vZpYOff
         jsr     @setOneTile
         lda     #$08       ;bottom-right tile
         sta     vZpXOff
         sta     vZpYOff
@setOneTile:
         iny
         iny
         iny
         iny
         lda     vZpXPos
         clc
         adc     vZpXOff
         sta     oamSprXPos,y
         lda     vZpYPos
         clc
         adc     vZpYOff
         sta     oamSprYPos,y
rts_B082:
         rts                ;done!

DEF_maybeMove:
         cmp     #tok_MOVE
         bne     errSyn_B08A
         jmp     CmdFn_DEFMOVE

errSyn_B08A:
         jmp     ErrorSyntax

ErrUnlessZeroOrOne:
         cmp     #$01
         beq     rts_B082
         and     #$ff
         beq     rts_B082
errIllVal_B095:
         jmp     ErrorIllegalValue

vZpSprAttr .set  $19        ;Value to use for OAM sprite attributes bitflags
vZpTilesPtr .set $1b        ;Pointer to user-specified tiles (the assigned string from user)
vZpArgCntr .set  $6d        ;counter for loading DEF SPRITE args
vZpTwoByTwo .set $ad        ;Holds the value of the 2nd parenthesized arg: character construction
CmdFn_DEF:
         cmp     #tok_SPRITE ;next token SPRITE?
         bne     DEF_maybeMove ;no -> check if it's MOVE then (error otherwise)
         jsr     AdvThenEvalByteInt ;get the sprite number
         jsr     ErrUnlessZeroThruSeven ;ensure it's 0-7
         pha                ;push it
         jsr     SkipCommaOrSynErr ;skip a comma
         jsr     SkipLParenOrSynErr ;and a paren
         lda     #$04
         sta     vZpArgCntr ;counter to loop around fetching last 4 args
         jsr     EvalByteInteger ;eval 1st parenthesized arg: color combo, 0 to 3
         cmp     #$04
         bcs     errIllVal_B095 ; >= 4? -> error
         pha
@argLp:  jsr     EvalCommaThenByteInt ;get another arg
         pha                ;push it
         dec     vZpArgCntr
         bne     @argLp     ;do 3 more times. Now have 5 args on stack in reverse order
         jsr     SkipRParenOrSynErr ;ensure closing paren
         jsr     SkipEqualsOrErr ;ensure equal sign
         pla                ;grab last arg: Y-axis inversion
         jsr     ErrUnlessZeroOrOne ;we're expecting zero or one
         ror     A          ;move 1 to high-bit instead (yflip attr bit)
         ror     A
         and     #$80       ;<- this is redundant: we already knew it was 0 or 1
         sta     vZpSprAttr ;save
         pla                ;pull 4th paren arg: X-axis inversion
         jsr     ErrUnlessZeroOrOne ;ensure zero or one
         ror     A          ;move 1 to bit 6 instead (#$01 -> #$40)
         ror     A
         ror     A
         and     #$40       ;<- redundant
         ora     vZpSprAttr ;merge x-flip attr with y-flip attr
         sta     vZpSprAttr
         pla                ;pull 3rd paren arg: display priority
         jsr     ErrUnlessZeroOrOne ;ensure zero or one
         ror     A          ;move 1 to bit 5 instead (#$01 -> #$20)
         ror     A
         ror     A
         ror     A
         and     #$20       ;<- redundant
         ora     vZpSprAttr ;merge the flag
         sta     vZpSprAttr
         pla                ;pull 2nd paren arg: construction pattern
         jsr     ErrUnlessZeroOrOne ;ensure 0 or 1
         sta     vZpTwoByTwo ;save
         pla                ;pull 1st paren arg: color preset
         and     #$03       ;<- redundant; we checked <= 3 aleady
         ora     vZpSprAttr ;merge with other sprite attrs
         sta     vZpSprAttr
         pla                ;pull sprite number
vZpSpriteNum .set $6d
         sta     vZpSpriteNum ;get the sprite num
         jsr     MulABy16   ; *= 16
         ldy     #$04
         tax
@oamClrLp:
         lda     #$ef       ;for each of the four tiles of this sprite:
         sta     oamSprYPos,x ;move y-pos off-screen
         sta     oamSprXPos,x ;move x-pos off-screen
         lda     vZpSprAttr
         sta     oamSprAttr,x ;save sprite attrs from args
         lda     #$20       ;BUG. SPACE char? Actually Lady face char. This ought to be $EF for empty sprite tile (overwritten later anyway)
         sta     oamSprTileId,x ;save sprite tile ID
         inx
         inx
         inx
         inx
         dey
         bne     @oamClrLp  ;do the same for the other 3 tiles
         jsr     EvalString ;evaluate the expected string after the "="
         lda     exprParseStk+1
         sta     vZpTilesPtr ;copy string contents ptr from parse stack to ZP pointer var
         lda     exprParseStk+2
         sta     vZpTilesPtr+1
         ldy     #$00
         lda     vZpSpriteNum ;get sprite num
         asl     A
         asl     A          ; *= 4
         tax
         lda     exprParseStk
         beq     @emptyString
@tileCpy:
         lda     (vZpTilesPtr),y ;copy tile ID
         sta     sprTileMaps,x ;to data for this sprite
         inx
         iny
         cpy     #$04       ;copied 4 tiles?
         beq     @tileCpyDone ;-> done copying
         dec     exprParseStk ;decrement string length. Ran out of string chars?
         bne     @tileCpy   ;no -> loop back around for another copy from string
@emptyString:
         lda     #$20       ;yes. Copy Lady face tile (s/b $EF instead)
@cpyLadyTiles:
         sta     sprTileMaps,x ; over the remaining tiles.
         inx
         iny
         cpy     #$04
         bne     @cpyLadyTiles
@tileCpyDone:
         ldx     vZpSpriteNum ;Finally, save whether this is a 8x8 or 16x16 actor
         lda     vZpTwoByTwo
         sta     sprTwoByTwoFlags,x
rts_B152:
         rts

; Copy contents of screen 1 to screen 0.
; If screen 1 is the active screen, do nothing.
vZpScr0Page .set $74
CmdFn_VIEW:
         lda     zpCurScreenNum
         bne     rts_B152   ;not SCREEN 0? -> nothing to do.
         lda     #$20
         sta     vZpScr0Page ;set VRAM copy dest page to start of screen 0
         lda     #NC_PpuMaskClear
         jsr     WaitForNmiSubcommand ;clear PPUMASK
         ldx     #$00
@cpyLp:  lda     vZpScr0Page
         clc
         adc     #$04
         jsr     PpuGoToAX  ;set PPUADDR to screen 1 (copy source) page
         lda     PPUDATA    ;first faked read
         lda     PPUDATA    ;read the character/tile ID
         pha                ;push
         lda     vZpScr0Page
         jsr     PpuGoToAX  ;set PPUADDR to same page in screen 0 (dest)
         pla                ;pull tile ID
         sta     PPUDATA    ;and write to screen 0
         inx                ;next byte of vRAM page
         bne     @cpyLp     ;page not done? -> loop
         inc     vZpScr0Page ;page done; increment page number
         lda     vZpScr0Page
         cmp     #$24       ;did we finish copying to VRAM page #$23?
         bne     @cpyLp     ;no -> copy next page
         lda     zpVScroll1 ;yes: copy scr 1 vert scroll to scr 0
         sta     zpVScroll0
         jsr     NmiSetVScrollAndEnableNmi ;and update
         jsr     SetPpuCtrlAndEnableNmi
         lda     #NC_PpuMaskUpdate
         jmp     WaitForNmiSubcommand ;restore PPUMASK, and return

ClearSpriteData:
         ldx     #$3d
         lda     #$00
@sprClrLp:
         sta     $0600,x    ;clear sprites' 2x2 vs 1x1 data
         inx
         bne     @sprClrLp
         ldx     #$00
         lda     #SPR_NullTile
@tileClrLp:
         sta     sprTileMaps,x ;set all actor tilemaps to empty tile
         inx
         cpx     #32        ;8 actors * 4 tiles
         bne     @tileClrLp
         ldx     #192
         lda     #$00
@clrSprFacing:
         sta     defMovSFacing-$c0,x
         inx
         bne     @clrSprFacing
         rts

errOOM_B1B5:
         jmp     ErrorOutOfMemory

CmdFn_BGGET:
         jsr     Clear      ;clear vars
         lda     zpVAREND+1
         cmp     #>bgGetRam ;is there room after program for bg data?
         bcs     errOOM_B1B5 ;no -> OOM error
         lda     #NC_PpuMaskClear
         jsr     WaitForNmiSubcommand ;turn off rendering
         lda     #<bgGetRam
         sta     zpMisc     ;point zpMisc for storing the background data
         lda     #>bgGetRam
         sta     zpMisc+1
         lda     #>VRAM_screen1 ;set PPUADDR to SCREEN 1 in RAM
         sta     PPUADDR
         lda     #<VRAM_screen1
         sta     PPUADDR
         lda     PPUDATA    ;faked first read
         ldy     #$00
         ldx     #$04       ; # pages to copy
@cpyLp:  lda     PPUDATA    ;read byte from background data
         sta     (zpMisc),y ;write it to (battery-backed) RAM
         iny                ;did we read a full page?
         bne     @cpyLp     ;no -> keep copying
         inc     zpMisc+1   ;copied page, incr write page
         dex                ;copied four pages?
         bne     @cpyLp     ;no -> copy next page
         lda     zpVScroll1 ;yes: done copying
         sta     bgGetVScroll ;save vscroll for saved screen
         lda     #$ff       ;indicate screen 1 is saved in RAM
UpdateBgGotFlag:
         sta     bgGotFlag
         lda     #NC_PpuMaskUpdate
         jsr     WaitForNmiSubcommand ;restore rendering
         rts

ErrorNoBgData:
         lda     #err_NB
         jmp     PrintErrorAndStop

CmdFn_BGPUT:
         lda     bgGotFlag  ;flag indicate we have saved bg data?
         beq     ErrorNoBgData ;no? nothing to put then, is there? -> error
RestoreBackupBgData:
         lda     #NC_PpuMaskClear
         jsr     WaitForNmiSubcommand ;disable rendering
         lda     #>bgGetRam
         sta     zpMisc+1   ;point zpMisc at the saved bg data
         lda     #<bgGetRam
         sta     zpMisc
         ldy     #$00
         ldx     #$04       ; # pages to copy
         lda     #>VRAM_screen1
         sta     PPUADDR
         lda     #<VRAM_screen1
         sta     PPUADDR    ;set PPUADDR to addr of SCREEN 1 data
@cpyLp:  lda     (zpMisc),y ;read a byte from RAM-saved BG data
         sta     PPUDATA    ;copy to VRAM
         iny                ;have we copied a full page?
         bne     @cpyLp     ;no -> copy next byte
         inc     zpMisc+1   ;increment RAM page to read from
         dex                ;did we copy 4 pages?
         bne     @cpyLp     ;no -> copy next page
         lda     bgGetVScroll ;yes, done copying
         sta     zpVScroll1 ;restore saved vscroll
         lda     #$00
         beq     UpdateBgGotFlag ;(ALWAYS) -> clear bgGotFlag and restore PPU rendering

; Prints the two-character error code, saves running context, and returns to
; direct mode.
PrintErrorAndStop:
         cmp     #22        ;if the error code >= 
         bcc     @errCodeGood
         lda     #err_UP
@errCodeGood:
         sta     zpErrCode  ;save error code for BASIC
         ldx     zpRunLineNum
         stx     zpErrLineNum ;save cur line # as error line
         stx     zpRsmRunLineNum ;and also resume line
         ldx     zpRunLineNum+1
         stx     zpErrLineNum+1
         stx     zpRsmRunLineNum+1
         ldx     zpErrHandStat ;is an error handler installed?
         beq     PrintError_print ;no -> print error and exit
         cpx     #EH_IN_HANDLER ;are we currently in error handler?
         beq     PrintError_print ;yes -> print new error and exit
         lda     zpTxtThisCmd ;else: we should call the error handler instead of erroring
         sta     zpRsmTxtThisCmd ;save away all the resumable context
         lda     zpTxtThisCmd+1
         sta     zpRsmTxtThisCmd+1
         lda     zpRunTxtNxtLnk
         sta     zpRsmRunTxtNxtL
         lda     zpRunTxtNxtLnk+1
         sta     zpRsmRunTxtNxtL+1
         lda     zpErrHandLNum
         sta     zpFindLNum
         lda     zpErrHandLNum+1
         sta     zpFindLNum+1
         jsr     FindLineNum ;find error-handler line
         inc     zpErrHandStat ;from 1 (EH_NO_HANDLER) to 2 (EH_IN_HANDLER)
         ldx     zpSavedStack ;restore the saved stack
         txs
         jsr     GoTo       ;-> go to the erorr handler and execute
         jmp     ExecuteCommand

PrintError_print:
         pha
         jsr     EnsureSOL  ;move cursor to start of new line (if it isn't already)
         pla
         ldx     #$00       ;clear the stack
         txs
         asl     A          ;multiply error code by 2 for indexing
         tay
         lda     #'?'
         jsr     QueueCharForOutput ;queue a '?'
         lda     tbl_TwoCharErrCodes,y
         jsr     QueueCharForOutput ;get the two-char code
         lda     tbl_TwoCharErrCodes+1,y
         jsr     QueueCharForOutput ;and queue that
         lda     #<strERROR
         sta     zpOutputStr
         lda     #>strERROR
         sta     zpOutputStr+1
         jsr     QueueOutputStr ;queue " ERROR"
         jsr     ClearStoppedFlag ;clear stopped flag
; Code below this line is also used by STOP
StopOrErr_PrintBeepExit:
         lda     #$ff       ;are we in direct mode?
         cmp     zpRunLineNum+1
         bne     @INmsg     ;low byte doesn't match -> not direct
         cmp     zpRunLineNum
         beq     @skipIN    ;yes -> skip "IN [line #]" message
@INmsg:  lda     #<strIN
         sta     zpOutputStr
         lda     #>strIN
         sta     zpOutputStr+1
         jsr     QueueOutputStr ;queue for output: " IN "
         jsr     @prLineNum ;queue the line number
@skipIN: jsr     PrintOutBuf ;print queued STOP/ERROR message
         jsr     CmdFn_BEEP ;beep
         jmp     DirectModeLoop ;go to command prompt

@prLineNum:
         lda     zpRunLineNum ;get line number low byte
         sta     zpContRunLineNum ;save it away
         sta     zpWAccum   ;and store in WAccum
         lda     zpRunLineNum+1 ;ditto for high byte
         sta     zpContRunLineNum+1
         sta     zpWAccum+1
QueueWordAsDecimalOutput:
         jsr     PosDecStrFromWord ;translate to decimal string
         jsr     FindFirstNonzeroDigit ;skip leading zeroes
         jmp     QueueOutpNumStrTmp ;and queue for output

Stop_PrintBreakBeepExit:
         jsr     EnsureSOL  ;move cursor to start of a line (unless it is already)
         lda     #$00
         sta     zpOutTxtCurPos
         lda     #<strBREAK
         sta     zpOutputStr
         lda     #>strBREAK
         sta     zpOutputStr+1
         jsr     QueueOutputStr ;queue for output: "BREAK"
         jmp     StopOrErr_PrintBeepExit

PrintOK: lda     #'O'
         jsr     PrintOneChar
         lda     #'K'
         jmp     PrintOneChar

PrintStartupText:
         lda     #<strNS_HUDSON
         sta     zpOutputStr
         lda     #>strNS_HUDSON
         sta     zpOutputStr+1
         jsr     PrintString ;print "NS-HUBASIC V3.0 "
         jsr     EnsureSOL  ;next line
         lda     #<strCOPYRIGHT_MSG
         sta     zpOutputStr
         lda     #>strCOPYRIGHT_MSG
         sta     zpOutputStr+1
         jsr     PrintString ;print "(C) NINTENDO/SHARP/HUDSON"
         jsr     EnsureSOL  ;next line
bytesFree:
         jsr     AmtFreeMemToWAccum
         jsr     QueueWordAsDecimalOutput
         jsr     PrintOutBuf
         lda     #<strBYTES_FREE
         sta     zpOutputStr
         lda     #>strBYTES_FREE
         sta     zpOutputStr+1
         jmp     PrintString ;-> print "BYTES FREE", then return

PrintHotStart:
         lda     #<strBASIC_HOT_START
         sta     zpOutputStr
         lda     #>strBASIC_HOT_START
         sta     zpOutputStr+1
         jsr     PrintString ;print "BASIC HOT START "
         jsr     EnsureSOL  ;next line
         jmp     bytesFree  ;-> print how many bytes free, then return

strBASIC_HOT_START:
         .asciiz "BASIC HOT START "
strBYTES_FREE:
         .asciiz " BYTES FREE"
strIN:   .asciiz " IN "
strBREAK:
         .asciiz "BREAK"
strERROR:
         .asciiz " ERROR"
strWRITING:
         .asciiz "WRITING "
strLOADING:
         .asciiz "LOADING "
strSKIP: .asciiz "SKIP "
tbl_TwoCharErrCodes:
         .byte   "NF"       ;NEXT without FOR
         .byte   "SN"       ;Syntax Error
         .byte   "RG"       ;RETURN without GOSUB
         .byte   "OD"       ;Out of Data
         .byte   "IL"       ;Illegal value
         .byte   "OV"       ;Overflow
         .byte   "OM"       ;Out of Memory
         .byte   "UL"       ;Undefined Line number
         .byte   "SO"       ;Subscript Out of range
         .byte   "DD"       ;Duplicate Definition
         .byte   "DZ"       ;Division by Zero
         .byte   "TM"       ;Type Mismatch
         .byte   "ST"       ;String Too long
         .byte   "FT"       ;Formula Too complex
         .byte   "CC"       ;Cannot Continue
         .byte   "UF"       ;Undefined Function
         .byte   "MO"       ;Missing Operand
         .byte   "TP"       ;Tape read error
         .byte   "NR"       ;No Resume. Given on RESUME without error handler being called, or on program exit when error handled without resume.
         .byte   "RE"       ;RESUME without ERROR. RESUME called but no ON ERROR installed.
         .byte   "NB"       ;No BG Data
         .byte   "UP"       ;Unprintable Error

InitPpuApu:
         lda     #DEFAULT_PPUCTRL
         sta     zpPpuCtrlVal ;when used below (SetPpuCtrlAndEnableNmi), sets bg to use separate tiles from sprites; everything else defaults
         lda     #$0e
         sta     zpPpuMaskVal ;if used, will disable sprites, enable background
         jsr     AwaitVBlankAndClearPpuMask ;disables all rendering
         lda     #$00
         sta     $f5
         sta     zpCurScreenNum
         sta     zpVScroll0
         sta     zpVScroll1
         sta     zpNMICMD
         sta     zpNmiAnimNxtFr
         sta     zpNmiAnimate
         sta     zpOutTxtCurPos
         sta     zpKanaFlag
         sta     zpKanaHeld
         sta     zpModifierKeyDn
         sta     DMC_FREQ
         sta     SQ1_SWEEP
         sta     SQ2_SWEEP
         sta     SND_CHN
         sta     zpInsertMode
         sta     zpRkimMidMacro
         sta     zpFnKeyDfnOff
         lda     #$4f
         sta     JOY2       ;initialize the APU frame counter
         jsr     InitPromptChars
         jsr     SetPpuCtrlAndEnableNmi
         lda     #>VRAM_screen0
         sta     zpPpuScreenBasePage ;set SCREEN 0 as the current screen
         jsr     DoCLS      ;clear and activate SCREEN 0
         jsr     ResetPaletteSets ;reset palette sets to their startup values
         ldx     #$00
         txa
         ldy     #$80
@fkeyClrLp:
         sta     fnKey1_DfnBuf,x ;clear the function-key definitions
         inx
         dey
         bne     @fkeyClrLp
         ldx     #$00
; initialize the fn key definitions to their boot-up defaults
@fkeyDefsLp:
         lda     zpFnKeyDfnOff ;<- this is being as a counter of function keys, not offsets
         cmp     #$08       ;did we do 8 fn key definition?
         beq     rts_B435   ;yes -> we're done
         jsr     MulABy16   ;convert fnkey # to an index into the defns area
         tay                ;and move to the Y reg
@defnCpyLp:
         lda     FnKeyDefaultDefs,x ;load a character from the hard-coded default
         beq     @nxtFnKey  ;terminating null char? -> finished with this def, on to the next
         sta     fnKey1_DfnBuf,y ;store char in assigned definition space
         inx                ;incr source idx
         iny                ;incr dest idx
         jmp     @defnCpyLp ;(always) -> on to copying next character

@nxtFnKey:
         inx
         inc     zpFnKeyDfnOff
         jmp     @fkeyDefsLp

InitPromptChars:
         lda     #TileId_whiteBox ;"white box" tile character
         sta     zpKanaCursChr ;(set as cursor when KANA mode active)
         lda     #'_'       ;"underscore" tile character
         sta     zpNonKCursChr ;(set as normal cursor)
         jmp     DeactivateKanaMode ;initialize to normal (non-KANA) mode

WaitForVBlank:
         lda     PPUSTATUS  ;read from PPUSTATUS until vblank flag is clear, to clear it
         bmi     WaitForVBlank
@waitLp: lda     PPUSTATUS  ;now read from it until it's set again.
         bpl     @waitLp    ;then we know we've hit vblank
rts_B435:
         rts

ResetPaletteSets:
         lda     #<cgsetBgPalSet1
         sta     zpOutputStr
         lda     #>cgsetBgPalSet1 ;setup bg palette set no. 1
         sta     zpOutputStr+1
         lda     #$00
         sta     zpPaletBgOrSpr ;select writing bg palette set
         jsr     CGSET_SetPaletteSet ;set the palette set
         inc     zpPaletBgOrSpr ;select writing spr palette set
         jmp     CGSET_SetPaletteSet ;set the palette set (using the bg set for both bg and spr)

; These strings are used to set the default FN key shorthands.
FnKeyDefaultDefs:
         .byte   "GAME 0",$0d,$00
         .byte   "GAME 1",$0d,$00
         .byte   "GAME 2,1",$0d,$00
         .byte   "GAME 3",$0d,$00
         .asciiz "SPRITE "
         .byte   "LOAD",$0d,$00
         .byte   "LIST",$0d,$00
         .byte   "RUN",$0d,$00

ClearScreenAndAttrs:
         ldy     #$04
         ldx     #$c0       ;#$c0 first iteration, #$00 (256) iters 2-4.
         lda     #$20       ;SPC char
@lpSpaces:
         sta     PPUDATA
         dex
         bne     @lpSpaces  ;end of inner loop
         dey
         bne     @lpSpaces  ;end outer loop. 960x (30 rows * 30 cols, w margins)
ClearScreenAttrs:
         ldx     #$c0
         lda     zpPpuScreenBasePage
         clc
         adc     #$03
         jsr     PpuGoToAX  ;go to the update screen's attribute table location
         lda     #$00
@clrAttr:
         sta     PPUDATA    ;and clear it
         inx
         bne     @clrAttr
         rts

DoCLS_1: lda     #>VRAM_screen1
         sta     zpPpuScreenBasePage
DoCLS:   lda     #NC_PpuMaskClear
         jsr     WaitForNmiSubcommand ;Set PPUMASK = 0
         jsr     SetPpuCtrl
         jsr     AwaitVBlankAndClearPpuMask
         lda     zpPpuScreenBasePage
         ldx     #$00
         jsr     PpuGoToAX  ;Set PPU cur addr to start of update screen
         jsr     ClearScreenAndAttrs
         jsr     NmiSetVScrollAndEnableNmi
         jsr     SetPpuCtrlAndEnableNmi
         lda     #NC_PpuMaskUpdate
         jsr     WaitForNmiSubcommand ;Restore PPUMASK
         jsr     CursorHome ;LOCATE 0,0 (also sets A = 0)
         ldy     zpPpuScreenBasePage
         cpy     #>VRAM_screen0 ;upd scr == 0?
         beq     @scrIs0    ;yes ->
         sta     zpVScroll1 ;upd scr == 1, clear zpVScroll1
         jmp     @skip

@scrIs0: sta     zpVScroll0 ;upd scr == -, clear zpVScroll0
@skip:   tax
         ldy     zpPpuScreenBasePage
         cpy     #>VRAM_screen0 ;upd scr == 0?
         beq     @clrScrInf0 ;yes -> clear that screen's info
@clrScrInf1:
         sta     isRowWrappedArray1-1,x ;no -> clear screen 1's info
         inx
         cpx     #$1a
         bne     @clrScrInf1
         rts

@clrScrInf0:
         sta     isRowWrappedArray0-1,x
         inx
         cpx     #$1a
         bne     @clrScrInf0
         rts

CalcCursorTilemapPos:
         lda     #$20
         sta     zpWAccum
         lda     #$00
         sta     zpWAccum+1
         sta     zpWParam+1
         lda     zpVScroll0
         ldy     zpPpuScreenBasePage
         cpy     #>VRAM_screen0
         beq     @scr0
         lda     zpVScroll1
@scr0:   lsr     A
         lsr     A
         lsr     A
         clc
         adc     zpCV
         adc     #VMARGIN
         cmp     #MAP_ROWS
         bcc     @notOverfl
         sbc     #MAP_ROWS
@notOverfl:
         sta     zpWParam
; At this point, zpPARAM16 ($2C.2D) = ((zpVScroll/8) + CV + 3) MOD 30), or the
; current row number relative to the actual start of the tilemap in VRAM (not
; just "top of screen", like zpCV).
; 
; We set the multiplier to 32, or the size of a row on the screen (including
; margins)
         jsr     WordMultiply
         clc
         lda     zpCH
         adc     #$02
         adc     zpWAccum
         sta     zpCursTileAddr
         lda     #$00
         adc     zpWAccum+1
         clc
         adc     zpPpuScreenBasePage
         sta     zpCursTileAddr+1
         rts

; Sets the current VRAM address to the cursor's current tile position
PpuGoToCursor:
         lda     zpCursTileAddr+1
         sta     PPUADDR
         lda     zpCursTileAddr
         sta     PPUADDR
         rts

NmiWrTileSetVScrollAndEnableNmi:
         sta     PPUDATA
; Set the vertical scroll position from either zpVScroll0 or zpVScroll1,
; depending on the value of $F0
NmiSetVScrollAndEnableNmi:
         jsr     SetPpuCtrlAndEnableNmi
         lda     zpCurScreenNum ;which screen is active?
         beq     @scr0      ;screen 0? -> update scroll for that
         lda     #$00       ;otherwise, update scroll for scr 1
         sta     PPUSCROLL
         lda     zpVScroll1
         sta     PPUSCROLL
         rts

@scr0:   lda     #$00
         sta     PPUSCROLL
         lda     zpVScroll0
         sta     PPUSCROLL
         rts

AwaitVBlankAndClearPpuMask:
         jsr     WaitForVBlank
         lda     #$00
         sta     PPUMASK
         rts

AwaitVBlankAndUpdatePpuMask:
         jsr     WaitForVBlank
         lda     zpPpuMaskVal
         sta     PPUMASK
rts_B56A:
         rts

; Go to start of next line... unless we're already at the start of a line.
EnsureSOL:
         lda     zpCH
         beq     rts_B56A
DoCRLF:  lda     #$00       ;<- here's the CR
         sta     zpCH
         lda     #$0a       ;<- and here's the LF
PrintOneChar:
         cmp     #$20       ;is it a printable character?
         bcs     OutputChar
         cmp     #$08       ;backspace (ctrl-H)
         beq     @leaveInsertAlone
         cmp     #$01       ;insert space (ctrl-A)
         beq     @leaveInsertAlone
         cmp     #$12       ;toggle insert/overwrite (ctrl-R)
         beq     @leaveInsertAlone
         cmp     #$09       ;tab (ctrl-I)
         beq     @leaveInsertAlone
         ldy     #$00       ;all other controls disable insert mode
         sty     zpInsertMode
@leaveInsertAlone:
         asl     A
         tax
         lda     jtbl_CtrlCharHandlers,x
         sta     zpWAccum
         lda     jtbl_CtrlCharHandlers+1,x
         sta     zpWAccum+1
         jmp     (zpWAccum)

OutputChar:
         ldy     zpInsertMode
         beq     @overwr
         pha
         lda     #$12       ;control-R
         jsr     PrintOneChar
         pla
@overwr: jsr     QueueCharForOutput
         jmp     PrintOutBuf

; Advance the cursor to the start of the next row.
; Does exactly the same thing as CursorDown.
CursorToNextRowStart:
         inc     zpCV
         lda     zpCV
         cmp     #ROWS
         beq     ScrollScreenUpOneRow
; Handler for control chars that don't do anything when input.
ControlCharNOOP:
         lda     #$00
         rts

; Advance the cursor to the start of the next line, skipping over any wrapped
; rows in the current one.
CursorToNextLineStart:
         jsr     CarriageReturn
@findStart:
         ldx     zpCV
         jsr     DoesRowWrap
         beq     CursorToNextRowStart
         inc     zpCV
         jmp     @findStart

; Scrolls the screen up by one row, leaving the cursor on the first row of the
; (new) last row).
; 
; Erases the top line just before scrolling it up (so it can become a future new
; line when we scroll down to it in future).
ScrollScreenUpOneRow:
         dec     zp7E
         jsr     CursorHome
         jsr     CalcCursorTilemapPos
; Tell NMI handler to erase to end of row (cursor is at home row, so erase
; entire top row)
         lda     #NC_ClearToEndOfRow
         jsr     WaitForNmiSubcommand
; Scrolls the screen WITHOUT clearing any lines. Unlike many other systems,
; Family Basic doesn't scroll by copying lines upward: the tilemap is vertically
; 'mirrored' (repeated), so we have only to adjust the PPU vertical scroll
; register. Very fast scrolls!
; 
ScrollScreenOneRowNoErase:
         lda     zpPpuCtrlVal
         sta     PPUCTRL
         lda     zpVScroll0
         ldy     zpPpuScreenBasePage
         cpy     #>VRAM_screen0
         beq     @scr0
         lda     zpVScroll1
@scr0:   clc
         adc     #TILE_PIXELS
         cmp     #VPIXELS
         bcc     @notOvfl
         lda     #$00
@notOvfl:
         ldy     zpPpuScreenBasePage
         cpy     #<VRAM_screen0+$20
         beq     @scr01
         sta     zpVScroll1
         jmp     @scr1

@scr01:  sta     zpVScroll0
@scr1:   jsr     WaitForVBlank
         jsr     NmiSetVScrollAndEnableNmi
         ldy     #ROWS
         ldx     #$00
         lda     zpPpuScreenBasePage
         cmp     #>VRAM_screen0
         beq     @scrZLp
@scrOneLp:
         lda     isRowWrappedArray1+1,x
         sta     isRowWrappedArray1,x
         inx
         dey
         bne     @scrOneLp
         tya
         sty     isRowWrappedArray1+$17
         sty     $0633
         beq     @setLoc    ;always branches
@scrZLp: lda     isRowWrappedArray0+1,x
         sta     isRowWrappedArray0,x
         inx
         dey
         bne     @scrZLp
         lda     #$00
         sta     isRowWrappedArray0+$17
         sta     $0619
@setLoc: sta     zpCH
         lda     #ROWS-1
         sta     zpCV
         jmp     SetPpuCtrlAndEnableNmi

; Returns whether the row identified in register X wraps to the next row
DoesRowWrap:
         lda     zpPpuScreenBasePage
         cmp     #>VRAM_screen0
         beq     @scr0
         lda     isRowWrappedArray1,x
         rts

@scr0:   lda     isRowWrappedArray0,x
         rts

; Record that a given row was wrapped, and does not begin a new line of its own.
MarkWrappedRow:
         pha
         lda     zpPpuScreenBasePage
         cmp     #>VRAM_screen0
         beq     @scr0
         pla
         sta     isRowWrappedArray1,x
         rts

@scr0:   pla
         sta     isRowWrappedArray0,x
         rts

SaveCursorPos:
         lda     zpCH
         sta     zpSavedCH
         lda     zpCV
         sta     zpSavedCV
         rts

RestoreCursorPos:
         lda     zpSavedCH
         sta     zpCH
         lda     zpSavedCV
         sta     zpCV
         rts

; Invoked by Control-D
ResetGraphicSettings:
         jsr     AwaitVBlankAndClearPpuMask ;clear PPU mask
         lda     #>VRAM_screen0
         sta     zpPpuScreenBasePage ;set SCREEN 0 in zp vars
         lda     #$00
         sta     zpCurScreenNum
         lda     #$10
         sta     zpPpuCtrlVal
         jsr     SetPpuCtrlAndEnableNmi ;and switch to it
         lda     #$0e
         sta     PPUMASK    ;reasonable PPUMASK default settings
         sta     zpPpuMaskVal
         jsr     ResetPaletteSets ;set bg and spr palettes from bg palette set 1
         jsr     ClearScreenAttrs
         sta     zpInsertMode ;turn off auto-insert
         jsr     NmiSetVScrollAndEnableNmi ;make sure vert scroll is up to date
         jmp     AwaitVBlankAndUpdatePpuMask

; Clears to end of current (possibly multi-row) line
ClearToEndOfLine:
         jsr     SaveCursorPos
         jsr     CalcCursorTilemapPos
         lda     #NC_ClearToEndOfRow
@rowLp:  jsr     WaitForNmiSubcommand
         ldx     zpCV
         jsr     DoesRowWrap
         beq     restoreCursPos_B6AE
         inc     zpCV
         jsr     CarriageReturn
         jsr     CalcCursorTilemapPos
         lda     #$04
         jmp     @rowLp

restoreCursPos_B6AE:
         jmp     RestoreCursorPos

; Control-Z
ClearToEndOfScreen:
         jsr     SaveCursorPos ;save cursor pos
         jsr     CalcCursorTilemapPos ;calc VRAM addr for cursor pos
@clrLp:  lda     #NC_ClearToEndOfRow
         jsr     WaitForNmiSubcommand ;clear from cursor to end of row
         ldx     zpCV
         lda     #$00
         jsr     MarkWrappedRow ;mark this row doesn't wrap to next
         sta     zpCH
         inc     zpCV       ;set cursor to start of next row
         inx
         cpx     #ROWS      ;did we just move past the last row of screen?
         beq     restoreCursPos_B6AE ;yes -> restore cursor pos and return
         jsr     CalcCursorTilemapPos ;no -> calc VRAM addr for new pos
         jmp     @clrLp     ;and loop 'round to clear this row

; dead/unreachable code
         ldx     zpCV
         dex
         txa
         tax
         inx
         jsr     DoesRowWrap
         rts

         jmp     DoCRLF

HandleTabKey:
         lda     zpCH
         cmp     #21
         bcs     @ts3
         cmp     #14
         bcs     @ts2
         cmp     #7
         bcs     @ts1
         lda     #$07
         .byte   $ec
@ts3:    lda     #28
         .byte   $ec
@ts2:    lda     #21
         .byte   $ec
@ts1:    lda     #14
         sec
         sbc     zpCH
         sta     zpOutTxtCurPos
         tax
         lda     #$20
@spcLp:  sta     genPurposeBuf,x
         dex
         bpl     @spcLp
         jmp     PrintOutBuf

ToggleInsertOrOverwriteMode:
         lda     #$ff
         eor     zpInsertMode
         sta     zpInsertMode
         rts

CursorUp:
         lda     zpCV
         beq     @rts
         dec     zpCV
@rts:    rts

; Exactly the same as LineFeed, _except_ in the case when the cursor moves past
; the end of the screen. In that case, LineFeed will leave cursor at the start
; of the new line; CursorDown will leave cursor at the original column.
CursorDown:
         lda     zpCH
         pha
         jsr     LineFeed
         pla
         sta     zpCH
         rts

CursorLeft:
         lda     zpCH       ;already at leftmost column?
         beq     @chkUp     ;yes -> check if we can go up a row
         dec     zpCH       ;no, so just back up a column.
         rts

@chkUp:  lda     zpCV       ;already at topmost row?
         beq     @rts       ;yes -> nothing to do, exit
         lda     #$1b       ;no, so go up a row and to the rightmost column
         sta     zpCH
         dec     zpCV
@rts:    rts

CursorRight:
         lda     zpCH
         cmp     #$1b       ;already in rightmost column?
         beq     @ckNext    ;yes -> check if we can go to next row
         inc     zpCH       ;no, just go right a column
         rts

@ckNext: jsr     CarriageReturn
         lda     zpCV
         cmp     #$17       ;are we on the last row?
         beq     @rts       ;yes -> nothing to do, exit
         inc     zpCV       ;no, just drop down a row
@rts:    rts

CursorHome:
         lda     #$00
         sta     zpCV
CarriageReturn:
         lda     #$00
         sta     zpCH
         rts

LineFeed:
         ldx     zpCV
         inx                ;increment row
         cpx     #ROWS      ;past last row?
         bne     @nextRow   ;no -> store new row and exit
         jmp     ScrollScreenUpOneRow ;yes

@nextRow:
         stx     zpCV
         rts

ActivateKanaMode:
         lda     #$ff
         sta     zpKanaFlag
         lda     zpNonKCursChr
         bne     setCurs1
DeactivateKanaMode:
         lda     #$00
         sta     zpKanaFlag
         lda     zpKanaCursChr
setCurs1:
         sta     zpCursorChar
         rts

; Move cursor left one (unless at start of line), and shift all chars forward
; from the cursor, back by one, across all screen rows occupied by the (possibly
; wrapped) line.
; 
; If cursor is at start of the line, still shifts all chars forward, performing
; a forward-delete instead of backspace.
Backspace:
         ldx     zpCH
         beq     @bsFromSol
         dec     zpCH
         jmp     @dontGoUpRow

@bsFromSol:
         ldx     zpCV       ;backspacing from start of line
         beq     @dontGoUpRow ;backspacing from home position? -> can't back up higher
         dex
         jsr     DoesRowWrap ;check preceding row's wrap status
         beq     @dontGoUpRow ;doesn't wrap -> not same line; not backing up
         dec     zpCV       ;wraps.
         lda     #COLS-1    ;back up to last column of preceding row.
         sta     zpCH
@dontGoUpRow:
         jsr     SaveCursorPos ;save cursor pos
BS_ShiftRowLeftOneCol:
         lda     zpCH
         cmp     #COLS-1    ;on last char of row?
         beq     @skip      ;yes -> skip
         jsr     CalcCursorTilemapPos
         lda     zpCursTileAddr ;pass backspaced position
         sta     zpMisc     ; as parameter to upcoming NMI subcmd
         lda     zpCursTileAddr+1
         sta     zpMisc+1
         inc     zpCH       ;go forward a char
         jsr     CalcCursorTilemapPos ;recalc CalcCursorTilemapPos
         dec     zpCH       ;go back to our backspaced position
         lda     #NC_CopyCharsLeft
         jsr     WaitForNmiSubcommand ;copy this row back one char
         lda     #COLS-1
         sta     zpCH
@skip:   ldx     zpCV
         jsr     DoesRowWrap ;does the present row wrap to the next?
         bne     @backshiftNextRow ;yes -> give next row same treatment
         jsr     CalcCursorTilemapPos ;calculate position of last character of last row we moved
         jsr     WaitForVBlank ;wait for PPU ops to be safe
         jsr     PpuGoToCursor ;go to that location
         lda     #$20       ;overwrite character at this position with SPACE
         jsr     NmiWrTileSetVScrollAndEnableNmi
         jmp     RestoreCursorPos ;restore cursor position

@backshiftNextRow:
         inc     zpCV       ;incr row
         lda     #$ff       ;set x pos to last column
         sta     zpCH
         jsr     BS_moveStartCharBack ;move first char of next row to here (last char of preceding row)
         inc     zpCV       ;CV just got dec'd; re-increment
         jsr     CarriageReturn ;move cursor to start of the row
         jmp     BS_ShiftRowLeftOneCol ;shift this forward row back one

; This routine has some generalized handling, but is only used in very specific
; conditions (always grabs first char on next line). Special setup before
; calling is also performed to make it do that. It's all pretty silly.
BS_moveStartCharBack:
         inc     zpCH       ;bump cursor x
         jsr     CalcCursorTilemapPos ;calc position
         jsr     WaitForVBlank ;wait until it's safe for PPU ops
         jsr     PpuGoToCursor ;go to bumped cursor position
         lda     PPUDATA    ;fake first PPU read
         lda     PPUDATA    ;get the char value at bumped loc
         pha                ;push it
         jsr     NmiSetVScrollAndEnableNmi ;make sure vert scroll is up-to-date
         dec     zpCH       ;back up one char (back to original)
         lda     zpCH
         cmp     #$ff       ;did we wrap to prev line?
         bne     @notEndOfPrev ;(NEVER) no -> skip adjust
         lda     #COLS-1    ;yes: fix #$ff to #COLS-1
         sta     zpCH
         dec     zpCV       ;and decrement row
@notEndOfPrev:
         jsr     CalcCursorTilemapPos ;calc new position
         jsr     WaitForVBlank ;wait again for safe PPU ops
         jsr     PpuGoToCursor ;and go there
         pla                ;pull char we got from start
         jmp     NmiWrTileSetVScrollAndEnableNmi ;and put it on last char of prev line

vZpCpyLimitRow .set $91
vZpInsChar .set  $b0
InsertSpaceChar:
         jsr     SaveCursorPos ;save cursor pos
         lda     #$20       ;SPACE char
         sta     vZpInsChar ;set as char to insert
@shiftRowsLp:
         jsr     CalcCursorTilemapPos ;update cursor VRAM addr
         lda     #NC_InsertChar
         jsr     WaitForNmiSubcommand ;insert the char, shifting others right
         ldx     zpCV
         jsr     DoesRowWrap ;does the current row wrap to the next?
         beq     InsSpC_checkFinalWrap ;no -> check if we just wrapped
         inc     zpCV       ;yes: go to next row
         jsr     CarriageReturn
         jmp     @shiftRowsLp ;and insert the shifted-off char onto next line

restoreCursorPos_B823:
         jmp     RestoreCursorPos

InsSpC_checkFinalWrap:
         lda     vZpInsChar ;get the shifted-off char from this row
         cmp     #$20       ;was it a SPACE char?
         beq     restoreCursorPos_B823 ;yes -> don't need to re-insert. Restore curs, return
         lda     zpCV       ;no; gotta wrap it to next row
         cmp     #ROWS-1    ;are we on the last row?
         beq     InsSpC_scrollAndInsert ;yes -> got to scroll screen
         jsr     CarriageReturn ;no, don't need to scroll
         ldy     zpCV
         iny                ;<- (could skip that by `cpy #ROWS-2` instead...)
         cpy     #ROWS-1    ;is next row the last one?
         beq     @haveRoom  ;yes -> skip making room for a new row
         lda     zpCV
         sta     vZpCpyLimitRow ;set current row for limit of down-copies
         lda     #ROWS-2    ;start at penultimate row
         sta     zpCV
@rowMoveLp:
         jsr     CalcCursorTilemapPos ;calc cursor VRAM addr
         lda     zpCV
         pha                ;push y pos
         lda     #NC_CopyRowDown
         jsr     WaitForNmiSubcommand ;copy this row down to next
         pla                ;pull y pos
         sta     zpCV
         tax
         jsr     DoesRowWrap ;copy "row wrapped" mark down one, too
         inx
         jsr     MarkWrappedRow
         dec     zpCV       ;go up one row
         lda     zpCV
         cmp     vZpCpyLimitRow ;did we finish making room for new row?
         bne     @rowMoveLp ;no -> copy this row down, too
@haveRoom:
         ldx     zpCV
         lda     #$ff       ;mark that we wrapped to new row (that's how we got here!)
         jsr     MarkWrappedRow
         inc     zpCV       ;move to new row
         inx
         lda     #$00
         jsr     MarkWrappedRow ;mark that new row doesn't wrap (it's new!)
         ldx     #ROWS-1
         jsr     MarkWrappedRow ;mark that final row of screen also doesn't wrap (nowhere to go)
         lda     zpSavedCH
         pha                ;push original cursor pos, and auto-insert flag
         lda     zpSavedCV
         pha
         lda     zpInsertMode
         pha
         lda     #$05       ;"print" Control-E (clear to end of row)
         jsr     PrintOneChar
         pla                ;pull auto-insert flag
         sta     zpInsertMode ;restore it
         lda     #NC_InsertChar
         jsr     WaitForNmiSubcommand ;insert the shifted-off char (uh... blank row, we should directly set it instead)
         pla
         sta     zpCV
         pla
         sta     zpCH       ;restore cursor pos
         rts                ;and return

InsSpC_scrollAndInsert:
         lda     zpSavedCH  ;push saved cursor x pos
         pha
         ldx     zpSavedCV  ;decrement cursor y pos unless at top of screen
         beq     @noDec
         dex
@noDec:  txa
         pha                ;and push
         jsr     ScrollScreenUpOneRow ;scroll screen up by one row
         lda     #ROWS-1    ;set cursor to start of (new) last row
         sta     zpCV
         lda     #$00
         sta     zpCH
         jsr     CalcCursorTilemapPos ;recalc cursor VRAM addr
         lda     #NC_InsertChar ;insert new char (uh... new row, shouldn't we just
         jsr     WaitForNmiSubcommand ; set it directly?)
         ldx     #$16       ;set X-reg to preceding row
         lda     #$ff
         jsr     MarkWrappedRow ;mark that preceding row wrapped to this one
         pla
         sta     zpCV       ;restore cursor position (but up one row, bc of scroll)
         pla
         sta     zpCH
         rts

jtbl_CtrlCharHandlers:
         .word   ControlCharNOOP
         .word   ToggleInsertOrOverwriteMode ;Control-A
         .word   ControlCharNOOP
         .word   CursorToNextLineStart ;STOP (Control-C)
         .word   ResetGraphicSettings ;Control-D
         .word   ClearToEndOfLine ;Control-E
         .word   ControlCharNOOP
         .word   CmdFn_BEEP ;Control-G
         .word   Backspace  ;BACKSPACE (Control-H)
         .word   HandleTabKey ;TAB (Control-I)
         .word   LineFeed   ;LF (Control-J)
         .word   CursorHome ;HOME (Control-K)
         .word   DoCLS      ;CLR/Shift-HOME (Control-L)
         .word   CarriageReturn ;CR (Control-M)
         .word   ControlCharNOOP
         .word   ControlCharNOOP
         .word   ControlCharNOOP
         .word   ControlCharNOOP
         .word   InsertSpaceChar ;INSERT (Control-R)
         .word   ControlCharNOOP
         .word   ControlCharNOOP
         .word   ControlCharNOOP
         .word   ActivateKanaMode ;Control-V
         .word   DeactivateKanaMode ;Control-W
         .word   ControlCharNOOP
         .word   ControlCharNOOP
         .word   ClearToEndOfScreen ;Control-Z
         .word   ControlCharNOOP
         .word   CursorRight ;Control-\
         .word   CursorLeft ;Control-]
         .word   CursorUp   ;Control-^
         .word   CursorDown ;Control-_

Rkim_returnNull:
         lda     #$00
         rts

Rkim_maybeFkey:
         sta     zpKeyWhichKey ;save char code that is > #$F0. Might be fn key, might be graphical tile.
         jsr     GetFnKey   ;if it's a function key, find out which.
         bcs     Rkim_handleFkey ;fn key? -> set up reads from macro definition
         lda     zpKeyWhichKey ;not a fn key, so return the char code as-is
         and     #$ff
         rts

Rkim_handleFkey:
         lda     zpKeyWhichKey
         ldx     zpFnKeyHeld ;has this fn key already been processed, and just not released yet?
         bne     Rkim_returnNull ;yes -> return null char
         sta     zpFnKeyCode ;save the char code as the fn key that was pressed
         lda     #$04
         sta     zpCursFlashCtr ;set a counter to 4
@lp4:    jsr     ReadKeyboard ;scan keyboard again
         cmp     zpFnKeyCode ;is it still the same function key code?
         bne     ReadKeyInsMacros ;no -> restart our whole key-reading thing
         dec     zpCursFlashCtr
         bne     @lp4       ;loop until the function key has been scanned 4 times since when it was first detected
         sec
         sbc     #$f0       ;subtract the #$f0, leaving 0-7
         jsr     MulABy16   ;multiply by 16 to get offset into fnkey defs
         sta     zpFnKeyDfnOff ;store that offset
         lda     #$ff
         sta     zpRkimMidMacro ;indicate that a not-already-handled fkey was typed
Rkim_typeFromMacro:
         ldx     zpFnKeyDfnOff
         lda     fnKey1_DfnBuf,x ;is the fkey definition exhausted?
         beq     Rkim_cancelFkeyAndReread ;yes -> cancel fkey and re-scan for keypress
         inx                ;else, point offset at next char in macro dfn
         stx     zpFnKeyDfnOff
         and     #$ff       ;and return this current char from it
         rts

Rkim_cancelFkeyAndReread:
         lda     #$00
         sta     zpRkimMidMacro
         ldx     #$ff
         stx     zpFnKeyHeld
; Read a keyboard character and return it. If a function key is typed, insert
; its macro definition one character at a time on successive calls.
ReadKeyInsMacros:
         lda     zpRkimMidMacro ;are we typing from an fkey macro dfn?
         bne     Rkim_typeFromMacro ;yes -> type next char from that
         jsr     ReadKeyboard ;read a char from keyboard
         beq     @nullChar  ;null? -> finish out
         cmp     #$f0       ;possible fkey?
         bcs     Rkim_maybeFkey ;yes -> investigate further
         and     #$ff       ;else return the kbd char
         rts

@nullChar:
         sta     zpFnKeyHeld ;Mark that no fkey is currently pressed
         rts

; Kbd reading routine.
; See https://www.nesdev.org/wiki/Family_BASIC_Keyboard#Hardware_interface for
; details on how keyboard reading works.
ReadKeyboard:
         lda     #$05
         sta     JOY1       ;Write $05 to keyboard: reset row/col scanning
         nop
         nop
         nop
         nop
         nop
         nop
         ldx     #$00
@kbdLp:  lda     #$04
         sta     JOY1       ;Write $04: prep read for column 0 of a new row
         ldy     #$0a
@dlyLp:  dey
         bne     @dlyLp
         nop
         nop
;                     bit: 7       0
; Read col 0 scan results: ---x xxx-
; 
; row 0: ]   [   RET F8
;     1: ;   :   @   F7
;     2: K   L   O   F6
;     3: J   U   I   F5
;     4: H   G   Y   F4
;     5: D   R   T   F3
;     6: A   S   W   F2
;     7: CTR Q   ESC F1
;     8: LFT RGT UP  CLR
; 
         lda     JOY2
         lsr     A          ;Move to occupy the low nybble
         and     #$0f
         sta     kbdDataAry,x ;...and store in KbdData + <<ROW>>
         lda     #$06
         sta     JOY1       ;Write $06: prep read for column 1, same row
         ldy     #$0a
@dlyLp1: dey
         bne     @dlyLp1
         nop
         nop
; 
;                     bit: 7       0
; Read col 1 scan results: ---x xxx-
; 
; row 0: STP \   RSH KANA
;     1: ^   -   /   _
;     2: 0   P   ,   .
;     3: 8   9   N   M
;     4: 6   7   V   B
;     5: 4   5   C   F
;     6: 3   E   Z   X
;     7: 2   1   GRP LSH
;     8: INS DEL SPC DWN
; 
         lda     JOY2
         rol     A          ;Move to occupy the high nybble
         rol     A
         rol     A
         and     #$f0
         ora     kbdDataAry,x ;Combine with low nybble (cols 0 and 1 now combined)
         eor     #$ff       ;Invert the bits, so that 1 = pressed
         ldy     #$08       ;And then store them in reversed order
@rvsLp:  asl     A
         ror     kbdDataAry,x
         dey
         bne     @rvsLp
         inx
         cpx     #$09
         bne     @kbdLp     ;Loop around to handle the next keyboard row
; We now have in kbdDataAry:
; 
; bit    7   6   5   4   3    2   1   0
; 
; kbdDataAry
;   + 0: F8  RET [   ]   KANA RSH \   STP
;   + 1: F7  @   :   ;   _    /   -   ^
;   + 2: F6  O   L   K   .    ,   P   0
;   + 3: F5  I   U   J   M    N   9   8
;   + 4: F4  Y   G   H   B    V   7   6
;   + 5: F3  T   R   D   F    C   5   4
;   + 6: F2  W   S   A   X    Z   E   3
;   + 7: F1  ESC Q   CTR LSH  GRP 1   2
;   + 8: CLR UP  RGT LFT DWN  SPC DEL INS
         lda     #$00
         sta     zpCtrlKeyDn
         sta     zpShiftKeyDn
         sta     zpGrphKeyDn
         lda     kbdDataAry+7
         and     #$10       ;is control key down?
         bne     RdKey_handleControl
         lda     kbdDataAry+7
         and     #$08       ;is left-shift down?
         bne     RdKey_handleLShift
         lda     kbdDataAry
         and     #$04       ;is right-shift down?
         bne     RdKey_handleRShift
         lda     kbdDataAry+7
         and     #$04       ;is GRPH key down?
         bne     RdKey_handleGrph
         jsr     RdKey_keyFindRecMap ;if no modifiers, just map the key to a character
         bne     @nonNull   ;non-null char? ->
         sta     zpModifierKeyDn ;null char. Set "special key pressed" flag to zero
         rts

@nonNull:
         ldy     zpModifierKeyDn ;if modifier or kana key is down, return null
         bne     @retNull
         ldy     zpKanaHeld
         bne     @retNull
         and     #$ff       ;else, return mapped character code
         rts

@retNull:
         lda     #$00
         rts

RdKey_handleControl:
         lda     #$ff       ;set control-key, modifier-key flags
         sta     zpCtrlKeyDn
         sta     zpModifierKeyDn
RdKey_maskModsFindRecMap:
         lda     kbdDataAry+7
         and     #$e3       ;mask out left-shift, control, graph keys
         sta     kbdDataAry+7
; Find the pressed non-modifier key, record it, and map it, modifying it as
; necessary by any active modifier keys. The mapped character will be returned.
; If multiple non-modifier keys are pressed simultaneously, only the first found
; is reported.
RdKey_keyFindRecMap:
         ldx     #$00
         ldy     #$09
@keyLp:  lda     kbdDataAry,x ;search for other keys down
         bne     RdKey_keyRecMap ;key? -> record and modify
         inx
         dey
         bne     @keyLp     ;no keys this row? check next
         sta     zpKeyWhichKey ;If we get here, no non-modifier keys were down.
         sta     zpKanaHeld
         rts

RdKey_handleLShift:
         lda     #$ff       ;set shift-key, modifier-key flags
         sta     zpModifierKeyDn
         sta     zpShiftKeyDn
         bne     RdKey_maskModsFindRecMap

RdKey_handleRShift:
         lda     #$ff       ;set shift-key, modifier-key flags
         sta     zpModifierKeyDn
         sta     zpShiftKeyDn
         lda     kbdDataAry
         and     #$fb       ;mask out right-shift (why is this only done here, and not for other modifiers?)
         sta     kbdDataAry
         jmp     RdKey_maskModsFindRecMap

RdKey_handleGrph:
         lda     #$ff       ;set modifier-key, special-key flags
         sta     zpGrphKeyDn
         sta     zpModifierKeyDn
         jmp     RdKey_maskModsFindRecMap

RdKey_keyRecMap:
         stx     zpKeyWhichRow ;save which key matrix row we found a key down
         ldy     #$00
         clc
@findKey:
         lsr     A          ;loop over bits in row until we find which key
         bcs     RdKey_mapKey ;found -> translate and modify it
         iny
         jmp     @findKey

RdKey_mapKey:
         txa
         asl     A          ;multiply row by 8
         asl     A
         asl     A
         sty     zpKeyWhichKey ;save which bit,
         clc
         adc     zpKeyWhichKey ; and add that (0-7) to A
         tax                ;X now holds a keycode
         lda     zpCtrlKeyDn ;is control being pressed?
         bne     RdKey_mapCtrlChar ;yes -> modify
         lda     zpShiftKeyDn ;else is shift being pressed?
         bne     RdKey_mapShiftedChar ;yes -> modify
         lda     zpGrphKeyDn ;else is GRPH key down?
         bne     RdKey_mapGrphModChar ;yes -> modify
         lda     zpKanaFlag ;else is kana mode active?
         bne     RdKey_mapKanaChar ;yes -> map
         lda     tbl_KeyMap,x ;else map normally
         cmp     #$ff       ;was KANA key pressed?
         beq     RdKey_maybeActivateKana ;yes -> check if we should handle
         and     #$ff       ;return mapped char
         rts

RdKey_maybeActivateKana:
         cmp     zpKanaHeld ;did we already handle kana key being pressed?
         beq     RdKey_returnNull ;yes -> return null
         sta     zpKanaHeld ;no -> indicate we've handled it
         jsr     ActivateKanaMode ;activate KANA mode
RdKey_returnNull:
         lda     #$00       ;then return null
         rts

RdKey_mapCtrlChar:
         lda     tbl_KeyMap,x ;translate key code to char code (~ASCII)
         cmp     #$20       ;is the looked-up key already a control?
         bcs     @notCtrlYet ;no -> modify
         and     #$ff       ;yes -> return it unmodified
         rts

@notCtrlYet:
         sec
         sbc     #$40       ;subtract 'A'-1
         bcc     RdKey_returnNull ;underflow? -> return null
         cmp     #$20       ;still outside range of control chars?
         bcs     RdKey_returnNull ;yes -> return null
RdKey_returnAsIs:
         and     #$ff       ;else: return the control char
         rts

RdKey_mapShiftedChar:
         lda     zpKanaFlag ;is kana flag on?
         bne     RdKey_mapShiftedKanaChar ;yes -> handle shifted kana
         lda     tbl_ShiftedKeyMap,x ;else return shifted non-kana key
         rts

RdKey_mapGrphModChar:
         lda     zpKanaFlag ;is kana mode active?
         bne     @grphOk    ;yes -> map grph char
         rts                ;no -> return null (graph means nothing outside kana mode)

@grphOk: lda     tbl_GrphKeyMap,x
         rts

RdKey_mapKanaChar:
         lda     tbl_KanaKeyMap,x
         jmp     kana

RdKey_mapShiftedKanaChar:
         lda     tbl_ShiftedKanaKeyMap,x
kana:    cmp     #$ff       ;was KANA key pressed while in KANA mode?
         bne     RdKey_returnAsIs ;no -> return the mapped char
         cmp     zpKanaHeld ;did we already handle this same KANA press?
         beq     RdKey_returnNull ;yes -> return null
         sta     zpKanaHeld ;no: mark that we've proceesed it
         jsr     DeactivateKanaMode ;and deactivate kana mode
         lda     #$00       ;then return null
rts_BA98:
         rts

; Scan through the captured keyboard matrix (kbdDataAry) for function
; keypresses.
; If found, carry will be set, and the X register will contain (8 - fnKey). If
; not found, carry will be unset.
; 
; Example: if the pressed function key is F8, X will be 8 - 8 = 0. If it is F1,
; X will be 8 - 1 = 7.
GetFnKey:
         ldy     #$08
         ldx     #$00
@fkyLp:  lda     kbdDataAry,x
         asl     A
         bcs     rts_BA98
         inx
         dey
         bne     @fkyLp
         clc
         rts

; Keymap of non-modifier keys.
; 
; The four keymaps below are used to decode from a key code to a character code.
; tbl_KeyMap is a map of unmodified character codes (note that all the modifier
; keys in it are mapped to #$00); and the keymaps after that are used in various
; situations when the shift key or GRPH key are down, or when kana mode is
; activated.
; 
; The keycode is represented as 8 * BYTE_NUM + BIT_NUM where the key was found,
; in kbdDataAry. BYTE_NUM is stored in zpKeyWhichRow ($6E), and BIT_NUM in
; zpKeyWhichKey ($6D).
; 
; Keycode values:
; 
;           +1  +2  +3    +4  +5  +6  +7
;     0: STP \   RSH KANA  ]   [   RET F8
;     8: ^   -   /   _     ;   :   @   F7
;    16: 0   P   ,   .     K   L   O   F6
;    24: 8   9   N   M     J   U   I   F5
;    32: 6   7   V   B     H   G   Y   F4
;    40: 4   5   C   F     D   R   T   F3
;    48: 3   E   Z   X     A   S   W   F2
;    56: 2   1   GRP LSH   CTR Q   ESC F1.
;    64: INS DEL SPC DWN   LFT RGT UP  CLR
; 
; NOTE: Function keys are translated to $F0-$F7... but! other keys _also_ can
; translate to those values (especially from the GRPH key). Therefore, when the
; character code is at or above $F0, one must examine the keycode or key matrix
; bitmap to distinguish whether it was graphical characters, or a function key.
; (Note: although KANA key maps to $FF, it is never returned from ReadKeyboard;
; it is handled internally, and then the null character is returned.)
tbl_KeyMap:
         .byte   $03,$5c,$00,$ff,$b3,$b2,$0d,$f7
