ShowCursor:
         jsr     CalcCursorTilemapPos
         lda     #NC_ShowCursor
         bne     waitNmi

HideCursor:
         jsr     CalcCursorTilemapPos
         lda     #NC_RestoreCharAtCursor
waitNmi: jmp     WaitForNmiSubcommand

; Read a character from the keyboard.
; 
; Flashes the cursor when nothing is being pressed, and handles key-repeat
; timings.
; Since it uses ReadKeyInsMacro, it will also honor F-keys.
ReadChar:
         lda     #$00
         sta     zpUnusedStopFlg ;clear the STOP flag that is never set to anything else
         jsr     ReadKeyInsMacros ;read keyboard
         beq     RC_awaitChar ;no key? -> await with cursor flash
         ldx     zpRkimMidMacro ;else, are we in an fkey macro read?
         bne     RdChr_RetChar ;yes -> set and return key from that
         cmp     zpHeldKeyChar ;else, is the key we got the same one we got last read?
         bne     RC_awaitChar ;no -> new char, handle via await
         lda     zpKeyRepeating ;has this key reached the rapid-repeat phase?
         bne     RC_shortRepeatingKey ;yes -> skip the longer first wait for repeat
         jsr     ShowCursor ;show the cursor while we wait for keypress to exceed repeat timer
@frstKeyHoldLp:
         jsr     ReadKeyInsMacros ;read key character
         beq     RC_hideCursAwaitChar ;no key? -> restart await, with flashing cursor
         cmp     zpHeldKeyChar ;is it the held key?
         bne     RC_hideCursAwaitChar ;no -> new cbar, handle via await
         dec     zpKyRptLongCtr ;decrement long-wait keypress timer
         bne     @frstKeyHoldLp ;loop until timer expires
         dec     zpKyNotRpt ;<- this is only ever #01
         bne     @frstKeyHoldLp ;<- so this never rebranches
         lda     #$ff
         sta     zpKeyRepeating ;we reached first repeat, so indicate that
         jmp     RC_clickAndReturnChar ;and click, return repeated char

RdChr_RetStopChar:
         lda     #$03
RdChr_RetChar:
         sta     zpHeldKeyChar
         rts

RC_shortRepeatingKey:
         jsr     ReadKeyInsMacros
         beq     RC_awaitChar
         cmp     zpHeldKeyChar
         bne     RC_awaitChar
         dec     zpKyRptShtCtr
         bne     RC_shortRepeatingKey
         lda     #$20
         sta     zpKyRptShtCtr
         jsr     ShowCursor ;show cursor for a frame right before hiding again
         jmp     RC_clickAndReturnChar

RC_hideCursAwaitChar:
         jsr     HideCursor ;not really sure what one frame of hidden cursor accomplishes
; Await keypress (may have already got one, but point is key-repeating is
; reset).
; Flashes cursor while waiting.
RC_awaitChar:
         lda     #$00       ;reset repeat-key settings
         sta     zpKeyRepeating
         sta     zpKyRptLongCtr
         lda     #$20
         sta     zpKyRptShtCtr
         lda     #$01
         sta     zpKyNotRpt
         jsr     ShowCursor ;show the cursor at current tile position
         lda     #CURS_FLASH_TM
         sta     zpCursFlashCtr ;set a count-down for when we should hide the cursor
@showLp: jsr     ReadKeyInsMacros ;Read a key
         bne     RC_recheckThenClickAndReturnChar ;got one? -> recheck, click, and return
         dec     zpCursFlashCtr
         bne     @showLp    ;loop around Rkim until we get a key, or timer expires
         jsr     HideCursor ;timer expired; hide the cursor
         lda     zpUnusedStopFlg ;check for STOP flag (no one ever sets)
         bne     RdChr_RetStopChar ;and return STOP char if set (never)
         lda     #CURS_FLASH_TM
         sta     zpCursFlashCtr ;reset count-down for when we should _show_ cursor again
@hideLp: jsr     ReadKeyInsMacros ;Read a key
         bne     RC_recheckThenClickAndReturnChar ;got one? -> recheck, click, and return
         dec     zpCursFlashCtr
         bne     @hideLp    ;loop around Rkim until we get a key, or timer expires
         lda     zpUnusedStopFlg ;check for STOP flag (no one ever sets)
         bne     RdChr_RetStopChar ;and return STOP char if set (never)
         jmp     RC_awaitChar ;timer expired -> loop around to show-cursor side of routine

RC_hideCursAwaitChar1:
         jsr     HideCursor ;not really sure what one frame of hidden cursor accomplishes
         jmp     RC_awaitChar ;also $BC6C does this same thing already

RC_recheckThenClickAndReturnChar:
         sta     zpHeldKeyChar ;set the new char as the "held" char, in case it's held for repeats
         lda     zpRkimMidMacro ;was a function-key macro invoked?
         bne     RC_clickAndReturnChar ;yes -> skip re-check, we'd get a different char!
         lda     #$01
         sta     zpCursFlashCtr
@nonLp:  jsr     ReadKeyInsMacros ;check keyboard again
         cmp     zpHeldKeyChar ;was same key still held?
         bne     RC_hideCursAwaitChar1 ;no-> start keypress check over again
         dec     zpCursFlashCtr
         bne     @nonLp     ;we set $74 to #$01 before the first dec, so this never loops
RC_clickAndReturnChar:
         jsr     HideCursor
         lda     zpKeyClickFlg ;is keyclick on?
         beq     @skpClick  ;no -> skip click
         jsr     KeyClick   ;make the key-click sound
@skpClick:
         lda     zpHeldKeyChar ;and return the key we got
         rts

CmdFn_BEEP:
         lda     #$f0
         sta     zpMisc     ;set beep length short
         .byte   $2c        ;(bypass next instr)
KeyClick:
         lda     #$01       ;set beep length itty-bitty, teenie-weenie
         sta     zpMisc
         lda     #$01
         sta     SND_CHN    ;enable pulse channel 1
         lda     #$c0
         sta     JOY2       ;sync APU frame counter
         lda     #$ef
         sta     SQ1_VOL    ;set volume fairly high
         lda     #$00
         sta     SQ1_SWEEP  ;no sweep
         lda     #$5f
         sta     SQ1_LO     ;set pitch (E5?)
         ldy     #$00
         sty     SQ1_HI
@waitLp: dey
         bne     @waitLp    ;delay loop, 256 iterations
         dec     zpMisc     ;beep length: was set at top of fn
         bne     @waitLp    ;not done playing? -> loop another 256
         lda     #$00
         sta     SND_CHN    ;done: disable the sound channel
         rts                ;and return

; Read a line of user input into lineBuffer
ReadLine:
         lda     #$00
         sta     zpLineBufIdx ;set character index to start
         sta     zpNMICMD   ;deactivate any active NMI commands
@readLineChars:
         jsr     ReadChar
         cmp     #$0d
         beq     RL_handleCR
         cmp     #$03
         beq     RL_handleStopOrCtrlD
         cmp     #$04
         beq     RL_handleStopOrCtrlD
         jsr     PrintOneChar
         jmp     @readLineChars ;loop and read more chars

RL_handleStopOrCtrlD:
         jsr     PrintOneChar ;process the control char
         ldx     zpLineBufIdx
         lda     #$00       ;abort line-reading
         sta     lineBuffer+1,x
         lda     #$03
         sta     lineBuffer,x
         rts

; Handle CR character from input
; First: back up rows until we're not on a wrapped one (that is, we're at the
; first row of a possible multi-row line)
RL_handleCR:
         lda     zpCV       ;get current row
         beq     @lineStart ;Exit loop if we're on the topmost line
         tax
         dex                ;check preceding row
         jsr     DoesRowWrap ;does that row wrap to this?
         beq     @lineStart ;no -> we found our line start
         dec     zpCV       ;yes; go to that row and re-check
         jmp     RL_handleCR ;Row is wrapped: loop back to preceding row

@lineStart:
         lda     zpCV
         sta     zpLineStartRow ;set the line row start
         lda     #NC_BufferCurLine
         jsr     WaitForNmiSubcommand ;Fetch the on-screen, possibly-wrapped line from PPU into lineBuffer
         lda     zpOutTxtStartPos ;<- NMICMD_BufferCurLine always sets before deactivating
         bne     @skpTrm    ;<- so this always branches ->
         ldx     zpLineBufIdx
         dex
         lda     #$00
         sta     lineBuffer,x
         stx     zpLineBufIdx
@skpTrm: ldx     zpLineBufIdx
@stripLp:
         dex                ;strip trailing spaces
         txa
         beq     @brk
         lda     lineBuffer,x
         cmp     #$20
         beq     @stripLp
@brk:    inx
         lda     #$00       ;set null terminator where we found the first trailing space
         sta     lineBuffer,x
         jmp     CursorToNextLineStart ;do the actual CRLF

INPUT_readLine:
         ldx     zpCV       ;get curent row
         beq     @topRow    ;top row? -> skip next bit
         dex
         lda     #$00
         jsr     MarkWrappedRow ;else, disconnect this row from the preceding one (if it was wrapped, make it... not)
@topRow: lda     #$00
         sta     zpLineBufIdx ;reset line bufer
         sta     zpNMICMD   ;deactivate any active NMI command
@rdLp:   jsr     ReadChar   ;read a character
         cmp     #$0d       ;is it carriage-return (Enter)?
         beq     INPUT_RL_handleCR ;yes -> finish up
         cmp     #$03
         beq     RL_handleStopOrCtrlD
         cmp     #$04       ;is it STOP, or Ctrl-D?
         beq     RL_handleStopOrCtrlD ;yes -> handle it
         jsr     PrintOneChar ;otherwise print the char to screen and advance
         jmp     @rdLp      ;-> loop back to read next character

; Does basically same thing as RL_handleCR, not sure why we need another sub
; to do the same thing. Slurps the user-typed input into lineBuffer, and removes
; trailing spaces.
INPUT_RL_handleCR:
         lda     zpCV       ;get current row #
         beq     @recordInpLine ;first row of screen? doesn't wrap -> proceed
         tax
         dex
         jsr     DoesRowWrap ;else, does the preceding row wrap to this one?
         beq     @recordInpLine ;yes -> proceed
         dec     zpCV       ;else go up one row
         jmp     INPUT_RL_handleCR ;and repeat the check

@recordInpLine:
         lda     zpCV       ;we're at the starting row for the line input
         sta     zpLineStartRow ;save it as such
         lda     #NC_BufferCurLine
         jsr     WaitForNmiSubcommand ;copy this line (this row and any it wraps to) into lineBuffer
         lda     zpOutTxtStartPos ;did NMICMD_BufferCurLine set $64 to non-zero? (always true)
         bne     @remTrailSpc ;(always) -> remove trailing spaces
         ldx     zpLineBufIdx ;(never): delete final buffered character
         dex
         lda     #$00
         sta     lineBuffer,x
         stx     zpLineBufIdx
; remove trailing spaces from lineBuffer
@remTrailSpc:
         ldx     zpLineBufIdx ;work from end of lineBuffer, back toward its start
@remLp:  dex                ;back up by one character
         txa
         beq     @lpDone    ;at start of line? -> done backing up
         lda     lineBuffer,x ;get the char
         cmp     #$20       ;is it a space?
         beq     @remLp     ;yes -> loop back around until we get non-space
@lpDone: inx
         lda     #$00
         sta     lineBuffer,x ;null-terminate at this spot (removing the spaces)
         jmp     CursorToNextLineStart ;-> move cursor to following line, and return

IncrCasBufPtr:
         inc     zpCasBufPtr
         bne     rts_BDD4
         inc     zpCasBufPtr+1
rts_BDD4:
         rts

IncrOnesCounter:
         inc     zpCasCksum
         bne     rts_BDD4
         inc     zpCasCksum+1
         rts

; Z is set iff zpCasBufPtr has reached zpCasEndPtr, and we're done sending the
; buffer.
IsCasDataDone:
         lda     zpCasBufPtr
         cmp     zpCasEndPtr
         bne     rts_BDD4
         lda     zpCasBufPtr+1
         cmp     zpCasEndPtr+1
         rts

CasBufSetData:
         lda     lineBuffer+$14
         sta     zpCasBufPtr
         clc
         adc     lineBuffer+$12
         sta     zpCasEndPtr
         lda     lineBuffer+$15
         sta     zpCasBufPtr+1
         adc     lineBuffer+$13
         sta     zpCasEndPtr+1
         rts

CasBufSetHeader:
         lda     #<lineBuffer
         sta     zpCasBufPtr
         lda     #>lineBuffer
         sta     zpCasBufPtr+1
         lda     #<lineBuffer+$80
         sta     zpCasEndPtr
         lda     #>lineBuffer
         sta     zpCasEndPtr+1
         rts

; NOTE: Vblank NMI will be DISABLED, unless the high bit is set in zpPpuCtrlVal
SetPpuCtrl:
         lda     zpPpuCtrlVal
         sta     PPUCTRL
         rts

SetPpuCtrlAndEnableNmi:
         lda     zpPpuCtrlVal
         ora     #$80
         sta     PPUCTRL
         rts

CasVrfyProgram:
         jsr     SetPpuCtrl ;disable NMI
         lda     #$01
         jmp     CLP_vrfyEntry

; Load a file (whether program, or bg data) from cassette (after having
; processed the header)
vZpLoopCtr .set  $91
CasRcvFileData:
         jsr     SetPpuCtrl ;disable NMI
         lda     #$00
CLP_vrfyEntry:
         sta     zpVerfFlag
         lda     #$00
         sta     zpCasCksum+1
         jsr     CasBufSetData ;set up cassette loading to go where header says
; Read a data announce/tape mark
; (skipping everything that isn't that)
; 
; String of 20ones, first
CasRcvDataAnn:
         lda     #20
         sta     vZpLoopCtr
@lpTwentyOnes:
         jsr     CassetteRcvBit ;read a bit
         bcs     @errIfSTOPped ;STOP pressed? -> re-enable NMI, then TP error
         bne     CasRcvDataAnn ;zero bit? -> Not announce mark yet, check next
         dec     vZpLoopCtr ;got a "one" bit, see if we get 20 total
         bne     @lpTwentyOnes ;not 20 yet? get another "one"
; String of 20 zeroes, next
         lda     #20
         sta     vZpLoopCtr ;read a bit
@lpTwentyZeroes:
         jsr     CassetteRcvBit ;STOP pressed? -> re-enable NMI, then TP error
@errIfSTOPped:
         bcs     casLdEnableNmiRetErr ;one bit? -> Not announce mark yet, check next
         beq     CasRcvDataAnn ;got a zero bit, see if we get 20 total
         dec     vZpLoopCtr ;not 20 yet? get another zero
         bne     @lpTwentyZeroes
         jmp     CasRcvJustBeforeAnnEnd ;Got the announce. Go get the program data

CasRcvHeader:
         jsr     SetPpuCtrl ;presumably to disable NMI
         lda     #$00
         sta     zpVerfFlag
         jsr     CasBufSetHeader ;set up for loading a header
; Read a header announce/tape mark
; (skipping everything that isn't that)
; 
; String of 40 ones, first
CasRcvHdrAnn:
         lda     #40
         sta     vZpLoopCtr
@lpFortyOnes:
         jsr     CassetteRcvBit ;read a bit
         bcs     casLdEnableNmiRetErr ;STOP pressed? -> re-enable NMI, then TP error
         bne     CasRcvHdrAnn ;zero bit? -> Not announce mark yet, check next
         dec     vZpLoopCtr ;got a "one" bit, see if we get 40 total
         bne     @lpFortyOnes ;not 40 yet? get another "one"
; String of 40 zeroes, next
         lda     #40
         sta     vZpLoopCtr
@lpFortyZeroes:
         jsr     CassetteRcvBit ;read a bit
         bcs     casLdEnableNmiRetErr ;STOP pressed? -> re-enable NMI, then TP error
         beq     CasRcvHdrAnn ;one bit? -> Not announce mark yet, check next
         dec     vZpLoopCtr ;got a zero bit, see if we get 40 total
         bne     @lpFortyZeroes ;not 40 yet? get another zero
; Header announce mark successfully read!
CasRcvJustBeforeAnnEnd:
         lda     #$00
         sta     zpCasCksum ;receive first (higher-order) byte for checksum
         sta     zpCasCksum+1
         jsr     CasSkipNextHigh ;finish up the zero cycle
         jsr     CasSkipNextHigh ;and skip the following cycle (a final "one")
@rdHdrPayload:
         jsr     CassetteRcvByte ;we're on low; this will skip a start bit before read
         bcs     casLdEnableNmiRetErr
         ldx     zpVerfFlag
         bne     @verify
         ldy     #$00
         sta     (zpCasBufPtr),y
         jmp     @load

@verify: ldy     #$00       ;verify the byte matches, rather than load
         cmp     (zpCasBufPtr),y
         bne     casLdEnableNmiRetErr ;not matched -> TP error
@load:   jsr     IncrCasBufPtr ;prep next byte save loc
         jsr     IsCasDataDone ;did we reach end?
         bne     @rdHdrPayload ;no -> read next byte
         lda     zpCasCksum
         sta     zpWParam
         lda     zpCasCksum+1
         sta     zpWParam+1
         jsr     CassetteRcvByte ;get first (higher-order) byte of checksum
         cmp     zpWParam+1 ;does it match our high byte?
         bne     casLdEnableNmiRetErr ;no -> TP error!
         jsr     CassetteRcvByte ;get second (lower-order) byte of checksum
         cmp     zpWParam   ;does it match our low byte?
         beq     success    ;yes -> re-enable NMI and return success
casLdEnableNmiRetErr:
         jsr     SetPpuCtrlAndEnableNmi
         lda     #$02
rtnFalse_BEC0:
         sec
         rts

success: jsr     SetPpuCtrlAndEnableNmi
         lda     #$00
         clc
         rts

; If the incoming cassette signal is low, skip that.
; If the incoming cassete signal is high, skips THAT.
; Was going to call it "CasSkipOneCycle" - which it may do - but the way it's
; typically used, it will more often just skip a high signal, so the name would
; be misleading.
CasSkipNextHigh:
         jsr     CheckForStopKey
         beq     rtnFalse_BEC0
         lda     JOY1
         and     #$02
         beq     CasSkipNextHigh ;loop while cassette signal is low
@lpWhileHi:
         jsr     CheckForStopKey
         beq     rtnFalse_BEC0
         lda     JOY1
         and     #$02
         bne     @lpWhileHi ;loop while cassette signal is high
         clc                ;return true/success
         rts

; Rather unintuitively, this routine with Z set if it's a "1" bit, and Z reset
; if it's a "0" bit.
; 
; If called when signal is low, will skip a full cycle, otherwise just skip
; high.
; It then waits 623 cycles (~348 ns) and checks signal state (this number of
; cycles was chosen so that it should fall right where you could determine
; whether this is a long pulse or a short one, distinguishing the bit value.
; 
; Also checks for the STOP key being pressed. If pressed, aborts early with
; carry set; otherwisse carry will be reset.
CassetteRcvBit:
         jsr     CasSkipNextHigh
         bcs     rtnFalse_BEC0 ;STOP pressed? -> return false
         ldy     #$4e       ;we're def at start of low signal from cassette
         sty     zpHeldKeyChar
@waitLp: dec     zpHeldKeyChar
         bne     @waitLp    ;77 * 8 + 7 = 623 cycles (~348 ns)
         lda     JOY1
         and     #$02       ;signal level to accum
         clc                ;return true/success
         rts

vZpByteVal .set  $19
CassetteRcvByte:
         lda     #$08       ;prepare to read 8 bits
         sta     zpCursFlashCtr
         lda     #$00
         sta     vZpByteVal
@nextBit:
         lda     vZpByteVal
         clc
         adc     vZpByteVal ;equiv: asl vZpByteVal (so why not do that?)
         sta     vZpByteVal
         jsr     CassetteRcvBit
         bcs     rtnFalse_BEC0 ;STOPped? -> return early
         bne     @zero      ;zero? -> don't modify the byte
         jsr     IncrOnesCounter ;one. Stick it in the low bit.
         inc     vZpByteVal
@zero:   dec     zpCursFlashCtr
         bne     @nextBit
         jsr     CasSkipNextHigh ;finish cycle (CassetteRcvBit will skip start bit)
         bcs     rtnFalse_BEC0 ;another opportunutiy to handle STOP
         lda     vZpByteVal
         clc                ;return true, accum has the byte read
         rts

CasSendHeader:
         jsr     SetPpuCtrl
         jsr     CasBufSetHeader
         lda     #40        ;Prog header starts with 40 high bits followed by 40 zeroes
         sta     zpCasCksum
         lda     #$00
         sta     zpCasCksum+1
         jmp     CassetteSend

CasSendData:
         jsr     SetPpuCtrl ;I think this is to disable NMI?
         jsr     CasBufSetData
         lda     #20        ;Prog data starts with 20 high bits followed by 20 zeroes
         sta     zpCasCksum
         lda     #$00
         sta     zpCasCksum+1
CassetteSend:
         lda     #32
         sta     zpMisc
         lda     #78        ;if this had been a #79, we'd send 20,000, probably the intended amt
         sta     zpMisc+1
@twenThouZeroLp:
         jsr     CassetteSendZero ;send 77 * 256 + 32 = 19,744 zeroes
         dec     zpMisc
         bne     @twenThouZeroLp
         dec     zpMisc+1
         bne     @twenThouZeroLp
         lda     zpCasCksum
         sta     zpMisc
; After the (not quite) 20,000 zeroes, we send an announce string of N ones and
; N zeroes, where N is 40 for the header, and 20 for the packet that contains
; the actual payload (BASIC program code, or page of BG graphics)
@onesLp: jsr     CassetteSendOne ;send a string of ones
         dec     zpMisc
         bne     @onesLp
@zeroesLp:
         jsr     CassetteSendZero ;send a string of zeroes
         dec     zpCasCksum
         bne     @zeroesLp
         jsr     CassetteSendOne
         lda     #$00
         sta     zpCasCksum
         sta     zpCasCksum+1
@sendBuffer:
         ldy     #$00       ;now send the designated data buffer
         lda     (zpCasBufPtr),y
         jsr     CassetteSendByte
         jsr     IncrCasBufPtr
         jsr     IsCasDataDone
         bne     @sendBuffer
         lda     zpCasCksum ;and a checksum (count of the ones in all bytes)
         pha
         lda     zpCasCksum+1
         jsr     CassetteSendByte
         pla
         jsr     CassetteSendByte
         jsr     CassetteSendOne ;send a final "one" bit at the end
         jmp     SetPpuCtrlAndEnableNmi

; Sends a one (start bit), followed by eight bits from the accumulator, most-
; significant bit first.
; 
; Instead of using the ASL operator, the author uses CLC and ADC to add a zero-
; page value to itself, doubling it each iteration.
CassetteSendByte:
         jsr     CassetteSendOne
         ldx     #$08
@shftLp: sta     zpMisc
         clc
         adc     zpMisc
         bcs     @sndOne
         jsr     CassetteSendZero
@dex:    dex
         bne     @shftLp
         rts

@sndOne: jsr     CassetteSendOne
         jsr     IncrOnesCounter
         jmp     @dex

; Sends the shorter (higher-freq) off/on cycle, indicating a zero (reset bit)
CassetteSendZero:
         pha
         lda     #$34
         sta     zpMisc+2
         sta     zpMisc+3
         jmp     CassetteSendBit

; Sends the longer (lower-freq) off/on cycle, indicating a one (set bit)
CassetteSendOne:
         pha
         lda     #$6a
         sta     zpMisc+2
         sta     zpMisc+3
; zpMisc+2 specifies how long to send low signal,
; zpMisc+3 specifies how long to send high signal
CassetteSendBit:
         lda     #$04
         sta     JOY1
@loLp:   dec     zpMisc+3
         bne     @loLp
         lda     #$ff
         sta     JOY1
@hiLp:   dec     zpMisc+2
         bne     @hiLp
         pla
         rts

vZpBgtTileBufIdx .set $3d   ;index into buffer for saving tiles from behind BGTOOL mode-select menu
vZpRowsRemain .set $74
vZpBgtMenuItemIdx .set $75
vZpBgToolModeId .set $7c
vZpBgtSelectCurTileRow .set $7d ;which row of tiles is showing in the tile SELECT menu
vZpTileIdTmp .set $7e
vZpBgtCurRowSelTileNum .set $7f ;index to which of the tiles in current tile row is the active tile for insertion
vZpBgtCurPaletteNum .set $88 ;currently-selected palette num for inserted tiles
BgtMode_CLEAR:
         jsr     DoCLS_1    ;clear SCREEN 1, restart BGTOOL
CmdFn_BGTOOL:
         jsr     ResetPaletteSets ;reset the palette sets to their hard-coded defaults
         ldy     #$08
         ldx     #$00
         txa
@attrClrLp:
         sta     sprAttrFlags,x ;clear sprite tile attrs for the 8 actors.
         inx
         dey
         bne     @attrClrLp ;-> loop until 8 actors' sprite attrs cleared
         lda     #>VRAM_screen1
         sta     zpPpuScreenBasePage ;set SCREEN 1 as current screen
         lda     #0
         sta     zpCH
         lda     #21
         sta     zpCV       ;put cursor at x:0,y:21
         lda     #key_CtrlZ ;Control-Z
         jsr     PrintOneChar ;invokes Control-Z's ClearToEndOfScreen function
         lda     #$01       ; (clearing from 0,21 to end of screen: last 4 rows)
         sta     zpCurScreenNum ;set the other SCREEN 1 zp var
         jsr     ClearOam   ;clear all sprite info from OAM DMA area
         jsr     WaitForVBlank ;wait for vblank
         lda     zpPpuCtrlVal
         ora     #$09
         sta     zpPpuCtrlVal ;set screen 1 for PPU, and set BG to use BG tiles
         jsr     NmiSetVScrollAndEnableNmi
         jsr     SetPpuCtrlAndEnableNmi ;enact the PPUCTRL changes
         jsr     CmdFn_SPRITE_ON ;turn sprites on
         lda     #$00
         sta     bgtCH      ;move BGTOOL cursor to 0,0
         sta     bgtCV
         sta     vZpBgtCurPaletteNum ;use BG palette 0
         sta     lineBuffer+4 ;???
         jmp     BgtStartupSelectMode ;-> done with init, enter SELECT mode

; Copy BGTOOL's cursor coords to global (text) cursor coords
BgtCursorToGlobalCursor:
         lda     bgtCH
         sta     zpCH
         lda     bgtCV
         sta     zpCV
         rts

BgtSetCursorAndReadChar:
         sta     zpKanaCursChr
         sta     zpNonKCursChr
         jsr     DeactivateKanaMode
         jmp     ReadChar

; Move the tile cursor (box sprite) according to the cursor key that was typed.
BgtHandleCursorKeys:
         cmp     #key_CursorRight
         beq     BgtCursorRight
         cmp     #key_CursorLeft
         beq     BgtCursorLeft
         cmp     #key_CursorUp
         beq     BgtCursorUp
         cmp     #key_CursorDown
         beq     BgtCursorDown
         rts

BgtCursorRight:
         lda     bgtCH
         cmp     #COLS-1    ;cursor on last column?
         beq     BgtCursStartOfNextLn ;yes -> cursor to start of next screen row
         inc     bgtCH      ;else, move cursor right
BgtNullKey:
         lda     #$00       ;zero register A, to prevent further key handling
         rts

BgtCursorLeft:
         lda     bgtCH      ;cursor on first column?
         beq     BgtCursEndOfPrevLn ;yes -> cursor to end of prev row
         dec     bgtCH      ;else, move cursor left
         jmp     BgtNullKey ;-> done

BgtCursEndOfPrevLn:
         lda     #COLS-1
         sta     bgtCH      ;move cursor to last column
BgtCursorUp:
         lda     bgtCV      ;cursor already at top line?
         beq     BgtNullKey ;-> done (nothing to do)
         dec     bgtCV      ;else move cursor up
         jmp     BgtNullKey ;-> done

BgtCursStartOfNextLn:
         lda     #$00
         sta     bgtCH      ;move cursor to start of line
BgtCursorDown:
         lda     bgtCV
         cmp     #BGT_ROWS-1 ;cursor already on bottom line?
         beq     BgtNullKey ;yes -> done (nothing to do)
         inc     bgtCV      ;else move cursor down one row
         bne     BgtNullKey ;(always) -> done
; 
BgtModeSelectMenu:
         jsr     CmdFn_SPRITE_OFF ;turn off sprites
         jsr     BgtSaveTilesBehindMenu ;save the tiles behind where menu will be drawn
         jsr     CursorHome ;LOCATE 0,0
         jsr     BgtDisplayModeSelectMenu ;display the mode-select menu
         jsr     CursorHome ;LOCATE 0,0
BgtMenu_Prompt:
         lda     #'>'
         jsr     BgtSetCursorAndReadChar ;set '>' as prompt at 0,0 and read a character
         cmp     #key_CursorUp ;handle menu keypresses
         beq     BgtModeSel_PrvMenuItem
         cmp     #key_CursorDown
         beq     BgtModeSel_NxtMenuItem
         cmp     #key_Space
         beq     BgtModeSel_Select
         cmp     #key_Stop
         beq     BgtModeSel_ExitTool
         bne     BgtMenu_Prompt ;no match? -> reprompt

BgtModeSel_ExitTool:
         jsr     BgtRestoreTilesBehindMenu ;restore tiles that were behind mode-select menu
         jsr     CarriageReturn
         lda     #21
         sta     zpCV       ;LOCATE 0,21
         lda     #key_CtrlZ
         jsr     PrintOneChar ;print ^Z (clear to end of screen)
         jsr     InitPromptChars ;restore BASIC prompt cursor chars
         lda     #>VRAM_screen0
         sta     zpPpuScreenBasePage ;set SCREEN 0 base page
         jsr     ResetPaletteSets ;reset palette set definitions
         jsr     DoCLS      ;clear the screen (we just did this with Ctrl-Z?)
         jsr     ClearSpriteData ;clear sprite definitions
         jsr     ClearOam   ;hide all sprites, clear attributes
         lda     #DEFAULT_PPUCTRL
         sta     zpPpuCtrlVal
         lda     #$00
         sta     zpCurScreenNum ;set SCREEN 0
         jsr     SetPpuCtrlAndEnableNmi ;activate new PPUCTRL value, enable NMI
         jmp     CmdFn_END  ;-> return to BASIC

BgtModeSel_PrvMenuItem:
         lda     zpCV       ;already at top menu item?
         beq     BgtMenu_Prompt ;yes -> just reprompt
         dec     zpCV       ;else go up a row
         jmp     BgtMenu_Prompt ;-> reprompt

BgtModeSel_NxtMenuItem:
         lda     zpCV
         cmp     #BGT_MODESEL_ITEMS ;already at bottom menu item?
         beq     BgtMenu_Prompt ;yes -> just reprompt
         inc     zpCV       ;else go down a row
         bne     BgtMenu_Prompt ;-> reprompt
; 
BgtModeSel_Select:
         lda     zpCV       ;get cursor row # (= menu item #)
         asl     A          ;times 2 for jump-table index
         tax
         lda     jtbl_BgtModeEntryPoints,x ;get entry point for selected mode
         sta     zpMisc
         lda     jtbl_BgtModeEntryPoints+1,x
         sta     zpMisc+1
         jmp     (zpMisc)   ;-> and jump to entry point

jtbl_BgtModeEntryPoints:
         .word   BgtMode_SELECT
         .word   BgtMode_COPY
         .word   BgtMode_MOVE
         .word   BgtMode_CLEAR
         .word   BgtMode_FILE
         .word   BgtMode_CHAR

bgtMenu_SvRstWrapup:
         jsr     NmiSetVScrollAndEnableNmi
         jmp     AwaitVBlankAndUpdatePpuMask

BgtSaveTilesBehindMenu:
         lda     #$ff
         .byte   $ae
BgtRestoreTilesBehindMenu:
         lda     #$00
         sta     lineBuffer ;using this location to indicate save vs restore
         jsr     AwaitVBlankAndClearPpuMask ;turn off screen rendering
         lda     #9
         sta     vZpRowsRemain ;number of rows to save/restore = 9
         lda     #$00
         sta     vZpBgtTileBufIdx ;start buffer index at 0
         jsr     CursorHome ;LOCATE 0,0
bgtMenu_SvRstLoop:
         jsr     CalcCursorTilemapPos
         jsr     PpuGoToCursor ;set current VRAM addr to cursor position
         lda     lineBuffer ;"restore" mode?
         beq     @skipFake  ;yes -> skip faked PPUDATA read
         lda     PPUDATA    ;else, fake a read from PPU
@skipFake:
         ldy     #10        ;number of cols to save/restore per row = 10
         ldx     vZpBgtTileBufIdx
@nextTile:
         lda     lineBuffer ;"restore" mode?
         beq     @restore   ;yes -> restore buffered tile
         lda     PPUDATA    ;else, get next tile from VRAM
         sta     bgtMenuTilesBuf,x ;save to buffer
         jmp     @nextIter

@restore:
         lda     bgtMenuTilesBuf,x ;get the original tile ID from the save/restore buffer
         sta     PPUDATA    ;write it to VRAM
@nextIter:
         inx                ;incr index into tile buffer
         dey                ;decr remaining rows to copy
         bne     @nextTile  ;rows left? -> save or restore next row
         stx     vZpBgtTileBufIdx ;save buffer index
         dec     vZpRowsRemain ;one fewer row to save/restore
         beq     bgtMenu_SvRstWrapup ;out of rows? -> done
         inc     zpCV       ;move cursor to next screen row
         bne     bgtMenu_SvRstLoop ;-> loop to handle next row
; 
BgtUpdateCursorAndPrintPos:
         jsr     ClearOam   ;clear all sprite data
         lda     #TileId_emptyBox ;empty box tile ID
         sta     oamSprTileId ;set that as sprite graphic
         lda     #$00
         sta     oamSprAttr ;clear sprite attrs
         lda     bgtCH      ;get bgtool cursor X position
         clc
         adc     #HMARGIN   ;add 2 for margin
         asl     A
         asl     A
         asl     A          ;times 8 (tiles -> pixels)
         sta     oamSprXPos ;set as cursor sprite x pos
         lda     bgtCV      ;get bgtool cursor Y position
         clc
         adc     #VMARGIN   ;add 3 for vert margin
         asl     A
         asl     A
         asl     A          ;times 8 (tiles -> pixels)
         sta     oamSprYPos ;set as cursor sprite y pos
         dec     oamSprYPos ;subtract one (for framing? idk)
         jmp     BgtPrintCursorPos

modeSelMenu_C17A:
         jmp     BgtModeSelectMenu

BgtMode_CHAR:
         jsr     InitPromptChars ;restore text prompt cursor chars
         jsr     BgtRestoreTilesBehindMenu ;restore the tiles from before mode-select menu
         lda     #$05
         jsr     BgtSetAndPrintCurrentMode ;print that we're in CHAR mode
         jsr     CmdFn_SPRITE_OFF ;turn off sprites (using normal prompt cursor chars instead)
         jsr     BgtCursorToGlobalCursor ;copy BGTOOL cursor pos to global (text) cursor
BgtChar_Prompt:
         jsr     SaveCursorPos ;save the new cursor pos
         lda     zpCH       ;copy global (text) cursor pos to BGTOOL cursor pos
         sta     bgtCH
         lda     zpCV
         sta     bgtCV
         jsr     BgtPrintCursorPos ;update cursor position display
         jsr     RestoreCursorPos ;restore cursor pos (changed during display update)
         jsr     ReadChar   ;read keyboard (with flashing cursor prompt)
         cmp     #key_Enter ;handle special keys:
         beq     BgtChar_Enter
         cmp     #key_Escape
         beq     modeSelMenu_C17A
         bcc     BgtChar_Prompt
         jsr     PrintOneChar ;no special key? then echo it here (draw to background)
         jsr     BgtChar_MaybeFixCV ;if we exceeded last row, return to it
         jmp     BgtChar_Prompt ;-> prompt for another input key

BgtChar_Enter:
         jsr     DoCRLF     ;go to start of next line
         jsr     BgtChar_MaybeFixCV
         jmp     BgtChar_Prompt ;-> prompt for next input

BgtChar_MaybeFixCV:
         lda     zpCV
         cmp     #BGT_ROWS  ;cursor y pos >= last BG row?
         bcs     @fix       ;yes -> fix
         rts                ;else -> return

@fix:    lda     #$14
         sta     zpCV       ;set y pos to last BG row
         rts                ;-> return

BgtPrintCursorPos:
         jsr     CarriageReturn
         lda     #22
         sta     zpCV       ;LOCATE 0,22
         lda     #'X'
         jsr     QueueCharForOutput
         lda     #':'
         jsr     QueueCharForOutput
         jsr     PrintOutBuf ;print "X:"
         jsr     EnsureSOL  ;CRLF (start of next line)
         lda     #'Y'
         jsr     QueueCharForOutput
         lda     #':'
         jsr     QueueCharForOutput
         jsr     PrintOutBuf ;print "Y:"
         lda     bgtCH
         sta     zpWAccum   ;put cursor x pos into WAccum
         lda     #2
         sta     zpCH
         lda     #22
         sta     zpCV       ;LOCATE 2,22
         jsr     @prCursPos ;print cursor x pos
         lda     bgtCV      ;put cursor y pos into WAccum
         sta     zpWAccum
         lda     #2
         sta     zpCH
         inc     zpCV       ;LOCATE 2,23
@prCursPos:
         jsr     ClearOperandHiBytes ;set WAccum high byte to 0
         jsr     PosDecStrFromWord ;convert WAccum (cursor position) to decimal string
         lda     #zpNumStrTmp ;point output string at decimal string
         clc
         adc     #$03       ;...plus 3, so we get the final 2 digits (skips 3 leading zeroes)
         sta     zpOutputStr
         lda     #>zpNumStrTmp
         sta     zpOutputStr+1
         jmp     PrintString ;-> print the coordinate, and return

strMODE: .asciiz "MODE  "
strSELECT:
         .asciiz "SELECT"
strMOVE: .asciiz "MOVE  "
strCOPY: .asciiz "COPY  "
strCHAR: .asciiz "CHAR  "
strCLEAR:
         .asciiz "CLEAR "
strFILE: .asciiz "FILE  "
tbl_BgToolModeStrs:
         .word   strSELECT
         .word   strCOPY
         .word   strMOVE
         .word   strCLEAR
         .word   strFILE
         .word   strCHAR

BgtDisplayModeSelectMenu:
         lda     #$00
         sta     vZpBgtMenuItemIdx ;start with first menu item
@menuLp: lda     #$20
         jsr     QueueCharForOutput ;print SPACE char
         lda     vZpBgtMenuItemIdx
         jsr     BgtPrintModeStr ;print the menu item string
         jsr     DoCRLF     ;move cursor to start of next line
         inc     vZpBgtMenuItemIdx ;advance menu item
         lda     vZpBgtMenuItemIdx
         cmp     #$06       ;printed six menu items?
         bne     @menuLp    ;no -> loop and print next item
         rts

; Store the mode id in register A, and print the mode at bottom of screen.
BgtSetAndPrintCurrentMode:
         sta     vZpBgToolModeId
; Print the currently-selected BGTOOL mode at the bottom of the screen.
BgtPrintCurrentMode:
         lda     #5
         sta     zpCH
         lda     #22
         sta     zpCV       ;LOCATE 5,22
         lda     #<strMODE
         sta     zpOutputStr
         lda     #>strMODE
         sta     zpOutputStr+1
         jsr     PrintString ;print "MODE" at 5,22
         lda     #$05
         sta     zpCH
         inc     zpCV       ;LOCATE 5,23
         lda     vZpBgToolModeId ;get the current mode index
; Print the name of the BGTOOL mode whose ID is in the A register.
BgtPrintModeStr:
         asl     A          ;times 2 for use as a string-table index
         tax
         lda     tbl_BgToolModeStrs,x
         sta     zpOutputStr
         lda     tbl_BgToolModeStrs+1,x
         sta     zpOutputStr+1 ;point zpOutputStr at the indexed string
         jmp     PrintString ;and print it

; the starting tile ID for each row of 8 tiles that can be viewed in BGTOOL's
; SELECT mode. (Skips "character" tiles; hence the leap to $b8 after the row
; that starts with $18 - $20 would be the space character)
tbl_BgSelectTileRowStarts:
         .byte   $00,$08,$10,$18,$b8,$c0,$c8,$d0
         .byte   $d8,$e0,$e8,$f0,$f8

BgtSELECT_NextPalette:
         jsr     BgtIncrPaletteNumAndDisplay ;select next palette in palette set
         jmp     BgtSelectModeContinue

BgtIncrPaletteNumAndDisplay:
         jsr     BgtIncrPaletteNumAndSet
         lda     zpCH       ;push CH, CV
         pha
         lda     zpCV
         pha
         lda     #10
         sta     zpCH
         lda     #22
         sta     zpCV       ;locate 10,22
         lda     vZpBgtCurPaletteNum ;get the currently-selected palette number
         ora     #$30       ;add #$30 to convert to ASCII digit
         jsr     PrintOneChar ;print the digit (after "MODE") at bottom of screen
         pla
         sta     zpCV       ;pull & restore CH, CV
         pla
         sta     zpCH
         rts

BgtSELECT_DeleteTile:
         jsr     SaveCursorPos ;save global cursor pos
         jsr     BgtCursorToGlobalCursor ;set it to bgt cursor pos
         lda     #key_Space
         jsr     PrintOneChar ;write a space over this location
         jsr     RestoreCursorPos ;restore global cursor pos
         jmp     BgtSelectModeContinue ;-> done

; BGTOOL SELECT mode, entry from mode-select menu
BgtMode_SELECT:
         jsr     BgtRestoreTilesBehindMenu
; entry from BGTOOL command, or via CLEAR mode selection
BgtStartupSelectMode:
         jsr     CmdFn_SPRITE_ON ;turn sprites on
         lda     #$00
         sta     vZpBgtCurRowSelTileNum ;currently-selected tile idx = 0
         sta     vZpBgtSelectCurTileRow ;current tile row = 0
         jsr     BgtSetAndPrintCurrentMode ;print that we're in SELECT mode
         lda     #$03
         sta     vZpBgtCurPaletteNum ;set current palette to 3 bc we'll increment before displaying
         jsr     BgtIncrPaletteNumAndDisplay ;increment (wraparound to 0) and set for tile menu
         lda     #12
         sta     zpCH
         lda     #23
         sta     zpCV       ;LOCATE 12,23 (useless, immediately relocated in next subrtn)
BgtSelectModeContinue:
         jsr     BgtCalcAndDisplayTileSelectRow ;show the current set of bg tiles
@prompt: jsr     SaveCursorPos
         jsr     BgtUpdateCursorAndPrintPos ;show the cursor box, and print its position
         jsr     RestoreCursorPos ;LOCATE 12,23 (just under the first SELECT-menu tile)
         lda     #'^'
         jsr     BgtSetCursorAndReadChar ;set '^' as the kbd cursor and prompt for keyboard input
         jsr     BgtHandleCursorKeys
         ldx     #$00       ;start with index 0
@whatKeyLp:
         cmp     tbl_bgtSelModeKeys,x ;into SELECT's recognized-keys table
         beq     @handleKey ;got one? -> handle key
         inx                ;else, index++
         cpx     #$08       ;out of acceptable keys in table?
         bne     @whatKeyLp ;no -> loop to check next acceptable key value
         beq     @prompt

@handleKey:
         txa
         asl     A          ;multiply key index times 2, for jump-table index
         tax
         lda     jtbl_bgtSelectKeyHandlers,x ;get the address to jump to
         sta     zpMisc
         lda     jtbl_bgtSelectKeyHandlers+1,x
         sta     zpMisc+1
         jmp     (zpMisc)   ;-> then do the jump

; A table of the recognized input keys in BGTOOL's SELECT mode
tbl_bgtSelModeKeys:
         .byte   key_Escape
         .byte   key_Enter
         .byte   key_Cls
         .byte   key_Home
         .byte   key_Del
         .byte   key_Insert
         .byte   key_Space
         .byte   'D'
jtbl_bgtSelectKeyHandlers:
         .word   BgtSELECT_ModeMenu ;Esc
         .word   BgtSELECT_NextPalette ;Enter
         .word   BgtSELECT_TileMenuPrevRow ;Shift-Home
         .word   BgtSELECT_TileMenuNextRow ;Home
         .word   BgtSELECT_TileMenuNextTile ;Backspace (DEL)
         .word   BgtSELECT_TileMenuPrevTile ;Ins
         .word   BgtSELECT_WriteTile ;Space
         .word   BgtSELECT_DeleteTile ;D

wrapAround:
         lda     #$00
         sta     vZpBgtCurPaletteNum
         beq     wrapCont

BgtIncrPaletteNumAndSet:
         inc     vZpBgtCurPaletteNum ;increment the palette number
         lda     vZpBgtCurPaletteNum
         cmp     #NUM_PALETTES ;did we advance past the last palette #?
         beq     wrapAround ;yes -> wrap around to zero and then continue
wrapCont:
         asl     A
         asl     A
         ora     vZpBgtCurPaletteNum ;copy for the top two of the quadrants covered in an attr byte
         pha                ;then push that value to CPU stack
         jsr     WaitForVBlank ;wait for vblank so it's safe to mess with PPU
         lda     #$27
         ldx     #$f3       ;go to $27F3 in VRAM, corresponding to
         jsr     PpuGoToAX  ; the palette ids for SELECT mode's displayed tiles
         pla
         tax
         and     #$fc       ;make a version that covers just the top-right quadrant
         sta     PPUDATA    ;store that as the first attr (this avoids setting color on the text
         txa                ; to the left of the tile menu)
         ldx     #$04
@cpyLp:  sta     PPUDATA    ;copy the full attribute byte, for the next 4 bytes
         dex
         bne     @cpyLp
         jmp     NmiSetVScrollAndEnableNmi ;-> done

; When ESC is typed while in SELECT mode
BgtSELECT_ModeMenu:
         lda     #12
         sta     zpCH
         lda     #22
         sta     zpCV       ;LOCATE 5,22
         lda     #$05       ;Control-E
         jsr     PrintOneChar ;print ^E (clear to end of line - erases menu tiles)
         inc     zpCV       ;LOCATE 5,23
         lda     #$05       ;Control-E
         jsr     PrintOneChar ;print ^E (clear to end of line - erases ^ prompt)
         jmp     BgtModeSelectMenu ;-> present mode-select menu

BgtSELECT_TileMenuPrevRow:
         lda     vZpBgtSelectCurTileRow ;get current tiles-row index
         beq     bgtSelModeCont_C39A ;first row? -> done; nothing to do
         dec     vZpBgtSelectCurTileRow ;else decr row
bgtSelModeCont_C39A:
         jmp     BgtSelectModeContinue ;-> continue SELECT mode

BgtSELECT_TileMenuNextRow:
         lda     vZpBgtSelectCurTileRow ;get current tiles-row index
         cmp     #BGT_SELECT_NUM_TROWS-1 ;on last row of tiles?
         beq     bgtSelModeCont_C39A ;yes -> done; nothing to do
         inc     vZpBgtSelectCurTileRow ;else go to next tile row
         bne     bgtSelModeCont_C39A ;(always) -> done (redisplay)
; 
BgtSELECT_TileMenuNextTile:
         lda     zpCH       ;get cursor position
         cmp     #SELMD_LAST_TILEPOS ;cursor at last tile of row?
         beq     bgtSelModeCont_C39A ;yes -> done; nothing to do
         inc     zpCH       ;else advance cursor by two
         inc     zpCH
         inc     vZpBgtCurRowSelTileNum ;and tile selection by one
         bne     bgtSelModeCont_C39A ;(always) -> done (redisplay)
; 
BgtSELECT_TileMenuPrevTile:
         lda     zpCH
         cmp     #SELMD_FRST_TILEPOS ;cursor at first tile of row?
         beq     bgtSelModeCont_C39A ;yes -> done; nothing to do
         dec     zpCH       ;else back up cursor two spaces
         dec     zpCH
         dec     vZpBgtCurRowSelTileNum ;select previous tile
         bpl     bgtSelModeCont_C39A ;(always) -> done (redisplay)
; 
BgtSELECT_WriteTile:
         jsr     SaveCursorPos ;save prompt cursor location
         jsr     BgtCursorToGlobalCursor ;copy bgtCH,bgtCV to CH,CV
         jsr     CalcCursorTilemapPos ;calculate VRAM addr for new position
         ldx     vZpBgtSelectCurTileRow ;get tile-menu row #
         lda     tbl_BgSelectTileRowStarts,x ;get starting tile ID for row
         clc
         adc     vZpBgtCurRowSelTileNum ;add which tile in row is selected
         sta     zpCharUnderCurs ;save as the tile ID to write
         lda     #NC_RestoreCharAtCursor
         jsr     WaitForNmiSubcommand ;write the tile to screen
         lda     vZpBgtCurPaletteNum
         sta     zpPaletteNum ;set the palette at cursor's current quadrant,
         jsr     COLOR_SetPalette ; to current SELECT palette choice
         inc     bgtCH      ;after writing tile, advance BGTOOL cursor to next tile cell
         lda     bgtCH
         cmp     #COLS      ;did we go past the end of the screen?
         beq     @cursNextRow ;yes -> move cursor to first cell of next row
@rstCursAndDone:
         jsr     RestoreCursorPos ;restore prompt cursor location
         jmp     BgtSelectModeContinue ;-> return to SELECT kbd prompt

@cursNextRow:
         lda     #$00
         sta     bgtCH      ;put bgtool cursor at start of line
         inc     bgtCV      ;advance bgtool cursor to next line
         lda     bgtCV
         cmp     #BGT_ROWS  ;moved past the end of BGTOOL screen?
         bne     @rstCursAndDone ;no -> done
         lda     #BGT_ROWS-1 ;yes -> lock it to last row of BGTOOL
         sta     bgtCV
         bpl     @rstCursAndDone ;-> done

BgtCalcAndDisplayTileSelectRow:
         jsr     SaveCursorPos ;save cursor position
         lda     #12
         sta     zpCH
         lda     #22
         sta     zpCV       ;LOCATE 12, 22
         ldx     vZpBgtSelectCurTileRow ;get the current tile row for displaying
         lda     tbl_BgSelectTileRowStarts,x ;load the starting tile ID for that row
         sta     vZpTileIdTmp ;and save it
         ldy     #$08
         ldx     #$00
@tilesLp:
         lda     vZpTileIdTmp ;get tile ID
         sta     lineBuffer+$10,x ;store in buffer
         inx                ;increment dst buffer index
         lda     #$20       ;SPACE character
         sta     lineBuffer+$10,x ;store that after row tile, in buffer
         inx                ;incr dst buf index
         inc     vZpTileIdTmp ;next tile ID for row
         dey                ;one fewer tile remaining
         bne     @tilesLp   ;-> loop until 8 tiles done
         jsr     CalcCursorTilemapPos
         ldx     #$00
         ldy     #$08
         jsr     WaitForVBlank ;wait for next vblank so it's safe to write to VRAM
         jsr     PpuGoToCursor ;LOCATE 12, 13
@writeLp:
         lda     lineBuffer+$10,x ;copy the tile row buffer out to screen
         sta     PPUDATA
         inx
         lda     #$20
         sta     PPUDATA
         inx
         dey
         bne     @writeLp
         jsr     NmiSetVScrollAndEnableNmi
         jmp     RestoreCursorPos ;-> restore cursor position, then done

; Given a screen tile position in CH, CV, and a palette num in zpPaletteNum
; ($9C), returns the byte value that holds palette nums for the 4x4 tiles
; holding that location, and an inverted mask for the palette num of the
; sekected 2x2 tile quad within that byte in zpMisc+1 ($1A). Also bit-shifts
; zpPaletteNum to align with that bit position.
; 
; See https://www.nesdev.org/wiki/PPU_attribute_tables for how palette selection
; for a tile quad works in the PPU.
GetTileQuadPaletteVal:
         inc     zpCH       ;xpos += 2 (left margin)
         inc     zpCH
         lda     zpVScroll0 ;get the scroll value for the active screen
         ldx     zpPpuScreenBasePage
         cpx     #>VRAM_screen0
         beq     @scr0
         lda     zpVScroll1
@scr0:   lsr     A          ;divide vert. scroll amt by 8 (convert pixels to tiles)
         lsr     A
         lsr     A
         clc
         adc     zpCV       ;add Y pos + 3 (upper margin)
         adc     #$03
         cmp     #30        ;modulo 30
         bcc     @lt30
         sbc     #30        ;we now have Y, relative to start of screen in memory
@lt30:   sta     zpCV       ;save adjusted Y
         and     #$fc       ;strip off lowest two bits (now multiple of 4)
         asl     A          ;and mul by 2 (now multiple of 8)
         sta     zpCursTileAddr
         lda     zpCH
         lsr     A
         lsr     A          ;add xpos/4
         clc
         adc     zpCursTileAddr
         adc     #$c0       ;add to location of start of screen 0 or 1's
         sta     zpCursTileAddr ; attribute table in VRAM (either $23C0 or $27C0)
         lda     zpPpuScreenBasePage
         adc     #$03       ;and save as the VRAM address
         sta     zpCursTileAddr+1 ;(we have the byte addr, but which pair of bits is palette num for our quad?)
         lda     #$02
         and     zpCV       ;((ypos / 2) mod 2) * 2 [upper vs lower half of byte]
         sta     zpMisc
         lda     zpCH
         and     #$03
         lsr     A          ;+ ((xpos / 2) mod 2) [pair of bits within that byte half]
         clc
         adc     zpMisc
         sta     zpMisc     ;save as our bit-pair position
         lda     #$fc       ;binary 11111100, to mask out just our palette num
         sta     zpMisc+1
         asl     zpMisc     ;bit position *= 2
         ldx     zpMisc
         beq     @shiftDone ;bit pos zero? -> nothing to shift
@shLftLp:
         asl     zpPaletteNum ;shift our palette-num val left one bit
         sec
         rol     zpMisc+1   ;shift our palettes mask left one bit
         dex                ;decrement bit position
         bne     @shLftLp   ;not yet at bit position? -> shift left again
@shiftDone:
         lda     #NC_GetCharUnderCursor ;zpPaletteNum aligned with its palette nun, and zpMisc holds aligned mask
         jsr     WaitForNmiSubcommand ;get the palettes byte at the VRAM loc we calc'd
         lda     zpCharUnderCurs
         rts                ;and return it

; Calls GetTileQuadPaletteVal, and then shifts the value over to the right as
; needed, so we have the actual number value.
GetTileQuadPaletteNum:
         jsr     GetTileQuadPaletteVal ;get the palette number for this tile quad
         sta     zpPaletteNum
         lda     zpMisc+1
         eor     #$ff       ;invert bitmask for palette num
         and     zpPaletteNum ;mask out everything but our palette num
         sta     zpPaletteNum
         ldy     zpMisc
         beq     @rts
@shftPalLp:
         lsr     zpPaletteNum ;shift palette number right until it's
         dey                ; in the appropriate range
         bne     @shftPalLp
@rts:    rts                ;and return it

errIll_C4C7:
         jmp     ErrorIllegalValue

; COLOR x, y, N
; 
; Selects not a color, but a palette, numbered from the currently-selectded
; palette set (as specified by CGSET). Associates it with the group of four
; (2x2) background tiles which contains the location given by x, y.
CmdFn_COLOR:
         lda     zpCH
         pha                ;push cursor position to stack
         lda     zpCV
         pha
         jsr     EvalByteInteger ;get 1st arg (x pos)
         cmp     #COLS      ;>= num screen cols?
         bcs     errIll_C4C7 ;yes -> error
         pha                ;push Xpos arg
         jsr     EvalCommaThenByteInt ;get 2nd arg
         lda     exprParseStk
         cmp     #ROWS      ;>= num screen rows?
         bcs     errIll_C4C7 ;yes -> error
         sta     zpCV       ;save as cursor Y
         pla
         sta     zpCH       ;pull 1st arg (x) and set as cursor X
         jsr     EvalCommaThenByteInt ;final arg (color palette num)
         lda     exprParseStk
         cmp     #$04       ;>= 4?
         bcs     errIll_C4C7 ;yes -> error
         and     #$03       ;<- redundant
         sta     zpPaletteNum ;save palette num
         jsr     COLOR_SetPalette
         pla
         sta     zpCV
         pla
         sta     zpCH       ;restore original cursor pos
         rts

COLOR_SetPalette:
         jsr     GetTileQuadPaletteVal
         and     zpMisc+1   ;mask out the palette for our tile quad
         ora     zpPaletteNum ;replace it with user-specified palette num
         sta     zpCharUnderCurs
         lda     #NC_RestoreCharAtCursor
         jmp     WaitForNmiSubcommand ;store the new value, and end command

; BACKGROUND SCREEN HEADER FORMAT:
; 
; byte 0:        #$03
; bytes 1 - 17:  null-term'd filename (no len byte)
; byte 18 - 19:  size of following packet's payload (always #$0100)
; bytes 20 - 21: address of genPurposeBuf (#$0700)
; byte 22:       vScroll1
; bytes 23-127:  (unused) 
vZpVramCpyPage .set $5f
SaveBackgroundMap:
         lda     #CAS_HDR_SCREEN ;START HEADER CREATION
         sta     lineBuffer ;Indicate this header precedes screen data
         lda     #$00
         sta     lineBuffer+$14
         lda     #$07
         sta     lineBuffer+$15
         lda     zpVScroll1
         sta     lineBuffer+$16
         ldx     #$00
         stx     lineBuffer+$12
         inx
         stx     lineBuffer+$13 ;END HEADER CREATION
         lda     #<VRAM_screen1
         sta     vZpVramCpyPage
         lda     #>VRAM_screen1
         sta     vZpVramCpyPage+1
         jsr     Print_WRITING_fileName
; Sends the header, then a payload with one page (256 bytes) of tiles
; from screen 1.
; 
; Very expensive, but can't be helped: we have to wait for a vblank before we
; can safely access the screen data, and I guess we can't send a second page
; without risking vblank ending and getting garbage data. After we send a page,
; we must await vblank again, and we can't do that _and_ send the cassette
; signals at the same time. So, individual header + payload it is.
; 
; Header is exactly the same each time.
@sendNextPage:
         jsr     AwaitVBlankAndClearPpuMask ;wait for next vblank, then disable screen rendering
         lda     vZpVramCpyPage+1
         ldx     vZpVramCpyPage
         jsr     PpuGoToAX  ;go to the VRAM address we'll be copying from
         lda     PPUDATA    ;fake PPU read
         ldx     #$00
@cpyTiles:
         lda     PPUDATA    ;read a tile ID
         sta     genPurposeBuf,x ;save it to buffer
         inx                ;next tile
         bne     @cpyTiles  ;-> loop until 256 tiles read
         jsr     NmiSetVScrollAndEnableNmi
         jsr     AwaitVBlankAndUpdatePpuMask ;restore screen rendering
         jsr     CasSendHeader ;send the header for this page of the BG data
         jsr     CasSendData ;send the data packet for this page
         inc     vZpVramCpyPage+1 ;advance to next VRAM page
         lda     vZpVramCpyPage+1
         cmp     #>VRAM_screen1+4 ;sent all VRAM pages for the bg screen?
         bne     @sendNextPage ;no -> loop until 4 pages sent
rts_C561:
         rts

vZpVramAddr .set $5f        ;Where to send loaded screen 1 data
LBM_SkipFile:
         jsr     Print_SKIP_fileName
LoadBackgroundMap:
         lda     #$00       ;set up dest ptr: first page of screen 1
         sta     vZpVramAddr
         lda     #$24
         sta     vZpVramAddr+1
LBM_readAPage:
         jsr     CasRcvHeader ;find and read a header
         bcs     rts_C561   ;error? -> rts
         lda     lineBuffer ;get header type
         cmp     #CAS_HDR_SCREEN ;is it a graphics chunk?
         bne     LBM_SkipFile ;no -> skip next 'til next header
         jsr     LoadCheckFilename ;yes, it's a BG save. Does filename match?
         bcs     LBM_SkipFile ;no -> skip to next header
         jsr     Print_LOADING_fileName ;match! (or missing.) Tell user we'll load it.
         lda     lineBuffer+$16
         sta     zpVScroll1 ;set vert scroll from header val
         jsr     CasRcvFileData ;load the BG data
         bcs     rts_C561
         jsr     AwaitVBlankAndClearPpuMask ;wait until next vblank so we can safely write VRAM
         lda     vZpVramAddr+1
         ldx     vZpVramAddr
         jsr     PpuGoToAX  ;tell PPU: writes go to screen 1
         ldx     #$00
@cpyToVram:
         lda     genPurposeBuf,x ;transfer a page of data (one quarter-screen) to screen 1
         sta     PPUDATA
         inx
         bne     @cpyToVram ;loop until page sent
         jsr     NmiSetVScrollAndEnableNmi ;re-enable NMI on vblank
         jsr     AwaitVBlankAndUpdatePpuMask
         inc     vZpVramAddr+1 ;we'll set PPU to the succeeding page
         lda     vZpVramAddr+1
         cmp     #$28       ;are we at the end of screen 1?
         bne     LBM_readAPage ;no -> read next page of screen data
         rts                ;yes: return!

vZpDestCursPalette .set $88 ;color palette # for the destination cursor
vZpDestCursTileId .set $91  ;tile id for the move/copy destination cursor sprite
vZpDestStateOn .set $ae     ;true if we're the destination cursor is active
vZpAmMove .set   $af        ;flag var for whether we're MOVE or COPY
BgtMvCpy_GoToModeSelect:
         lda     #$00
         sta     vZpDestStateOn ;turn off dest mode
         lda     #$f8
         sta     oamBuffer+$10 ;move dest cursor sprite offscreen
         jmp     BgtModeSelectMenu ;go to mode-select menu

BgtMode_MOVE:
         lda     #$02
         .byte   $ae
BgtMode_COPY:
         lda     #$01
         sta     zpBgGotFlag ;(unused)
         tax
         dex
         stx     vZpAmMove  ;set flag for whether we're MOVE or COPY
         jsr     BgtRestoreTilesBehindMenu ;restore the tiles that were behind the mode-select menu
         jsr     CmdFn_SPRITE_ON ;turn on sprites
         lda     #$00
         sta     vZpDestStateOn ;we're in "source" state
         jsr     BgtPrintCurrentMode ;update display of what MODE this is
BgtMvCpy_KbdPrompt:
         jsr     BgtUpdateCursorAndPrintPos ;redraw cursor sprite and coords
         jsr     BgtCpyMvUpdateDestCursor ;update/redraw destination cursor sprite
         lda     #key_Space
         jsr     BgtSetCursorAndReadChar ;prompt for a char (use a blank prompt char (no flashing))
         jsr     BgtHandleCursorKeys ;handle arrow keys
         cmp     #key_Escape ;handle other keys:
         beq     BgtMvCpy_GoToModeSelect
         cmp     #key_Insert
         beq     BgtCpyMv_PickupTile
         cmp     #key_Del
         beq     BgtCpyMv_DropTile
         bne     BgtMvCpy_KbdPrompt ;unrecognized key? -> reprompt

BgtCpyMv_DropTile:
         lda     vZpDestStateOn ;in "destination" state?
         beq     BgtMvCpy_KbdPrompt ;no -> nothing to do; reprompt
         jsr     SaveCursorPos ;save global cursor pos
         jsr     BgtCursorToGlobalCursor ;bgt cursor pos to global cursor pos
         jsr     CalcCursorTilemapPos ;get VRAM addr for cursor location
         lda     vZpDestCursTileId
         sta     zpCharUnderCurs
         lda     #NC_RestoreCharAtCursor
         jsr     WaitForNmiSubcommand ;write the source tile's ID to the current tile position
         lda     vZpDestCursPalette
         sta     zpPaletteNum
         jsr     COLOR_SetPalette ;write the source tile's palette to the current tile quad
         jsr     RestoreCursorPos ;restore global cursor pos
         lda     vZpAmMove  ;are we MOVE?
         beq     @reprompt  ;no -> just reprompt then
         lda     #$00
         sta     vZpDestStateOn ;MOVE completed, turn off "destination" state
@reprompt:
         beq     BgtMvCpy_KbdPrompt

BgtCpyMv_PickupTile:
         jsr     SaveCursorPos ;save global cursor
         jsr     BgtCursorToGlobalCursor ;copy bgt cursor to global cursor pos
         jsr     CalcCursorTilemapPos ;and calc the VRAM addr for that spot
         lda     #NC_GetCharUnderCursor
         jsr     WaitForNmiSubcommand ;get the tile that's under the cursor
         lda     zpCharUnderCurs
         sta     vZpDestCursTileId ;and copy it as the destination cursor sprite graphic
         lda     vZpAmMove  ;are we MOVE?
         beq     @amCopy    ;no, copy -> skip erasing existing tile
         lda     #key_Space ;yes, move
         sta     zpCharUnderCurs
         lda     #NC_RestoreCharAtCursor
         jsr     WaitForNmiSubcommand ;write space char to current tile pos (erasing existing)
@amCopy: lda     #$ff
         sta     vZpDestStateOn ;turn on destination state
         jsr     GetTileQuadPaletteNum ;copy tile's palette to dest cursor palette
         lda     zpPaletteNum
         sta     vZpDestCursPalette
         jsr     RestoreCursorPos ;restore global cursor
         jmp     BgtMvCpy_KbdPrompt ;-> go back to COPY/MOVE input prompt

BgtCpyMvUpdateDestCursor:
         lda     vZpDestStateOn ;are we in "source" state?
         beq     BgtCpyMvHideDestCursor ;yes -> hide the dest cursor sprite
         lda     vZpDestCursTileId
         sta     oamSprTileId+$10
         lda     vZpDestCursPalette
         and     #$0f       ;get the sprite palette for dest cursor
         sta     oamSprAttr+$10 ;and set for dest cursor sprite
         lda     bgtCH      ;get bgt cursor x pos
         clc
         adc     #HMARGIN   ;add 2 for the margin
         asl     A          ;times 8 (tiles -> pixels)
         asl     A
         asl     A
         sta     oamSprXPos+$10 ;save as dest cursor x pos
         lda     bgtCV      ;get bgt cursor y pos
         clc
         adc     #VMARGIN   ;add 3 for margin
         asl     A          ;times 8 (tiles -> pixels)
         asl     A
         asl     A
         sta     oamSprYPos+$10 ;save as dest cursor y pos
         dec     oamSprYPos+$10 ;decrement by one (for framing?)
         rts                ;-> done

BgtCpyMvHideDestCursor:
         lda     #248
         sta     oamSprYPos+$10 ;move dest sprite offscreen to hide it
         rts

strSAVE_OR_LOAD_Q:
         .asciiz "SAVE(S),LOAD(L)?"
strFILE_NAME:
         .byte   "FILE NAME",$22,$00

BgtMode_FILE:
         jsr     BgtRestoreTilesBehindMenu ;restore tiles from before menu display
         jsr     CarriageReturn
         lda     #22
         sta     zpCV       ;LOCATE 0,22
         lda     #key_CtrlZ
         jsr     PrintOneChar ;print Ctrl-Z, clearing to end of screen (rows 22,23)
         jsr     BgtFile_GoToScreen0 ;activate SCREEN 0
         jsr     InitPromptChars ;restore normal text prompt characters
         jsr     DoCLS      ;clear screen 0
         lda     #<strSAVE_OR_LOAD_Q
         sta     zpOutputStr
         lda     #>strSAVE_OR_LOAD_Q
         sta     zpOutputStr+1
         jsr     PrintString ;print "SAVE OR LOAD?"
         jsr     ReadChar   ;prompt for keyboard char
         cmp     #'S'
         beq     BgtFile_Save
         cmp     #'L'
         beq     BgtFile_Load
         bne     bgtoolRestart_C6D0

BgtFile_Save:
         jsr     PrintOneChar ;echo the typed 'S'
         jsr     BgtFile_PromptFilename ;prompt for the filename
         jsr     SaveBackgroundMap ;save the background out to tape
bgtoolRestart_C6D0:
         jmp     CmdFn_BGTOOL ;-> restart BGTOOL

BgtFile_Load:
         jsr     PrintOneChar ;echo the typed 'L'
         jsr     BgtFile_PromptFilename ;prompt for the filename
         jsr     LoadBackgroundMap ;load the background from tape
         jmp     bgtoolRestart_C6D0 ;-> restart BGTOOL

BgtFile_PromptFilename:
         jsr     DoCRLF     ;cursor to start of next line
         lda     #<strFILE_NAME
         sta     zpOutputStr
         lda     #>strFILE_NAME
         sta     zpOutputStr+1
         jsr     PrintString ;print "FILENAME", followed by double-quote char
         jsr     ReadLine   ;read line of input from user
         lda     lineBuffer
         cmp     #key_Stop  ;did we get STOP key?
         beq     @abort     ;yes -> abort load/save, restart BGTOOL in SELECT mode
         jsr     InitLineBufferScanning ;point TXTPTR at lineBuffer
         lda     #$09       ;lineBuffer includes "FILE NAME" in it;
         sta     zpTXTPTR   ; skip over that prompt (but not double-quote char)
         jsr     GetFileNameArg ;get the filename into the "cassette header" area of buffer
         jmp     FileNameCpyToLineBuffer ;-> and copy that back to the start of lineBuffer (erasing "FILE NAME" prompt and dquot)

@abort:  pla                ;pull up caller subrtn's return address
         pla
         jmp     bgtoolRestart_C6D0 ;-> and restart BGTOOL

tbl_MoveTables:
         .word   mtbl_SideProfiles ;Mario
         .word   mtbl_SideProfiles ;Lady
         .word   mtbl_StaticFacing ;Fighter Fly
         .word   mtbl_EightDir ;Achilles
         .word   mtbl_Penguin ;Penguin
         .word   mtbl_TwoFrame ;Fireball
         .word   mtbl_EightDir ;Car
         .word   mtbl_StaticFacing ;Spinner
         .word   mtbl_Spaceships ;Star Killer
         .word   mtbl_Spaceships ;Starship
         .word   mtbl_StaticFacing ;Explosion
         .word   mtbl_StaticFacing ;Smiley
         .word   mtbl_Laser ;Laser
         .word   mtbl_TwoFrame ;Shell Creeper
         .word   mtbl_StaticFacing ;Side Stepper
         .word   mtbl_TwoFrame ;Nitpicker
tbl_ActorSprShtOffsets:
         .byte   0          ;Mario
         .byte   28         ;Lady (added to tile IDs from ss_Mario)
         .byte   0          ;Fighter Fly
         .byte   0          ;Achilles
         .byte   0          ;Penguin
         .byte   0          ;Fireball
         .byte   56         ;Car (added to tile IDs from ss_Achilles)
         .byte   88         ;Spinner (added to tile IDs from ss_FighterFly)
         .byte   0          ;Star Killer
         .byte   12         ;Starship (added to tile IDs from ss_StarKiller)
         .byte   120        ;Explosion (added to tile IDs from ss_FighterFly)
         .byte   32         ;Smiley (added to tile IDs from ss_FighterFly)
         .byte   0          ;Laser
         .byte   72         ;Shell Creeper (added to tile IDs from ss_Fireball)
         .byte   136        ;Side Stepper (added to tile IDs from ss_FighterFly)
         .byte   88         ;Nitpicker (added to tile IDs from ss_Fireball)
; Mario and Lady
mtbl_SideProfiles:
         .word   fftbl_SideProfiles ;animation frame counts
         .word   ss_Mario
         .word   fftbl_SideProfiles ;tile flips
; Fireball, Shell Creeper, Nitpicker
mtbl_TwoFrame:
         .word   fftbl_NoFlipsTwoFrames ;animation frame counts (always two)
         .word   ss_Fireball
         .word   fftbl_OnlyHFlips_TwoFOneSt ;tile flips (just horizontally)
; Fighter Fly, Spinner, Explosion, Smiley, Side Stepper
mtbl_StaticFacing:
         .word   fftbl_NoFlipsTwoFrames ;animation frame counts (always two)
         .word   ss_FighterFly
         .word   fftbl_NoFlipsTwoFrames ;tile flips (never flip)
; Achilles and Car
mtbl_EightDir:
         .word   fftbl_NoFlipsTwoFrames ;animation frame counts (always two)
         .word   ss_Achilles
         .word   fftbl_AllFlipsNoAnim ;tile flips (every direction)
; Penguin
mtbl_Penguin:
         .word   fftbl_OnlyHFlips_TwoFOneSt ;animation frame cnts (always two, except when stationary)
         .word   ss_Penguin
         .word   fftbl_OnlyHFlips_TwoFOneSt ;tile flips (horizontal only)
; Star Killer and Starship
mtbl_Spaceships:
         .word   fftbl_AllFlipsNoAnim ;animation frame counts (always one: no animation!)
         .word   ss_StarKiller
         .word   fftbl_AllFlipsNoAnim ;tile flips (every direction)
; Laser (identical to spaceships, except spritesheets)
mtbl_Laser:
         .word   fftbl_AllFlipsNoAnim ;animation frame counts (always one: no animation!)
         .word   ss_Laser
         .word   fftbl_AllFlipsNoAnim ;tile flips (every direction)
; The following four tables are pointed at by the first and last entries of the
; mtbl_* tables above, and are indexed by the 9 possible sprite movement
; directions.
; 
; The high nybbles represent the horizontal and vertical "flip" to use with
; tiles in the actor's sprite sheets (bits 7 and 8 of the sprite object's sprite
; attr flags (in sprAttrFlags).
; 
; The low nybble indicates how many frames of animation exist for that
; facing/posture.
; 
; The structure of the mtbl_* vars allows mix-and-match between using the flip
; bits of one row, and the number-of-frames from a different row. For instance,
; both the spaceships, and the sprites I've dubbed "EightDir" (Car, Achilles),
; can truly point in eight different directions (I'm not counting "stationary",
; here), and both use three separate sprite sheets in total, flipping and
; reordering the tiles of those three to make up the other five. So, they both
; use the same row to specify their "flip" bits for the various orientations.
; However, they differ in that Car and Achilles each have two frames of
; animation for each facing, while the spaceships only have one. Therefore, they
; use _different_ rows to specify the number of frames.
; 
; Using "fftbl_" as the prefix for these tables; "ff" for "flips-n'-frames".
; 
; fftbl_SideProfiles, the first of these, is used only by Mario and Lady, and is
; used for both the flips, and the animation frame counts.
fftbl_SideProfiles:
         .byte   $01,$02,$41,$43,$41,$02,$01,$03,$01
; fftbl_NoFlipsTwoFrames: When used for animation frame counts, specifies two
; frames. When used for tile flips, never flips any tiles. Both regardless fo
; direction, including stationary.
fftbl_NoFlipsTwoFrames:
         .byte   $02,$02,$02,$02,$02,$02,$02,$02,$02
; fftbl_AllFlipsNoAnim: flips in all directions, all sprite sheets
; have one frame
fftbl_AllFlipsNoAnim:
         .byte   $01,$01,$41,$41,$c1,$81,$81,$01,$01
