AnimateAndToggleNextFrame:
         txa                ;push X
         pha
         tya                ;push Y
         pha
         jsr     Animate    ;run the animations!
         pla
         tay                ;pull Y
         pla
         tax                ;pull X
         lda     #$00
         sta     zpNmiAnimNxtFr ;indicate next frame should do NMI subcmds, not animate
         pla
         rti                ;return from interrupt

Animate: ldx     #$00
         stx     zpNmiActorNum ;start with sprite #0
         lda     #$08
         sta     zpNmiAnimActCtr ;start with assumption that all 8 sprites are animated
sprLoop: ldx     zpNmiActorNum
         lda     sprAttrFlags,x
         and     #SpAtt_ANIMATE ;is this sprite animated?
         bne     AnimateOne ;yes -> handle
         dec     zpNmiAnimActCtr ;no: decrement animated sprites counter
         beq     disableAnims ;# animated sprites == 0? -> disable animation flag
         inx                ;(useless)
AnimateCont:
         inc     zpNmiActorNum
         lda     zpNmiActorNum
         cmp     #$08       ;have we done all 8 sprites yet?
         bne     sprLoop    ;no -> go to next sprite
         rts                ;return

disableAnims:
         lda     #$00
         sta     zpNmiAnimate
         rts

MoveExpired:
         lda     defMovSMotion,x ;reset total movement remaining
         sta     defMovSMotionCtr,x
         ldx     zpNmiActorNum
         lda     sprAttrFlags,x
         and     #$ef
         sta     sprAttrFlags,x ;stop animation for this sprite
         jmp     AnimateCont ;continue on to next sprite

; Handle animation of one sprite
AnimateOne:
         lda     zpNmiActorNum ;sprite number...
         asl     A
         asl     A
         asl     A          ;...times eight...
         sta     zpNmiDefMovIdx
         tax                ;...gives offset to start of this sprite's defMovS* vars
         dec     defMovSSpdCtr,x ;decrement speed counter. Is it zero?
         bne     AnimateCont ;no -> skip animating this sprite this frame (throttle speed)
         lda     defMovSSpeed,x ;yes: reset the counter to user-specified speed value
         sta     defMovSSpdCtr,x
         dec     defMovSMotionCtr,x ;decrement movement counter. Is it zero?
         beq     MoveExpired ;yes -> reached max motion; stop animating this sprite
         lda     defMovSActorFrm,x ;no: get MOVE actor id and frame number
         and     #$0f       ;mask for the actor id nybble (removing frame number)
         tay
         lda     tbl_ActorSprShtOffsets,y
         sta     zpNmiSprShtOff
         tya
         asl     A          ;multiply actor id * 2, to get entry in tbl_MoveTables
         tay
         lda     tbl_MoveTables,y ;get the pointer entry into zpNmiCurMTbl
         sta     zpNmiCurMTbl
         lda     tbl_MoveTables+1,y
         sta     zpNmiCurMTbl+1
         lda     defMovSFacing,x ;get the sprite's direction
         asl     A          ; * 2 for pointer entry
         tay
         lda     tbl_moveDeltaX,y ;look up sprite's horizontal motion
         clc
         adc     defMovSPosX,x
         sta     defMovSPosX,x ;and add it to sprite's horizontal position (move the sprite)
         clc
         lda     tbl_moveDeltaY,y ;look up sprite's vertical motion
         adc     defMovSPosY,x
         sta     defMovSPosY,x ;and add it to sprite's vert position (move the sprite)
         ldy     #$00
         lda     (zpNmiCurMTbl),y ;get a pointer to this sprite's frame counts vector
         sta     zpNmiCurFrCnts
         iny
         lda     (zpNmiCurMTbl),y
         sta     zpNmiCurFrCnts+1
         lda     defMovSFacing,x ;get sprite's facing again
         tay
         lda     (zpNmiCurFrCnts),y ;use that to get frame count for cur facing's animation
         and     #$0f       ;mask out h/v tile flip info, we just want frame cnt
         jsr     MulABy16   ;move low nybble to high
         and     #$ff       ;(for comparison below?)
         sta     zpNmiNumFrames ;and save
         beq     AnimOne_skipAnim ;(never branches! should've compared to #$01 first)
         lda     defMovSActorFrm,x ;get the sprite's actor id and frame num
         and     #$f0       ;mask out the id, just want frm num (high nybble)
         clc
         adc     #$10       ;increment frame count
         cmp     zpNmiNumFrames ;did we exceed maximum frame count for this facing?
         bne     @noRst     ;no -> don't reset
         lda     #$00       ;yes: reset frame num to zero
@noRst:  pha                ;push frame number
         lda     #$0f
         and     defMovSActorFrm,x
         sta     defMovSActorFrm,x ;mask out sprite's frame num, and save
         pla
         pha
         ora     defMovSActorFrm,x
         sta     defMovSActorFrm,x ;save our new frame num in sprite's info
         pla
AnimOne_skipAnim:
         lsr     A
         lsr     A          ;Multiply by 4 and save in zpNmiNumFrames
         sta     zpNmiNumFrames ; which is now an offset to add to tile IDs, to get cur frame's tilemap
         ldy     #$02
         lda     (zpNmiCurMTbl),y ;fetch a pointer to the facings spritsheet for cur spr
         sta     zpNmiCurSprSht
         iny
         lda     (zpNmiCurMTbl),y
         sta     zpNmiCurSprSht+1
         lda     defMovSFacing,x ;get facing
         asl     A
         tay
         lda     (zpNmiCurSprSht),y ;index spritesheet by the facing
         sta     zpNmiSprTileMp ;save pointer to the 2x2 tilemap
         iny
         lda     (zpNmiCurSprSht),y
         sta     zpNmiSprTileMp+1
         lda     defMovSFacing,x ;get facing yet again
         cmp     #$01       ;is it facing #1 (straight up)?
         beq     @oneOrFive
         cmp     #$05       ;is it facing #1 (up) or #5 (down)?
         bne     AnimOne_ordinaryAnim ;no -> handle normally
@oneOrFive:
         lda     defMovSActorFrm,x ;yes: get actor id
         and     #$0f       ;mask out frame num
         beq     AnimOne_marioOrLady
         cmp     #$01
         beq     AnimOne_marioOrLady ;id 0 (Mario) or 1 (Lady)? -> handle specially
         cmp     #$04
         bne     AnimOne_ordinaryAnim ;NOT id 4 (penguin)? -> handle normally
         lda     zpNmiNumFrames ;(If we're here, we are the penguin)
         beq     AnimOne_frameZero ;anim frame 0? -> no alterations
         lda     defMovSFacing,x ;get facing
         cmp     #$05       ;facing 5 (down)?
         beq     AnimOne_penguinDown ;yes -> deal with that
         lda     #<spr_PenguinUp1 ;no: we're facing 1 (up)
         sta     zpNmiSprTileMp ;set the tilemap ptr value directly
         lda     #>spr_PenguinUp1
         bne     AnimOne_setTMapHiByt

AnimOne_penguinDown:
         lda     #<spr_PenguinDown1 ;set the tilemap ptr value directly
         sta     zpNmiSprTileMp
         lda     #>spr_PenguinDown1
         bne     AnimOne_setTMapHiByt

AnimOne_marioOrLady:
         lda     zpNmiNumFrames
         beq     AnimOne_frameZero ;anim frame 0? -> no alterations
         lda     #<spr_MarioClimb1 ;2nd frame: use alternate (h. mirrored) tilemap
         sta     zpNmiSprTileMp ;(doesn't matter if we're climbing up or down)
         lda     #>spr_MarioClimb1
AnimOne_setTMapHiByt:
         sta     zpNmiSprTileMp+1
         ldy     zpNmiActorNum
         lda     #$40       ;ensure horizontal tile flipping is on for mirrored sprite
         ora     sprAttrFlags,y
         sta     sprAttrFlags,y
         lda     #$00       ;clear tile ID offsets for animation frame; we took care of it
         sta     zpNmiNumFrames
         beq     AnimOne_ordinaryAnim

AnimOne_frameZero:
         ldy     zpNmiActorNum
         lda     sprAttrFlags,y
         and     #$3f       ;clear tile flipping (frame zero of up/down anim, so not mirrored)
         sta     sprAttrFlags,y
AnimOne_ordinaryAnim:
         lda     zpNmiActorNum
         jsr     MulABy16   ;get index into DMA buffer for this sprite number
         tax
         ldy     #$00
         lda     (zpNmiSprTileMp),y ;get tile 0 ID
         clc
         adc     zpNmiSprShtOff ;add offset for this actor (character)
         adc     zpNmiNumFrames ;and the offset for the anim frame
         sta     oamBuffer+$81,x ;save to PPU DMA area
         iny
         lda     (zpNmiSprTileMp),y ;..repeat for tile 1 ID...
         clc
         adc     zpNmiSprShtOff
         adc     zpNmiNumFrames
         sta     oamBuffer+$85,x
         iny
         lda     (zpNmiSprTileMp),y ;..repeat for tile 2 ID...
         clc
         adc     zpNmiSprShtOff
         adc     zpNmiNumFrames
         sta     oamBuffer+$89,x
         iny
         lda     (zpNmiSprTileMp),y ;..repeat for (final) tile 3 ID...
         clc
         adc     zpNmiSprShtOff
         adc     zpNmiNumFrames
         sta     oamBuffer+$8d,x
         ldy     zpNmiActorNum
         lda     sprAttrFlags,y ;get the sprite attrs
         sta     oamBuffer+$82,x ;and copy to each of the four sprite tiles
         sta     oamBuffer+$86,x
         sta     oamBuffer+$8a,x
         sta     oamBuffer+$8e,x
         ldy     zpNmiDefMovIdx
         lda     defMovSPosX,y
         sta     oamBuffer+$83,x ;copy sprite X position to tile 0 X pos
         sta     oamBuffer+$8b,x ;and tile 2 X pos
         clc
         adc     #$08       ;add 8
         sta     oamBuffer+$87,x ;and save that as tile 1 X pos
         sta     oamBuffer+$8f,x ;and tile 3
         lda     defMovSPosY,y
         sta     oamBuffer+$80,x ;copy sprite Y position to tile 0 Y pos
         sta     oamBuffer+$84,x ;and tile 2 Y pos
         clc
         adc     #$08       ;add 8
         sta     oamBuffer+$88,x ;and save that as tile 1 Y pos
         sta     oamBuffer+$8c,x ;and tile 3
         jmp     AnimateCont ;Done with this sprite! On to the next.

errIllVal_CA55:
         jmp     ErrorIllegalValue

errSyn_CA58:
         jmp     ErrorSyntax

; Not in jtbl_Commands: in reality, this is the "DEF" command when immediately
; followed by the "MOVE" token. CmdFn_DEF jumps to here in that case.
vZpSprMvTbl .set $19
vZpSprFacingFlipTbl .set $1b
vZpSavedX .set   $ad
CmdFn_DEFMOVE:
         jsr     TxtPtrIncr
         jsr     SkipLParenOrSynErr ;parse '('
         jsr     EvalByteInteger ;get sprite #
         jsr     ErrUnlessZeroThruSeven ;demand it be less than 8
         jsr     SkipRParenOrSynErr ;parse ')'
         lda     exprParseStk ;sprite #
         tax
         lda     #$e7
         and     sprAttrFlags,x
         sta     sprAttrFlags,x ;clear sprite attr flags SpAtt_ANIMATE and SpAtt_DEFMOVE
         txa
         sta     zpActorNum ;store sprite number
         asl     A
         asl     A
         asl     A
         sta     zpDefMovIdx ;store offset for defMovS* vars
         jsr     SkipEqualsOrErr ;parse '='
         jsr     TxtSkipSpaces
         cmp     #tok_SPRITE ;parse 'SPRITE'
         bne     errSyn_CA58 ;(or error)
         jsr     TxtPtrIncr
         jsr     SkipLParenOrSynErr ;parse '('
         jsr     DefMvEvalFirstArg ;get first arg after SPRITE
         cmp     #$10
         bcs     errIllVal_CA55 ;>= 16? -> error
         sta     defMovSActorFrm,x ;first arg is charactor/actor id
         jsr     DefMvEvalNextArg ;2nd arg
         stx     vZpSavedX  ;save X away (...isn't it already saved in zpDefMovIdx?)
         sta     zpWAccum   ;save 2nd arg to WAccum
         cmp     #$09       ;<= 8?
         bcc     @argFits   ;yes -> leave arg val alone
         lda     #$08
         sta     zpWParam
         lda     #$00
         sta     zpWAccum+1
         sta     zpWParam+1
         jsr     ModAndReplaceExpr ;get value of (arg MOD 8)
         lda     zpWAccum
         bne     @argFits
         inc     zpWAccum   ;add one if MOD gave zero (forcing to 1..7)
@argFits:
         lda     zpWAccum
         ldx     vZpSavedX
         sta     defMovSFacing,x ;save (possibly force-fitted) 2nd arg as facing
         lda     defMovSActorFrm,x ;get character/actor
         asl     A          ;multiply times 2
         tay
         lda     tbl_MoveTables,y ;Multiple indirections! We're doing something like:
         sta     vZpSprMvTbl ; moveTables[actor id]->[2]->[facing]
         lda     tbl_MoveTables+1,y ;index tbl_MoveTables by actor id
         sta     vZpSprMvTbl+1 ; to get movement tables for this actor
         ldy     #$04       ;indicate actor-specific table by [2] (bytes #4 and #5)
         lda     (vZpSprMvTbl),y
         sta     vZpSprFacingFlipTbl
         iny
         lda     (vZpSprMvTbl),y
         sta     vZpSprFacingFlipTbl+1
         lda     defMovSFacing,x ;get the movement direction
         tay
         lda     (vZpSprFacingFlipTbl),y ;and index by that
         and     #$f0       ;mask to obtain just horizontal and vertical flip
         ldy     zpActorNum
         pha
         lda     sprAttrFlags,y ;clear horizontal and vertical flip in sprite's flags
         and     #$3f
         sta     sprAttrFlags,y
         pla
         ora     sprAttrFlags,y ;and insert the ones we got from the table lookups
         sta     sprAttrFlags,y
         jsr     DefMvMaybeParseRParen ;are we at ')'?
         bcs     DefMvFinish ;yes -> finish up
         jsr     DefMvEvalNextArg ;no: get 3rd arg (speed)
         bcs     @arg4      ;empty arg (comma)? -> skip this one
         sta     defMovSSpdCtr,x ;set frames-til-move
         sta     defMovSSpeed,x ;and initializer for same
         jsr     DefMvMaybeParseRParen ;are we at ')'?
         bcs     DefMvFinish ;yes -> finish up
@arg4:   jsr     DefMvEvalNextArg ;no: get 4th arg (movement distance)
         bcs     @arg5      ;empty arg (comma)? -> skip this one
         adc     #$01       ;increment
         sta     defMovSMotionCtr,x ;set as how far we have left to move
         sta     defMovSMotion,x ;and initializer for same
         jsr     DefMvMaybeParseRParen ;are we at ')'?
         bcs     DefMvFinish ;yes -> finish up
@arg5:   jsr     DefMvEvalNextArg ;no: get 5th arg (display priority)
         bcs     @arg6      ;empty arg (comma)? -> skip this one
         ldy     #$00       ;"fore" (empty) flag
         lda     exprParseStk
         jsr     ErrUnlessZeroOrOne
         and     #$ff
         beq     @fore      ;zero? -> skip next instr
         ldy     #SpAtt_BEHIND ;"behind" flag
@fore:   ldx     zpActorNum
         lda     sprAttrFlags,x
         and     #$df       ;clear fore/behind flag in sprite attr flags
         sta     sprAttrFlags,x
         tya
         ora     sprAttrFlags,x ;store new fore/behind flag in sprite attr flags
         sta     sprAttrFlags,x
         jsr     DefMvMaybeParseRParen ;are we at ')'?
         bcs     DefMvFinish ;yes -> finish up
@arg6:   jsr     DefMvEvalNextArg ;no: get 6th arg (color palette #)
         cmp     #$04
         bcs     errIllVal_CB72 ;-> error if arg >= 4
         ldx     zpActorNum
         pha                ;push arg
         lda     sprAttrFlags,x
         and     #$fc
         sta     sprAttrFlags,x ;clear palette info from sprite attr flags
         pla                ;pull arg
         ora     sprAttrFlags,x ;combine with other attr flags
         sta     sprAttrFlags,x ;set combined flags
         jsr     SkipRParenOrSynErr ;must end with ')' here
         lda     #120
         ldx     zpDefMovIdx
         sta     defMovSPosX,x ;center sprite in the middle of the screen
         sta     defMovSPosY,x ;(only if all 6 SPRITE arguments were provided)
DefMvFinish:
         ldx     zpActorNum
         lda     sprAttrFlags,x
         ora     #SpAtt_DEFMOVE ;indicate DEF MOVE completed
         sta     sprAttrFlags,x
         rts

errIllVal_CB72:
         jmp     ErrorIllegalValue

DefMvEvalNextArg:
         jsr     SkipCommaOrSynErr ;parse comma
         jsr     DefMvSecIfEmptyArg ;is it an empty arg?
         bcs     DefMvSecAndRts ;yes -> return with carry set
DefMvEvalFirstArg:
         jsr     EvalByteInteger ;no: parse byte arg
         ldx     zpDefMovIdx ;reload x
         clc                ;and return with carry unset
         rts

DefMvMaybeParseRParen:
         jsr     TxtSkipSpaces
         cmp     #')'       ;did we get a ')'?
         beq     DefMvAdvTxtPtrAndSetCarry ;yes -> move past it, set carry
         clc                ;no: clear carry
         rts                ;return

DefMvAdvTxtPtrAndSetCarry:
         jsr     TxtPtrIncr
DefMvSecAndRts:
         sec
         rts

DefMvSecIfEmptyArg:
         jsr     TxtSkipSpaces
         cmp     #','
         beq     DefMvSecAndRts
         clc
         rts

CmdFn_POSITION:
         jsr     EvalByteInteger ;get first arg
         jsr     ErrUnlessZeroThruSeven ;ensure 0-7
         asl     A          ;multiply by 8
         asl     A
         asl     A
         sta     zpDefMovIdx
         jsr     DefMvEvalNextArg ;get next arg
         sta     defMovSPosX,x ;set actor's new X pos (in its DEF MOVE data)
         jsr     DefMvEvalNextArg
         sta     defMovSPosY,x ;set actor's new Y pos (in its DEF MOVE data)
         rts                ;return

CmdFn_MOVE:
         jsr     EvalByteInteger ;evaluate argument
         jsr     ErrUnlessZeroThruSeven ;ensure it's 0 thru 7
         tax
         lda     sprAttrFlags,x ;load sprite flags
         and     #SpAtt_DEFMOVE ;check if DEF MOVE was defined for this sprite
         beq     @skipArg   ;no -> do nothing for this arg
         lda     #SpAtt_ANIMATE
         ora     sprAttrFlags,x
         sta     sprAttrFlags,x ;set the SpAtt_ANIMATE flag for this move;
@skipArg:
         jsr     IsEndOfCmd ;NMI handler will start animating it
         beq     @animsOn   ;end of command? -> close up
         jsr     SkipCommaOrSynErr ;otherwise, we should have a comma here. Skip it.
         jmp     CmdFn_MOVE ;and evaluate next arg

@animsOn:
         lda     #$ff
         sta     zpNmiAnimate ;tell NMI hanlder there are animations to perform
rts_CBD8:
         rts

vZpEraOrCut .set $75        ;#$FF if ERA; #$00 if CUT
CmdFn_ERA:
         lda     #$ff       ;ERA mode
         .byte   $ae        ;(disable next instr)
CmdFn_CUT:
         lda     #$00       ;CUT mode
         sta     vZpEraOrCut ;save mode
         jsr     EvalByteInteger ;eval arg
         jsr     ErrUnlessZeroThruSeven ;ensure it's 0-7
         tay
         lda     sprAttrFlags,y
         and     #$ef
         sta     sprAttrFlags,y ;disable animation for the sprite
         lda     vZpEraOrCut ;check ERA or CUT
         beq     @skipEra   ;CUT? -> skip erase
         jsr     EraseSprite
@skipEra:
         jsr     IsEndOfCmd ;any other args?
         beq     rts_CBD8   ;no -> done
         jsr     SkipCommaOrSynErr ;skip a comma
         lda     vZpEraOrCut
         beq     CmdFn_CUT  ;and loop to start of command again
         bne     CmdFn_ERA

vZpActorNum .set $74
FnFn_CRASH:
         jsr     EvalParenZeroThruSevenOrError ;parse left paren, and actor number
         lda     zpWAccum   ;<- UNNECESSARY, we already have the value in both A reg and X reg.
         sta     vZpActorNum ;save actor num aside
         lda     sprAttrFlags,x
         and     #SpAtt_DEFMOVE ;does actor has a DEF MOVE set?
         beq     CRASH_retMinusTwo ;no -> return -2 (as mandated by the manual)
         jsr     GetActorDefMoveIdx ;multiply by 8 to get index to DEF MOVE data
         lda     defMovSPosX,x
         sta     zpSavedCH  ;grab and save actor's X pos
         lda     defMovSPosY,x
         sta     zpSavedCV  ;grab and save actor's Y pos
         lda     #$00
         sta     zpWAccum   ;set current actor-to-check to actor #0
         ldy     #NUM_ACTORS ;set Y reg to num actors (for count-down)
CRASH_actorLoop:
         lda     vZpActorNum
         cmp     zpWAccum   ;is the requested actor # same as one we're checking?
         beq     CRASH_nextActor ;yes -> skip this one (can't "crash" with self)
         jsr     GetActorDefMoveIdx ;else, multiply check-actor # by 8 to get index
         lda     defMovSPosX,x ;get X pos
         sec
         sbc     zpSavedCH  ;subtract user-specified actor's X pos from that
         jsr     CRASH_cmpAbs16 ;compare absolute value with 16
         bcs     CRASH_nextActor ; >= 16? -> no collision. Next actor
         lda     defMovSPosY,x ;get Y pos of check-actor
         sec
         sbc     zpSavedCV  ;subtract our actor's Y pos
         jsr     CRASH_cmpAbs16 ;compare absolute value with 16
         bcs     CRASH_nextActor ; >= 16? -> no collision, check next actor
         jmp     SkipRParenSetParseStkInt ;-> collision! Return this actor's number.

CRASH_nextActor:
         inc     zpWAccum   ;incr actor-to-check's number
         dey                ;decr Y (count-down # actors)
         bne     CRASH_actorLoop ;actors remaining to check? -> check next
         lda     #$ff       ;set WAccum to -1
         sta     zpWAccum
retMinus:
         sta     zpWAccum+1 ;set WAccum high byte
         jmp     SkipRParenSetParseStkInt ;parse closing paren, return WAccum via expr parse stack

CRASH_retMinusTwo:
         lda     #$fe       ;set WAccum to -2
         sta     zpWAccum
         lda     #$ff
         bne     retMinus   ;(always) -> parse closing paren, and return WAccum

CRASH_cmpAbs16:
         bcs     @pos       ;positive difference? -> skip negation
         sta     zpHeldKeyChar ;save original difference
         lda     #255       ;<- could've set this to zero, and skipped the clc/adc at end
         sec
         sbc     zpHeldKeyChar ;subtract difference from -1
         clc
         adc     #$01       ;add zero so it's subtraction from zero (straight negation)
@pos:    cmp     #$10       ;have positive. Cmp with 16, and return
rts_CC6B:
         rts

CmdFn_CAN:
         jsr     EvalByteInteger ;get actor # arg
         jsr     ErrUnlessZeroThruSeven ;ensure < 8
         pha                ;push actor num
         tay
         lda     #$00
         sta     sprAttrFlags,y ;clear actor's sprite flags (including animation)
         jsr     EraseSprite ;erase the sprite from screen
         pla                ;pull actor # again
         asl     A
         asl     A
         asl     A          ;multiply by 8, for indexing
         tax
         lda     #$00
         sta     defMovSFacing,x ;clear facing and position
         sta     defMovSPosX,x
         sta     defMovSPosY,x
         jsr     IsEndOfCmd ;more args?
         beq     rts_CC6B   ;no -> done!
         jsr     SkipCommaOrSynErr ;more args: ensure comma first.
         jmp     CmdFn_CAN  ; then loop back to the top!

EraseSprite:
         tya
         jsr     MulABy16
         tay
         lda     #$f8
         sta     oamBuffer+$80,y ;move the actor's sprites off-screen so they're hidden
         sta     oamBuffer+$84,y
         sta     oamBuffer+$88,y
         sta     oamBuffer+$8c,y
         rts

